INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Ex', 9, 'pt', '[{"numero": 1, "texto": "Então o SENHOR disse a Moisés: Entra a Faraó, e dize-lhe: o SENHOR, o Deus dos hebreus, diz assim: Deixa ir a meu povo, para que me sirvam;"}, {"numero": 2, "texto": "Porque se não o queres deixar ir, e os detiverdes ainda,"}, {"numero": 3, "texto": "Eis que a mão do SENHOR será sobre teus gados que estão no campo, cavalos, asnos, camelos, vacas e ovelhas, com pestilência gravíssima:"}, {"numero": 4, "texto": "E o SENHOR fará separação entre os gados de Israel e os do Egito, de modo que nada morra de todo o dos filhos de Israel."}, {"numero": 5, "texto": "E o SENHOR assinalou tempo, dizendo: Amanhã fará o SENHOR esta coisa na terra."}, {"numero": 6, "texto": "E o dia seguinte o SENHOR fez aquilo, e morreu todo o gado do Egito; mas do gado dos filhos de Israel não morreu um."}, {"numero": 7, "texto": "Então Faraó enviou, e eis que do gado dos filhos de Israel não havia um morto sequer. Mas o coração de Faraó se agravou, e não deixou ir ao povo."}, {"numero": 8, "texto": "E o SENHOR disse a Moisés e a Arão: Tomai punhados de cinza de um forno, e espalha-a Moisés até o céu diante de Faraó:"}, {"numero": 9, "texto": "E virá a ser pó sobre toda a terra do Egito, o qual originará sarna que cause feridas com ulcerações nos homens e nos animais, por toda a terra do Egito."}, {"numero": 10, "texto": "E tomaram a cinza do forno, e puseram-se diante de Faraó, e espalhou-a Moisés até o céu; e veio uma sarna que causava feridas com ulcerações tanto nos homens como nos animais."}, {"numero": 11, "texto": "E os magos não podiam estar diante de Moisés por causa das feridas, porque houve sarna nos magos e em todos os egípcios."}, {"numero": 12, "texto": "E o SENHOR endureceu o coração de Faraó, e não os ouviu; como o SENHOR o disse a Moisés."}, {"numero": 13, "texto": "Então o SENHOR disse a Moisés: Levanta-te de manhã, e põe-te diante de Faraó, e dize-lhe: o SENHOR, o Deus dos hebreus, disse assim: Deixa ir a meu povo, para que me sirva."}, {"numero": 14, "texto": "Porque eu enviarei esta vez todas minhas pragas a teu coração, sobre teus servos, e sobre teu povo, para que entendas que não há outro como eu em toda a terra."}, {"numero": 15, "texto": "Porque agora eu estenderei minha mão para ferir a ti e a teu povo de pestilência, e serás tirado da terra."}, {"numero": 16, "texto": "E à verdade eu te pus para declarar em ti meu poder, e que meu Nome seja contado em toda a terra."}, {"numero": 17, "texto": "Todavia te exaltas tu contra meu povo, para não deixá-los ir?"}, {"numero": 18, "texto": "Eis que amanhã a estas horas eu farei chover granizo muito grave, qual nunca foi em Egito, desde o dia que se fundou até agora."}, {"numero": 19, "texto": "Envia, pois, a recolher teu gado, e tudo o que tens no campo; porque todo homem ou animal que se achar no campo, e não for recolhido a casa, o granizo descerá sobre ele, e morrerá."}, {"numero": 20, "texto": "Dos servos de Faraó o que temeu a palavra do SENHOR, fez fugir seus criados e seu gado a casa:"}, {"numero": 21, "texto": "Mas o que não pôs em seu coração a palavra do SENHOR, deixou seus criados e seus gados no campo."}, {"numero": 22, "texto": "E o SENHOR disse a Moisés: Estende a tua mão até o céu, para que venha granizo em toda a terra do Egito sobre os homens, e sobre os animais, e sobre toda a erva do campo na terra do Egito."}, {"numero": 23, "texto": "E Moisés estendeu sua vara até o céu, e o SENHOR fez trovejar e cair granizo, e o fogo corria pela terra; e choveu o SENHOR granizo sobre a terra do Egito."}, {"numero": 24, "texto": "Houve, pois, granizo, e fogo misturado com o granizo, tão grande, qual nunca houve em toda a terra do Egito desde que foi habitada."}, {"numero": 25, "texto": "E aquele granizo feriu em toda a terra do Egito todo o que estava no campo, tanto homens como animais; o granizo também feriu toda erva do campo, e quebrou os galhos de todas as árvores daquela terra."}, {"numero": 26, "texto": "Somente na terra de Gósen, onde os filhos de Israel estavam, não houve granizo."}, {"numero": 27, "texto": "Então Faraó mandou chamar a Moisés e a Arão, e lhes disse: Pequei esta vez: o SENHOR é justo, e eu e meu povo ímpios."}, {"numero": 28, "texto": "Orai ao SENHOR: e cessem os trovões de Deus e o granizo; e eu vos deixarei ir, e não vos detereis mais."}, {"numero": 29, "texto": "E respondeu-lhe Moisés: Em saindo eu da cidade estenderei minhas mãos ao SENHOR, e os trovões cessarão, e não haverá mais granizo; para que saibas que do SENHOR é a terra."}, {"numero": 30, "texto": "Mas eu sei que nem tu nem teus servos temereis todavia a presença do Deus o SENHOR."}, {"numero": 31, "texto": "O linho, pois, e a cevada foram feridos; porque a cevada estava já espigada, e o linho em flor."}, {"numero": 32, "texto": "Mas o trigo e o centeio não foram feridos; porque eram tardios."}, {"numero": 33, "texto": "E saído Moisés da presença de Faraó da cidade, estendeu suas mãos ao SENHOR, e cessaram os trovões e o granizo; e a chuva não caiu mais sobre a terra."}, {"numero": 34, "texto": "E vendo Faraó que a chuva havia cessado e o granizo e os trovões, perseverou em pecar, e agravou seu coração, ele e seus servos."}, {"numero": 35, "texto": "E o coração de Faraó se endureceu, e não deixou ir aos filhos de Israel; como o SENHOR o havia dito por meio de Moisés."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 9, 'en', '[{"numero": 1, "texto": "Then the Lord said unto Moses, Go in unto Pharaoh, and tell him, Thus saith the Lord God of the Hebrews, Let my people go, that they may serve me."}, {"numero": 2, "texto": "For if thou refuse to let them go, and wilt hold them still,"}, {"numero": 3, "texto": "Behold, the hand of the Lord is upon thy cattle which is in the field, upon the horses, upon the asses, upon the camels, upon the oxen, and upon the sheep: there shall be a very grievous murrain."}, {"numero": 4, "texto": "And the Lord shall sever between the cattle of Israel and the cattle of Egypt: and there shall nothing die of all that is the children''s of Israel."}, {"numero": 5, "texto": "And the Lord appointed a set time, saying, To morrow the Lord shall do this thing in the land."}, {"numero": 6, "texto": "And the Lord did that thing on the morrow, and all the cattle of Egypt died: but of the cattle of the children of Israel died not one."}, {"numero": 7, "texto": "And Pharaoh sent, and, behold, there was not one of the cattle of the Israelites dead. And the heart of Pharaoh was hardened, and he did not let the people go."}, {"numero": 8, "texto": "And the Lord said unto Moses and unto Aaron, Take to you handfuls of ashes of the furnace, and let Moses sprinkle it toward the heaven in the sight of Pharaoh."}, {"numero": 9, "texto": "And it shall become small dust in all the land of Egypt, and shall be a boil breaking forth with blains upon man, and upon beast, throughout all the land of Egypt."}, {"numero": 10, "texto": "And they took ashes of the furnace, and stood before Pharaoh; and Moses sprinkled it up toward heaven; and it became a boil breaking forth with blains upon man, and upon beast."}, {"numero": 11, "texto": "And the magicians could not stand before Moses because of the boils; for the boil was upon the magicians, and upon all the Egyptians."}, {"numero": 12, "texto": "And the Lord hardened the heart of Pharaoh, and he hearkened not unto them; as the Lord had spoken unto Moses."}, {"numero": 13, "texto": "And the Lord said unto Moses, Rise up early in the morning, and stand before Pharaoh, and say unto him, Thus saith the Lord God of the Hebrews, Let my people go, that they may serve me."}, {"numero": 14, "texto": "For I will at this time send all my plagues upon thine heart, and upon thy servants, and upon thy people; that thou mayest know that there is none like me in all the earth."}, {"numero": 15, "texto": "For now I will stretch out my hand, that I may smite thee and thy people with pestilence; and thou shalt be cut off from the earth."}, {"numero": 16, "texto": "And in very deed for this cause have I raised thee up, for to shew in thee my power; and that my name may be declared throughout all the earth."}, {"numero": 17, "texto": "As yet exaltest thou thyself against my people, that thou wilt not let them go?"}, {"numero": 18, "texto": "Behold, to morrow about this time I will cause it to rain a very grievous hail, such as hath not been in Egypt since the foundation thereof even until now."}, {"numero": 19, "texto": "Send therefore now, and gather thy cattle, and all that thou hast in the field; for upon every man and beast which shall be found in the field, and shall not be brought home, the hail shall come down upon them, and they shall die."}, {"numero": 20, "texto": "He that feared the word of the Lord among the servants of Pharaoh made his servants and his cattle flee into the houses:"}, {"numero": 21, "texto": "And he that regarded not the word of the Lord left his servants and his cattle in the field."}, {"numero": 22, "texto": "And the Lord said unto Moses, Stretch forth thine hand toward heaven, that there may be hail in all the land of Egypt, upon man, and upon beast, and upon every herb of the field, throughout the land of Egypt."}, {"numero": 23, "texto": "And Moses stretched forth his rod toward heaven: and the Lord sent thunder and hail, and the fire ran along upon the ground; and the Lord rained hail upon the land of Egypt."}, {"numero": 24, "texto": "So there was hail, and fire mingled with the hail, very grievous, such as there was none like it in all the land of Egypt since it became a nation."}, {"numero": 25, "texto": "And the hail smote throughout all the land of Egypt all that was in the field, both man and beast; and the hail smote every herb of the field, and brake every tree of the field."}, {"numero": 26, "texto": "Only in the land of Goshen, where the children of Israel were, was there no hail."}, {"numero": 27, "texto": "And Pharaoh sent, and called for Moses and Aaron, and said unto them, I have sinned this time: the Lord is righteous, and I and my people are wicked."}, {"numero": 28, "texto": "Intreat the Lord (for it is enough) that there be no more mighty thunderings and hail; and I will let you go, and ye shall stay no longer."}, {"numero": 29, "texto": "And Moses said unto him, As soon as I am gone out of the city, I will spread abroad my hands unto the Lord; and the thunder shall cease, neither shall there be any more hail; that thou mayest know how that the earth is the Lord''s."}, {"numero": 30, "texto": "But as for thee and thy servants, I know that ye will not yet fear the Lord God."}, {"numero": 31, "texto": "And the flax and the barley was smitten: for the barley was in the ear, and the flax was bolled."}, {"numero": 32, "texto": "But the wheat and the rie were not smitten: for they were not grown up."}, {"numero": 33, "texto": "And Moses went out of the city from Pharaoh, and spread abroad his hands unto the Lord: and the thunders and hail ceased, and the rain was not poured upon the earth."}, {"numero": 34, "texto": "And when Pharaoh saw that the rain and the hail and the thunders were ceased, he sinned yet more, and hardened his heart, he and his servants."}, {"numero": 35, "texto": "And the heart of Pharaoh was hardened, neither would he let the children of Israel go; as the Lord had spoken by Moses."}]'::jsonb, 'King James Version'),
  ('Ex', 9, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Va vers Pharaon, et tu lui diras: Ainsi parle l''''Eternel, le Dieu des Hébreux: Laisse aller mon peuple, afin qu''''il me serve."}, {"numero": 2, "texto": "Si tu refuses de le laisser aller, et si tu le retiens encore,"}, {"numero": 3, "texto": "voici, la main de l''''Eternel sera sur tes troupeaux qui sont dans les champs, sur les chevaux, sur les ânes, sur les chameaux, sur les boeufs et sur les brebis; il y aura une mortalité très grande."}, {"numero": 4, "texto": "L''''Eternel distinguera entre les troupeaux d''''Israël et les troupeaux des Egyptiens, et il ne périra rien de tout ce qui est aux enfants d''''Israël."}, {"numero": 5, "texto": "L''''Eternel fixa le temps, et dit: Demain, l''''Eternel fera cela dans le pays."}, {"numero": 6, "texto": "Et l''''Eternel fit ainsi, dès le lendemain. Tous les troupeaux des Egyptiens périrent, et il ne périt pas une bête des troupeaux des enfants d''''Israël."}, {"numero": 7, "texto": "Pharaon s''''informa de ce qui était arrivé; et voici, pas une bête des troupeaux d''''Israël n''''avait péri. Mais le coeur de Pharaon s''''endurcit, et il ne laissa point aller le peuple."}, {"numero": 8, "texto": "L''''Eternel dit à Moïse et à Aaron: Remplissez vos mains de cendre de fournaise, et que Moïse la jette vers le ciel, sous les yeux de Pharaon."}, {"numero": 9, "texto": "Elle deviendra une poussière qui couvrira tout le pays d''''Egypte; et elle produira, dans tout le pays d''''Egypte, sur les hommes et sur les animaux, des ulcères formés par une éruption de pustules."}, {"numero": 10, "texto": "Ils prirent de la cendre de fournaise, et se présentèrent devant Pharaon; Moïse la jeta vers le ciel, et elle produisit sur les hommes et sur les animaux des ulcères formés par une éruption de pustules."}, {"numero": 11, "texto": "Les magiciens ne purent paraître devant Moïse, à cause des ulcères; car les ulcères étaient sur les magiciens, comme sur tous les Egyptiens."}, {"numero": 12, "texto": "L''''Eternel endurcit le coeur de Pharaon, et Pharaon n''''écouta point Moïse et Aaron, selon ce que l''''Eternel avait dit à Moïse."}, {"numero": 13, "texto": "L''''Eternel dit à Moïse: Lève-toi de bon matin, et présente-toi devant Pharaon. Tu lui diras: Ainsi parle l''''Eternel, le Dieu des Hébreux: Laisse aller mon peuple, afin qu''''il me serve."}, {"numero": 14, "texto": "Car, cette fois, je vais envoyer toutes mes plaies contre ton coeur, contre tes serviteurs et contre ton peuple, afin que tu saches que nul n''''est semblable à moi sur toute la terre."}, {"numero": 15, "texto": "Si j''''avais étendu ma main, et que je t''''eusse frappé par la mortalité, toi et ton peuple, tu aurais disparu de la terre."}, {"numero": 16, "texto": "Mais, je t''''ai laissé subsister, afin que tu voies ma puissance, et que l''''on publie mon nom par toute la terre."}, {"numero": 17, "texto": "Si tu t''''élèves encore contre mon peuple, et si tu ne le laisses point aller,"}, {"numero": 18, "texto": "voici, je ferai pleuvoir demain, à cette heure, une grêle tellement forte, qu''''il n''''y en a point eu de semblable en Egypte depuis le jour où elle a été fondée jusqu''''à présent."}, {"numero": 19, "texto": "Fais donc mettre en sûreté tes troupeaux et tout ce qui est à toi dans les champs. La grêle tombera sur tous les hommes et sur tous les animaux qui se trouveront dans les champs et qui n''''auront pas été recueillis dans les maisons, et ils périront."}, {"numero": 20, "texto": "Ceux des serviteurs de Pharaon qui craignirent la parole de l''''Eternel firent retirer dans les maisons leurs serviteurs et leurs troupeaux."}, {"numero": 21, "texto": "Mais ceux qui ne prirent point à coeur la parole de l''''Eternel laissèrent leurs serviteurs et leurs troupeaux dans les champs."}, {"numero": 22, "texto": "L''''Eternel dit à Moïse: Etends ta main vers le ciel; et qu''''il tombe de la grêle dans tout le pays d''''Egypte sur les hommes, sur les animaux, et sur toutes les herbes des champs, dans le pays d''''Egypte."}, {"numero": 23, "texto": "Moïse étendit sa verge vers le ciel; et l''''Eternel envoya des tonnerres et de la grêle, et le feu se promenait sur la terre. L''''Eternel fit pleuvoir de la grêle sur le pays d''''Egypte."}, {"numero": 24, "texto": "Il tomba de la grêle, et le feu se mêlait avec la grêle; elle était tellement forte qu''''il n''''y en avait point eu de semblable dans tout le pays d''''Egypte depuis qu''''il existe comme nation."}, {"numero": 25, "texto": "La grêle frappa, dans tout le pays d''''Egypte, tout ce qui était dans les champs, depuis les hommes jusqu''''aux animaux; la grêle frappa aussi toutes les herbes des champs, et brisa tous les arbres des champs."}, {"numero": 26, "texto": "Ce fut seulement dans le pays de Gosen, où étaient les enfants d''''Israël, qu''''il n''''y eut point de grêle."}, {"numero": 27, "texto": "Pharaon fit appeler Moïse et Aaron, et leur dit: Cette fois, j''''ai péché; c''''est l''''Eternel qui est le juste, et moi et mon peuple nous sommes les coupables."}, {"numero": 28, "texto": "Priez l''''Eternel, pour qu''''il n''''y ait plus de tonnerres et de grêle; et je vous laisserai aller, et l''''on ne vous retiendra plus."}, {"numero": 29, "texto": "Moïse lui dit: Quand je sortirai de la ville, je lèverai mes mains vers l''''Eternel, les tonnerres cesseront et il n''''y aura plus de grêle, afin que tu saches que la terre est à l''''Eternel."}, {"numero": 30, "texto": "Mais je sais que toi et tes serviteurs, vous ne craindrez pas encore l''''Eternel Dieu."}, {"numero": 31, "texto": "Le lin et l''''orge avaient été frappés, parce que l''''orge était en épis et que c''''était la floraison du lin;"}, {"numero": 32, "texto": "le froment et l''''épeautre n''''avaient point été frappés, parce qu''''ils sont tardifs."}, {"numero": 33, "texto": "Moïse sortit de chez Pharaon, pour aller hors de la ville; il leva ses mains vers l''''Eternel, les tonnerres et la grêle cessèrent, et la pluie ne tomba plus sur la terre."}, {"numero": 34, "texto": "Pharaon, voyant que la pluie, la grêle et les tonnerres avaient cessé, continua de pécher, et il endurcit son coeur, lui et ses serviteurs."}, {"numero": 35, "texto": "Le coeur de Pharaon s''''endurcit, et il ne laissa point aller les enfants d''''Israël, selon ce que l''''Eternel avait dit par l''''intermédiaire de Moïse."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 9, 'es', '[{"numero": 1, "texto": "ENTONCES Jehová dijo á Moisés: Entra á Faraón, y dile: Jehová, el Dios de los Hebreos, dice así: Deja ir á mi pueblo, para que me sirvan;"}, {"numero": 2, "texto": "Porque si no lo quieres dejar ir, y los detuvieres aún,"}, {"numero": 3, "texto": "He aquí la mano de Jehová será sobre tus ganados que están en el campo, caballos, asnos, camellos, vacas y ovejas, con pestilencia gravísima:"}, {"numero": 4, "texto": "Y Jehová hará separación entre los ganados de Israel y los de Egipto, de modo que nada muera de todo lo de los hijos de Israel."}, {"numero": 5, "texto": "Y Jehová señaló tiempo, diciendo: Mañana hará Jehová esta cosa en la tierra."}, {"numero": 6, "texto": "Y el día siguiente Jehová hizo aquello, y murió todo el ganado de Egipto; mas del ganado de los hijos de Israel no murió uno."}, {"numero": 7, "texto": "Entonces Faraón envió, y he aquí que del ganado de los hijos de Israel no había muerto uno. Mas el corazón de Faraón se agravó, y no dejó ir al pueblo."}, {"numero": 8, "texto": "Y Jehová dijo á Moisés y á Aarón: Tomad puñados de ceniza de un horno, y espárzala Moisés hacia el cielo delante de Faraón:"}, {"numero": 9, "texto": "Y vendrá á ser polvo sobre toda la tierra de Egipto, el cual originará sarpullido que cause tumores apostemados en los hombres y en las bestias, por todo el país de Egipto."}, {"numero": 10, "texto": "Y tomaron la ceniza del horno, y pusiéronse delante de Faraón, y esparcióla Moisés hacia el cielo; y vino un sarpullido que causaba tumores apostemados así en los hombres como en las bestias."}, {"numero": 11, "texto": "Y los magos no podían estar delante de Moisés á causa de los tumores, porque hubo sarpullido en los magos y en todos los Egipcios."}, {"numero": 12, "texto": "Y Jehová endureció el corazón de Faraón, y no los oyó; como Jehová lo había dicho á Moisés."}, {"numero": 13, "texto": "Entonces Jehová dijo á Moisés: Levántate de mañana, y ponte delante de Faraón, y dile: Jehová, el Dios de los Hebreos, dice así: Deja ir á mi pueblo, para que me sirva."}, {"numero": 14, "texto": "Porque yo enviaré esta vez todas mis plagas á tu corazón, sobre tus siervos, y sobre tu pueblo, para que entiendas que no hay otro como yo en toda la tierra."}, {"numero": 15, "texto": "Porque ahora yo extenderé mi mano para herirte á ti y á tu pueblo de pestilencia, y serás quitado de la tierra."}, {"numero": 16, "texto": "Y á la verdad yo te he puesto para declarar en ti mi potencia, y que mi Nombre sea contado en toda la tierra."}, {"numero": 17, "texto": "¿Todavía te ensalzas tú contra mi pueblo, para no dejarlos ir?"}, {"numero": 18, "texto": "He aquí que mañana á estas horas yo haré llover granizo muy grave, cual nunca fué en Egipto, desde el día que se fundó hasta ahora."}, {"numero": 19, "texto": "Envía, pues, á recoger tu ganado, y todo lo que tienes en el campo; porque todo hombre ó animal que se hallare en el campo, y no fuere recogido á casa, el granizo descenderá sobre él, y morirá."}, {"numero": 20, "texto": "De los siervos de Faraón el que temió la palabra de Jehová, hizo huir sus criados y su ganado á casa:"}, {"numero": 21, "texto": "Mas el que no puso en su corazón la palabra de Jehová, dejó sus criados y sus ganados en el campo."}, {"numero": 22, "texto": "Y Jehová dijo á Moisés: Extiende tu mano hacia el cielo, para que venga granizo en toda la tierra de Egipto sobre los hombres, y sobre las bestias, y sobre toda la hierba del campo en el país de Egipto."}, {"numero": 23, "texto": "Y Moisés extendió su vara hacia el cielo, y Jehová hizo tronar y granizar, y el fuego discurría por la tierra; y llovió Jehová granizo sobre la tierra de Egipto."}, {"numero": 24, "texto": "Hubo pues granizo, y fuego mezclado con el granizo, tan grande, cual nunca hubo en toda la tierra de Egipto desde que fué habitada."}, {"numero": 25, "texto": "Y aquel granizo hirió en toda la tierra de Egipto todo lo que estaba en el campo, así hombres como bestias; asimismo hirió el granizo toda la hierba del campo, y desgajó todos los árboles del país."}, {"numero": 26, "texto": "Solamente en la tierra de Gosén, donde los hijos de Israel estaban, no hubo granizo."}, {"numero": 27, "texto": "Entonces Faraón envió á llamar á Moisés y á Aarón, y les dijo: He pecado esta vez: Jehová es justo, y yo y mi pueblo impíos."}, {"numero": 28, "texto": "Orad á Jehová: y cesen los truenos de Dios y el granizo; y yo os dejaré ir, y no os detendréis más."}, {"numero": 29, "texto": "Y respondióle Moisés: En saliendo yo de la ciudad extenderé mis manos á Jehová, y los truenos cesarán, y no habrá más granizo; para que sepas que de Jehová es la tierra."}, {"numero": 30, "texto": "Mas yo sé que ni tú ni tus siervos temeréis todavía la presencia del Dios Jehová."}, {"numero": 31, "texto": "El lino, pues, y la cebada fueron heridos; porque la cebada estaba ya espigada, y el lino en caña."}, {"numero": 32, "texto": "Mas el trigo y el centeno no fueron heridos; porque eran tardíos."}, {"numero": 33, "texto": "Y salido Moisés de con Faraón de la ciudad, extendió sus manos á Jehová, y cesaron los truenos y el granizo; y la lluvia no cayó más sobre la tierra."}, {"numero": 34, "texto": "Y viendo Faraón que la lluvia había cesado y el granizo y los truenos, perseveró en pecar, y agravó su corazón, él y sus siervos."}, {"numero": 35, "texto": "Y el corazón de Faraón se endureció, y no dejó ir á los hijos de Israel; como Jehová lo había dicho por medio de Moisés."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 10, 'pt', '[{"numero": 1, "texto": "E o SENHOR disse a Moisés: Vai à presença de Faraó; porque agravei o coração dele, e o coração de seus servos, para fazer entre eles estes meus sinais;"}, {"numero": 2, "texto": "e para que contes a teus filhos e a teus netos as coisas que eu fiz em Egito, e meus sinais que realizei entre eles; e para que saibais que eu sou o SENHOR."}, {"numero": 3, "texto": "Então vieram Moisés e Arão a Faraó, e lhe disseram: O SENHOR, o Deus dos hebreus disse assim: Até quando não quererás te humilhar diante de mim? Deixa ir a meu povo para que me sirvam."}, {"numero": 4, "texto": "E se ainda recusas deixá-lo ir, eis que trarei amanhã gafanhotos em teu território,"}, {"numero": 5, "texto": "os quais cobrirão a face da terra, de modo que não se possa ver a terra; e ela comerá o que restou salvo, o que vos restou do granizo; comerão também toda árvore que vos produz fruto no campo;"}, {"numero": 6, "texto": "e encherão tuas casas, e as casas de todos os teus servos, e as casas de todos os egípcios, que nunca viram teus pais nem teus avós, desde que eles existiram sobre a terra até hoje. E voltou-se, e saiu da presença de Faraó."}, {"numero": 7, "texto": "Então os servos de Faraó lhe disseram: Até quando este nos será por laço? Deixa ir a estes homens, para que sirvam ao SENHOR seu Deus; ainda não sabes que Egito está destruído?"}, {"numero": 8, "texto": "E Moisés e Arão voltaram a ser chamados a Faraó, o qual lhes disse: Andai, servi ao SENHOR vosso Deus. Quem e quem são os que irão?"}, {"numero": 9, "texto": "E Moisés respondeu: Iremos com nossos meninos e com nossos idosos, com nossos filhos e com nossas filhas; iremos com nossas ovelhas e com nossas vacas, porque temos solenidade do SENHOR."}, {"numero": 10, "texto": "E ele lhes disse: Assim esteja o SENHOR convosco se eu vos deixar ir a vós e a vossos meninos; olhai como o mal está diante de vosso rosto."}, {"numero": 11, "texto": "Não será assim: ide agora vós, os homens, e servi ao SENHOR; pois isto é o que vós pedistes. E eles foram expulsos de diante de Faraó."}, {"numero": 12, "texto": "Então o SENHOR disse a Moisés: Estende tua mão sobre a terra do Egito para gafanhotos, a fim de que subam sobre a terra do Egito, e consumam tudo o que o granizo deixou."}, {"numero": 13, "texto": "E estendeu Moisés sua vara sobre a terra do Egito, e o SENHOR trouxe um vento oriental sobre aquela terra durante todo aquele dia e toda aquela noite; e na manhã o vento oriental trouxe os gafanhotos;"}, {"numero": 14, "texto": "E os gafanhotos subiram sobre toda a terra do Egito, e pousaram em todos os termos do Egito, em gravíssima maneira; antes dela não houve gafanhotos semelhantes, nem depois deles vieram outros tais;"}, {"numero": 15, "texto": "E cobriram a face de todo o país, e aquela terra se escureceu; e consumiram toda a erva da terra, e todo o fruto das árvores que o granizo havia deixado; que não restou coisa verde em árvores nem em erva do campo, por toda a terra do Egito."}, {"numero": 16, "texto": "Então Faraó fez chamar depressa a Moisés e a Arão, e disse: Pequei contra o SENHOR vosso Deus, e contra vós."}, {"numero": 17, "texto": "Mas rogo agora que perdoes meu pecado somente esta vez, e que oreis ao SENHOR vosso Deus que tire de mim somente esta morte."}, {"numero": 18, "texto": "E saiu da presença de Faraó, e orou ao SENHOR."}, {"numero": 19, "texto": "E o SENHOR voltou um vento ocidental fortíssimo, e tirou os gafanhotos, e lançou-os ao mar Vermelho; nem um gafanhoto restou ao todo o território do Egito."}, {"numero": 20, "texto": "Mas o SENHOR endureceu o coração de Faraó; e não permitiu a saída dos filhos de Israel."}, {"numero": 21, "texto": "E o SENHOR disse a Moisés: Estende tua mão até o céu, para que haja trevas sobre a terra do Egito, tão intensas que qualquer um as apalpe."}, {"numero": 22, "texto": "E estendeu Moisés sua mão até o céu, e houve densas durante trevas três dias por toda a terra do Egito."}, {"numero": 23, "texto": "Nenhum podia ver seu próximo, nem ninguém se levantou de seu lugar em três dias; mas todos os filhos de Israel tinham luz em suas habitações."}, {"numero": 24, "texto": "Então Faraó fez chamar a Moisés, e disse: Ide, servi ao SENHOR; somente restem vossas ovelhas e vossas vacas; vão também vossas crianças convosco."}, {"numero": 25, "texto": "E Moisés respondeu: Tu também nos entregarás sacrifícios e holocaustos para que sacrifiquemos ao SENHOR nosso Deus."}, {"numero": 26, "texto": "Nossos gados irão também conosco; não ficará nem uma casco; porque deles tomaremos para servir ao SENHOR nosso Deus; e não sabemos com que serviremos ao SENHOR, até que cheguemos ali."}, {"numero": 27, "texto": "Mas o SENHOR endureceu o coração de Faraó, e não quis deixá-los ir."}, {"numero": 28, "texto": "E disse-lhe Faraó: Retira-te de mim; guarda-te que não vejas mais meu rosto, porque em qualquer dia que vires meu rosto, morrerás."}, {"numero": 29, "texto": "E Moisés respondeu: Bem disseste; não verei mais teu rosto."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 10, 'en', '[{"numero": 1, "texto": "And the Lord said unto Moses, Go in unto Pharaoh: for I have hardened his heart, and the heart of his servants, that I might shew these my signs before him:"}, {"numero": 2, "texto": "And that thou mayest tell in the ears of thy son, and of thy son''s son, what things I have wrought in Egypt, and my signs which I have done among them; that ye may know how that I am the Lord."}, {"numero": 3, "texto": "And Moses and Aaron came in unto Pharaoh, and said unto him, Thus saith the Lord God of the Hebrews, How long wilt thou refuse to humble thyself before me? let my people go, that they may serve me."}, {"numero": 4, "texto": "Else, if thou refuse to let my people go, behold, to morrow will I bring the locusts into thy coast:"}, {"numero": 5, "texto": "And they shall cover the face of the earth, that one cannot be able to see the earth: and they shall eat the residue of that which is escaped, which remaineth unto you from the hail, and shall eat every tree which groweth for you out of the field:"}, {"numero": 6, "texto": "And they shall fill thy houses, and the houses of all thy servants, and the houses of all the Egyptians; which neither thy fathers, nor thy fathers'' fathers have seen, since the day that they were upon the earth unto this day. And he turned himself, and went out from Pharaoh."}, {"numero": 7, "texto": "And Pharaoh''s servants said unto him, How long shall this man be a snare unto us? let the men go, that they may serve the Lord their God: knowest thou not yet that Egypt is destroyed?"}, {"numero": 8, "texto": "And Moses and Aaron were brought again unto Pharaoh: and he said unto them, Go, serve the Lord your God: but who are they that shall go?"}, {"numero": 9, "texto": "And Moses said, We will go with our young and with our old, with our sons and with our daughters, with our flocks and with our herds will we go; for we must hold a feast unto the Lord."}, {"numero": 10, "texto": "And he said unto them, Let the Lord be so with you, as I will let you go, and your little ones: look to it; for evil is before you."}, {"numero": 11, "texto": "Not so: go now ye that are men, and serve the Lord; for that ye did desire. And they were driven out from Pharaoh''s presence."}, {"numero": 12, "texto": "And the Lord said unto Moses, Stretch out thine hand over the land of Egypt for the locusts, that they may come up upon the land of Egypt, and eat every herb of the land, even all that the hail hath left."}, {"numero": 13, "texto": "And Moses stretched forth his rod over the land of Egypt, and the Lord brought an east wind upon the land all that day, and all that night; and when it was morning, the east wind brought the locusts."}, {"numero": 14, "texto": "And the locust went up over all the land of Egypt, and rested in all the coasts of Egypt: very grievous were they; before them there were no such locusts as they, neither after them shall be such."}, {"numero": 15, "texto": "For they covered the face of the whole earth, so that the land was darkened; and they did eat every herb of the land, and all the fruit of the trees which the hail had left: and there remained not any green thing in the trees, or in the herbs of the field, through all the land of Egypt."}, {"numero": 16, "texto": "Then Pharaoh called for Moses and Aaron in haste; and he said, I have sinned against the Lord your God, and against you."}, {"numero": 17, "texto": "Now therefore forgive, I pray thee, my sin only this once, and intreat the Lord your God, that he may take away from me this death only."}, {"numero": 18, "texto": "And he went out from Pharaoh, and intreated the Lord."}, {"numero": 19, "texto": "And the Lord turned a mighty strong west wind, which took away the locusts, and cast them into the Red sea; there remained not one locust in all the coasts of Egypt."}, {"numero": 20, "texto": "But the Lord hardened Pharaoh''s heart, so that he would not let the children of Israel go."}, {"numero": 21, "texto": "And the Lord said unto Moses, Stretch out thine hand toward heaven, that there may be darkness over the land of Egypt, even darkness which may be felt."}, {"numero": 22, "texto": "And Moses stretched forth his hand toward heaven; and there was a thick darkness in all the land of Egypt three days:"}, {"numero": 23, "texto": "They saw not one another, neither rose any from his place for three days: but all the children of Israel had light in their dwellings."}, {"numero": 24, "texto": "And Pharaoh called unto Moses, and said, Go ye, serve the Lord; only let your flocks and your herds be stayed: let your little ones also go with you."}, {"numero": 25, "texto": "And Moses said, Thou must give us also sacrifices and burnt offerings, that we may sacrifice unto the Lord our God."}, {"numero": 26, "texto": "Our cattle also shall go with us; there shall not an hoof be left behind; for thereof must we take to serve the Lord our God; and we know not with what we must serve the Lord, until we come thither."}, {"numero": 27, "texto": "But the Lord hardened Pharaoh''s heart, and he would not let them go."}, {"numero": 28, "texto": "And Pharaoh said unto him, Get thee from me, take heed to thyself, see my face no more; for in that day thou seest my face thou shalt die."}, {"numero": 29, "texto": "And Moses said, Thou hast spoken well, I will see thy face again no more."}]'::jsonb, 'King James Version'),
  ('Ex', 10, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Va vers Pharaon, car j''''ai endurci son coeur et le coeur de ses serviteurs, pour faire éclater mes signes au milieu d''''eux."}, {"numero": 2, "texto": "C''''est aussi pour que tu racontes à ton fils et au fils de ton fils comment j''''ai traité les Egyptiens, et quels signes j''''ai fait éclater au milieu d''''eux. Et vous saurez que je suis l''''Eternel."}, {"numero": 3, "texto": "Moïse et Aaron allèrent vers Pharaon, et lui dirent: Ainsi parle l''''Eternel, le Dieu des Hébreux: Jusqu''''à quand refuseras-tu de t''''humilier devant moi? Laisse aller mon peuple, afin qu''''il me serve."}, {"numero": 4, "texto": "Si tu refuses de laisser aller mon peuple, voici, je ferai venir demain des sauterelles dans toute l''''étendue de ton pays."}, {"numero": 5, "texto": "Elles couvriront la surface de la terre, et l''''on ne pourra plus voir la terre; elles dévoreront le reste de ce qui est échappé, ce que vous a laissé la grêle, elles dévoreront tous les arbres qui croissent dans vos champs;"}, {"numero": 6, "texto": "elles rempliront tes maisons, les maisons de tous tes serviteurs et les maisons de tous les Egyptiens. Tes pères et les pères de tes pères n''''auront rien vu de pareil depuis qu''''ils existent sur la terre jusqu''''à ce jour. Moïse se retira, et sortit de chez Pharaon."}, {"numero": 7, "texto": "Les serviteurs de Pharaon lui dirent: Jusqu''''à quand cet homme sera-t-il pour nous un piège? Laisse aller ces gens, et qu''''ils servent l''''Eternel, leur Dieu. Ne vois-tu pas encore que l''''Egypte périt?"}, {"numero": 8, "texto": "On fit revenir vers Pharaon Moïse et Aaron: Allez, leur dit-il, servez l''''Eternel, votre Dieu. Qui sont ceux qui iront?"}, {"numero": 9, "texto": "Moïse répondit: Nous irons avec nos enfants et nos vieillards, avec nos fils et nos filles, avec nos brebis et nos boeufs; car c''''est pour nous une fête en l''''honneur de l''''Eternel."}, {"numero": 10, "texto": "Pharaon leur dit: Que l''''Eternel soit avec vous, tout comme je vais vous laisser aller, vous et vos enfants! Prenez garde, car le malheur est devant vous!"}, {"numero": 11, "texto": "Non, non: allez, vous les hommes, et servez l''''Eternel, car c''''est là ce que vous avez demandé. Et on les chassa de la présence de Pharaon."}, {"numero": 12, "texto": "L''''Eternel dit à Moïse: Etends ta main sur le pays d''''Egypte, et que les sauterelles montent sur le pays d''''Egypte; qu''''elles dévorent toute l''''herbe de la terre, tout ce que la grêle a laissé."}, {"numero": 13, "texto": "Moïse étendit sa verge sur le pays d''''Egypte; et l''''Eternel fit souffler un vent d''''orient sur le pays toute cette journée et toute la nuit. Quand ce fut le matin, le vent d''''orient avait apporté les sauterelles."}, {"numero": 14, "texto": "Les sauterelles montèrent sur le pays d''''Egypte, et se posèrent dans toute l''''étendue de l''''Egypte; elles étaient en si grande quantité qu''''il n''''y avait jamais eu et qu''''il n''''y aura jamais rien de semblable."}, {"numero": 15, "texto": "Elles couvrirent la surface de toute la terre, et la terre fut dans l''''obscurité; elles dévorèrent toute l''''herbe de la terre et tout le fruit des arbres, tout ce que la grêle avait laissé; et il ne resta aucune verdure aux arbres ni à l''''herbe des champs, dans tout le pays d''''Egypte."}, {"numero": 16, "texto": "Aussitôt Pharaon appela Moïse et Aaron, et dit: J''''ai péché contre l''''Eternel, votre Dieu, et contre vous."}, {"numero": 17, "texto": "Mais pardonne mon péché pour cette fois seulement; et priez l''''Eternel, votre Dieu, afin qu''''il éloigne de moi encore cette plaie mortelle."}, {"numero": 18, "texto": "Moïse sortit de chez Pharaon, et il pria l''''Eternel."}, {"numero": 19, "texto": "L''''Eternel fit souffler un vent d''''occident très fort, qui emporta les sauterelles, et les précipita dans la mer Rouge; il ne resta pas une seule sauterelle dans toute l''''étendue de l''''Egypte."}, {"numero": 20, "texto": "L''''Eternel endurcit le coeur de Pharaon, et Pharaon ne laissa point aller les enfants d''''Israël."}, {"numero": 21, "texto": "L''''Eternel dit à Moïse: Etends ta main vers le ciel, et qu''''il y ait des ténèbres sur le pays d''''Egypte, et que l''''on puisse les toucher."}, {"numero": 22, "texto": "Moïse étendit sa main vers le ciel; et il y eut d''''épaisses ténèbres dans tout le pays d''''Egypte, pendant trois jours."}, {"numero": 23, "texto": "On ne se voyait pas les uns les autres, et personne ne se leva de sa place pendant trois jours. Mais il y avait de la lumière dans les lieux où habitaient tous les enfants d''''Israël."}, {"numero": 24, "texto": "Pharaon appela Moïse, et dit: Allez, servez l''''Eternel. Il n''''y aura que vos brebis et vos boeufs qui resteront, et vos enfants pourront aller avec vous."}, {"numero": 25, "texto": "Moïse répondit: Tu mettras toi-même entre nos mains de quoi faire les sacrifices et les holocaustes que nous offrirons à l''''Eternel, notre Dieu."}, {"numero": 26, "texto": "Nos troupeaux iront avec nous, et il ne restera pas un ongle; car c''''est là que nous prendrons pour servir l''''Eternel, notre Dieu; et jusqu''''à ce que nous soyons arrivés, nous ne savons pas ce que nous choisirons pour offrir à l''''Eternel."}, {"numero": 27, "texto": "L''''Eternel endurcit le coeur de Pharaon, et Pharaon ne voulut point les laisser aller."}, {"numero": 28, "texto": "Pharaon dit à Moïse: Sors de chez moi! Garde-toi de paraître encore en ma présence, car le jour où tu paraîtras en ma présence, tu mourras."}, {"numero": 29, "texto": "Tu l''''as dit! répliqua Moïse, je ne paraîtrai plus en ta présence."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 10, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Moisés: Entra á Faraón; porque yo he agravado su corazón, y el corazón de sus siervos, para dar entre ellos estas mis señales;"}, {"numero": 2, "texto": "Y para que cuentes á tus hijos y á tus nietos las cosas que yo hice en Egipto, y mis señales que dí entre ellos; y para que sepáis que yo soy Jehová."}, {"numero": 3, "texto": "Entonces vinieron Moisés y Aarón á Faraón, y le dijeron: Jehová, el Dios de los Hebreos, ha dicho así: ¿Hasta cuándo no querrás humillarte delante de mí? Deja ir á mi pueblo para que me sirvan."}, {"numero": 4, "texto": "Y si aun rehusas dejarlo ir, he aquí que yo traeré mañana langosta en tus términos,"}, {"numero": 5, "texto": "La cual cubrirá la faz de la tierra, de modo que no pueda verse la tierra; y ella comerá lo que quedó salvo, lo que os ha quedado del granizo; comerá asimismo todo árbol que os produce fruto en el campo:"}, {"numero": 6, "texto": "Y llenarse han tus casas, y las casas de todos tus siervos, y las casas de todos los Egipcios, cual nunca vieron tus padres ni tus abuelos, desde que ellos fueron sobre la tierra hasta hoy. Y volvióse, y salió de con Faraón."}, {"numero": 7, "texto": "Entonces los siervos de Faraón le dijeron: ¿Hasta cuándo nos ha de ser éste por lazo? Deja ir á estos hombres, para que sirvan á Jehová su Dios; ¿aun no sabes que Egipto está destruído?"}, {"numero": 8, "texto": "Y Moisés y Aarón volvieron á ser llamados á Faraón, el cual les dijo: Andad, servid á Jehová vuestro Dios. ¿Quién y quién son los que han de ir?"}, {"numero": 9, "texto": "Y Moisés respondió: Hemos de ir con nuestros niños y con nuestros viejos, con nuestros hijos y con nuestras hijas: con nuestras ovejas y con nuestras vacas hemos de ir; porque tenemos solemnidad de Jehová."}, {"numero": 10, "texto": "Y él les dijo: Así sea Jehová con vosotros como yo os dejaré ir á vosotros y á vuestros niños: mirad como el mal está delante de vuestro rostro."}, {"numero": 11, "texto": "No será así: id ahora vosotros los varones, y servid á Jehová: pues esto es lo que vosotros demandasteis. Y echáronlos de delante de Faraón."}, {"numero": 12, "texto": "Entonces Jehová dijo á Moisés: Extiende tu mano sobre la tierra de Egipto para langosta, á fin de que suba sobre el país de Egipto, y consuma todo lo que el granizo dejó."}, {"numero": 13, "texto": "Y extendió Moisés su vara sobre la tierra de Egipto, y Jehová trajo un viento oriental sobre el país todo aquel día y toda aquella noche; y á la mañana el viento oriental trajo la langosta:"}, {"numero": 14, "texto": "Y subió la langosta sobre toda la tierra de Egipto, y asentóse en todos los términos de Egipto, en gran manera grave: antes de ella no hubo langosta semejante, ni después de ella vendrá otra tal;"}, {"numero": 15, "texto": "Y cubrió la faz de todo el país, y oscurecióse la tierra; y consumió toda la hierba de la tierra, y todo el fruto de los árboles que había dejado el granizo; que no quedó cosa verde en árboles ni en hierba del campo, por toda la tierra de Egipto."}, {"numero": 16, "texto": "Entonces Faraón hizo llamar apriesa á Moisés y á Aarón, y dijo: He pecado contra Jehová vuestro Dios, y contra vosotros."}, {"numero": 17, "texto": "Mas ruego ahora que perdones mi pecado solamente esta vez, y que oréis á Jehová vuestro Dios que quite de mí solamente esta muerte."}, {"numero": 18, "texto": "Y salió de con Faraón, y oró á Jehová."}, {"numero": 19, "texto": "Y Jehová volvió un viento occidental fortísimo, y quitó la langosta, y arrojóla en el mar Bermejo: ni una langosta quedó en todo el término de Egipto."}, {"numero": 20, "texto": "Mas Jehová endureció el corazón de Faraón; y no envió los hijos de Israel."}, {"numero": 21, "texto": "Y Jehová dijo á Moisés: Extiende tu mano hacia el cielo, para que haya tinieblas sobre la tierra de Egipto, tales que cualquiera las palpe."}, {"numero": 22, "texto": "Y extendió Moisés su mano hacia el cielo, y hubo densas tinieblas tres días por toda la tierra de Egipto."}, {"numero": 23, "texto": "Ninguno vió á su prójimo, ni nadie se levantó de su lugar en tres días; mas todos los hijos de Israel tenían luz en sus habitaciones."}, {"numero": 24, "texto": "Entonces Faraón hizo llamar á Moisés, y dijo: Id, servid á Jehová; solamente queden vuestras ovejas y vuestras vacas: vayan también vuestros niños con vosotros."}, {"numero": 25, "texto": "Y Moisés respondió: Tú también nos entregarás sacrificios y holocaustos que sacrifiquemos á Jehová nuestro Dios."}, {"numero": 26, "texto": "Nuestros ganados irán también con nosotros; no quedará ni una uña; porque de ellos hemos de tomar para servir á Jehová nuestro Dios; y no sabemos con qué hemos de servir á Jehová, hasta que lleguemos allá."}, {"numero": 27, "texto": "Mas Jehová endureció el corazón de Faraón, y no quiso dejarlos ir."}, {"numero": 28, "texto": "Y díjole Faraón: Retírate de mí: guárdate que no veas más mi rostro, porque en cualquier día que vieres mi rostro, morirás."}, {"numero": 29, "texto": "Y Moisés respondió: Bien has dicho; no veré más tu rostro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 11, 'pt', '[{"numero": 1, "texto": "E o SENHOR disse a Moisés: Uma praga trarei ainda sobre Faraó, e sobre o Egito; depois da qual ele vos deixará ir daqui; e seguramente vos expulsará daqui de todo."}, {"numero": 2, "texto": "Fala agora ao povo, e que cada um peça a seu vizinho, e cada uma à sua vizinha, objetos de prata e de ouro."}, {"numero": 3, "texto": "E o SENHOR fez o povo ser favorecido aos olhos dos egípcios. Também Moisés era muito grande homem na terra do Egito, aos olhos dos servos de Faraó, e aos olhos do povo."}, {"numero": 4, "texto": "E disse Moisés: o SENHOR disse assim: À meia noite eu sairei por meio do Egito,"}, {"numero": 5, "texto": "E morrerá todo primogênito na terra do Egito, desde o primogênito de Faraó que se assenta em seu trono, até o primogênito da serva que está atrás do moinho; e todo primogênito dos animais."}, {"numero": 6, "texto": "E haverá grande clamor por toda a terra do Egito, qual nunca foi, nem jamais será."}, {"numero": 7, "texto": "Mas entre todos os filhos de Israel, desde o homem até o animal, nem um cão moverá sua língua; para que saibais que o SENHOR fará diferença entre os egípcios e os israelitas."}, {"numero": 8, "texto": "E descerão a mim todos estes teus servos, e inclinados diante de mim dirão: Sai tu, e todo o povo que está abaixo de ti; e depois disto eu sairei. E saiu-se muito irado da presença de Faraó."}, {"numero": 9, "texto": "E o SENHOR disse a Moisés: Faraó não vos ouvirá, para que minhas maravilhas se multipliquem na terra do Egito."}, {"numero": 10, "texto": "E Moisés e Arão fizeram todos estes prodígios diante de Faraó; mas o SENHOR havia endurecido o coração de Faraó, e não permitiu que os filhos de Israel saíssem da sua terra."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 11, 'en', '[{"numero": 1, "texto": "And the Lord said unto Moses, Yet will I bring one plague more upon Pharaoh, and upon Egypt; afterwards he will let you go hence: when he shall let you go, he shall surely thrust you out hence altogether."}, {"numero": 2, "texto": "Speak now in the ears of the people, and let every man borrow of his neighbour, and every woman of her neighbour, jewels of silver and jewels of gold."}, {"numero": 3, "texto": "And the Lord gave the people favour in the sight of the Egyptians. Moreover the man Moses was very great in the land of Egypt, in the sight of Pharaoh''s servants, and in the sight of the people."}, {"numero": 4, "texto": "And Moses said, Thus saith the Lord, About midnight will I go out into the midst of Egypt:"}, {"numero": 5, "texto": "And all the firstborn in the land of Egypt shall die, from the first born of Pharaoh that sitteth upon his throne, even unto the firstborn of the maidservant that is behind the mill; and all the firstborn of beasts."}, {"numero": 6, "texto": "And there shall be a great cry throughout all the land of Egypt, such as there was none like it, nor shall be like it any more."}, {"numero": 7, "texto": "But against any of the children of Israel shall not a dog move his tongue, against man or beast: that ye may know how that the Lord doth put a difference between the Egyptians and Israel."}, {"numero": 8, "texto": "And all these thy servants shall come down unto me, and bow down themselves unto me, saying, Get thee out, and all the people that follow thee: and after that I will go out. And he went out from Pharaoh in a great anger."}, {"numero": 9, "texto": "And the Lord said unto Moses, Pharaoh shall not hearken unto you; that my wonders may be multiplied in the land of Egypt."}, {"numero": 10, "texto": "And Moses and Aaron did all these wonders before Pharaoh: and the Lord hardened Pharaoh''s heart, so that he would not let the children of Israel go out of his land."}]'::jsonb, 'King James Version'),
  ('Ex', 11, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Je ferai venir encore une plaie sur Pharaon et sur l''''Egypte. Après cela, il vous laissera partir d''''ici. Lorsqu''''il vous laissera tout à fait aller, il vous chassera même d''''ici."}, {"numero": 2, "texto": "Parle au peuple, pour que chacun demande à son voisin et chacune à sa voisine des vases d''''argent et des vases d''''or."}, {"numero": 3, "texto": "L''''Eternel fit trouver grâce au peuple aux yeux des Egyptiens; Moïse lui-même était très considéré dans le pays d''''Egypte, aux yeux des serviteurs de Pharaon et aux yeux du peuple."}, {"numero": 4, "texto": "Moïse dit: Ainsi parle l''''Eternel: Vers le milieu de la nuit, je passerai au travers de l''''Egypte;"}, {"numero": 5, "texto": "et tous les premiers-nés mourront dans le pays d''''Egypte, depuis le premier-né de Pharaon assis sur son trône, jusqu''''au premier-né de la servante qui est derrière la meule, et jusqu''''à tous les premiers-nés des animaux."}, {"numero": 6, "texto": "Il y aura dans tout le pays d''''Egypte de grands cris, tels qu''''il n''''y en a point eu et qu''''il n''''y en aura plus de semblables."}, {"numero": 7, "texto": "Mais parmi tous les enfants d''''Israël, depuis les hommes jusqu''''aux animaux, pas même un chien ne remuera sa langue, afin que vous sachiez quelle différence l''''Eternel fait entre l''''Egypte et Israël."}, {"numero": 8, "texto": "Alors tous tes serviteurs que voici descendront vers moi et se prosterneront devant moi, en disant: Sors, toi et tout le peuple qui s''''attache à tes pas! Après cela, je sortirai. Moïse sortit de chez Pharaon, dans une ardente colère."}, {"numero": 9, "texto": "L''''Eternel dit à Moïse: Pharaon ne vous écoutera point, afin que mes miracles se multiplient dans le pays d''''Egypte."}, {"numero": 10, "texto": "Moïse et Aaron firent tous ces miracles devant Pharaon, et Pharaon ne laissa point aller les enfants d''''Israël hors de son pays. Exode"}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 11, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Moisés: Una plaga traeré aún sobre Faraón, y sobre Egipto; después de la cual él os dejará ir de aquí; y seguramente os echará de aquí del todo."}, {"numero": 2, "texto": "Habla ahora al pueblo, y que cada uno demande á su vecino, y cada una á su vecina, vasos de plata y de oro."}, {"numero": 3, "texto": "Y Jehová dió gracia al pueblo en los ojos de los Egipcios. También Moisés era muy gran varón en la tierra de Egipto, á los ojos de los siervos de Faraón, y á los ojos del pueblo."}, {"numero": 4, "texto": "Y dijo Moisés: Jehová ha dicho así: A la media noche yo saldré por medio de Egipto,"}, {"numero": 5, "texto": "Y morirá todo primogénito en tierra de Egipto, desde el primogénito de Faraón que se sienta en su trono, hasta el primogénito de la sierva que está tras la muela; y todo primogénito de las bestias."}, {"numero": 6, "texto": "Y habrá gran clamor por toda la tierra de Egipto, cual nunca fué, ni jamás será."}, {"numero": 7, "texto": "Mas entre todos los hijos de Israel, desde el hombre hasta la bestia, ni un perro moverá su lengua: para que sepáis que hará diferencia Jehová entre los Egipcios y los Israelitas."}, {"numero": 8, "texto": "Y descenderán á mí todos estos tus siervos, é inclinados delante de mí dirán: Sal tú, y todo el pueblo que está bajo de ti; y después de esto yo saldré. Y salióse muy enojado de con Faraón."}, {"numero": 9, "texto": "Y Jehová dijo á Moisés: Faraón no os oirá, para que mis maravillas se multipliquen en la tierra de Egipto."}, {"numero": 10, "texto": "Y Moisés y Aarón hicieron todos estos prodigios delante de Faraón: mas Jehová había endurecido el corazón de Faraón, y no envió á los hijos de Israel fuera de su país."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 12, 'pt', '[{"numero": 1, "texto": "E falou o SENHOR a Moisés e a Arão na terra do Egito, dizendo:"}, {"numero": 2, "texto": "Este mês vos será o princípio dos meses; será este para vós o primeiro nos meses do ano."}, {"numero": 3, "texto": "Falai a toda a congregação de Israel, dizendo: No [dia] dez deste mês tome para si cada um um cordeiro pelas famílias dos pais, um cordeiro por família:"}, {"numero": 4, "texto": "Mas se a família for pequena que não seja capaz de comer o cordeiro inteiro, então tomará a seu vizinho imediato à sua casa, e segundo o número das pessoas, cada um conforme seu comer, fareis a conta sobre o cordeiro."}, {"numero": 5, "texto": "O cordeiro será sem defeito, macho de um ano; vós o tomareis das ovelhas ou das cabras:"}, {"numero": 6, "texto": "E o guardareis até o dia catorze desse mês; e toda a congregação do povo de Israel o imolará ao entardecer."}, {"numero": 7, "texto": "E tomarão do sangue, e o porão nos dois postes e na verga das casas em que o comerão."}, {"numero": 8, "texto": "E naquela noite comerão a carne assada ao fogo, e pães sem levedura; com ervas amargas o comerão."}, {"numero": 9, "texto": "Nenhuma coisa comereis dele crua, nem cozida em água, mas sim assada ao fogo; sua cabeça com seus pés e seus intestinos."}, {"numero": 10, "texto": "Nenhuma coisa deixareis dele até a manhã; e o que houver restado até a manhã, queimareis no fogo."}, {"numero": 11, "texto": "E assim tereis de comê-lo: cingidos vossos lombos, vossos calçados em vossos pés, e vosso bordão em vossa mão; e o comereis apressadamente: é a Páscoa do SENHOR."}, {"numero": 12, "texto": "Pois eu passarei naquela noite pela terra do Egito, e ferirei todo primogênito na terra do Egito, tanto nos homens como nos animais; e executarei juízos em todos os deuses do Egito. EU SOU O SENHOR."}, {"numero": 13, "texto": "E o sangue vos será por sinal nas casas onde vós estejais; e verei o sangue, e passarei de vós, e não haverá em vós praga de mortandade, quando ferirei a terra do Egito."}, {"numero": 14, "texto": "E hoje vos será em memória, e tereis de celebrá-lo como solenidade ao SENHOR durante vossas gerações; por estatuto perpétuo o celebrareis."}, {"numero": 15, "texto": "Sete dias comereis pães sem levedura; e assim o primeiro dia fareis que não haja levedura em vossas casas; porque qualquer um que comer levedado desde o primeiro dia até o sétimo, aquela alma será eliminada de Israel."}, {"numero": 16, "texto": "No primeiro dia haverá santa convocação, e também no sétimo dia tereis uma santa convocação; nenhuma obra se fará neles, exceto somente que prepareis o que cada qual houver de comer."}, {"numero": 17, "texto": "E guardareis a festa dos pães ázimos, porque em este mesmo dia tirei vossos exércitos da terra do Egito: portanto guardareis hoje em vossas gerações por costume perpétuo."}, {"numero": 18, "texto": "No mês primeiro, o dia catorze do mês pela tarde, comereis os pães sem levedura, até o vinte e um do mês pela tarde."}, {"numero": 19, "texto": "Por sete dias não se achará levedura em vossas casas, porque qualquer um que comer algo levedado, tanto o estrangeiro como o natural da terra, tal alma será eliminada da congregação de Israel."}, {"numero": 20, "texto": "Nenhuma coisa levedada comereis; em todas as vossas habitações comereis pães sem levedura."}, {"numero": 21, "texto": "E Moisés convocou a todos os anciãos de Israel, e disse-lhes: Tirai, e tomai para vós cordeiros por vossas famílias, e sacrificai a páscoa."}, {"numero": 22, "texto": "E tomai um molho de hissopo, e molhai-lhe no sangue que estará em uma bacia, e untai a verga e os dois postes com o sangue que estará na bacia; e nenhum de vós saia das portas de sua casa até a manhã."}, {"numero": 23, "texto": "Porque o SENHOR passará ferindo os egípcios; e quando vir o sangue na verga e nos dois postes, passará o SENHOR aquela porta, e não deixará entrar o feridor em vossas casas para ferir."}, {"numero": 24, "texto": "E guardareis isto por estatuto para vós e para vossos filhos para sempre."}, {"numero": 25, "texto": "E será que quando houverdes entrado na terra que o SENHOR vos dará, como tem falado, que guardareis este rito."}, {"numero": 26, "texto": "E quando vos perguntarem vossos filhos: Que rito é este vosso?"}, {"numero": 27, "texto": "Respondereis: É o sacrifício da Páscoa do SENHOR, que passou nas casas dos filhos de Israel no Egito, quando feriu os egípcios, e livrou nossas casas. Então o povo se inclinou e adorou."}, {"numero": 28, "texto": "E os filhos de Israel se foram, e fizeram exatamente assim, como o SENHOR havia mandado a Moisés e a Arão."}, {"numero": 29, "texto": "E aconteceu que à meia-noite o SENHOR feriu todo primogênito na terra do Egito, desde o primogênito de Faraó que se sentava sobre seu trono, até o primogênito do prisioneiro que estava no cárcere, e todo primogênito dos animais."}, {"numero": 30, "texto": "E levantou-se naquela noite Faraó, ele e todos os seus servos, e todos os egípcios; e havia um grande clamor no Egito, porque não havia casa onde não houvesse morto."}, {"numero": 31, "texto": "E fez chamar a Moisés e a Arão de noite, e disse-lhes: Saí do meio de meu povo vós, e os filhos de Israel; e ide, servi ao SENHOR, como dissestes."}, {"numero": 32, "texto": "Tomai também vossas ovelhas e vossas vacas, como dissestes, e ide; e abençoai também a mim."}, {"numero": 33, "texto": "E os egípcios apressavam ao povo, dando pressa a expulsá-los da terra; porque diziam: Todos seremos mortos."}, {"numero": 34, "texto": "E levou o povo sua massa antes que se levedasse, suas massas envoltas em suas mantas sobre seus ombros."}, {"numero": 35, "texto": "E fizeram os filhos de Israel conforme o mandamento de Moisés, pedindo aos egípcios objetos de prata, e objetos de ouro, e roupas."}, {"numero": 36, "texto": "E o SENHOR deu favor ao povo diante dos egípcios, e deram-lhes; e eles despojaram os egípcios."}, {"numero": 37, "texto": "E partiram os filhos de Israel de Ramessés a Sucote, como seiscentos mil homens a pé, sem contar os meninos."}, {"numero": 38, "texto": "E também subiu com eles grande multidão de diversa variedade de gentes; e ovelhas, e gados muito muitos."}, {"numero": 39, "texto": "E cozeram tortas sem levedura da massa que haviam tirado do Egito; porque não havia levedado, porquanto expulsando-os os egípcios, não haviam podido deter-se, nem ainda preparar para si comida."}, {"numero": 40, "texto": "O tempo que os filhos de Israel habitaram no Egito foi quatrocentos e trinta anos."}, {"numero": 41, "texto": "E passados quatrocentos e trinta anos, no mesmo dia saíram todos os exércitos do SENHOR da terra do Egito."}, {"numero": 42, "texto": "É noite de guardar ao SENHOR, por havê-los tirado nela da terra do Egito. Esta noite devem guardar ao SENHOR todos os filhos de Israel em suas gerações."}, {"numero": 43, "texto": "E o SENHOR disse a Moisés e a Arão: Esta é a ordenança da Páscoa: Nenhum estrangeiro comerá dela;"}, {"numero": 44, "texto": "Mas todo servo humano comprado por dinheiro, comerá dela depois que o houveres circuncidado."}, {"numero": 45, "texto": "O estrangeiro e o assalariado não comerão dela."}, {"numero": 46, "texto": "Em uma casa se comerá, e não levarás daquela carne fora de casa, nem quebrareis osso seu."}, {"numero": 47, "texto": "Toda a congregação de Israel o sacrificará."}, {"numero": 48, "texto": "Mas se algum estrangeiro peregrinar contigo, e quiser fazer a páscoa ao SENHOR, seja-lhe circuncidado todo homem, e então se chegará a fazê-la, e será como o natural da terra; mas nenhum incircunciso comerá dela."}, {"numero": 49, "texto": "A mesma lei será para o natural e para o estrangeiro que peregrinar entre vós."}, {"numero": 50, "texto": "Assim o fizeram todos os filhos de Israel; como mandou o SENHOR a Moisés e a Arão, assim o fizeram."}, {"numero": 51, "texto": "E naquele mesmo dia o SENHOR tirou os filhos de Israel da terra do Egito, agrupados em seus esquadrões."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 12, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses and Aaron in the land of Egypt saying,"}, {"numero": 2, "texto": "This month shall be unto you the beginning of months: it shall be the first month of the year to you."}, {"numero": 3, "texto": "Speak ye unto all the congregation of Israel, saying, In the tenth day of this month they shall take to them every man a lamb, according to the house of their fathers, a lamb for an house:"}, {"numero": 4, "texto": "And if the household be too little for the lamb, let him and his neighbour next unto his house take it according to the number of the souls; every man according to his eating shall make your count for the lamb."}, {"numero": 5, "texto": "Your lamb shall be without blemish, a male of the first year: ye shall take it out from the sheep, or from the goats:"}, {"numero": 6, "texto": "And ye shall keep it up until the fourteenth day of the same month: and the whole assembly of the congregation of Israel shall kill it in the evening."}, {"numero": 7, "texto": "And they shall take of the blood, and strike it on the two side posts and on the upper door post of the houses, wherein they shall eat it."}, {"numero": 8, "texto": "And they shall eat the flesh in that night, roast with fire, and unleavened bread; and with bitter herbs they shall eat it."}, {"numero": 9, "texto": "Eat not of it raw, nor sodden at all with water, but roast with fire; his head with his legs, and with the purtenance thereof."}, {"numero": 10, "texto": "And ye shall let nothing of it remain until the morning; and that which remaineth of it until the morning ye shall burn with fire."}, {"numero": 11, "texto": "And thus shall ye eat it; with your loins girded, your shoes on your feet, and your staff in your hand; and ye shall eat it in haste: it is the Lord''s passover."}, {"numero": 12, "texto": "For I will pass through the land of Egypt this night, and will smite all the firstborn in the land of Egypt, both man and beast; and against all the gods of Egypt I will execute judgment: I am the Lord."}, {"numero": 13, "texto": "And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you, when I smite the land of Egypt."}, {"numero": 14, "texto": "And this day shall be unto you for a memorial; and ye shall keep it a feast to the Lord throughout your generations; ye shall keep it a feast by an ordinance for ever."}, {"numero": 15, "texto": "Seven days shall ye eat unleavened bread; even the first day ye shall put away leaven out of your houses: for whosoever eateth leavened bread from the first day until the seventh day, that soul shall be cut off from Israel."}, {"numero": 16, "texto": "And in the first day there shall be an holy convocation, and in the seventh day there shall be an holy convocation to you; no manner of work shall be done in them, save that which every man must eat, that only may be done of you."}, {"numero": 17, "texto": "And ye shall observe the feast of unleavened bread; for in this selfsame day have I brought your armies out of the land of Egypt: therefore shall ye observe this day in your generations by an ordinance for ever."}, {"numero": 18, "texto": "In the first month, on the fourteenth day of the month at even, ye shall eat unleavened bread, until the one and twentieth day of the month at even."}, {"numero": 19, "texto": "Seven days shall there be no leaven found in your houses: for whosoever eateth that which is leavened, even that soul shall be cut off from the congregation of Israel, whether he be a stranger, or born in the land."}, {"numero": 20, "texto": "Ye shall eat nothing leavened; in all your habitations shall ye eat unleavened bread."}, {"numero": 21, "texto": "Then Moses called for all the elders of Israel, and said unto them, Draw out and take you a lamb according to your families, and kill the passover."}, {"numero": 22, "texto": "And ye shall take a bunch of hyssop, and dip it in the blood that is in the bason, and strike the lintel and the two side posts with the blood that is in the bason; and none of you shall go out at the door of his house until the morning."}, {"numero": 23, "texto": "For the Lord will pass through to smite the Egyptians; and when he seeth the blood upon the lintel, and on the two side posts, the Lord will pass over the door, and will not suffer the destroyer to come in unto your houses to smite you."}, {"numero": 24, "texto": "And ye shall observe this thing for an ordinance to thee and to thy sons for ever."}, {"numero": 25, "texto": "And it shall come to pass, when ye be come to the land which the Lord will give you, according as he hath promised, that ye shall keep this service."}, {"numero": 26, "texto": "And it shall come to pass, when your children shall say unto you, What mean ye by this service?"}, {"numero": 27, "texto": "That ye shall say, It is the sacrifice of the Lord''s passover, who passed over the houses of the children of Israel in Egypt, when he smote the Egyptians, and delivered our houses. And the people bowed the head and worshipped."}, {"numero": 28, "texto": "And the children of Israel went away, and did as the Lord had commanded Moses and Aaron, so did they."}, {"numero": 29, "texto": "And it came to pass, that at midnight the Lord smote all the firstborn in the land of Egypt, from the firstborn of Pharaoh that sat on his throne unto the firstborn of the captive that was in the dungeon; and all the firstborn of cattle."}, {"numero": 30, "texto": "And Pharaoh rose up in the night, he, and all his servants, and all the Egyptians; and there was a great cry in Egypt; for there was not a house where there was not one dead."}, {"numero": 31, "texto": "And he called for Moses and Aaron by night, and said, Rise up, and get you forth from among my people, both ye and the children of Israel; and go, serve the Lord, as ye have said."}, {"numero": 32, "texto": "Also take your flocks and your herds, as ye have said, and be gone; and bless me also."}, {"numero": 33, "texto": "And the Egyptians were urgent upon the people, that they might send them out of the land in haste; for they said, We be all dead men."}, {"numero": 34, "texto": "And the people took their dough before it was leavened, their kneadingtroughs being bound up in their clothes upon their shoulders."}, {"numero": 35, "texto": "And the children of Israel did according to the word of Moses; and they borrowed of the Egyptians jewels of silver, and jewels of gold, and raiment:"}, {"numero": 36, "texto": "And the Lord gave the people favour in the sight of the Egyptians, so that they lent unto them such things as they required. And they spoiled the Egyptians."}, {"numero": 37, "texto": "And the children of Israel journeyed from Rameses to Succoth, about six hundred thousand on foot that were men, beside children."}, {"numero": 38, "texto": "And a mixed multitude went up also with them; and flocks, and herds, even very much cattle."}, {"numero": 39, "texto": "And they baked unleavened cakes of the dough which they brought forth out of Egypt, for it was not leavened; because they were thrust out of Egypt, and could not tarry, neither had they prepared for themselves any victual."}, {"numero": 40, "texto": "Now the sojourning of the children of Israel, who dwelt in Egypt, was four hundred and thirty years."}, {"numero": 41, "texto": "And it came to pass at the end of the four hundred and thirty years, even the selfsame day it came to pass, that all the hosts of the Lord went out from the land of Egypt."}, {"numero": 42, "texto": "It is a night to be much observed unto the Lord for bringing them out from the land of Egypt: this is that night of the Lord to be observed of all the children of Israel in their generations."}, {"numero": 43, "texto": "And the Lord said unto Moses and Aaron, This is the ordinance of the passover: There shall no stranger eat thereof:"}, {"numero": 44, "texto": "But every man''s servant that is bought for money, when thou hast circumcised him, then shall he eat thereof."}, {"numero": 45, "texto": "A foreigner and an hired servant shall not eat thereof."}, {"numero": 46, "texto": "In one house shall it be eaten; thou shalt not carry forth ought of the flesh abroad out of the house; neither shall ye break a bone thereof."}, {"numero": 47, "texto": "All the congregation of Israel shall keep it."}, {"numero": 48, "texto": "And when a stranger shall sojourn with thee, and will keep the passover to the Lord, let all his males be circumcised, and then let him come near and keep it; and he shall be as one that is born in the land: for no uncircumcised person shall eat thereof."}, {"numero": 49, "texto": "One law shall be to him that is homeborn, and unto the stranger that sojourneth among you."}, {"numero": 50, "texto": "Thus did all the children of Israel; as the Lord commanded Moses and Aaron, so did they."}, {"numero": 51, "texto": "And it came to pass the selfsame day, that the Lord did bring the children of Israel out of the land of Egypt by their armies."}]'::jsonb, 'King James Version'),
  ('Ex', 12, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse et à Aaron dans le pays d''''Egypte:"}, {"numero": 2, "texto": "Ce mois-ci sera pour vous le premier des mois; il sera pour vous le premier des mois de l''''année."}, {"numero": 3, "texto": "Parlez à toute l''''assemblée d''''Israël, et dites: Le dixième jour de ce mois, on prendra un agneau pour chaque famille, un agneau pour chaque maison."}, {"numero": 4, "texto": "Si la maison est trop peu nombreuse pour un agneau, on le prendra avec son plus proche voisin, selon le nombre des personnes; vous compterez pour cet agneau d''''après ce que chacun peut manger."}, {"numero": 5, "texto": "Ce sera un agneau sans défaut, mâle, âgé d''''un an; vous pourrez prendre un agneau ou un chevreau."}, {"numero": 6, "texto": "Vous le garderez jusqu''''au quatorzième jour de ce mois; et toute l''''assemblée d''''Israël l''''immolera entre les deux soirs."}, {"numero": 7, "texto": "On prendra de son sang, et on en mettra sur les deux poteaux et sur le linteau de la porte des maisons où on le mangera."}, {"numero": 8, "texto": "Cette même nuit, on en mangera la chair, rôtie au feu; on la mangera avec des pains sans levain et des herbes amères."}, {"numero": 9, "texto": "Vous ne le mangerez point à demi cuit et bouilli dans l''''eau; mais il sera rôti au feu, avec la tête, les jambes et l''''intérieur."}, {"numero": 10, "texto": "Vous n''''en laisserez rien jusqu''''au matin; et, s''''il en reste quelque chose le matin, vous le brûlerez au feu."}, {"numero": 11, "texto": "Quand vous le mangerez, vous aurez vos reins ceints, vos souliers aux pieds, et votre bâton à la main; et vous le mangerez à la hâte. C''''est la Pâque de l''''Eternel."}, {"numero": 12, "texto": "Cette nuit-là, je passerai dans le pays d''''Egypte, et je frapperai tous les premiers-nés du pays d''''Egypte, depuis les hommes jusqu''''aux animaux, et j''''exercerai des jugements contre tous les dieux de l''''Egypte. Je suis l''''Eternel."}, {"numero": 13, "texto": "Le sang vous servira de signe sur les maisons où vous serez; je verrai le sang, et je passerai par-dessus vous, et il n''''y aura point de plaie qui vous détruise, quand je frapperai le pays d''''Egypte."}, {"numero": 14, "texto": "Vous conserverez le souvenir de ce jour, et vous le célébrerez par une fête en l''''honneur de l''''Eternel; vous le célébrerez comme une loi perpétuelle pour vos descendants."}, {"numero": 15, "texto": "Pendant sept jours, vous mangerez des pains sans levain. Dès le premier jour, il n''''y aura plus de levain dans vos maisons; car toute personne qui mangera du pain levé, du premier jour au septième jour, sera retranchée d''''Israël."}, {"numero": 16, "texto": "Le premier jour, vous aurez une sainte convocation; et le septième jour, vous aurez une sainte convocation. On ne fera aucun travail ces jours-là; vous pourrez seulement préparer la nourriture de chaque personne."}, {"numero": 17, "texto": "Vous observerez la fête des pains sans levain, car c''''est en ce jour même que j''''aurai fait sortir vos armées du pays d''''Egypte; vous observerez ce jour comme une loi perpétuelle pour vos descendants."}, {"numero": 18, "texto": "Le premier mois, le quatorzième jour du mois, au soir, vous mangerez des pains sans levain jusqu''''au soir du vingt et unième jour."}, {"numero": 19, "texto": "Pendant sept jours, il ne se trouvera point de levain dans vos maisons; car toute personne qui mangera du pain levé sera retranchée de l''''assemblée d''''Israël, que ce soit un étranger ou un indigène."}, {"numero": 20, "texto": "Vous ne mangerez point de pain levé; dans toutes vos demeures, vous mangerez des pains sans levain."}, {"numero": 21, "texto": "Moïse appela tous les anciens d''''Israël, et leur dit: Allez prendre du bétail pour vos familles, et immolez la Pâque."}, {"numero": 22, "texto": "Vous prendrez ensuite un bouquet d''''hysope, vous le tremperez dans le sang qui sera dans le bassin, et vous toucherez le linteau et les deux poteaux de la porte avec le sang qui sera dans le bassin. Nul de vous ne sortira de sa maison jusqu''''au matin."}, {"numero": 23, "texto": "Quand l''''Eternel passera pour frapper l''''Egypte, et verra le sang sur le linteau et sur les deux poteaux, l''''Eternel passera par-dessus la porte, et il ne permettra pas au destructeur d''''entrer dans vos maisons pour frapper."}, {"numero": 24, "texto": "Vous observerez cela comme une loi pour vous et pour vos enfants à perpétuité."}, {"numero": 25, "texto": "Quand vous serez entrés dans le pays que l''''Eternel vous donnera, selon sa promesse, vous observerez cet usage sacré."}, {"numero": 26, "texto": "Et lorsque vos enfants vous diront: Que signifie pour vous cet usage?"}, {"numero": 27, "texto": "vous répondrez: C''''est le sacrifice de Pâque en l''''honneur de l''''Eternel, qui a passé par-dessus les maisons des enfants d''''Israël en Egypte, lorsqu''''il frappa l''''Egypte et qu''''il sauva nos maisons. Le peuple s''''inclina et se prosterna."}, {"numero": 28, "texto": "Et les enfants d''''Israël s''''en allèrent, et firent ce que l''''Eternel avait ordonné à Moïse et à Aaron; ils firent ainsi."}, {"numero": 29, "texto": "Au milieu de la nuit, l''''Eternel frappa tous les premiers-nés dans le pays d''''Egypte, depuis le premier-né de Pharaon assis sur son trône, jusqu''''au premier-né du captif dans sa prison, et jusqu''''à tous les premiers-nés des animaux."}, {"numero": 30, "texto": "Pharaon se leva de nuit, lui et tous ses serviteurs, et tous les Egyptiens; et il y eut de grands cris en Egypte, car il n''''y avait point de maison où il n''''y eût un mort."}, {"numero": 31, "texto": "Dans la nuit même, Pharaon appela Moïse et Aaron, et leur dit: Levez-vous, sortez du milieu de mon peuple, vous et les enfants d''''Israël. Allez, servez l''''Eternel, comme vous l''''avez dit."}, {"numero": 32, "texto": "Prenez vos brebis et vos boeufs, comme vous l''''avez dit; allez, et bénissez-moi."}, {"numero": 33, "texto": "Les Egyptiens pressaient le peuple, et avaient hâte de le renvoyer du pays, car ils disaient: Nous périrons tous."}, {"numero": 34, "texto": "Le peuple emporta sa pâte avant qu''''elle fût levée. Ils enveloppèrent les pétrins dans leurs vêtements, et les mirent sur leurs épaules."}, {"numero": 35, "texto": "Les enfants d''''Israël firent ce que Moïse avait dit, et ils demandèrent aux Egyptiens des vases d''''argent, des vases d''''or et des vêtements."}, {"numero": 36, "texto": "L''''Eternel fit trouver grâce au peuple aux yeux des Egyptiens, qui se rendirent à leur demande. Et ils dépouillèrent les Egyptiens."}, {"numero": 37, "texto": "Les enfants d''''Israël partirent de Ramsès pour Succoth au nombre d''''environ six cent mille hommes de pied, sans les enfants."}, {"numero": 38, "texto": "Une multitude de gens de toute espèce montèrent avec eux; ils avaient aussi des troupeaux considérables de brebis et de boeufs."}, {"numero": 39, "texto": "Ils firent des gâteaux cuits sans levain avec la pâte qu''''ils avaient emportée d''''Egypte, et qui n''''était pas levée; car ils avaient été chassés d''''Egypte, sans pouvoir tarder, et sans prendre des provisions avec eux."}, {"numero": 40, "texto": "Le séjour des enfants d''''Israël en Egypte fut de quatre cent trente ans."}, {"numero": 41, "texto": "Et au bout de quatre cent trente ans, le jour même, toutes les armées de l''''Eternel sortirent du pays d''''Egypte."}, {"numero": 42, "texto": "Cette nuit sera célébrée en l''''honneur de l''''Eternel, parce qu''''il les fit sortir du pays d''''Egypte; cette nuit sera célébrée en l''''honneur de l''''Eternel par tous les enfants d''''Israël et par leurs descendants."}, {"numero": 43, "texto": "L''''Eternel dit à Moïse et à Aaron: Voici une ordonnance au sujet de la Pâque: Aucun étranger n''''en mangera."}, {"numero": 44, "texto": "Tu circonciras tout esclave acquis à prix d''''argent; alors il en mangera."}, {"numero": 45, "texto": "L''''habitant et le mercenaire n''''en mangeront point."}, {"numero": 46, "texto": "On ne la mangera que dans la maison; vous n''''emporterez point de chair hors de la maison, et vous ne briserez aucun os."}, {"numero": 47, "texto": "Toute l''''assemblée d''''Israël fera la Pâque."}, {"numero": 48, "texto": "Si un étranger en séjour chez toi veut faire la Pâque de l''''Eternel, tout mâle de sa maison devra être circoncis; alors il s''''approchera pour la faire, et il sera comme l''''indigène; mais aucun incirconcis n''''en mangera."}, {"numero": 49, "texto": "La même loi existera pour l''''indigène comme pour l''''étranger en séjour au milieu de vous."}, {"numero": 50, "texto": "Tous les enfants d''''Israël firent ce que l''''Eternel avait ordonné à Moïse et à Aaron; ils firent ainsi."}, {"numero": 51, "texto": "Et ce même jour l''''Eternel fit sortir du pays d''''Egypte les enfants d''''Israël, selon leurs armées."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 12, 'es', '[{"numero": 1, "texto": "Y HABLÓ Jehová á Moisés y á Aarón en la tierra de Egipto, diciendo:"}, {"numero": 2, "texto": "Este mes os será principio de los meses; será este para vosotros el primero en los meses del año."}, {"numero": 3, "texto": "Hablad á toda la congregación de Israel, diciendo: En el diez de aqueste mes tómese cada uno un cordero por las familias de los padres, un cordero por familia:"}, {"numero": 4, "texto": "Mas si la familia fuere pequeña que no baste á comer el cordero, entonces tomará á su vecino inmediato á su casa, y según el número de las personas, cada uno conforme á su comer, echaréis la cuenta sobre el cordero."}, {"numero": 5, "texto": "El cordero será sin defecto, macho de un año: tomaréislo de las ovejas ó de las cabras:"}, {"numero": 6, "texto": "Y habéis de guardarlo hasta el día catorce de este mes; y lo inmolará toda la congregación del pueblo de Israel entre las dos tardes."}, {"numero": 7, "texto": "Y tomarán de la sangre, y pondrán en los dos postes y en el dintel de las casas en que lo han de comer."}, {"numero": 8, "texto": "Y aquella noche comerán la carne asada al fuego, y panes sin levadura: con hierbas amargas lo comerán."}, {"numero": 9, "texto": "Ninguna cosa comeréis de él cruda, ni cocida en agua, sino asada al fuego; su cabeza con sus pies y sus intestinos."}, {"numero": 10, "texto": "Ninguna cosa dejaréis de él hasta la mañana; y lo que habrá quedado hasta la mañana, habéis de quemarlo en el fuego."}, {"numero": 11, "texto": "Y así habéis de comerlo: ceñidos vuestros lomos, vuestros zapatos en vuestros pies, y vuestro bordón en vuestra mano; y lo comeréis apresuradamente: es la Pascua de Jehová."}, {"numero": 12, "texto": "Pues yo pasaré aquella noche por la tierra de Egipto, y heriré á todo primogénito en la tierra de Egipto, así en los hombres como en las bestias: y haré juicios en todos los dioses de Egipto. Yo JEHOVÁ."}, {"numero": 13, "texto": "Y la sangre os será por señal en las casas donde vosotros estéis; y veré la sangre, y pasaré de vosotros, y no habrá en vosotros plaga de mortandad, cuando heriré la tierra de Egipto."}, {"numero": 14, "texto": "Y este día os ha de ser en memoria, y habéis de celebrarlo como solemne á Jehová durante vuestras generaciones: por estatuto perpetuo lo celebraréis."}, {"numero": 15, "texto": "Siete días comeréis panes sin levadura; y así el primer día haréis que no haya levadura en vuestras casas: porque cualquiera que comiere leudado desde el primer día hasta el séptimo, aquella alma será cortada de Israel."}, {"numero": 16, "texto": "El primer día habrá santa convocación, y asimismo en el séptimo día tendréis una santa convocación: ninguna obra se hará en ellos, excepto solamente que aderecéis lo que cada cual hubiere de comer."}, {"numero": 17, "texto": "Y guardaréis la fiesta de los ázimos, porque en aqueste mismo día saqué vuestros ejércitos de la tierra de Egipto: por tanto guardaréis este día en vuestras generaciones por costumbre perpetua."}, {"numero": 18, "texto": "En el mes primero, el día catorce del mes por la tarde, comeréis los panes sin levadura, hasta el veintiuno del mes por la tarde."}, {"numero": 19, "texto": "Por siete días no se hallará levadura en vuestras casas, porque cualquiera que comiere leudado, así extranjero como natural del país, aquella alma será cortada de la congregación de Israel."}, {"numero": 20, "texto": "Ninguna cosa leudada comeréis; en todas vuestras habitaciones comeréis panes sin levadura."}, {"numero": 21, "texto": "Y Moisés convocó á todos los ancianos de Israel, y díjoles: Sacad, y tomaos corderos por vuestras familias, y sacrificad la pascua."}, {"numero": 22, "texto": "Y tomad un manojo de hisopo, y mojadle en la sangre que estará en una jofaina, y untad el dintel y los dos postes con la sangre que estará en la jofaina; y ninguno de vosotros salga de las puertas de su casa hasta la mañana."}, {"numero": 23, "texto": "Porque Jehová pasará hiriendo á los Egipcios; y como verá la sangre en el dintel y en los dos postes, pasará Jehová aquella puerta, y no dejará entrar al heridor en vuestras casas para herir."}, {"numero": 24, "texto": "Y guardaréis esto por estatuto para vosotros y para vuestros hijos para siempre."}, {"numero": 25, "texto": "Y será, cuando habréis entrado en la tierra que Jehová os dará, como tiene hablado, que guardaréis este rito."}, {"numero": 26, "texto": "Y cuando os dijeren vuestros hijos: ¿Qué rito es este vuestro?"}, {"numero": 27, "texto": "Vosotros responderéis: Es la víctima de la Pascua de Jehová, el cual pasó las casas de los hijos de Israel en Egipto, cuando hirió á los Egipcios, y libró nuestras casas. Entonces el pueblo se inclinó y adoró."}, {"numero": 28, "texto": "Y los hijos de Israel se fueron, é hicieron puntualmente así; como Jehová había mandado á Moisés y á Aarón."}, {"numero": 29, "texto": "Y aconteció que á la medianoche Jehová hirió á todo primogénito en la tierra de Egipto, desde el primogénito de Faraón que se sentaba sobre su trono, hasta el primogénito del cautivo que estaba en la cárcel, y todo primogénito de los animales."}, {"numero": 30, "texto": "Y levantóse aquella noche Faraón, él y todos sus siervos, y todos los Egipcios; y había un gran clamor en Egipto, porque no había casa donde no hubiese muerto."}, {"numero": 31, "texto": "E hizo llamar á Moisés y á Aarón de noche, y díjoles: Salid de en medio de mi pueblo vosotros, y los hijos de Israel; é id, servid á Jehová, como habéis dicho."}, {"numero": 32, "texto": "Tomad también vuestras ovejas y vuestras vacas, como habéis dicho, é idos; y bendecidme también á mí."}, {"numero": 33, "texto": "Y los Egipcios apremiaban al pueblo, dándose priesa á echarlos de la tierra; porque decían: Todos somos muertos."}, {"numero": 34, "texto": "Y llevó el pueblo su masa antes que se leudase, sus masas envueltas en sus sábanas sobre sus hombros."}, {"numero": 35, "texto": "E hicieron los hijos de Israel conforme al mandamiento de Moisés, demandando á los Egipcios vasos de plata, y vasos de oro, y vestidos."}, {"numero": 36, "texto": "Y Jehová dió gracia al pueblo delante de los Egipcios, y prestáronles; y ellos despojaron á los Egipcios."}, {"numero": 37, "texto": "Y partieron los hijos de Israel de Rameses á Succoth, como seiscientos mil hombres de á pie, sin contar los niños."}, {"numero": 38, "texto": "Y también subió con ellos grande multitud de diversa suerte de gentes; y ovejas, y ganados muy muchos."}, {"numero": 39, "texto": "Y cocieron tortas sin levadura de la masa que habían sacado de Egipto; porque no había leudado, por cuanto echándolos los Egipcios, no habían podido detenerse, ni aun prepararse comida."}, {"numero": 40, "texto": "El tiempo que los hijos de Israel habitaron en Egipto, fué cuatrocientos treinta años."}, {"numero": 41, "texto": "Y pasados cuatrocientos treinta años, en el mismo día salieron todos los ejércitos de Jehová de la tierra de Egipto."}, {"numero": 42, "texto": "Es noche de guardar á Jehová, por haberlos sacado en ella de la tierra de Egipto. Esta noche deben guardar á Jehová todos los hijos de Israel en sus generaciones."}, {"numero": 43, "texto": "Y Jehová dijo á Moisés y á Aarón: Esta es la ordenanza de la Pascua: Ningún extraño comerá de ella:"}, {"numero": 44, "texto": "Mas todo siervo humano comprado por dinero, comerá de ella después que lo hubieres circuncidado."}, {"numero": 45, "texto": "El extranjero y el asalariado no comerán de ella."}, {"numero": 46, "texto": "En una casa se comerá, y no llevarás de aquella carne fuera de casa, ni quebraréis hueso suyo."}, {"numero": 47, "texto": "Toda la congregación de Israel le sacrificará."}, {"numero": 48, "texto": "Mas si algún extranjero peregrinare contigo, y quisiere hacer la pascua á Jehová, séale circuncidado todo varón, y entonces se llegará á hacerla, y será como el natural de la tierra; pero ningún incircunciso comerá de ella."}, {"numero": 49, "texto": "La misma ley será para el natural y para el extranjero que peregrinare entre vosotros."}, {"numero": 50, "texto": "Así lo hicieron todos los hijos de Israel; como mandó Jehová á Moisés y á Aarón, así lo hicieron."}, {"numero": 51, "texto": "Y en aquel mismo día sacó Jehová á los hijos de Israel de la tierra de Egipto por sus escuadrones."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 13, 'pt', '[{"numero": 1, "texto": "E o SENHOR falou a Moisés, dizendo:"}, {"numero": 2, "texto": "Santifica para mim todo primogênito, qualquer um que abre madre entre os filhos de Israel, tanto dos homens como dos animais: meu é."}, {"numero": 3, "texto": "E Moisés disse ao povo: Tende memória deste dia, no qual saístes do Egito, da casa de servidão; pois o SENHOR vos tirou daqui com mão forte; portanto, não comereis levedado."}, {"numero": 4, "texto": "Vós saís hoje no mês de Abibe."}, {"numero": 5, "texto": "E quando o SENHOR te houver posto na terra dos cananeus, e dos heteus, e dos amorreus, e dos heveus, e dos jebuseus, a qual jurou a teus pais que te daria, terra que destila leite e mel, farás este serviço em este mês."}, {"numero": 6, "texto": "Sete dias comerás sem levedar, e o sétimo dia será festa ao SENHOR."}, {"numero": 7, "texto": "Por os sete dias se comerão os pães sem levedura; e não se verá contigo levedado, nem levedura ao todo teu termo."}, {"numero": 8, "texto": "E contarás naquele dia a teu filho, dizendo: Isto se faz por causa do que o SENHOR fez comigo quando me tirou do Egito."}, {"numero": 9, "texto": "E será para ti como um sinal sobre tua mão, e como uma memória diante de teus olhos, para que a lei do SENHOR esteja na tua boca; pois com mão forte te tirou o SENHOR do Egito."}, {"numero": 10, "texto": "Portanto, tu guardarás este rito em seu tempo de ano em ano."}, {"numero": 11, "texto": "E quando o SENHOR te houver posto na terra dos cananeus, como jurou a ti e a teus pais, e quando te a houver dado,"}, {"numero": 12, "texto": "Farás passar ao SENHOR todo o que abrir a madre, também todo primeiro que abrir a madre de teus animais: os machos serão do SENHOR."}, {"numero": 13, "texto": "Mas todo primogênito de asno resgatarás com um cordeiro; e se não o resgatares, o degolarás: também resgatarás todo homem primogênito de teus filhos."}, {"numero": 14, "texto": "E quando amanhã te perguntar teu filho, dizendo: Que é isto? Tu lhe dirás: o SENHOR tirou com mão forte do Egito, de casa de servidão;"}, {"numero": 15, "texto": "E endurecendo-se Faraó em não nos deixar ir, o SENHOR matou na terra do Egito a todo primogênito, desde o primogênito homem até o primogênito do animal; e por esta causa eu sacrifico ao SENHOR todo primogênito macho, e resgato todo primogênito de meus filhos."}, {"numero": 16, "texto": "Será para ti, pois, como um sinal sobre tua mão, e por uma memória diante de teus olhos; já que o SENHOR tirou do Egito com mão forte."}, {"numero": 17, "texto": "E logo que Faraó deixou ir ao povo, Deus não os levou pelo caminho da terra dos filisteus, que estava próxima; porque disse Deus: Que talvez não se arrependa o povo quando virem a guerra, e se voltem ao Egito:"}, {"numero": 18, "texto": "Mas fez Deus ao povo que rodeasse pelo caminho do deserto do mar Vermelho. E subiram os filhos de Israel do Egito armados."}, {"numero": 19, "texto": "Tomou também consigo Moisés os ossos de José, o qual havia juramentado aos filhos de Israel, dizendo: Deus certamente vos visitará, e fareis subir meus ossos daqui convosco."}, {"numero": 20, "texto": "E partidos de Sucote, assentaram acampamento em Etã, à entrada do deserto."}, {"numero": 21, "texto": "E o SENHOR ia diante deles de dia em uma coluna de nuvem, para guiá-los pelo caminho; e de noite em uma coluna de fogo para iluminá-los, a fim de que andassem de dia e de noite."}, {"numero": 22, "texto": "Nunca se partiu de diante do povo a coluna de nuvem de dia, nem de noite a coluna de fogo."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 13, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 2, "texto": "Sanctify unto me all the firstborn, whatsoever openeth the womb among the children of Israel, both of man and of beast: it is mine."}, {"numero": 3, "texto": "And Moses said unto the people, Remember this day, in which ye came out from Egypt, out of the house of bondage; for by strength of hand the Lord brought you out from this place: there shall no leavened bread be eaten."}, {"numero": 4, "texto": "This day came ye out in the month Abib."}, {"numero": 5, "texto": "And it shall be when the Lord shall bring thee into the land of the Canaanites, and the Hittites, and the Amorites, and the Hivites, and the Jebusites, which he sware unto thy fathers to give thee, a land flowing with milk and honey, that thou shalt keep this service in this month."}, {"numero": 6, "texto": "Seven days thou shalt eat unleavened bread, and in the seventh day shall be a feast to the Lord."}, {"numero": 7, "texto": "Unleavened bread shall be eaten seven days; and there shall no leavened bread be seen with thee, neither shall there be leaven seen with thee in all thy quarters."}, {"numero": 8, "texto": "And thou shalt shew thy son in that day, saying, This is done because of that which the Lord did unto me when I came forth out of Egypt."}, {"numero": 9, "texto": "And it shall be for a sign unto thee upon thine hand, and for a memorial between thine eyes, that the Lord''s law may be in thy mouth: for with a strong hand hath the Lord brought thee out of Egypt."}, {"numero": 10, "texto": "Thou shalt therefore keep this ordinance in his season from year to year."}, {"numero": 11, "texto": "And it shall be when the Lord shall bring thee into the land of the Canaanites, as he sware unto thee and to thy fathers, and shall give it thee,"}, {"numero": 12, "texto": "That thou shalt set apart unto the Lord all that openeth the matrix, and every firstling that cometh of a beast which thou hast; the males shall be the Lord''s."}, {"numero": 13, "texto": "And every firstling of an ass thou shalt redeem with a lamb; and if thou wilt not redeem it, then thou shalt break his neck: and all the firstborn of man among thy children shalt thou redeem."}, {"numero": 14, "texto": "And it shall be when thy son asketh thee in time to come, saying, What is this? that thou shalt say unto him, By strength of hand the Lord brought us out from Egypt, from the house of bondage:"}, {"numero": 15, "texto": "And it came to pass, when Pharaoh would hardly let us go, that the Lord slew all the firstborn in the land of Egypt, both the firstborn of man, and the firstborn of beast: therefore I sacrifice to the Lord all that openeth the matrix, being males; but all the firstborn of my children I redeem."}, {"numero": 16, "texto": "And it shall be for a token upon thine hand, and for frontlets between thine eyes: for by strength of hand the Lord brought us forth out of Egypt."}, {"numero": 17, "texto": "And it came to pass, when Pharaoh had let the people go, that God led them not through the way of the land of the Philistines, although that was near; for God said, Lest peradventure the people repent when they see war, and they return to Egypt:"}, {"numero": 18, "texto": "But God led the people about, through the way of the wilderness of the Red sea: and the children of Israel went up harnessed out of the land of Egypt."}, {"numero": 19, "texto": "And Moses took the bones of Joseph with him: for he had straitly sworn the children of Israel, saying, God will surely visit you; and ye shall carry up my bones away hence with you."}, {"numero": 20, "texto": "And they took their journey from Succoth, and encamped in Etham, in the edge of the wilderness."}, {"numero": 21, "texto": "And the Lord went before them by day in a pillar of a cloud, to lead them the way; and by night in a pillar of fire, to give them light; to go by day and night:"}, {"numero": 22, "texto": "He took not away the pillar of the cloud by day, nor the pillar of fire by night, from before the people."}]'::jsonb, 'King James Version'),
  ('Ex', 13, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 2, "texto": "Consacre-moi tout premier-né, tout premier-né parmi les enfants d''''Israël, tant des hommes que des animaux: il m''''appartient."}, {"numero": 3, "texto": "Moïse dit au peuple: Souvenez-vous de ce jour, où vous êtes sortis d''''Egypte, de la maison de servitude; car c''''est par sa main puissante que l''''Eternel vous en a fait sortir. On ne mangera point de pain levé."}, {"numero": 4, "texto": "Vous sortez aujourd''''hui, dans le mois des épis."}, {"numero": 5, "texto": "Quand l''''Eternel t''''aura fait entrer dans le pays des Cananéens, des Héthiens, des Amoréens, des Héviens et des Jébusiens, qu''''il a juré à tes pères de te donner, pays où coulent le lait et le miel, tu rendras ce culte à l''''Eternel dans ce même mois."}, {"numero": 6, "texto": "Pendant sept jours, tu mangeras des pains sans levain; et le septième jour, il y aura une fête en l''''honneur de l''''Eternel."}, {"numero": 7, "texto": "On mangera des pains sans levain pendant les sept jours; on ne verra point chez toi de pain levé, et l''''on ne verra point chez toi de levain, dans toute l''''étendue de ton pays."}, {"numero": 8, "texto": "Tu diras alors à ton fils: C''''est en mémoire de ce que l''''Eternel a fait pour moi, lorsque je suis sorti d''''Egypte."}, {"numero": 9, "texto": "Ce sera pour toi comme un signe sur ta main et comme un souvenir entre tes yeux, afin que la loi de l''''Eternel soit dans ta bouche; car c''''est par sa main puissante que l''''Eternel t''''a fait sortir d''''Egypte."}, {"numero": 10, "texto": "Tu observeras cette ordonnance au temps fixé d''''année en année."}, {"numero": 11, "texto": "Quand l''''Eternel t''''aura fait entrer dans le pays des Cananéens, comme il l''''a juré à toi et à tes pères, et qu''''il te l''''aura donné,"}, {"numero": 12, "texto": "tu consacreras à l''''Eternel tout premier-né, même tout premier-né des animaux que tu auras: les mâles appartiennent à l''''Eternel."}, {"numero": 13, "texto": "Tu rachèteras avec un agneau tout premier-né de l''''âne; et, si tu ne le rachètes pas, tu lui briseras la nuque. Tu rachèteras aussi tout premier-né de l''''homme parmi tes fils."}, {"numero": 14, "texto": "Et lorsque ton fils te demandera un jour: Que signifie cela? tu lui répondras: Par sa main puissante, l''''Eternel nous a fait sortir d''''Egypte, de la maison de servitude;"}, {"numero": 15, "texto": "et, comme Pharaon s''''obstinait à ne point nous laisser aller, l''''Eternel fit mourir tous les premiers-nés dans le pays d''''Egypte, depuis les premiers-nés des hommes jusqu''''aux premiers-nés des animaux. Voilà pourquoi j''''offre en sacrifice à l''''Eternel tout premier-né des mâles, et je rachète tout premier-né de mes fils."}, {"numero": 16, "texto": "Ce sera comme un signe sur ta main et comme des fronteaux entre tes yeux; car c''''est par sa main puissante que l''''Eternel nous a fait sortir d''''Egypte."}, {"numero": 17, "texto": "Lorsque Pharaon laissa aller le peuple, Dieu ne le conduisit point par le chemin du pays des Philistins, quoique le plus proche; car Dieu dit: Le peuple pourrait se repentir en voyant la guerre, et retourner en Egypte."}, {"numero": 18, "texto": "Mais Dieu fit faire au peuple un détour par le chemin du désert, vers la mer Rouge. Les enfants d''''Israël montèrent en armes hors du pays d''''Egypte."}, {"numero": 19, "texto": "Moïse prit avec lui les os de Joseph; car Joseph avait fait jurer les fils d''''Israël, en disant: Dieu vous visitera, et vous ferez remonter avec vous mes os loin d''''ici."}, {"numero": 20, "texto": "Ils partirent de Succoth, et ils campèrent à Etham, à l''''extrémité du désert."}, {"numero": 21, "texto": "L''''Eternel allait devant eux, le jour dans une colonne de nuée pour les guider dans leur chemin, et la nuit dans une colonne de feu pour les éclairer, afin qu''''ils marchassent jour et nuit."}, {"numero": 22, "texto": "La colonne de nuée ne se retirait point de devant le peuple pendant le jour, ni la colonne de feu pendant la nuit."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 13, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ habló á Moisés, diciendo:"}, {"numero": 2, "texto": "Santifícame todo primogénito, cualquiera que abre matriz entre los hijos de Israel, así de los hombres como de los animales: mío es."}, {"numero": 3, "texto": "Y Moisés dijo al pueblo: Tened memoria de aqueste día, en el cual habéis salido de Egipto, de la casa de servidumbre; pues Jehová os ha sacado de aquí con mano fuerte: por tanto, no comeréis leudado."}, {"numero": 4, "texto": "Vosotros salís hoy en el mes de Abib."}, {"numero": 5, "texto": "Y cuando Jehová te hubiere metido en la tierra del Cananeo, y del Hetheo, y del Amorrheo, y del Hebeo, y del Jebuseo, la cual juró á tus padres que te daría, tierra que destila leche y miel, harás este servicio en aqueste mes."}, {"numero": 6, "texto": "Siete días comerás por leudar, y el séptimo día será fiesta á Jehová."}, {"numero": 7, "texto": "Por los siete días se comerán los panes sin levadura; y no se verá contigo leudado, ni levadura en todo tu término."}, {"numero": 8, "texto": "Y contarás en aquel día á tu hijo, diciendo: Hácese esto con motivo de lo que Jehová hizo conmigo cuando me sacó de Egipto."}, {"numero": 9, "texto": "Y serte ha como una señal sobre tu mano, y como una memoria delante de tus ojos, para que la ley de Jehová esté en tu boca; por cuanto con mano fuerte te sacó Jehová de Egipto."}, {"numero": 10, "texto": "Por tanto, tú guardarás este rito en su tiempo de año en año."}, {"numero": 11, "texto": "Y cuando Jehová te hubiere metido en la tierra del Cananeo, como te ha jurado á ti y á tus padres, y cuando te la hubiere dado,"}, {"numero": 12, "texto": "Harás pasar á Jehová todo lo que abriere la matriz, asimismo todo primerizo que abriere la matriz de tus animales: los machos serán de Jehová."}, {"numero": 13, "texto": "Mas todo primogénito de asno redimirás con un cordero; y si no lo redimieres, le degollarás: asimismo redimirás todo humano primogénito de tus hijos."}, {"numero": 14, "texto": "Y cuando mañana te preguntare tu hijo, diciendo: ¿Qué es esto? decirle has: Jehová nos sacó con mano fuerte de Egipto, de casa de servidumbre;"}, {"numero": 15, "texto": "Y endureciéndose Faraón en no dejarnos ir, Jehová mató en la tierra de Egipto á todo primogénito, desde el primogénito humano hasta el primogénito de la bestia: y por esta causa yo sacrifico á Jehová todo primogénito macho, y redimo todo primogénito de mis hijos."}, {"numero": 16, "texto": "Serte ha, pues, como una señal sobre tu mano, y por una memoria delante de tus ojos; ya que Jehová nos sacó de Egipto con mano fuerte."}, {"numero": 17, "texto": "Y luego que Faraón dejó ir al pueblo, Dios no los llevó por el camino de la tierra de los Filisteos, que estaba cerca; porque dijo Dios: Que quizá no se arrepienta el pueblo cuando vieren la guerra, y se vuelvan á Egipto:"}, {"numero": 18, "texto": "Mas hizo Dios al pueblo que rodease por el camino del desierto del mar Bermejo. Y subieron los hijos de Israel de Egipto armados."}, {"numero": 19, "texto": "Tomó también consigo Moisés los huesos de José, el cual había juramentado á los hijos de Israel, diciendo: Dios ciertamente os visitará, y haréis subir mis huesos de aquí con vosotros."}, {"numero": 20, "texto": "Y partidos de Succoth, asentaron campo en Etham, á la entrada del desierto."}, {"numero": 21, "texto": "Y Jehová iba delante de ellos de día en una columna de nube, para guiarlos por el camino; y de noche en una columna de fuego para alumbrarles; á fin de que anduviesen de día y de noche."}, {"numero": 22, "texto": "Nunca se partió de delante del pueblo la columna de nube de día, ni de noche la columna de fuego."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 14, 'pt', '[{"numero": 1, "texto": "E falou o SENHOR a Moisés, dizendo:"}, {"numero": 2, "texto": "Fala aos filhos de Israel que deem a volta, e assentem seu acampamento diante de Pi-Hairote, entre Migdol e o mar até Baal-Zefom: diante dele assentareis o campo, junto ao mar."}, {"numero": 3, "texto": "Porque Faraó dirá dos filhos de Israel: Estão andando confusos na terra, o deserto os encurralou."}, {"numero": 4, "texto": "E eu endurecerei o coração de Faraó para que os siga; e serei glorificado em Faraó e em todo o seu exército; e saberão os egípcios que eu sou o SENHOR. E eles o fizeram assim."}, {"numero": 5, "texto": "E foi dado aviso ao rei do Egito como o povo se fugia: e o coração de Faraó e de seus servos se voltou contra o povo, e disseram: Como fizemos isto de haver deixado ir a Israel, para que não nos sirva?"}, {"numero": 6, "texto": "E preparou seu carro, e tomou consigo seu povo;"}, {"numero": 7, "texto": "e tomou seiscentos carros escolhidos, e todos os carros do Egito, e os capitães sobre eles."}, {"numero": 8, "texto": "E endureceu o SENHOR o coração de Faraó rei do Egito, e seguiu aos filhos de Israel; mas os filhos de Israel haviam saído com mão poderosa."}, {"numero": 9, "texto": "Seguindo-os, pois, os egípcios, com toda a cavalaria e carros de Faraó, seus cavaleiros, e todo seu exército, alcançaram-nos assentando o acampamento junto ao mar, ao lado de Pi-Hairote, diante de Baal-Zefom."}, {"numero": 10, "texto": "E quando Faraó se aproximou, os filhos de Israel levantaram seus olhos, e eis que os egípcios vinham atrás deles; por isso temeram muito, e os filhos de Israel clamaram ao SENHOR."}, {"numero": 11, "texto": "E disseram a Moisés: Não havia sepulcros no Egito, que nos tiraste para morrermos no deserto? Por que o fizeste assim conosco, que nos tiraste do Egito?"}, {"numero": 12, "texto": "Não é isto o que te falamos no Egito, dizendo: Deixa-nos servir aos egípcios? Pois melhor nos teria sido servir aos egípcios, que morrermos no deserto."}, {"numero": 13, "texto": "E Moisés disse ao povo: Não temais; ficai quietos, e vede a salvação do SENHOR, que ele fará hoje convosco; porque os egípcios que hoje vistes, nunca mais para sempre os vereis."}, {"numero": 14, "texto": "O SENHOR lutará por vós, e vós ficai quietos."}, {"numero": 15, "texto": "Então o SENHOR disse a Moisés: “Por que clamas a mim? Diz aos filhos de Israel que marchem."}, {"numero": 16, "texto": "Quanto a ti, ergue a tua vara, estende a tua mão sobre o mar, e divide-o. Que os filhos de Israel entre por meio do mar em seco."}, {"numero": 17, "texto": "E eu, eis que endurecerei o coração dos egípcios, para que os sigam. E eu me glorificarei em Faraó, e em todo o seu exército, e em suas carruagens, e em sua cavalaria;"}, {"numero": 18, "texto": "E os egípcios saberão que eu sou o SENHOR, quando eu me glorificar em Faraó, em seus carros, e em seus cavaleiros.”"}, {"numero": 19, "texto": "E o anjo de Deus que ia diante do acampamento de Israel, se separou, e ia detrás deles; e também a coluna de nuvem que ia diante deles, separou-se, e pôs-se atrás deles;"}, {"numero": 20, "texto": "e ia entre o acampamento dos egípcios e o acampamento de Israel; e era nuvem e trevas para aqueles, e iluminava a Israel de noite; e em toda aquela noite não se aproximaram uns dos outros."}, {"numero": 21, "texto": "E estendeu Moisés sua mão sobre o mar, e fez o SENHOR que o mar se retirasse por forte vento oriental toda aquela noite; e tornou o mar em seco, e as águas restaram divididas."}, {"numero": 22, "texto": "Então os filhos de Israel entraram por meio do mar em seco, tendo as águas como muro à sua direita e à sua esquerda;"}, {"numero": 23, "texto": "E seguindo-os os egípcios, entraram atrás deles até o meio do mar, toda a cavalaria de Faraó, seus carros, e seus cavaleiros."}, {"numero": 24, "texto": "E aconteceu à vigília da manhã, que o SENHOR olhou ao campo dos egípcios desde a coluna de fogo e nuvem, e perturbou o acampamento dos egípcios."}, {"numero": 25, "texto": "E tirou-lhes as rodas de seus carros, e transtornou-os gravemente. Então os egípcios disseram: Fujamos de diante de Israel, porque o SENHOR luta por eles contra os egípcios."}, {"numero": 26, "texto": "E o SENHOR disse a Moisés: Estende tua mão sobre o mar, para que as águas voltem sobre os egípcios, sobre seus carros, e sobre sua cavalaria."}, {"numero": 27, "texto": "E Moisés estendeu sua mão sobre o mar, e o mar se voltou em sua força quando amanhecia; e os egípcios iam até ela: e o SENHOR derrubou aos egípcios em meio do mar."}, {"numero": 28, "texto": "E voltaram as águas, e cobriram os carros e a cavalaria, e todo o exército de Faraó que havia entrado atrás eles no mar; não restou deles nenhum."}, {"numero": 29, "texto": "E os filhos de Israel foram por meio do mar em seco, tendo as águas por muro à sua direita e à sua esquerda."}, {"numero": 30, "texto": "Assim salvou o SENHOR aquele dia a Israel da mão dos egípcios; e Israel viu aos egípcios mortos à beira do mar."}, {"numero": 31, "texto": "E viu Israel aquele grande feito que o SENHOR executou contra os egípcios: e o povo temeu ao SENHOR, e creram no SENHOR e em Moisés seu servo."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 14, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 2, "texto": "Speak unto the children of Israel, that they turn and encamp before Pihahiroth, between Migdol and the sea, over against Baalzephon: before it shall ye encamp by the sea."}, {"numero": 3, "texto": "For Pharaoh will say of the children of Israel, They are entangled in the land, the wilderness hath shut them in."}, {"numero": 4, "texto": "And I will harden Pharaoh''s heart, that he shall follow after them; and I will be honoured upon Pharaoh, and upon all his host; that the Egyptians may know that I am the Lord. And they did so."}, {"numero": 5, "texto": "And it was told the king of Egypt that the people fled: and the heart of Pharaoh and of his servants was turned against the people, and they said, Why have we done this, that we have let Israel go from serving us?"}, {"numero": 6, "texto": "And he made ready his chariot, and took his people with him:"}, {"numero": 7, "texto": "And he took six hundred chosen chariots, and all the chariots of Egypt, and captains over every one of them."}, {"numero": 8, "texto": "And the Lord hardened the heart of Pharaoh king of Egypt, and he pursued after the children of Israel: and the children of Israel went out with an high hand."}, {"numero": 9, "texto": "But the Egyptians pursued after them, all the horses and chariots of Pharaoh, and his horsemen, and his army, and overtook them encamping by the sea, beside Pihahiroth, before Baalzephon."}, {"numero": 10, "texto": "And when Pharaoh drew nigh, the children of Israel lifted up their eyes, and, behold, the Egyptians marched after them; and they were sore afraid: and the children of Israel cried out unto the Lord."}, {"numero": 11, "texto": "And they said unto Moses, Because there were no graves in Egypt, hast thou taken us away to die in the wilderness? wherefore hast thou dealt thus with us, to carry us forth out of Egypt?"}, {"numero": 12, "texto": "Is not this the word that we did tell thee in Egypt, saying, Let us alone, that we may serve the Egyptians? For it had been better for us to serve the Egyptians, than that we should die in the wilderness."}, {"numero": 13, "texto": "And Moses said unto the people, Fear ye not, stand still, and see the salvation of the Lord, which he will shew to you to day: for the Egyptians whom ye have seen to day, ye shall see them again no more for ever."}, {"numero": 14, "texto": "The Lord shall fight for you, and ye shall hold your peace."}, {"numero": 15, "texto": "And the Lord said unto Moses, Wherefore criest thou unto me? speak unto the children of Israel, that they go forward:"}, {"numero": 16, "texto": "But lift thou up thy rod, and stretch out thine hand over the sea, and divide it: and the children of Israel shall go on dry ground through the midst of the sea."}, {"numero": 17, "texto": "And I, behold, I will harden the hearts of the Egyptians, and they shall follow them: and I will get me honour upon Pharaoh, and upon all his host, upon his chariots, and upon his horsemen."}, {"numero": 18, "texto": "And the Egyptians shall know that I am the Lord, when I have gotten me honour upon Pharaoh, upon his chariots, and upon his horsemen."}, {"numero": 19, "texto": "And the angel of God, which went before the camp of Israel, removed and went behind them; and the pillar of the cloud went from before their face, and stood behind them:"}, {"numero": 20, "texto": "And it came between the camp of the Egyptians and the camp of Israel; and it was a cloud and darkness to them, but it gave light by night to these: so that the one came not near the other all the night."}, {"numero": 21, "texto": "And Moses stretched out his hand over the sea; and the Lord caused the sea to go back by a strong east wind all that night, and made the sea dry land, and the waters were divided."}, {"numero": 22, "texto": "And the children of Israel went into the midst of the sea upon the dry ground: and the waters were a wall unto them on their right hand, and on their left."}, {"numero": 23, "texto": "And the Egyptians pursued, and went in after them to the midst of the sea, even all Pharaoh''s horses, his chariots, and his horsemen."}, {"numero": 24, "texto": "And it came to pass, that in the morning watch the Lord looked unto the host of the Egyptians through the pillar of fire and of the cloud, and troubled the host of the Egyptians,"}, {"numero": 25, "texto": "And took off their chariot wheels, that they drave them heavily: so that the Egyptians said, Let us flee from the face of Israel; for the Lord fighteth for them against the Egyptians."}, {"numero": 26, "texto": "And the Lord said unto Moses, Stretch out thine hand over the sea, that the waters may come again upon the Egyptians, upon their chariots, and upon their horsemen."}, {"numero": 27, "texto": "And Moses stretched forth his hand over the sea, and the sea returned to his strength when the morning appeared; and the Egyptians fled against it; and the Lord overthrew the Egyptians in the midst of the sea."}, {"numero": 28, "texto": "And the waters returned, and covered the chariots, and the horsemen, and all the host of Pharaoh that came into the sea after them; there remained not so much as one of them."}, {"numero": 29, "texto": "But the children of Israel walked upon dry land in the midst of the sea; and the waters were a wall unto them on their right hand, and on their left."}, {"numero": 30, "texto": "Thus the Lord saved Israel that day out of the hand of the Egyptians; and Israel saw the Egyptians dead upon the sea shore."}, {"numero": 31, "texto": "And Israel saw that great work which the Lord did upon the Egyptians: and the people feared the Lord, and believed the Lord, and his servant Moses."}]'::jsonb, 'King James Version'),
  ('Ex', 14, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 2, "texto": "Parle aux enfants d''''Israël; qu''''ils se détournent, et qu''''ils campent devant Pi-Hahiroth, entre Migdol et la mer, vis-à-vis de Baal-Tsephon; c''''est en face de ce lieu que vous camperez, près de la mer."}, {"numero": 3, "texto": "Pharaon dira des enfants d''''Israël: Ils sont égarés dans le pays; le désert les enferme."}, {"numero": 4, "texto": "J''''endurcirai le coeur de Pharaon, et il les poursuivra; mais Pharaon et toute son armée serviront à faire éclater ma gloire, et les Egyptiens sauront que je suis l''''Eternel. Et les enfants d''''Israël firent ainsi."}, {"numero": 5, "texto": "On annonça au roi d''''Egypte que le peuple avait pris la fuite. Alors le coeur de Pharaon et celui de ses serviteurs furent changés à l''''égard du peuple. Ils dirent: Qu''''avons-nous fait, en laissant aller Israël, dont nous n''''aurons plus les services?"}, {"numero": 6, "texto": "Et Pharaon attela son char, et il prit son peuple avec lui."}, {"numero": 7, "texto": "Il prit six cents chars d''''élite, et tous les chars de l''''Egypte; il y avait sur tous des combattants."}, {"numero": 8, "texto": "L''''Eternel endurcit le coeur de Pharaon, roi d''''Egypte, et Pharaon poursuivit les enfants d''''Israël. Les enfants d''''Israël étaient sortis la main levée."}, {"numero": 9, "texto": "Les Egyptiens les poursuivirent; et tous les chevaux, les chars de Pharaon, ses cavaliers et son armée, les atteignirent campés près de la mer, vers Pi-Hahiroth, vis-à-vis de Baal-Tsephon."}, {"numero": 10, "texto": "Pharaon approchait. Les enfants d''''Israël levèrent les yeux, et voici, les Egyptiens étaient en marche derrière eux. Et les enfants d''''Israël eurent une grande frayeur, et crièrent à l''''Eternel."}, {"numero": 11, "texto": "Ils dirent à Moïse: N''''y avait-il pas des sépulcres en Egypte, sans qu''''il fût besoin de nous mener mourir au désert? Que nous as-tu fait en nous faisant sortir d''''Egypte?"}, {"numero": 12, "texto": "N''''est-ce pas là ce que nous te disions en Egypte: Laisse-nous servir les Egyptiens, car nous aimons mieux servir les Egyptiens que de mourir au désert?"}, {"numero": 13, "texto": "Moïse répondit au peuple: Ne craignez rien, restez en place, et regardez la délivrance que l''''Eternel va vous accorder en ce jour; car les Egyptiens que vous voyez aujourd''''hui, vous ne les verrez plus jamais."}, {"numero": 14, "texto": "L''''Eternel combattra pour vous; et vous, gardez le silence."}, {"numero": 15, "texto": "L''''Eternel dit à Moïse: Pourquoi ces cris? Parle aux enfants d''''Israël, et qu''''ils marchent."}, {"numero": 16, "texto": "Toi, lève ta verge, étends ta main sur la mer, et fends-la; et les enfants d''''Israël entreront au milieu de la mer à sec."}, {"numero": 17, "texto": "Et moi, je vais endurcir le coeur des Egyptiens, pour qu''''ils y entrent après eux: et Pharaon et toute son armée, ses chars et ses cavaliers, feront éclater ma gloire."}, {"numero": 18, "texto": "Et les Egyptiens sauront que je suis l''''Eternel, quand Pharaon, ses chars et ses cavaliers, auront fait éclater ma gloire."}, {"numero": 19, "texto": "L''''ange de Dieu, qui allait devant le camp d''''Israël, partit et alla derrière eux; et la colonne de nuée qui les précédait, partit et se tint derrière eux."}, {"numero": 20, "texto": "Elle se plaça entre le camp des Egyptiens et le camp d''''Israël. Cette nuée était ténébreuse d''''un côté, et de l''''autre elle éclairait la nuit. Et les deux camps n''''approchèrent point l''''un de l''''autre pendant toute la nuit."}, {"numero": 21, "texto": "Moïse étendit sa main sur la mer. Et l''''Eternel refoula la mer par un vent d''''orient, qui souffla avec impétuosité toute la nuit; il mit la mer à sec, et les eaux se fendirent."}, {"numero": 22, "texto": "Les enfants d''''Israël entrèrent au milieu de la mer à sec, et les eaux formaient comme une muraille à leur droite et à leur gauche."}, {"numero": 23, "texto": "Les Egyptiens les poursuivirent; et tous les chevaux de Pharaon, ses chars et ses cavaliers, entrèrent après eux au milieu de la mer."}, {"numero": 24, "texto": "A la veille du matin, l''''Eternel, de la colonne de feu et de nuée, regarda le camp des Egyptiens, et mit en désordre le camp des Egyptiens."}, {"numero": 25, "texto": "Il ôta les roues de leurs chars et en rendit la marche difficile. Les Egyptiens dirent alors: Fuyons devant Israël, car l''''Eternel combat pour lui contre les Egyptiens."}, {"numero": 26, "texto": "L''''Eternel dit à Moïse: Etends ta main sur la mer; et les eaux reviendront sur les Egyptiens, sur leurs chars et sur leurs cavaliers."}, {"numero": 27, "texto": "Moïse étendit sa main sur la mer. Et vers le matin, la mer reprit son impétuosité, et les Egyptiens s''''enfuirent à son approche; mais l''''Eternel précipita les Egyptiens au milieu de la mer."}, {"numero": 28, "texto": "Les eaux revinrent, et couvrirent les chars, les cavaliers et toute l''''armée de Pharaon, qui étaient entrés dans la mer après les enfants d''''Israël; et il n''''en échappa pas un seul."}, {"numero": 29, "texto": "Mais les enfants d''''Israël marchèrent à sec au milieu de la mer, et les eaux formaient comme une muraille à leur droite et à leur gauche."}, {"numero": 30, "texto": "En ce jour, l''''Eternel délivra Israël de la main des Egyptiens; et Israël vit sur le rivage de la mer les Egyptiens qui étaient morts."}, {"numero": 31, "texto": "Israël vit la main puissante que l''''Eternel avait dirigée contre les Egyptiens. Et le peuple craignit l''''Eternel, et il crut en l''''Eternel et en Moïse, son serviteur."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 14, 'es', '[{"numero": 1, "texto": "Y HABLÓ Jehová á Moisés, diciendo:"}, {"numero": 2, "texto": "Habla á los hijos de Israel que den la vuelta, y asienten su campo delante de Pihahiroth, entre Migdol y la mar hacia Baalzephón: delante de él asentaréis el campo, junto á la mar."}, {"numero": 3, "texto": "Porque Faraón dirá de los hijos de Israel: Encerrados están en la tierra, el desierto los ha encerrado."}, {"numero": 4, "texto": "Y yo endureceré el corazón de Faraón para que los siga; y seré glorificado en Faraón y en todo su ejército; y sabrán los Egipcios que yo soy Jehová. Y ellos lo hicieron así."}, {"numero": 5, "texto": "Y fué dado aviso al rey de Egipto cómo el pueblo se huía: y el corazón de Faraón y de sus siervos se volvió contra el pueblo, y dijeron: ¿Cómo hemos hecho esto de haber dejado ir á Israel, para que no nos sirva?"}, {"numero": 6, "texto": "Y unció su carro, y tomó consigo su pueblo;"}, {"numero": 7, "texto": "Y tomó seiscientos carros escogidos, y todos los carros de Egipto, y los capitanes sobre ellos."}, {"numero": 8, "texto": "Y endureció Jehová el corazón de Faraón rey de Egipto, y siguió á los hijos de Israel; pero los hijos de Israel habían salido con mano poderosa."}, {"numero": 9, "texto": "Siguiéndolos, pues, los Egipcios, con toda la caballería y carros de Faraón, su gente de á caballo, y todo su ejército, alcanzáronlos asentando el campo junto á la mar, al lado de Pihahiroth, delante de Baalzephón."}, {"numero": 10, "texto": "Y cuando Faraón se hubo acercado, los hijos de Israel alzaron sus ojos, y he aquí los Egipcios que venían tras ellos; por lo que temieron en gran manera, y clamaron los hijos de Israel á Jehová."}, {"numero": 11, "texto": "Y dijeron á Moisés: ¿No había sepulcros en Egipto, que nos has sacado para que muramos en el desierto? ¿Por qué lo has hecho así con nosotros, que nos has sacado de Egipto?"}, {"numero": 12, "texto": "¿No es esto lo que te hablamos en Egipto, diciendo: Déjanos servir á los Egipcios? Que mejor nos fuera servir á los Egipcios, que morir nosotros en el desierto."}, {"numero": 13, "texto": "Y Moisés dijo al pueblo: No temáis; estáos quedos, y ved la salud de Jehová, que él hará hoy con vosotros; porque los Egipcios que hoy habéis visto, nunca más para siempre los veréis."}, {"numero": 14, "texto": "Jehová peleará por vosotros, y vosotros estaréis quedos."}, {"numero": 15, "texto": "Entonces Jehová dijo á Moisés: ¿Por qué clamas á mí? di á los hijos de Israel que marchen:"}, {"numero": 16, "texto": "Y tú alza tu vara, y extiende tu mano sobre la mar, y divídela; y entren los hijos de Israel por medio de la mar en seco."}, {"numero": 17, "texto": "Y yo, he aquí yo endureceré el corazón de los Egipcios, para que los sigan: y yo me glorificaré en Faraón, y en todo su ejército, y en sus carros, y en su caballería;"}, {"numero": 18, "texto": "Y sabrán los Egipcios que yo soy Jehová, cuando me glorificaré en Faraón, en sus carros, y en su gente de á caballo."}, {"numero": 19, "texto": "Y el ángel de Dios que iba delante del campo de Israel, se apartó, é iba en pos de ellos; y asimismo la columna de nube que iba delante de ellos, se apartó, y púsose á sus espaldas:"}, {"numero": 20, "texto": "E iba entre el campo de los Egipcios y el campo de Israel; y era nube y tinieblas para aquéllos, y alumbraba á Israel de noche: y en toda aquella noche nunca llegaron los unos á los otros."}, {"numero": 21, "texto": "Y extendió Moisés su mano sobre la mar, é hizo Jehová que la mar se retirase por recio viento oriental toda aquella noche; y tornó la mar en seco, y las aguas quedaron divididas."}, {"numero": 22, "texto": "Entonces los hijos de Israel entraron por medio de la mar en seco, teniendo las aguas como muro á su diestra y á su siniestra:"}, {"numero": 23, "texto": "Y siguiéndolos los Egipcios, entraron tras ellos hasta el medio de la mar, toda la caballería de Faraón, sus carros, y su gente de á caballo."}, {"numero": 24, "texto": "Y aconteció á la vela de la mañana, que Jehová miró al campo de los Egipcios desde la columna de fuego y nube, y perturbó el campo de los Egipcios."}, {"numero": 25, "texto": "Y quitóles las ruedas de sus carros, y trastornólos gravemente. Entonces los Egipcios dijeron: Huyamos de delante de Israel, porque Jehová pelea por ellos contra los Egipcios."}, {"numero": 26, "texto": "Y Jehová dijo á Moisés: Extiende tu mano sobre la mar, para que las aguas vuelvan sobre los Egipcios, sobre sus carros, y sobre su caballería."}, {"numero": 27, "texto": "Y Moisés extendió su mano sobre la mar, y la mar se volvió en su fuerza cuando amanecía; y los Egipcios iban hacia ella: y Jehová derribó á los Egipcios en medio de la mar."}, {"numero": 28, "texto": "Y volvieron las aguas, y cubrieron los carros y la caballería, y todo el ejército de Faraón que había entrado tras ellos en la mar; no quedó de ellos ni uno."}, {"numero": 29, "texto": "Y los hijos de Israel fueron por medio de la mar en seco, teniendo las aguas por muro á su diestra y á su siniestra."}, {"numero": 30, "texto": "Así salvó Jehová aquel día á Israel de mano de los Egipcios; é Israel vió á los Egipcios muertos á la orilla de la mar."}, {"numero": 31, "texto": "Y vió Israel aquel grande hecho que Jehová ejecutó contra los Egipcios: y el pueblo temió á Jehová, y creyeron á Jehová y á Moisés su siervo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 15, 'pt', '[{"numero": 1, "texto": "Então cantou Moisés e os filhos de Israel este cântico ao SENHOR, e disseram: Cantarei eu ao SENHOR, porque se triunfou grandemente, Lançando no mar ao cavalo e ao que nele subia."}, {"numero": 2, "texto": "O SENHOR é minha força, e minha canção, E foi-me por salvação: Este é meu Deus, e a este engrandecerei; Deus de meu pai, e a este exaltarei."}, {"numero": 3, "texto": "O SENHOR, homem de guerra; o SENHOR é seu nome."}, {"numero": 4, "texto": "Os carros de Faraó e a seu exército lançou no mar; E seus escolhidos príncipes foram afundados no mar Vermelho."}, {"numero": 5, "texto": "Os abismos os cobriram; Como pedra desceram aos profundos."}, {"numero": 6, "texto": "Tua mão direita, ó SENHOR, foi engrandecida em força; Tua mão direita, ó SENHOR, quebrantou ao inimigo."}, {"numero": 7, "texto": "E com a grandeza de tua poder transtornaste aos que se levantaram contra ti: Enviaste teu furor; os tragou como o restolho."}, {"numero": 8, "texto": "Com o sopro de tuas narinas se amontoaram as águas; Pararam-se as correntezas como em um amontoado; Os abismos se solidificaram em meio do mar."}, {"numero": 9, "texto": "O inimigo disse: Perseguirei, prenderei, repartirei despojos; Minha alma se encherá deles; Tirarei minha espada, minha mão os destruirá."}, {"numero": 10, "texto": "Sopraste com teu vento, cobriu-os o mar: Afundaram-se como chumbo nas impetuosas águas."}, {"numero": 11, "texto": "Quem como tu, SENHOR, entre os deuses? Quem como tu, magnífico em santidade, Terrível em louvores, autor de maravilhas?"}, {"numero": 12, "texto": "Estendeste a tua mão direita; a terra os tragou."}, {"numero": 13, "texto": "Conduziste em tua misericórdia a este povo, ao qual salvaste; Levaste-o com tua força à habitação de teu santuário."}, {"numero": 14, "texto": "Ouviram-no os povos, e tremerão; Dor se apoderará dos moradores da filístia."}, {"numero": 15, "texto": "Então os príncipes de Edom se perturbarão; Aos robustos de Moabe os ocupará tremor; Todos os moradores de Canaã se abaterão."}, {"numero": 16, "texto": "Caia sobre eles tremor e espanto; À grandeza de teu braço emudeçam como uma pedra; Até que tenha passado teu povo, ó SENHOR, Até que tenha passado este povo que tu resgataste."}, {"numero": 17, "texto": "Tu os introduzirás e os plantarás no monte de tua herança, No lugar de tua morada, que tu preparaste, ó SENHOR; No santuário do Senhor, que firmaram tuas mãos."}, {"numero": 18, "texto": "O SENHOR reinará pelos séculos dos séculos."}, {"numero": 19, "texto": "Porque Faraó entrou cavalgando com seus carros e seus cavaleiros no mar, e o SENHOR voltou a trazer as águas do mar sobre eles; mas os filhos de Israel foram a seco por meio do mar."}, {"numero": 20, "texto": "E Miriã a profetisa, irmã de Arão, tomou um pandeiro em sua mão, e todas as mulheres saíram atrás dela com pandeiros e danças."}, {"numero": 21, "texto": "E Miriã lhes respondia: Cantai ao SENHOR; porque em extremo se engrandeceu, Lançando no mar ao cavalo, e ao que nele subia."}, {"numero": 22, "texto": "E fez Moisés que partisse Israel do mar Vermelho, e saíram ao deserto de Sur; e andaram três dias pelo deserto sem achar água."}, {"numero": 23, "texto": "E chegaram a Mara, e não puderam beber as águas de Mara, porque eram amargas; por isso lhe puseram o nome de Mara."}, {"numero": 24, "texto": "Então o povo murmurou contra Moisés, e disse: Que beberemos?"}, {"numero": 25, "texto": "E Moisés clamou ao SENHOR; e o SENHOR lhe mostrou uma árvore, a qual quando a meteu dentro das águas, as águas se tornaram doces. Ali lhes deu estatutos e ordenanças, e ali os provou;"}, {"numero": 26, "texto": "E disse: Se ouvires atentamente a voz do SENHOR teu Deus, e fizeres o correto diante de seus olhos, e deres ouvido a seus mandamentos, e guardares todos os seus estatutos, nenhuma enfermidade das que enviei aos egípcios te enviarei a ti; porque eu sou o SENHOR que te sara."}, {"numero": 27, "texto": "E chegaram a Elim, onde havia doze fontes de águas, e setenta palmeiras; e assentaram ali junto às águas."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 15, 'en', '[{"numero": 1, "texto": "Then sang Moses and the children of Israel this song unto the Lord, and spake, saying, I will sing unto the Lord, for he hath triumphed gloriously: the horse and his rider hath he thrown into the sea."}, {"numero": 2, "texto": "The Lord is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father''s God, and I will exalt him."}, {"numero": 3, "texto": "The Lord is a man of war: the Lord is his name."}, {"numero": 4, "texto": "Pharaoh''s chariots and his host hath he cast into the sea: his chosen captains also are drowned in the Red sea."}, {"numero": 5, "texto": "The depths have covered them: they sank into the bottom as a stone."}, {"numero": 6, "texto": "Thy right hand, O Lord, is become glorious in power: thy right hand, O Lord, hath dashed in pieces the enemy."}, {"numero": 7, "texto": "And in the greatness of thine excellency thou hast overthrown them that rose up against thee: thou sentest forth thy wrath, which consumed them as stubble."}, {"numero": 8, "texto": "And with the blast of thy nostrils the waters were gathered together, the floods stood upright as an heap, and the depths were congealed in the heart of the sea."}, {"numero": 9, "texto": "The enemy said, I will pursue, I will overtake, I will divide the spoil; my lust shall be satisfied upon them; I will draw my sword, my hand shall destroy them."}, {"numero": 10, "texto": "Thou didst blow with thy wind, the sea covered them: they sank as lead in the mighty waters."}, {"numero": 11, "texto": "Who is like unto thee, O Lord, among the gods? who is like thee, glorious in holiness, fearful in praises, doing wonders?"}, {"numero": 12, "texto": "Thou stretchedst out thy right hand, the earth swallowed them."}, {"numero": 13, "texto": "Thou in thy mercy hast led forth the people which thou hast redeemed: thou hast guided them in thy strength unto thy holy habitation."}, {"numero": 14, "texto": "The people shall hear, and be afraid: sorrow shall take hold on the inhabitants of Palestina."}, {"numero": 15, "texto": "Then the dukes of Edom shall be amazed; the mighty men of Moab, trembling shall take hold upon them; all the inhabitants of Canaan shall melt away."}, {"numero": 16, "texto": "Fear and dread shall fall upon them; by the greatness of thine arm they shall be as still as a stone; till thy people pass over, O Lord, till the people pass over, which thou hast purchased."}, {"numero": 17, "texto": "Thou shalt bring them in, and plant them in the mountain of thine inheritance, in the place, O Lord, which thou hast made for thee to dwell in, in the Sanctuary, O Lord, which thy hands have established."}, {"numero": 18, "texto": "The Lord shall reign for ever and ever."}, {"numero": 19, "texto": "For the horse of Pharaoh went in with his chariots and with his horsemen into the sea, and the Lord brought again the waters of the sea upon them; but the children of Israel went on dry land in the midst of the sea."}, {"numero": 20, "texto": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}, {"numero": 21, "texto": "And Miriam answered them, Sing ye to the Lord, for he hath triumphed gloriously; the horse and his rider hath he thrown into the sea."}, {"numero": 22, "texto": "So Moses brought Israel from the Red sea, and they went out into the wilderness of Shur; and they went three days in the wilderness, and found no water."}, {"numero": 23, "texto": "And when they came to Marah, they could not drink of the waters of Marah, for they were bitter: therefore the name of it was called Marah."}, {"numero": 24, "texto": "And the people murmured against Moses, saying, What shall we drink?"}, {"numero": 25, "texto": "And he cried unto the Lord; and the Lord shewed him a tree, which when he had cast into the waters, the waters were made sweet: there he made for them a statute and an ordinance, and there he proved them,"}, {"numero": 26, "texto": "And said, If thou wilt diligently hearken to the voice of the Lord thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the Lord that healeth thee."}, {"numero": 27, "texto": "And they came to Elim, where were twelve wells of water, and threescore and ten palm trees: and they encamped there by the waters."}]'::jsonb, 'King James Version'),
  ('Ex', 15, 'fr', '[{"numero": 1, "texto": "Alors Moïse et les enfants d''''Israël chantèrent ce cantique à l''''Eternel. Ils dirent: Je chanterai à l''''Eternel, car il a fait éclater sa gloire; Il a précipité dans la mer le cheval et son cavalier."}, {"numero": 2, "texto": "L''''Eternel est ma force et le sujet de mes louanges; C''''est lui qui m''''a sauvé. Il est mon Dieu: je le célèbrerai; Il est le Dieu de mon père: je l''''exalterai."}, {"numero": 3, "texto": "L''''Eternel est un vaillant guerrier; L''''Eternel est son nom."}, {"numero": 4, "texto": "Il a lancé dans la mer les chars de Pharaon et son armée; Ses combattants d''''élite ont été engloutis dans la mer Rouge."}, {"numero": 5, "texto": "Les flots les ont couverts: Ils sont descendus au fond des eaux, comme une pierre."}, {"numero": 6, "texto": "Ta droite, ô Eternel! a signalé sa force; Ta droite, ô Eternel! a écrasé l''''ennemi."}, {"numero": 7, "texto": "Par la grandeur de ta majesté Tu renverses tes adversaires; Tu déchaînes ta colère: Elle les consume comme du chaume."}, {"numero": 8, "texto": "Au souffle de tes narines, les eaux se sont amoncelées, Les courants se sont dressés comme une muraille, Les flots se sont durcis au milieu de la mer."}, {"numero": 9, "texto": "L''''ennemi disait: Je poursuivrai, j''''atteindrai, Je partagerai le butin; Ma vengeance sera assouvie, Je tirerai l''''épée, ma main les détruira."}, {"numero": 10, "texto": "Tu as soufflé de ton haleine: La mer les a couverts; Ils se sont enfoncés comme du plomb, Dans la profondeur des eaux."}, {"numero": 11, "texto": "Qui est comme toi parmi les dieux, ô Eternel? Qui est comme toi magnifique en sainteté, Digne de louanges, Opérant des prodiges?"}, {"numero": 12, "texto": "Tu as étendu ta droite: La terre les a engloutis."}, {"numero": 13, "texto": "Par ta miséricorde tu as conduit, Tu as délivré ce peuple; Par ta puissance tu le diriges Vers la demeure de ta sainteté."}, {"numero": 14, "texto": "Les peuples l''''apprennent, et ils tremblent: La terreur s''''empare des Philistins;"}, {"numero": 15, "texto": "Les chefs d''''Edom s''''épouvantent; Un tremblement saisit les guerriers de Moab; Tous les habitants de Canaan tombent en défaillance."}, {"numero": 16, "texto": "La crainte et la frayeur les surprendront; Par la grandeur de ton bras Ils deviendront muets comme une pierre, Jusqu''''à ce que ton peuple soit passé, ô Eternel! Jusqu''''à ce qu''''il soit passé, Le peuple que tu as acquis."}, {"numero": 17, "texto": "Tu les amèneras et tu les établiras sur la montagne de ton héritage, Au lieu que tu as préparé pour ta demeure, ô Eternel! Au sanctuaire, Seigneur! que tes mains ont fondé."}, {"numero": 18, "texto": "L''''Eternel régnera éternellement et à toujours."}, {"numero": 19, "texto": "Car les chevaux de Pharaon, ses chars et ses cavaliers sont entrés dans la mer, Et l''''Eternel a ramené sur eux les eaux de la mer; Mais les enfants d''''Israël ont marché à sec au milieu de la mer."}, {"numero": 20, "texto": "Marie, la prophétesse, soeur d''''Aaron, prit à sa main un tambourin, et toutes les femmes vinrent après elle, avec des tambourins et en dansant."}, {"numero": 21, "texto": "Marie répondait aux enfants d''''Israël: Chantez à l''''Eternel, car il a fait éclater sa gloire; Il a précipité dans la mer le cheval et son cavalier."}, {"numero": 22, "texto": "Moïse fit partir Israël de la mer Rouge. Ils prirent la direction du désert de Schur; et, après trois journées de marche dans le désert, ils ne trouvèrent point d''''eau."}, {"numero": 23, "texto": "Ils arrivèrent à Mara; mais ils ne purent pas boire l''''eau de Mara parce qu''''elle était amère. C''''est pourquoi ce lieu fut appelé Mara."}, {"numero": 24, "texto": "Le peuple murmura contre Moïse, en disant: Que boirons-nous?"}, {"numero": 25, "texto": "Moïse cria à l''''Eternel; et l''''Eternel lui indiqua un bois, qu''''il jeta dans l''''eau. Et l''''eau devint douce. Ce fut là que l''''Eternel donna au peuple des lois et des ordonnances, et ce fut là qu''''il le mit à l''''épreuve."}, {"numero": 26, "texto": "Il dit: Si tu écoutes attentivement la voix de l''''Eternel, ton Dieu, si tu fais ce qui est droit à ses yeux, si tu prêtes l''''oreille à ses commandements, et si tu observes toutes ses lois, je ne te frapperai d''''aucune des maladies dont j''''ai frappé les Egyptiens; car je suis l''''Eternel, qui te guérit."}, {"numero": 27, "texto": "Ils arrivèrent à Elim, où il y avait douze sources d''''eau et soixante-dix palmiers. Ils campèrent là, près de l''''eau."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 15, 'es', '[{"numero": 1, "texto": "ENTONCES cantó Moisés y los hijos de Israel este cántico á Jehová, y dijeron: Cantaré yo á Jehová, porque se ha magnificado grandemente, echando en la mar al caballo y al que en él subía."}, {"numero": 2, "texto": "Jehová es mi fortaleza, y mi canción, y hame sido por salud: éste es mi Dios, y á éste engrandeceré; Dios de mi padre, y á éste ensalzaré."}, {"numero": 3, "texto": "Jehová, varón de guerra; Jehová es su nombre."}, {"numero": 4, "texto": "Los carros de Faraón y á su ejército echó en la mar; y sus escogidos príncipes fueron hundidos en el mar Bermejo."}, {"numero": 5, "texto": "Los abismos los cubrieron; como piedra descendieron á los profundos."}, {"numero": 6, "texto": "Tu diestra, oh Jehová, ha sido magnificada en fortaleza; tu diestra, oh Jehová, ha quebrantado al enemigo."}, {"numero": 7, "texto": "Y con la grandeza de tu poder has trastornado á los que se levantaron contra ti: enviaste tu furor; los tragó como á hojarasca."}, {"numero": 8, "texto": "Con el soplo de tus narices se amontonaron las aguas; paráronse las corrientes como en un montón; los abismos se cuajaron en medio de la mar."}, {"numero": 9, "texto": "El enemigo dijo: Perseguiré, prenderé, repartiré despojos; mi alma se henchirá de ellos; sacaré mi espada, destruirlos ha mi mano."}, {"numero": 10, "texto": "Soplaste con tu viento, cubriólos la mar: hundiéronse como plomo en las impetuosas aguas."}, {"numero": 11, "texto": "¿Quién como tú, Jehová, entre los dioses? ¿quién como tú, magnífico en santidad, terrible en loores, hacedor de maravillas?"}, {"numero": 12, "texto": "Extendiste tu diestra; la tierra los tragó."}, {"numero": 13, "texto": "Condujiste en tu misericordia á este pueblo, al cual salvaste; llevástelo con tu fortaleza á la habitación de tu santuario."}, {"numero": 14, "texto": "Oiránlo los pueblos, y temblarán; apoderarse ha dolor de los moradores de Palestina."}, {"numero": 15, "texto": "Entonces los príncipes de Edom se turbarán; á los robustos de Moab los ocupará temblor; abatirse han todos los moradores de Canaán."}, {"numero": 16, "texto": "Caiga sobre ellos temblor y espanto; á la grandeza de tu brazo enmudezcan como una piedra; hasta que haya pasado tu pueblo, oh Jehová, hasta que haya pasado este pueblo que tú rescataste."}, {"numero": 17, "texto": "Tú los introducirás y los plantarás en el monte de tu heredad, en el lugar de tu morada, que tú has aparejado, oh Jehová; en el santuario del Señor, que han afirmado tus manos."}, {"numero": 18, "texto": "Jehová reinará por los siglos de los siglos."}, {"numero": 19, "texto": "Porque Faraón entró cabalgando con sus carros y su gente de á caballo en la mar, y Jehová volvió á traer las aguas de la mar sobre ellos; mas los hijos de Israel fueron en seco por medio de la mar."}, {"numero": 20, "texto": "Y María la profetisa, hermana de Aarón, tomó un pandero en su mano, y todas las mujeres salieron en pos de ella con panderos y danzas;"}, {"numero": 21, "texto": "Y María les respondía: Cantad á Jehová; porque en extremo se ha engrandecido, echando en la mar al caballo, y al que en él subía."}, {"numero": 22, "texto": "E hizo Moisés que partiese Israel del mar Bermejo, y salieron al desierto de Shur; y anduvieron tres días por el desierto sin hallar agua."}, {"numero": 23, "texto": "Y llegaron á Mara, y no pudieron beber las aguas de Mara, porque eran amargas; por eso le pusieron el nombre de Mara."}, {"numero": 24, "texto": "Entonces el pueblo murmuró contra Moisés, y dijo: ¿Qué hemos de beber?"}, {"numero": 25, "texto": "Y Moisés clamó á Jehová; y Jehová le mostró un árbol, el cual metídolo que hubo dentro de las aguas, las aguas se endulzaron. Allí les dió estatutos y ordenanzas, y allí los probó;"}, {"numero": 26, "texto": "Y dijo: Si oyeres atentamente la voz de Jehová tu Dios, é hicieres lo recto delante de sus ojos, y dieres oído á sus mandamientos, y guardares todos sus estatutos, ninguna enfermedad de las que envié á los Egipcios te enviaré á ti; porque yo soy Jehová tu Sanador."}, {"numero": 27, "texto": "Y llegaron á Elim, donde había doce fuentes de aguas, y setenta palmas; y asentaron allí junto á las aguas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 16, 'pt', '[{"numero": 1, "texto": "Depois que partiram de Elim, toda a congregação dos filhos de Israel veio ao deserto de Sim, que está entre Elim e Sinai, aos quinze dias do segundo mês depois que saíram da terra do Egito."}, {"numero": 2, "texto": "E toda a congregação dos filhos de Israel murmurou contra Moisés e Arão no deserto;"}, {"numero": 3, "texto": "E diziam-lhes os filhos de Israel: Bom seria se tivéssemos morrido por meio do SENHOR na terra do Egito, quando nos sentávamos junto às panelas das carnes, quando comíamos pão em fartura; pois nos tirastes a este deserto, para matar de fome a toda esta multidão."}, {"numero": 4, "texto": "E o SENHOR disse a Moisés: Eis que eu vos farei chover pão do céu; e o povo sairá, e colherá para cada um dia, para que eu lhe prove se anda em minha lei, ou não."}, {"numero": 5, "texto": "Mas ao sexto dia prepararão o que coletarem, que será o dobro do que costumam colher cada dia."}, {"numero": 6, "texto": "Então disse Moisés e Arão a todos os filhos de Israel: À tarde sabereis que o SENHOR vos tirou da terra do Egito:"}, {"numero": 7, "texto": "E à próxima manhã vereis a glória do SENHOR; porque ele ouviu as vossas murmurações contra o SENHOR; pois quem somos nós, para que vós murmureis contra nós?"}, {"numero": 8, "texto": "E disse Moisés: o SENHOR vos dará à tarde carne para comer, e à manhã pão em fartura; pois o SENHOR ouviu as vossas murmurações com que murmurais contra ele; pois quem somos nós? As vossas murmurações não são contra nós, mas sim contra o SENHOR."}, {"numero": 9, "texto": "E disse Moisés a Arão: Dize a toda a congregação dos filhos de Israel: Aproximai-vos à presença do SENHOR; que ele ouviu vossas murmurações."}, {"numero": 10, "texto": "E falando Arão a toda a congregação dos filhos de Israel, olharam até o deserto, e eis a glória do SENHOR, que apareceu na nuvem."}, {"numero": 11, "texto": "E o SENHOR falou a Moisés, dizendo:"}, {"numero": 12, "texto": "Eu ouvi as murmurações dos filhos de Israel; fala-lhes, dizendo: Ao entardecer comereis carne, e pela manhã vos fartareis de pão, e sabereis que eu sou o SENHOR vosso Deus."}, {"numero": 13, "texto": "E vinda a tarde subiram codornizes que cobriram o acampamento; e à manhã desceu orvalho em derredor do acampamento."}, {"numero": 14, "texto": "E quando o orvalho cessou de descer, eis sobre a face do deserto uma coisa miúda, redonda, miúda como uma geada sobre a terra."}, {"numero": 15, "texto": "E vendo-o os filhos de Israel, se disseram uns aos outros: Que é isto? porque não sabiam que era. Então Moisés lhes disse: É o pão que o SENHOR vos dá para comer."}, {"numero": 16, "texto": "Isto é o que o SENHOR mandou: Colhereis dele cada um segundo puder comer; um gômer por cabeça, conforme o número de vossas pessoas, tomareis cada um para os que estão em sua tenda."}, {"numero": 17, "texto": "E os filhos de Israel o fizeram assim: e recolheram uns mais, outros menos:"}, {"numero": 18, "texto": "E mediam-no por gômer, e não sobrava ao que havia recolhido muito, nem faltava ao que havia recolhido pouco: cada um recolheu conforme o que havia de comer."}, {"numero": 19, "texto": "E disse-lhes Moisés: Nenhum deixe nada disso para amanhã."}, {"numero": 20, "texto": "Mas eles não obedeceram a Moisés, mas sim que alguns deixaram dele para outro dia, e criou bichos, e apodreceu-se; e irou-se contra eles Moisés."}, {"numero": 21, "texto": "E recolhiam-no cada manhã, cada um segundo o que havia de comer: e logo que o sol aquecia, derretia-se."}, {"numero": 22, "texto": "No sexto dia recolheram comida em dobro, dois gômeres para cada um; e todos os príncipes da congregação vieram a Moisés, e contaram-lhe isso."}, {"numero": 23, "texto": "E ele lhes disse: Isto é o que o SENHOR disse: Amanhã é o repouso, o santo sábado do SENHOR; o que houverdes de assar, assai-o hoje, e o que houverdes de cozinhar, cozinhai-o; e tudo o que vos sobrar, guardai-o para amanhã."}, {"numero": 24, "texto": "E eles o guardaram até a manhã, segundo que Moisés havia mandado, e não se apodreceu, nem houve nele bicho."}, {"numero": 25, "texto": "E disse Moisés: Comei-o hoje, porque hoje é sábado do SENHOR: hoje não achareis no campo."}, {"numero": 26, "texto": "Nos seis dias o recolhereis; mas o sétimo dia é sábado, no qual não se achará."}, {"numero": 27, "texto": "E aconteceu que alguns do povo saíram no sétimo dia a recolher, e não acharam."}, {"numero": 28, "texto": "E o SENHOR disse a Moisés: Até quando não querereis guardar meus mandamentos e minhas leis?"}, {"numero": 29, "texto": "Olhai que o SENHOR vos deu o sábado, e por isso vos dá no sexto dia pão para dois dias. Fique, pois, cada um em sua morada, e ninguém saia de seu lugar no sétimo dia."}, {"numero": 30, "texto": "Assim o povo repousou o sétimo dia."}, {"numero": 31, "texto": "E a casa de Israel o chamou maná; e era como semente de coentro, branco, e seu sabor como de bolos com mel."}, {"numero": 32, "texto": "E disse Moisés: Isto é o que o SENHOR mandou: Encherás um gômer dele para que se guarde para vossos descendentes, a fim de que vejam o pão que eu vos dei a comer no deserto, quando eu vos tirei da terra do Egito."}, {"numero": 33, "texto": "E disse Moisés a Arão: Toma um vaso e põe nele um gômer cheio de maná, e põe-o diante do SENHOR, para que seja guardado para vossos descendentes."}, {"numero": 34, "texto": "E Arão o pôs diante do testemunho para guardá-lo, como o SENHOR o mandou a Moisés."}, {"numero": 35, "texto": "Assim os filhos de Israel comeram maná por quarenta anos, até que entraram em terra habitada; comeram maná até que chegaram ao limite da terra de Canaã."}, {"numero": 36, "texto": "E um gômer é a décima parte do efa."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 16, 'en', '[{"numero": 1, "texto": "And they took their journey from Elim, and all the congregation of the children of Israel came unto the wilderness of Sin, which is between Elim and Sinai, on the fifteenth day of the second month after their departing out of the land of Egypt."}, {"numero": 2, "texto": "And the whole congregation of the children of Israel murmured against Moses and Aaron in the wilderness:"}, {"numero": 3, "texto": "And the children of Israel said unto them, Would to God we had died by the hand of the Lord in the land of Egypt, when we sat by the flesh pots, and when we did eat bread to the full; for ye have brought us forth into this wilderness, to kill this whole assembly with hunger."}, {"numero": 4, "texto": "Then said the Lord unto Moses, Behold, I will rain bread from heaven for you; and the people shall go out and gather a certain rate every day, that I may prove them, whether they will walk in my law, or no."}, {"numero": 5, "texto": "And it shall come to pass, that on the sixth day they shall prepare that which they bring in; and it shall be twice as much as they gather daily."}, {"numero": 6, "texto": "And Moses and Aaron said unto all the children of Israel, At even, then ye shall know that the Lord hath brought you out from the land of Egypt:"}, {"numero": 7, "texto": "And in the morning, then ye shall see the glory of the Lord; for that he heareth your murmurings against the Lord: and what are we, that ye murmur against us?"}, {"numero": 8, "texto": "And Moses said, This shall be, when the Lord shall give you in the evening flesh to eat, and in the morning bread to the full; for that the Lord heareth your murmurings which ye murmur against him: and what are we? your murmurings are not against us, but against the Lord."}, {"numero": 9, "texto": "And Moses spake unto Aaron, Say unto all the congregation of the children of Israel, Come near before the Lord: for he hath heard your murmurings."}, {"numero": 10, "texto": "And it came to pass, as Aaron spake unto the whole congregation of the children of Israel, that they looked toward the wilderness, and, behold, the glory of the Lord appeared in the cloud."}, {"numero": 11, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 12, "texto": "I have heard the murmurings of the children of Israel: speak unto them, saying, At even ye shall eat flesh, and in the morning ye shall be filled with bread; and ye shall know that I am the Lord your God."}, {"numero": 13, "texto": "And it came to pass, that at even the quails came up, and covered the camp: and in the morning the dew lay round about the host."}, {"numero": 14, "texto": "And when the dew that lay was gone up, behold, upon the face of the wilderness there lay a small round thing, as small as the hoar frost on the ground."}, {"numero": 15, "texto": "And when the children of Israel saw it, they said one to another, It is manna: for they wist not what it was. And Moses said unto them, This is the bread which the Lord hath given you to eat."}, {"numero": 16, "texto": "This is the thing which the Lord hath commanded, Gather of it every man according to his eating, an omer for every man, according to the number of your persons; take ye every man for them which are in his tents."}, {"numero": 17, "texto": "And the children of Israel did so, and gathered, some more, some less."}, {"numero": 18, "texto": "And when they did mete it with an omer, he that gathered much had nothing over, and he that gathered little had no lack; they gathered every man according to his eating."}, {"numero": 19, "texto": "And Moses said, Let no man leave of it till the morning."}, {"numero": 20, "texto": "Notwithstanding they hearkened not unto Moses; but some of them left of it until the morning, and it bred worms, and stank: and Moses was wroth with them."}, {"numero": 21, "texto": "And they gathered it every morning, every man according to his eating: and when the sun waxed hot, it melted."}, {"numero": 22, "texto": "And it came to pass, that on the sixth day they gathered twice as much bread, two omers for one man: and all the rulers of the congregation came and told Moses."}, {"numero": 23, "texto": "And he said unto them, This is that which the Lord hath said, To morrow is the rest of the holy sabbath unto the Lord: bake that which ye will bake to day, and seethe that ye will seethe; and that which remaineth over lay up for you to be kept until the morning."}, {"numero": 24, "texto": "And they laid it up till the morning, as Moses bade: and it did not stink, neither was there any worm therein."}, {"numero": 25, "texto": "And Moses said, Eat that to day; for to day is a sabbath unto the Lord: to day ye shall not find it in the field."}, {"numero": 26, "texto": "Six days ye shall gather it; but on the seventh day, which is the sabbath, in it there shall be none."}, {"numero": 27, "texto": "And it came to pass, that there went out some of the people on the seventh day for to gather, and they found none."}, {"numero": 28, "texto": "And the Lord said unto Moses, How long refuse ye to keep my commandments and my laws?"}, {"numero": 29, "texto": "See, for that the Lord hath given you the sabbath, therefore he giveth you on the sixth day the bread of two days; abide ye every man in his place, let no man go out of his place on the seventh day."}, {"numero": 30, "texto": "So the people rested on the seventh day."}, {"numero": 31, "texto": "And the house of Israel called the name thereof Manna: and it was like coriander seed, white; and the taste of it was like wafers made with honey."}, {"numero": 32, "texto": "And Moses said, This is the thing which the Lord commandeth, Fill an omer of it to be kept for your generations; that they may see the bread wherewith I have fed you in the wilderness, when I brought you forth from the land of Egypt."}, {"numero": 33, "texto": "And Moses said unto Aaron, Take a pot, and put an omer full of manna therein, and lay it up before the Lord, to be kept for your generations."}, {"numero": 34, "texto": "As the Lord commanded Moses, so Aaron laid it up before the Testimony, to be kept."}, {"numero": 35, "texto": "And the children of Israel did eat manna forty years, until they came to a land inhabited; they did eat manna, until they came unto the borders of the land of Canaan."}, {"numero": 36, "texto": "Now an omer is the tenth part of an ephah."}]'::jsonb, 'King James Version'),
  ('Ex', 16, 'fr', '[{"numero": 1, "texto": "Toute l''''assemblée des enfants d''''Israël partit d''''Elim, et ils arrivèrent au désert de Sin, qui est entre Elim et Sinaï, le quinzième jour du second mois après leur sortie du pays d''''Egypte."}, {"numero": 2, "texto": "Et toute l''''assemblée des enfants d''''Israël murmura dans le désert contre Moïse et Aaron."}, {"numero": 3, "texto": "Les enfants d''''Israël leur dirent: Que ne sommes-nous morts par la main de l''''Eternel dans le pays d''''Egypte, quand nous étions assis près des pots de viande, quand nous mangions du pain à satiété? car vous nous avez menés dans ce désert pour faire mourir de faim toute cette multitude."}, {"numero": 4, "texto": "L''''Eternel dit à Moïse: Voici, je ferai pleuvoir pour vous du pain, du haut des cieux. Le peuple sortira, et en ramassera, jour par jour, la quantité nécessaire, afin que je le mette à l''''épreuve, et que je voie s''''il marchera, ou non, selon ma loi."}, {"numero": 5, "texto": "Le sixième jour, lorsqu''''ils prépareront ce qu''''ils auront apporté, il s''''en trouvera le double de ce qu''''ils ramasseront jour par jour."}, {"numero": 6, "texto": "Moïse et Aaron dirent à tous les enfants d''''Israël: Ce soir, vous comprendrez que c''''est l''''Eternel qui vous a fait sortir du pays d''''Egypte."}, {"numero": 7, "texto": "Et, au matin, vous verrez la gloire de l''''Eternel, parce qu''''il a entendu vos murmures contre l''''Eternel; car que sommes-nous, pour que vous murmuriez contre nous?"}, {"numero": 8, "texto": "Moïse dit: L''''Eternel vous donnera ce soir de la viande à manger, et au matin du pain à satiété, parce que l''''Eternel a entendu les murmures que vous avez proférés contre lui; car que sommes-nous? Ce n''''est pas contre nous que sont vos murmures, c''''est contre l''''Eternel."}, {"numero": 9, "texto": "Moïse dit à Aaron: Dis à toute l''''assemblée des enfants d''''Israël: Approchez-vous devant l''''Eternel, car il a entendu vos murmures."}, {"numero": 10, "texto": "Et tandis qu''''Aaron parlait à toute l''''assemblée des enfants d''''Israël, ils se tournèrent du côté du désert, et voici, la gloire de l''''Eternel parut dans la nuée."}, {"numero": 11, "texto": "L''''Eternel, s''''adressant à Moïse, dit:"}, {"numero": 12, "texto": "J''''ai entendu les murmures des enfants d''''Israël. Dis-leur: Entre les deux soirs vous mangerez de la viande, et au matin vous vous rassasierez de pain; et vous saurez que je suis l''''Eternel, votre Dieu."}, {"numero": 13, "texto": "Le soir, il survint des cailles qui couvrirent le camp; et, au matin, il y eut une couche de rosée autour du camp."}, {"numero": 14, "texto": "Quand cette rosée fut dissipée, il y avait à la surface du désert quelque chose de menu comme des grains, quelque chose de menu comme la gelée blanche sur la terre."}, {"numero": 15, "texto": "Les enfants d''''Israël regardèrent et ils se dirent l''''un à l''''autre: Qu''''est-ce que cela? car ils ne savaient pas ce que c''''était. Moïse leur dit: C''''est le pain que L''''Eternel vous donne pour nourriture."}, {"numero": 16, "texto": "Voici ce que l''''Eternel a ordonné: Que chacun de vous en ramasse ce qu''''il faut pour sa nourriture, un omer par tête, suivant le nombre de vos personnes; chacun en prendra pour ceux qui sont dans sa tente."}, {"numero": 17, "texto": "Les Israélites firent ainsi; et ils en ramassèrent les uns plus, les autres moins."}, {"numero": 18, "texto": "On mesurait ensuite avec l''''omer; celui qui avait ramassé plus n''''avait rien de trop, et celui qui avait ramassé moins n''''en manquait pas. Chacun ramassait ce qu''''il fallait pour sa nourriture."}, {"numero": 19, "texto": "Moïse leur dit: Que personne n''''en laisse jusqu''''au matin."}, {"numero": 20, "texto": "Ils n''''écoutèrent pas Moïse, et il y eut des gens qui en laissèrent jusqu''''au matin; mais il s''''y mit des vers, et cela devint infect. Moïse fut irrité contre ces gens."}, {"numero": 21, "texto": "Tous les matins, chacun ramassait ce qu''''il fallait pour sa nourriture; et quand venait la chaleur du soleil, cela fondait."}, {"numero": 22, "texto": "Le sixième jour, ils ramassèrent une quantité double de nourriture, deux omers pour chacun. Tous les principaux de l''''assemblée vinrent le rapporter à Moïse."}, {"numero": 23, "texto": "Et Moïse leur dit: C''''est ce que l''''Eternel a ordonné. Demain est le jour du repos, le sabbat consacré à l''''Eternel; faites cuire ce que vous avez à faire cuire, faites bouillir ce que vous avez à faire bouillir, et mettez en réserve jusqu''''au matin tout ce qui restera."}, {"numero": 24, "texto": "Ils le laissèrent jusqu''''au matin, comme Moïse l''''avait ordonné; et cela ne devint point infect, et il ne s''''y mit point de vers."}, {"numero": 25, "texto": "Moïse dit: Mangez-le aujourd''''hui, car c''''est le jour du sabbat; aujourd''''hui vous n''''en trouverez point dans la campagne."}, {"numero": 26, "texto": "Pendant six jours vous en ramasserez; mais le septième jour, qui est le sabbat, il n''''y en aura point."}, {"numero": 27, "texto": "Le septième jour, quelques-uns du peuple sortirent pour en ramasser, et ils n''''en trouvèrent point."}, {"numero": 28, "texto": "Alors l''''Eternel dit à Moïse: Jusques à quand refuserez-vous d''''observer mes commandements et mes lois?"}, {"numero": 29, "texto": "Considérez que l''''Eternel vous a donné le sabbat; c''''est pourquoi il vous donne au sixième jour de la nourriture pour deux jours. Que chacun reste à sa place, et que personne ne sorte du lieu où il est au septième jour."}, {"numero": 30, "texto": "Et le peuple se reposa le septième jour."}, {"numero": 31, "texto": "La maison d''''Israël donna à cette nourriture le nom de manne. Elle ressemblait à de la graine de coriandre; elle était blanche, et avait le goût d''''un gâteau au miel."}, {"numero": 32, "texto": "Moïse dit: Voici ce que l''''Eternel a ordonné: Qu''''un omer rempli de manne soit conservé pour vos descendants, afin qu''''ils voient le pain que je vous ai fait manger dans le désert, après vous avoir fait sortir du pays d''''Egypte."}, {"numero": 33, "texto": "Et Moïse dit à Aaron: Prends un vase, mets-y de la manne plein un omer, et dépose-le devant l''''Eternel, afin qu''''il soit conservé pour vos descendants."}, {"numero": 34, "texto": "Suivant l''''ordre donné par l''''Eternel à Moïse, Aaron le déposa devant le témoignage, afin qu''''il fût conservé."}, {"numero": 35, "texto": "Les enfants d''''Israël mangèrent la manne pendant quarante ans, jusqu''''à leur arrivée dans un pays habité; ils mangèrent la manne jusqu''''à leur arrivée aux frontières du pays de Canaan."}, {"numero": 36, "texto": "L''''omer est la dixième partie de l''''épha."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 16, 'es', '[{"numero": 1, "texto": "Y PARTIENDO de Elim toda la congregación de los hijos de Israel, vino al desierto de Sin, que está entre Elim y Sinaí, á los quince días del segundo mes después que salieron de la tierra de Egipto."}, {"numero": 2, "texto": "Y toda la congregación de los hijos de Israel murmuró contra Moisés y Aarón en el desierto;"}, {"numero": 3, "texto": "Y decíanles los hijos de Israel: Ojalá hubiéramos muerto por mano de Jehová en la tierra de Egipto, cuando nos sentábamos á las ollas de las carnes, cuando comíamos pan en hartura; pues nos habéis sacado á este desierto, para matar de hambre á toda esta multitud."}, {"numero": 4, "texto": "Y Jehová dijo á Moisés: He aquí yo os haré llover pan del cielo; y el pueblo saldrá, y cogerá para cada un día, para que yo le pruebe si anda en mi ley, ó no."}, {"numero": 5, "texto": "Mas al sexto día aparejarán lo que han de encerrar, que será el doble de lo que solían coger cada día."}, {"numero": 6, "texto": "Entonces dijo Moisés y Aarón á todos los hijos de Israel: A la tarde sabréis que Jehová os ha sacado de la tierra de Egipto:"}, {"numero": 7, "texto": "Y á la mañana veréis la gloria de Jehová; porque él ha oído vuestras murmuraciones contra Jehová; que nosotros, ¿qué somos, para que vosotros murmuréis contra nosotros?"}, {"numero": 8, "texto": "Y dijo Moisés: Jehová os dará á la tarde carne para comer, y á la mañana pan en hartura; por cuanto Jehová ha oído vuestras murmuraciones con que habéis murmurado contra él: que nosotros, ¿qué somos? vuestras murmuraciones no son contra nosotros, sino contra Jehová."}, {"numero": 9, "texto": "Y dijo Moisés á Aarón: Di á toda la congregación de los hijos de Israel: Acercaos á la presencia de Jehová; que él ha oído vuestras murmuraciones."}, {"numero": 10, "texto": "Y hablando Aarón á toda la congregación de los hijos de Israel, miraron hacia el desierto, y he aquí la gloria de Jehová, que apareció en la nube."}, {"numero": 11, "texto": "Y Jehová habló á Moisés, diciendo:"}, {"numero": 12, "texto": "Yo he oído las murmuraciones de los hijos de Israel; háblales, diciendo: Entre las dos tardes comeréis carne, y por la mañana os hartaréis de pan, y sabréis que yo soy Jehová vuestro Dios."}, {"numero": 13, "texto": "Y venida la tarde subieron codornices que cubrieron el real; y á la mañana descendió rocío en derredor del real."}, {"numero": 14, "texto": "Y como el rocío cesó de descender, he aquí sobre la haz del desierto una cosa menuda, redonda, menuda como una helada sobre la tierra."}, {"numero": 15, "texto": "Y viéndolo los hijos de Israel, se dijeron unos á otros: ¿Qué es esto? porque no sabían qué era. Entonces Moisés les dijo: Es el pan que Jehová os da para comer."}, {"numero": 16, "texto": "Esto es lo que Jehová ha mandado: cogeréis de él cada uno según pudiere comer; un gomer por cabeza, conforme al número de vuestras personas, tomaréis cada uno para los que están en su tienda."}, {"numero": 17, "texto": "Y los hijos de Israel lo hicieron así: y recogieron unos más, otros menos:"}, {"numero": 18, "texto": "Y medíanlo por gomer, y no sobraba al que había recogido mucho, ni faltaba al que había recogido poco: cada uno recogió conforme á lo que había de comer."}, {"numero": 19, "texto": "Y díjoles Moisés: Ninguno deje nada de ello para mañana."}, {"numero": 20, "texto": "Mas ellos no obedecieron á Moisés, sino que algunos dejaron de ello para otro día, y crió gusanos, y pudrióse; y enojóse contra ellos Moisés."}, {"numero": 21, "texto": "Y recogíanlo cada mañana, cada uno según lo que había de comer: y luego que el sol calentaba, derretíase."}, {"numero": 22, "texto": "En el sexto día recogieron doblada comida, dos gomeres para cada uno: y todos los príncipes de la congregación vinieron á Moisés, y se lo hicieron saber."}, {"numero": 23, "texto": "Y él les dijo: Esto es lo que ha dicho Jehová: Mañana es el santo sábado, el reposo de Jehová: lo que hubiereis de cocer, cocedlo hoy, y lo que hubiereis de cocinar, cocinadlo; y todo lo que os sobrare, guardadlo para mañana."}, {"numero": 24, "texto": "Y ellos lo guardaron hasta la mañana, según que Moisés había mandado, y no se pudrió, ni hubo en él gusano."}, {"numero": 25, "texto": "Y dijo Moisés: Comedlo hoy, porque hoy es sábado de Jehová: hoy no hallaréis en el campo."}, {"numero": 26, "texto": "En los seis días lo recogeréis; mas el séptimo día es sábado, en el cual no se hallará."}, {"numero": 27, "texto": "Y aconteció que algunos del pueblo salieron en el séptimo día á recoger, y no hallaron."}, {"numero": 28, "texto": "Y Jehová dijo á Moisés: ¿Hasta cuándo no querréis guardar mis mandamientos y mis leyes?"}, {"numero": 29, "texto": "Mirad que Jehová os dió el sábado, y por eso os da en el sexto día pan para dos días. Estése, pues, cada uno en su estancia, y nadie salga de su lugar en el séptimo día."}, {"numero": 30, "texto": "Así el pueblo reposó el séptimo día."}, {"numero": 31, "texto": "Y la casa de Israel lo llamó Maná; y era como simiente de culantro, blanco, y su sabor como de hojuelas con miel."}, {"numero": 32, "texto": "Y dijo Moisés: Esto es lo que Jehová ha mandado: Henchirás un gomer de él para que se guarde para vuestros descendientes, á fin de que vean el pan que yo os dí á comer en el desierto, cuando yo os saqué de la tierra de Egipto."}, {"numero": 33, "texto": "Y dijo Moisés á Aarón: Toma un vaso, y pon en él un gomer lleno de maná, y ponlo delante de Jehová, para que sea guardado para vuestros descendientes."}, {"numero": 34, "texto": "Y Aarón lo puso delante del Testimonio para guardarlo, como Jehová lo mandó á Moisés."}, {"numero": 35, "texto": "Así comieron los hijos de Israel maná cuarenta años, hasta que entraron en la tierra habitada: maná comieron hasta que llegaron al término de la tierra de Canaán."}, {"numero": 36, "texto": "Y un gomer es la décima parte del epha."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 17, 'pt', '[{"numero": 1, "texto": "E toda a congregação dos filhos de Israel partiu do deserto de Sim, por suas jornadas, ao mandamento do SENHOR, e assentaram o acampamento em Refidim: e não havia água para que o povo bebesse."}, {"numero": 2, "texto": "E brigou o povo com Moisés, e disseram: Dá-nos água que bebamos. E Moisés lhes disse: Por que brigais comigo? Por que tentais ao SENHOR?"}, {"numero": 3, "texto": "Assim que o povo teve ali sede de água, e murmurou contra Moisés, e disse: Por que nos fizeste subir do Egito para matar-nos de sede a nós, e a nossos filhos e a nossos gados?"}, {"numero": 4, "texto": "Então clamou Moisés ao SENHOR, dizendo: Que farei com este povo? Daqui um pouco me apedrejarão."}, {"numero": 5, "texto": "E o SENHOR disse a Moisés: Passa diante do povo, e toma contigo dos anciãos de Israel; e toma também em tua mão tua vara, com que feriste o rio, e vai:"}, {"numero": 6, "texto": "Eis que eu estou diante de ti ali sobre a rocha em Horebe; e ferirás a rocha, e sairão dela águas, e beberá o povo. E Moisés o fez assim em presença dos anciãos de Israel."}, {"numero": 7, "texto": "E chamou o nome daquele lugar Massá e Meribá, pela briga dos filhos de Israel, e porque tentaram ao SENHOR, dizendo: Está, pois, o SENHOR entre nós, ou não?"}, {"numero": 8, "texto": "E veio Amaleque e lutou com Israel em Refidim."}, {"numero": 9, "texto": "E disse Moisés a Josué: Escolhe para nós homens, e sai, luta com Amaleque: amanhã eu estarei sobre o cume do morro, e a vara de Deus em minha mão."}, {"numero": 10, "texto": "E fez Josué como lhe disse Moisés, lutando com Amaleque; e Moisés e Arão e Hur subiram ao cume do morro."}, {"numero": 11, "texto": "E sucedia que quando erguia Moisés sua mão, Israel prevalecia; mas quando ele baixava sua mão, prevalecia Amaleque."}, {"numero": 12, "texto": "E as mãos de Moisés estavam pesadas; pelo que tomaram uma pedra, e puseram-na debaixo dele, e se sentou sobre ela; e Arão e Hur sustentavam suas mãos, o um de uma parte e o outro de outra; assim houve em suas mãos firmeza até que se pôs o sol."}, {"numero": 13, "texto": "E Josué derrotou a Amaleque e a seu povo a fio de espada."}, {"numero": 14, "texto": "E o SENHOR disse a Moisés: Escreve isto para memória em um livro, e dize a Josué que de todo tenho de apagar a memória de Amaleque de debaixo do céu."}, {"numero": 15, "texto": "E Moisés edificou um altar, e chamou seu nome O SENHOR é minha bandeira;"}, {"numero": 16, "texto": "E disse: Porquanto há mão sobre o trono do SENHOR, o SENHOR terá guerra com Amaleque de geração em geração."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 17, 'en', '[{"numero": 1, "texto": "And all the congregation of the children of Israel journeyed from the wilderness of Sin, after their journeys, according to the commandment of the Lord, and pitched in Rephidim: and there was no water for the people to drink."}, {"numero": 2, "texto": "Wherefore the people did chide with Moses, and said, Give us water that we may drink. And Moses said unto them, Why chide ye with me? wherefore do ye tempt the Lord?"}, {"numero": 3, "texto": "And the people thirsted there for water; and the people murmured against Moses, and said, Wherefore is this that thou hast brought us up out of Egypt, to kill us and our children and our cattle with thirst?"}, {"numero": 4, "texto": "And Moses cried unto the Lord, saying, What shall I do unto this people? they be almost ready to stone me."}, {"numero": 5, "texto": "And the Lord said unto Moses, Go on before the people, and take with thee of the elders of Israel; and thy rod, wherewith thou smotest the river, take in thine hand, and go."}, {"numero": 6, "texto": "Behold, I will stand before thee there upon the rock in Horeb; and thou shalt smite the rock, and there shall come water out of it, that the people may drink. And Moses did so in the sight of the elders of Israel."}, {"numero": 7, "texto": "And he called the name of the place Massah, and Meribah, because of the chiding of the children of Israel, and because they tempted the Lord, saying, Is the Lord among us, or not?"}, {"numero": 8, "texto": "Then came Amalek, and fought with Israel in Rephidim."}, {"numero": 9, "texto": "And Moses said unto Joshua, Choose us out men, and go out, fight with Amalek: to morrow I will stand on the top of the hill with the rod of God in mine hand."}, {"numero": 10, "texto": "So Joshua did as Moses had said to him, and fought with Amalek: and Moses, Aaron, and Hur went up to the top of the hill."}, {"numero": 11, "texto": "And it came to pass, when Moses held up his hand, that Israel prevailed: and when he let down his hand, Amalek prevailed."}, {"numero": 12, "texto": "But Moses hands were heavy; and they took a stone, and put it under him, and he sat thereon; and Aaron and Hur stayed up his hands, the one on the one side, and the other on the other side; and his hands were steady until the going down of the sun."}, {"numero": 13, "texto": "And Joshua discomfited Amalek and his people with the edge of the sword."}, {"numero": 14, "texto": "And the Lord said unto Moses, Write this for a memorial in a book, and rehearse it in the ears of Joshua: for I will utterly put out the remembrance of Amalek from under heaven."}, {"numero": 15, "texto": "And Moses built an altar, and called the name of it Jehovahnissi:"}, {"numero": 16, "texto": "For he said, Because the Lord hath sworn that the Lord will have war with Amalek from generation to generation."}]'::jsonb, 'King James Version'),
  ('Ex', 17, 'fr', '[{"numero": 1, "texto": "Toute l''''assemblée des enfants d''''Israël partit du désert de Sin, selon les marches que l''''Eternel leur avait ordonnées; et ils campèrent à Rephidim, où le peuple ne trouva point d''''eau à boire."}, {"numero": 2, "texto": "Alors le peuple chercha querelle à Moïse. Ils dirent: Donnez-nous de l''''eau à boire. Moïse leur répondit: Pourquoi me cherchez-vous querelle? Pourquoi tentez-vous l''''Eternel?"}, {"numero": 3, "texto": "Le peuple était là, pressé par la soif, et murmurait contre Moïse. Il disait: Pourquoi nous as-tu fait monter hors d''''Egypte, pour me faire mourir de soif avec mes enfants et mes troupeaux?"}, {"numero": 4, "texto": "Moïse cria à l''''Eternel, en disant: Que ferai-je à ce peuple? Encore un peu, et ils me lapideront."}, {"numero": 5, "texto": "L''''Eternel dit à Moïse: Passe devant le peuple, et prends avec toi des anciens d''''Israël; prends aussi dans ta main ta verge avec laquelle tu as frappé le fleuve, et marche!"}, {"numero": 6, "texto": "Voici, je me tiendrai devant toi sur le rocher d''''Horeb; tu frapperas le rocher, et il en sortira de l''''eau, et le peuple boira. Et Moïse fit ainsi, aux yeux des anciens d''''Israël."}, {"numero": 7, "texto": "Il donna à ce lieu le nom de Massa et Meriba, parce que les enfants d''''Israël avaient contesté, et parce qu''''ils avaient tenté l''''Eternel, en disant: L''''Eternel est-il au milieu de nous, ou n''''y est-il pas?"}, {"numero": 8, "texto": "Amalek vint combattre Israël à Rephidim."}, {"numero": 9, "texto": "Alors Moïse dit à Josué: Choisis-nous des hommes, sors, et combats Amalek; demain je me tiendrai sur le sommet de la colline, la verge de Dieu dans ma main."}, {"numero": 10, "texto": "Josué fit ce que lui avait dit Moïse, pour combattre Amalek. Et Moïse, Aaron et Hur montèrent au sommet de la colline."}, {"numero": 11, "texto": "Lorsque Moïse élevait sa main, Israël était le plus fort; et lorsqu''''il baissait sa main, Amalek était le plus fort."}, {"numero": 12, "texto": "Les mains de Moïse étant fatiguées, ils prirent une pierre qu''''ils placèrent sous lui, et il s''''assit dessus. Aaron et Hur soutenaient ses mains, l''''un d''''un côté, l''''autre de l''''autre; et ses mains restèrent fermes jusqu''''au coucher du soleil."}, {"numero": 13, "texto": "Et Josué vainquit Amalek et son peuple, au tranchant de l''''épée."}, {"numero": 14, "texto": "L''''Eternel dit à Moïse: Ecris cela dans le livre, pour que le souvenir s''''en conserve, et déclare à Josué que j''''effacerai la mémoire d''''Amalek de dessous les cieux."}, {"numero": 15, "texto": "Moïse bâtit un autel, et lui donna pour nom: l''''Eternel ma bannière."}, {"numero": 16, "texto": "Il dit: Parce que la main a été levée sur le trône de l''''Eternel, il y aura guerre de l''''Eternel contre Amalek, de génération en génération."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 17, 'es', '[{"numero": 1, "texto": "Y TODA la congregación de los hijos de Israel partió del desierto de Sin, por sus jornadas, al mandamiento de Jehová, y asentaron el campo en Rephidim: y no había agua para que el pueblo bebiese."}, {"numero": 2, "texto": "Y altercó el pueblo con Moisés, y dijeron: Danos agua que bebamos. Y Moisés les dijo: ¿Por qué altercáis conmigo? ¿por qué tentáis á Jehová?"}, {"numero": 3, "texto": "Así que el pueblo tuvo allí sed de agua, y murmuró contra Moisés, y dijo: ¿Por qué nos hiciste subir de Egipto, para matarnos de sed á nosotros, y á nuestros hijos, y á nuestros ganados?"}, {"numero": 4, "texto": "Entonces clamó Moisés á Jehová, diciendo: ¿Qué haré con este pueblo? de aquí á un poco me apedrearán."}, {"numero": 5, "texto": "Y Jehová dijo á Moisés: Pasa delante del pueblo, y toma contigo de los ancianos de Israel; y toma también en tu mano tu vara, con que heriste el río, y ve:"}, {"numero": 6, "texto": "He aquí que yo estoy delante de ti allí sobre la peña en Horeb; y herirás la peña, y saldrán de ella aguas, y beberá el pueblo. Y Moisés lo hizo así en presencia de los ancianos de Israel."}, {"numero": 7, "texto": "Y llamó el nombre de aquel lugar Massah y Meribah, por la rencilla de los hijos de Israel, y porque tentaron á Jehová, diciendo: ¿Está, pues, Jehová entre nosotros, ó no?"}, {"numero": 8, "texto": "Y vino Amalec, y peleó con Israel en Rephidim."}, {"numero": 9, "texto": "Y dijo Moisés á Josué: Escógenos varones, y sal, pelea con Amalec: mañana yo estaré sobre la cumbre del collado, y la vara de Dios en mi mano."}, {"numero": 10, "texto": "E hizo Josué como le dijo Moisés, peleando con Amalec; y Moisés y Aarón y Hur subieron á la cumbre del collado."}, {"numero": 11, "texto": "Y sucedía que cuando alzaba Moisés su mano, Israel prevalecía; mas cuando él bajaba su mano, prevalecía Amalec."}, {"numero": 12, "texto": "Y las manos de Moisés estaban pesadas; por lo que tomaron una piedra, y pusiéronla debajo de él, y se sentó sobre ella: y Aarón y Hur sustentaban sus manos, el uno de una parte y el otro de otra; así hubo en sus manos firmeza hasta que se puso el sol."}, {"numero": 13, "texto": "Y Josué deshizo á Amalec y á su pueblo á filo de espada."}, {"numero": 14, "texto": "Y Jehová dijo á Moisés: Escribe esto para memoria en un libro, y di á Josué que del todo tengo de raer la memoria de Amalec de debajo del cielo."}, {"numero": 15, "texto": "Y Moisés edificó un altar, y llamó su nombre Jehová-nissi;"}, {"numero": 16, "texto": "Y dijo: Por cuanto la mano sobre el trono de Jehová, Jehová tendrá guerra con Amalec de generación en generación."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 18, 'pt', '[{"numero": 1, "texto": "E ouviu Jetro, sacerdote de Midiã, sogro de Moisés, todas as coisas que Deus havia feito com Moisés, e com Israel seu povo, e como o SENHOR havia tirado a Israel do Egito:"}, {"numero": 2, "texto": "E tomou Jetro, sogro de Moisés a Zípora a mulher de Moisés, depois que ele a enviou,"}, {"numero": 3, "texto": "E a seus dois filhos; um se chamava Gérson, porque disse: Peregrino fui em terra alheia;"}, {"numero": 4, "texto": "E o outro se chamava Eliézer, porque disse, O Deus de meu pai me ajudou, e me livrou da espada de Faraó."}, {"numero": 5, "texto": "E Jetro o sogro de Moisés, com seus filhos e sua mulher, chegou a Moisés no deserto, onde tinha o acampamento junto ao monte de Deus;"}, {"numero": 6, "texto": "E disse a Moisés: Eu teu sogro Jetro venho a ti, com tua mulher, e seus dois filhos com ela."}, {"numero": 7, "texto": "E Moisés saiu a receber a seu sogro, e inclinou-se, e beijou-o: e perguntaram-se um ao outro como estavam, e vieram à tenda."}, {"numero": 8, "texto": "E Moisés contou a seu sogro todas as coisas que o SENHOR havia feito a Faraó e aos egípcios por causa de Israel, e todo o trabalho que haviam passado no caminho, e como os havia livrado o SENHOR."}, {"numero": 9, "texto": "E alegrou-se Jetro de todo o bem que o SENHOR havia feito a Israel, que o havia livrado da mão dos egípcios."}, {"numero": 10, "texto": "E Jetro disse: Bendito seja o SENHOR, que vos livrou da mão dos egípcios, e da mão de Faraó, e que livrou ao povo da mão dos egípcios."}, {"numero": 11, "texto": "Agora conheço que o SENHOR é maior que todos os deuses, até naquilo em que se vangloriavam contra o povo."}, {"numero": 12, "texto": "E tomou Jetro, sogro de Moisés, holocaustos e sacrifícios para Deus: e veio Arão e todos os anciãos de Israel a comer pão com o sogro de Moisés diante de Deus."}, {"numero": 13, "texto": "E aconteceu que outro dia se sentou Moisés a julgar ao povo; e o povo esteve diante de Moisés desde a manhã até à tarde."}, {"numero": 14, "texto": "E vendo o sogro de Moisés tudo o que ele fazia com o povo, disse: Que é isto que fazes tu com o povo? por que te sentas tu sozinho, e todo o povo está diante de ti desde a manhã até à tarde?"}, {"numero": 15, "texto": "E Moisés respondeu a seu sogro: Porque o povo vem a mim para consultar a Deus:"}, {"numero": 16, "texto": "Quando têm negócios, vem a mim; e eu julgo entre o um e o outro, e declaro as ordenanças de Deus e suas leis."}, {"numero": 17, "texto": "Então o sogro de Moisés lhe disse: Não fazes bem:"}, {"numero": 18, "texto": "Desfalecerás de todo, tu, e também este povo que está contigo; porque o negócio é demasiado pesado para ti; não poderás fazê-lo tu sozinho."}, {"numero": 19, "texto": "Ouve agora minha voz; eu te aconselharei, e Deus será contigo. Está tu pelo povo diante de Deus, e traze tu os negócios a Deus."}, {"numero": 20, "texto": "E ensina a eles as ordenanças e as leis, e mostra-lhes o caminho por onde andem, e o que hão de fazer."}, {"numero": 21, "texto": "Ademais busca dentre todo o povo homens de virtude, temerosos de Deus, homens de verdade, que odeiem a ganância; e constituirás a estes sobre eles líderes sobre mil, sobre cem, sobre cinquenta e sobre dez."}, {"numero": 22, "texto": "Os quais julgarão ao povo ao todo tempo; e será que todo negócio grave o trarão a ti, e eles julgarão todo negócio pequeno: alivia assim a carga de sobre ti, e eles a levarão contigo."}, {"numero": 23, "texto": "Se isto fizeres, e Deus te o mandar, tu poderás persistir, e todo este povo se irá também em paz a seu lugar."}, {"numero": 24, "texto": "E ouviu Moisés a voz de seu sogro, e fez tudo o que disse."}, {"numero": 25, "texto": "E escolheu Moisés homens de virtude de todo Israel, e os pôs por chefes sobre o povo, líderes sobre mil, sobre cem, sobre cinquenta, e sobre dez."}, {"numero": 26, "texto": "E julgavam ao povo ao todo tempo; o negócio árduo traziam-no a Moisés, e eles julgavam todo negócio pequeno."}, {"numero": 27, "texto": "E despediu Moisés a seu sogro, e foi-se à sua terra."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 18, 'en', '[{"numero": 1, "texto": "When Jethro, the priest of Midian, Moses'' father in law, heard of all that God had done for Moses, and for Israel his people, and that the Lord had brought Israel out of Egypt;"}, {"numero": 2, "texto": "Then Jethro, Moses'' father in law, took Zipporah, Moses'' wife, after he had sent her back,"}, {"numero": 3, "texto": "And her two sons; of which the name of the one was Gershom; for he said, I have been an alien in a strange land:"}, {"numero": 4, "texto": "And the name of the other was Eliezer; for the God of my father, said he, was mine help, and delivered me from the sword of Pharaoh:"}, {"numero": 5, "texto": "And Jethro, Moses'' father in law, came with his sons and his wife unto Moses into the wilderness, where he encamped at the mount of God:"}, {"numero": 6, "texto": "And he said unto Moses, I thy father in law Jethro am come unto thee, and thy wife, and her two sons with her."}, {"numero": 7, "texto": "And Moses went out to meet his father in law, and did obeisance, and kissed him; and they asked each other of their welfare; and they came into the tent."}, {"numero": 8, "texto": "And Moses told his father in law all that the Lord had done unto Pharaoh and to the Egyptians for Israel''s sake, and all the travail that had come upon them by the way, and how the Lord delivered them."}, {"numero": 9, "texto": "And Jethro rejoiced for all the goodness which the Lord had done to Israel, whom he had delivered out of the hand of the Egyptians."}, {"numero": 10, "texto": "And Jethro said, Blessed be the Lord, who hath delivered you out of the hand of the Egyptians, and out of the hand of Pharaoh, who hath delivered the people from under the hand of the Egyptians."}, {"numero": 11, "texto": "Now I know that the Lord is greater than all gods: for in the thing wherein they dealt proudly he was above them."}, {"numero": 12, "texto": "And Jethro, Moses'' father in law, took a burnt offering and sacrifices for God: and Aaron came, and all the elders of Israel, to eat bread with Moses'' father in law before God."}, {"numero": 13, "texto": "And it came to pass on the morrow, that Moses sat to judge the people: and the people stood by Moses from the morning unto the evening."}, {"numero": 14, "texto": "And when Moses'' father in law saw all that he did to the people, he said, What is this thing that thou doest to the people? why sittest thou thyself alone, and all the people stand by thee from morning unto even?"}, {"numero": 15, "texto": "And Moses said unto his father in law, Because the people come unto me to enquire of God:"}, {"numero": 16, "texto": "When they have a matter, they come unto me; and I judge between one and another, and I do make them know the statutes of God, and his laws."}, {"numero": 17, "texto": "And Moses'' father in law said unto him, The thing that thou doest is not good."}, {"numero": 18, "texto": "Thou wilt surely wear away, both thou, and this people that is with thee: for this thing is too heavy for thee; thou art not able to perform it thyself alone."}, {"numero": 19, "texto": "Hearken now unto my voice, I will give thee counsel, and God shall be with thee: Be thou for the people to God-ward, that thou mayest bring the causes unto God:"}, {"numero": 20, "texto": "And thou shalt teach them ordinances and laws, and shalt shew them the way wherein they must walk, and the work that they must do."}, {"numero": 21, "texto": "Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and rulers of hundreds, rulers of fifties, and rulers of tens:"}, {"numero": 22, "texto": "And let them judge the people at all seasons: and it shall be, that every great matter they shall bring unto thee, but every small matter they shall judge: so shall it be easier for thyself, and they shall bear the burden with thee."}, {"numero": 23, "texto": "If thou shalt do this thing, and God command thee so, then thou shalt be able to endure, and all this people shall also go to their place in peace."}, {"numero": 24, "texto": "So Moses hearkened to the voice of his father in law, and did all that he had said."}, {"numero": 25, "texto": "And Moses chose able men out of all Israel, and made them heads over the people, rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens."}, {"numero": 26, "texto": "And they judged the people at all seasons: the hard causes they brought unto Moses, but every small matter they judged themselves."}, {"numero": 27, "texto": "And Moses let his father in law depart; and he went his way into his own land."}]'::jsonb, 'King James Version'),
  ('Ex', 18, 'fr', '[{"numero": 1, "texto": "Jéthro, sacrificateur de Madian, beau-père de Moïse, apprit tout ce que Dieu avait fait en faveur de Moïse et d''''Israël, son peuple; il apprit que l''''Eternel avait fait sortir Israël d''''Egypte."}, {"numero": 2, "texto": "Jéthro, beau-père de Moïse, prit Séphora, femme de Moïse, qui avait été renvoyée."}, {"numero": 3, "texto": "Il prit aussi les deux fils de Séphora; l''''un se nommait Guerschom, car Moïse avait dit: J''''habite un pays étranger;"}, {"numero": 4, "texto": "l''''autre se nommait Eliézer, car il avait dit: Le Dieu de mon père m''''a secouru, et il m''''a délivré de l''''épée de Pharaon."}, {"numero": 5, "texto": "Jéthro, beau-père de Moïse, avec les fils et la femme de Moïse, vint au désert où il campait, à la montagne de Dieu."}, {"numero": 6, "texto": "Il fit dire à Moïse: Moi, ton beau-père Jéthro, je viens vers toi, avec ta femme et ses deux fils."}, {"numero": 7, "texto": "Moïse sortit au-devant de son beau-père, il se prosterna, et il le baisa. Ils s''''informèrent réciproquement de leur santé, et ils entrèrent dans la tente de Moïse."}, {"numero": 8, "texto": "Moïse raconta à son beau-père tout ce que l''''Eternel avait fait à Pharaon et à l''''Egypte à cause d''''Israël, toutes les souffrances qui leur étaient survenues en chemin, et comment l''''Eternel les avait délivrés."}, {"numero": 9, "texto": "Jéthro se réjouit de tout le bien que l''''Eternel avait fait à Israël, et de ce qu''''il l''''avait délivré de la main des Egyptiens."}, {"numero": 10, "texto": "Et Jéthro dit: Béni soit l''''Eternel, qui vous a délivrés de la main des Egyptiens et de la main de Pharaon; qui a délivré le peuple de la main des Egyptiens!"}, {"numero": 11, "texto": "Je reconnais maintenant que l''''Eternel est plus grand que tous les dieux; car la méchanceté des Egyptiens est retombée sur eux."}, {"numero": 12, "texto": "Jéthro, beau-père de Moïse, offrit à Dieu un holocauste et des sacrifices. Aaron et tous les anciens d''''Israël vinrent participer au repas avec le beau-père de Moïse, en présence de Dieu."}, {"numero": 13, "texto": "Le lendemain, Moïse s''''assit pour juger le peuple, et le peuple se tint devant lui depuis le matin jusqu''''au soir."}, {"numero": 14, "texto": "Le beau-père de Moïse vit tout ce qu''''il faisait pour le peuple, et il dit: Que fais-tu là avec ce peuple? Pourquoi sièges-tu seul, et tout le peuple se tient-il devant toi, depuis le matin jusqu''''au soir?"}, {"numero": 15, "texto": "Moïse répondit à son beau-père: C''''est que le peuple vient à moi pour consulter Dieu."}, {"numero": 16, "texto": "Quand ils ont quelque affaire, ils viennent à moi; je prononce entre eux, et je fais connaître les ordonnances de Dieu et ses lois."}, {"numero": 17, "texto": "Le beau-père de Moïse lui dit: Ce que tu fais n''''est pas bien."}, {"numero": 18, "texto": "Tu t''''épuiseras toi-même, et tu épuiseras ce peuple qui est avec toi; car la chose est au-dessus de tes forces, tu ne pourras pas y suffire seul."}, {"numero": 19, "texto": "Maintenant écoute ma voix; je vais te donner un conseil, et que Dieu soit avec toi! Sois l''''interprète du peuple auprès de Dieu, et porte les affaires devant Dieu."}, {"numero": 20, "texto": "Enseigne-leur les ordonnances et les lois; et fais-leur connaître le chemin qu''''ils doivent suivre, et ce qu''''ils doivent faire."}, {"numero": 21, "texto": "Choisis parmi tout le peuple des hommes capables, craignant Dieu, des hommes intègres, ennemis de la cupidité; établis-les sur eux comme chefs de mille, chefs de cent, chefs de cinquante et chefs de dix."}, {"numero": 22, "texto": "Qu''''ils jugent le peuple en tout temps; qu''''ils portent devant toi toutes les affaires importantes, et qu''''ils prononcent eux-mêmes sur les petites causes. Allège ta charge, et qu''''ils la portent avec toi."}, {"numero": 23, "texto": "Si tu fais cela, et que Dieu te donne des ordres, tu pourras y suffire, et tout ce peuple parviendra heureusement à sa destination."}, {"numero": 24, "texto": "Moïse écouta la voix de son beau-père, et fit tout ce qu''''il avait dit."}, {"numero": 25, "texto": "Moïse choisit des hommes capables parmi tout Israël, et il les établit chefs du peuple, chefs de mille, chefs de cent, chefs de cinquante et chefs de dix."}, {"numero": 26, "texto": "Ils jugeaient le peuple en tout temps; ils portaient devant Moïse les affaires difficiles, et ils prononçaient eux-mêmes sur toutes les petites causes."}, {"numero": 27, "texto": "Moïse laissa partir son beau-père, et Jéthro s''''en alla dans son pays."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 18, 'es', '[{"numero": 1, "texto": "Y OYÓ Jethro, sacerdote de Madián, suegro de Moisés, todas las cosas que Dios había hecho con Moisés, y con Israel su pueblo, y cómo Jehová había sacado á Israel de Egipto:"}, {"numero": 2, "texto": "Y tomó Jethro, suegro de Moisés, á Séphora la mujer de Moisés, después que él la envió,"}, {"numero": 3, "texto": "Y á sus dos hijos; el uno se llamaba Gersom, porque dijo, Peregrino he sido en tierra ajena;"}, {"numero": 4, "texto": "Y el otro se llamaba Eliezer, porque dijo, El Dios de mi padre me ayudó, y me libró del cuchillo de Faraón."}, {"numero": 5, "texto": "Y Jethro, el suegro de Moisés, con sus hijos y su mujer, llegó á Moisés en el desierto, donde tenía el campo junto al monte de Dios;"}, {"numero": 6, "texto": "Y dijo á Moisés: Yo tu suegro Jethro vengo á ti, con tu mujer, y sus dos hijos con ella."}, {"numero": 7, "texto": "Y Moisés salió á recibir á su suegro, é inclinóse, y besólo: y preguntáronse el uno al otro cómo estaban, y vinieron á la tienda."}, {"numero": 8, "texto": "Y Moisés contó á su suegro todas las cosas que Jehová había hecho á Faraón y á los Egipcios por amor de Israel, y todo el trabajo que habían pasado en el camino, y cómo los había librado Jehová."}, {"numero": 9, "texto": "Y alegróse Jethro de todo el bien que Jehová había hecho á Israel, que lo había librado de mano de los Egipcios."}, {"numero": 10, "texto": "Y Jethro dijo: Bendito sea Jehová, que os libró de mano de los Egipcios, y de la mano de Faraón, y que libró al pueblo de la mano de los Egipcios."}, {"numero": 11, "texto": "Ahora conozco que Jehová es grande más que todos los dioses; hasta en lo que se ensoberbecieron contra ellos."}, {"numero": 12, "texto": "Y tomó Jethro, suegro de Moisés, holocaustos y sacrificios para Dios: y vino Aarón y todos los ancianos de Israel á comer pan con el suegro de Moisés delante de Dios."}, {"numero": 13, "texto": "Y aconteció que otro día se sentó Moisés á juzgar al pueblo; y el pueblo estuvo delante de Moisés desde la mañana hasta la tarde."}, {"numero": 14, "texto": "Y viendo el suegro de Moisés todo lo que él hacía con el pueblo, dijo: ¿Qué es esto que haces tú con el pueblo? ¿por qué te sientas tú solo, y todo el pueblo está delante de ti desde la mañana hasta la tarde?"}, {"numero": 15, "texto": "Y Moisés respondió á su suegro: Porque el pueblo viene á mí para consultar á Dios:"}, {"numero": 16, "texto": "Cuando tienen negocios, vienen á mí; y yo juzgo entre el uno y el otro, y declaro las ordenanzas de Dios y sus leyes."}, {"numero": 17, "texto": "Entonces el suegro de Moisés le dijo: No haces bien:"}, {"numero": 18, "texto": "Desfallecerás del todo, tú, y también este pueblo que está contigo; porque el negocio es demasiado pesado para ti; no podrás hacerlo tú solo."}, {"numero": 19, "texto": "Oye ahora mi voz, yo te aconsejaré, y Dios será contigo. Está tú por el pueblo delante de Dios, y somete tú los negocios á Dios."}, {"numero": 20, "texto": "Y enseña á ellos las ordenanzas y las leyes, y muéstrales el camino por donde anden, y lo que han de hacer."}, {"numero": 21, "texto": "Además inquiere tú de entre todo el pueblo varones de virtud, temerosos de Dios, varones de verdad, que aborrezcan la avaricia; y constituirás á éstos sobre ellos caporales sobre mil, sobre ciento, sobre cincuenta y sobre diez."}, {"numero": 22, "texto": "Los cuales juzgarán al pueblo en todo tiempo; y será que todo negocio grave lo traerán á ti, y ellos juzgarán todo negocio pequeño: alivia así la carga de sobre ti, y llevarla han ellos contigo."}, {"numero": 23, "texto": "Si esto hicieres, y Dios te lo mandare, tú podrás persistir, y todo este pueblo se irá también en paz á su lugar."}, {"numero": 24, "texto": "Y oyó Moisés la voz de su suegro, é hizo todo lo que dijo."}, {"numero": 25, "texto": "Y escogió Moisés varones de virtud de todo Israel, y púsolos por cabezas sobre el pueblo, caporales sobre mil, sobre ciento, sobre cincuenta, y sobre diez;"}, {"numero": 26, "texto": "Y juzgaban al pueblo en todo tiempo: el negocio arduo traíanlo á Moisés, y ellos juzgaban todo negocio pequeño."}, {"numero": 27, "texto": "Y despidió Moisés á su suegro, y fuése á su tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 19, 'pt', '[{"numero": 1, "texto": "Ao mês terceiro da saída dos filhos de Israel da terra do Egito, naquele dia vieram ao deserto de Sinai."}, {"numero": 2, "texto": "Porque partiram de Refidim, e chegaram ao deserto de Sinai, e assentaram no deserto; e acampou ali Israel diante do monte."}, {"numero": 3, "texto": "E Moisés subiu a Deus; e o SENHOR o chamou desde o monte, dizendo: Assim dirás à casa de Jacó, e anunciarás aos filhos de Israel:"}, {"numero": 4, "texto": "Vós vistes o que fiz aos egípcios, e como vos tomei sobre asas de águas, e vos trouxe a mim."}, {"numero": 5, "texto": "Agora pois, se deres ouvido à minha voz, e guardardes meu pacto, vós sereis meu especial tesouro sobre todos os povos; porque minha é toda a terra."}, {"numero": 6, "texto": "E vós sereis meu reino de sacerdotes, e gente santa. Estas são as palavras que dirás aos filhos de Israel."}, {"numero": 7, "texto": "Então veio Moisés, e chamou aos anciãos do povo, e propôs em presença deles todas estas palavras que o SENHOR lhe havia mandado."}, {"numero": 8, "texto": "E todo o povo respondeu em unidade, e disseram: Tudo o que o SENHOR disse faremos. E Moisés referiu as palavras do povo ao SENHOR."}, {"numero": 9, "texto": "E o SENHOR disse a Moisés: Eis que, eu venho a ti em uma nuvem espessa, para que o povo ouça enquanto eu falo contigo, e também para que te creiam para sempre. E Moisés anunciou as palavras do povo ao SENHOR."}, {"numero": 10, "texto": "E o SENHOR disse a Moisés: Vai ao povo, e santifica-os hoje e amanhã, e lavem suas roupas;"}, {"numero": 11, "texto": "E estejam prontos para o dia terceiro, porque ao terceiro dia o SENHOR descerá, à vista de todo o povo, sobre o monte de Sinai."}, {"numero": 12, "texto": "E assinalarás termo ao povo em derredor, dizendo: Guardai-vos, não subais ao monte, nem toqueis a seu termo: qualquer um que tocar o monte, certamente morrerá:"}, {"numero": 13, "texto": "Não lhe tocará mão, mas será apedrejado ou flechado; seja animal ou seja homem, não viverá. Em havendo soado longamente a trombeta, subirão ao monte."}, {"numero": 14, "texto": "E desceu Moisés do monte ao povo, e santificou ao povo; e lavaram suas roupas."}, {"numero": 15, "texto": "E disse ao povo: Estai prontos para o terceiro dia; não chegueis a mulher."}, {"numero": 16, "texto": "E aconteceu ao terceiro dia quando veio a manhã, que vieram trovões e relâmpagos, e espessa nuvem sobre o monte, e som de trombeta muito forte; e estremeceu-se todo o povo que estava no acampamento."}, {"numero": 17, "texto": "E Moisés tirou do acampamento ao povo a receber a Deus; e puseram-se ao abaixo do monte."}, {"numero": 18, "texto": "E todo o monte de Sinai fumegava, porque o SENHOR havia descido sobre ele em fogo: e a fumaça dele subia como a fumaça de um forno, e todo o monte se estremeceu em grande maneira."}, {"numero": 19, "texto": "E o som da trombeta ia fortalecendo-se em extremo: Moisés falava, e Deus lhe respondia em voz."}, {"numero": 20, "texto": "E desceu o SENHOR sobre o monte de Sinai, sobre o cume do monte: e chamou o SENHOR a Moisés ao cume do monte, e Moisés subiu."}, {"numero": 21, "texto": "E o SENHOR disse a Moisés: Desce, exige ao povo que não ultrapassem o termo para ver ao SENHOR, para que não caia multidão deles."}, {"numero": 22, "texto": "E também os sacerdotes que se achegam ao SENHOR, se santifiquem, para que o SENHOR não faça neles dano."}, {"numero": 23, "texto": "E Moisés disse ao SENHOR: O povo não poderá subir ao monte de Sinai, porque tu nos hás exigiste dizendo: Assinala termos ao monte, e santifica-o."}, {"numero": 24, "texto": "E o SENHOR lhe disse: Vai, desce, e subirás tu, e Arão contigo: mas os sacerdotes e o povo não ultrapassem o termo para subir ao SENHOR, para que não faça neles dano."}, {"numero": 25, "texto": "Então Moisés desceu ao povo e falou com eles."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 19, 'en', '[{"numero": 1, "texto": "In the third month, when the children of Israel were gone forth out of the land of Egypt, the same day came they into the wilderness of Sinai."}, {"numero": 2, "texto": "For they were departed from Rephidim, and were come to the desert of Sinai, and had pitched in the wilderness; and there Israel camped before the mount."}, {"numero": 3, "texto": "And Moses went up unto God, and the Lord called unto him out of the mountain, saying, Thus shalt thou say to the house of Jacob, and tell the children of Israel;"}, {"numero": 4, "texto": "Ye have seen what I did unto the Egyptians, and how I bare you on eagles'' wings, and brought you unto myself."}, {"numero": 5, "texto": "Now therefore, if ye will obey my voice indeed, and keep my covenant, then ye shall be a peculiar treasure unto me above all people: for all the earth is mine:"}, {"numero": 6, "texto": "And ye shall be unto me a kingdom of priests, and an holy nation. These are the words which thou shalt speak unto the children of Israel."}, {"numero": 7, "texto": "And Moses came and called for the elders of the people, and laid before their faces all these words which the Lord commanded him."}, {"numero": 8, "texto": "And all the people answered together, and said, All that the Lord hath spoken we will do. And Moses returned the words of the people unto the Lord."}, {"numero": 9, "texto": "And the Lord said unto Moses, Lo, I come unto thee in a thick cloud, that the people may hear when I speak with thee, and believe thee for ever. And Moses told the words of the people unto the Lord."}, {"numero": 10, "texto": "And the Lord said unto Moses, Go unto the people, and sanctify them to day and to morrow, and let them wash their clothes,"}, {"numero": 11, "texto": "And be ready against the third day: for the third day the Lord will come down in the sight of all the people upon mount Sinai."}, {"numero": 12, "texto": "And thou shalt set bounds unto the people round about, saying, Take heed to yourselves, that ye go not up into the mount, or touch the border of it: whosoever toucheth the mount shall be surely put to death:"}, {"numero": 13, "texto": "There shall not an hand touch it, but he shall surely be stoned, or shot through; whether it be beast or man, it shall not live: when the trumpet soundeth long, they shall come up to the mount."}, {"numero": 14, "texto": "And Moses went down from the mount unto the people, and sanctified the people; and they washed their clothes."}, {"numero": 15, "texto": "And he said unto the people, Be ready against the third day: come not at your wives."}, {"numero": 16, "texto": "And it came to pass on the third day in the morning, that there were thunders and lightnings, and a thick cloud upon the mount, and the voice of the trumpet exceeding loud; so that all the people that was in the camp trembled."}, {"numero": 17, "texto": "And Moses brought forth the people out of the camp to meet with God; and they stood at the nether part of the mount."}, {"numero": 18, "texto": "And mount Sinai was altogether on a smoke, because the Lord descended upon it in fire: and the smoke thereof ascended as the smoke of a furnace, and the whole mount quaked greatly."}, {"numero": 19, "texto": "And when the voice of the trumpet sounded long, and waxed louder and louder, Moses spake, and God answered him by a voice."}, {"numero": 20, "texto": "And the Lord came down upon mount Sinai, on the top of the mount: and the Lord called Moses up to the top of the mount; and Moses went up."}, {"numero": 21, "texto": "And the Lord said unto Moses, Go down, charge the people, lest they break through unto the Lord to gaze, and many of them perish."}, {"numero": 22, "texto": "And let the priests also, which come near to the Lord, sanctify themselves, lest the Lord break forth upon them."}, {"numero": 23, "texto": "And Moses said unto the Lord, The people cannot come up to mount Sinai: for thou chargedst us, saying, Set bounds about the mount, and sanctify it."}, {"numero": 24, "texto": "And the Lord said unto him, Away, get thee down, and thou shalt come up, thou, and Aaron with thee: but let not the priests and the people break through to come up unto the Lord, lest he break forth upon them."}, {"numero": 25, "texto": "So Moses went down unto the people, and spake unto them."}]'::jsonb, 'King James Version'),
  ('Ex', 19, 'fr', '[{"numero": 1, "texto": "Le troisième mois après leur sortie du pays d''''Egypte, les enfants d''''Israël arrivèrent ce jour-là au désert de Sinaï."}, {"numero": 2, "texto": "Etant partis de Rephidim, ils arrivèrent au désert de Sinaï, et ils campèrent dans le désert; Israël campa là, vis-à-vis de la montagne."}, {"numero": 3, "texto": "Moïse monta vers Dieu: et l''''Eternel l''''appela du haut de la montagne, en disant: Tu parleras ainsi à la maison de Jacob, et tu diras aux enfants d''''Israël:"}, {"numero": 4, "texto": "Vous avez vu ce que j''''ai fait à l''''Egypte, et comment je vous ai portés sur des ailes d''''aigle et amenés vers moi."}, {"numero": 5, "texto": "Maintenant, si vous écoutez ma voix, et si vous gardez mon alliance, vous m''''appartiendrez entre tous les peuples, car toute la terre est à moi;"}, {"numero": 6, "texto": "vous serez pour moi un royaume de sacrificateurs et une nation sainte. Voilà les paroles que tu diras aux enfants d''''Israël."}, {"numero": 7, "texto": "Moïse vint appeler les anciens du peuple, et il mit devant eux toutes ces paroles, comme l''''Eternel le lui avait ordonné."}, {"numero": 8, "texto": "Le peuple tout entier répondit: Nous ferons tout ce que l''''Eternel a dit. Moïse rapporta les paroles du peuple à l''''Eternel."}, {"numero": 9, "texto": "Et l''''Eternel dit à Moïse: Voici, je viendrai vers toi dans une épaisse nuée, afin que le peuple entende quand je te parlerai, et qu''''il ait toujours confiance en toi. Moïse rapporta les paroles du peuple à l''''Eternel."}, {"numero": 10, "texto": "Et l''''Eternel dit à Moïse: Va vers le peuple; sanctifie-les aujourd''''hui et demain, qu''''ils lavent leurs vêtements."}, {"numero": 11, "texto": "Qu''''ils soient prêts pour le troisième jour; car le troisième jour l''''Eternel descendra, aux yeux de tout le peuple, sur la montagne de Sinaï."}, {"numero": 12, "texto": "Tu fixeras au peuple des limites tout à l''''entour, et tu diras: Gardez-vous de monter sur la montagne, ou d''''en toucher le bord. Quiconque touchera la montagne sera puni de mort."}, {"numero": 13, "texto": "On ne mettra pas la main sur lui, mais on le lapidera, ou on le percera de flèches: animal ou homme, il ne vivra point. Quand la trompette sonnera, ils s''''avanceront près de la montagne."}, {"numero": 14, "texto": "Moïse descendit de la montagne vers le peuple; il sanctifia le peuple, et ils lavèrent leurs vêtements."}, {"numero": 15, "texto": "Et il dit au peuple: Soyez prêts dans trois jours; ne vous approchez d''''aucune femme."}, {"numero": 16, "texto": "Le troisième jour au matin, il y eut des tonnerres, des éclairs, et une épaisse nuée sur la montagne; le son de la trompette retentit fortement; et tout le peuple qui était dans le camp fut saisi d''''épouvante."}, {"numero": 17, "texto": "Moïse fit sortir le peuple du camp, à la rencontre de Dieu; et ils se placèrent au bas de la montagne."}, {"numero": 18, "texto": "La montagne de Sinaï était toute en fumée, parce que l''''Eternel y était descendu au milieu du feu; cette fumée s''''élevait comme la fumée d''''une fournaise, et toute la montagne tremblait avec violence."}, {"numero": 19, "texto": "Le son de la trompette retentissait de plus en plus fortement. Moïse parlait, et Dieu lui répondait à haute voix."}, {"numero": 20, "texto": "Ainsi l''''Eternel descendit sur la montagne de Sinaï, sur le sommet de la montagne; l''''Eternel appela Moïse sur le sommet de la montagne. Et Moïse monta."}, {"numero": 21, "texto": "L''''Eternel dit à Moïse: Descends, fais au peuple la défense expresse de se précipiter vers l''''Eternel, pour regarder, de peur qu''''un grand nombre d''''entre eux ne périssent."}, {"numero": 22, "texto": "Que les sacrificateurs, qui s''''approchent de l''''Eternel, se sanctifient aussi, de peur que l''''Eternel ne les frappe de mort."}, {"numero": 23, "texto": "Moïse dit à l''''Eternel: Le peuple ne pourra pas monter sur la montagne de Sinaï, car tu nous en as fait la défense expresse, en disant: Fixe des limites autour de la montagne, et sanctifie-la."}, {"numero": 24, "texto": "L''''Eternel lui dit: Va, descends; tu monteras ensuite avec Aaron; mais que les sacrificateurs et le peuple ne se précipitent point pour monter vers l''''Eternel, de peur qu''''il ne les frappe de mort."}, {"numero": 25, "texto": "Moïse descendit vers le peuple, et lui dit ces choses."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 19, 'es', '[{"numero": 1, "texto": "AL mes tercero de la salida de los hijos de Israel de la tierra de Egipto, en aquel día vinieron al desierto de Sinaí."}, {"numero": 2, "texto": "Porque partieron de Rephidim, y llegaron al desierto de Sinaí, y asentaron en el desierto; y acampó allí Israel delante del monte."}, {"numero": 3, "texto": "Y Moisés subió á Dios; y Jehová lo llamó desde el monte, diciendo: Así dirás á la casa de Jacob, y denunciarás á los hijos de Israel:"}, {"numero": 4, "texto": "Vosotros visteis lo que hice á los Egipcios, y cómo os tomé sobre alas de águilas, y os he traído á mí."}, {"numero": 5, "texto": "Ahora pues, si diereis oído á mi voz, y guardareis mi pacto, vosotros seréis mi especial tesoro sobre todos los pueblos; porque mía es toda la tierra."}, {"numero": 6, "texto": "Y vosotros seréis mi reino de sacerdotes, y gente santa. Estas son las palabras que dirás á los hijos de Israel."}, {"numero": 7, "texto": "Entonces vino Moisés, y llamó á los ancianos del pueblo, y propuso en presencia de ellos todas estas palabras que Jehová le había mandado."}, {"numero": 8, "texto": "Y todo el pueblo respondió á una, y dijeron: Todo lo que Jehová ha dicho haremos. Y Moisés refirió las palabras del pueblo á Jehová."}, {"numero": 9, "texto": "Y Jehová dijo á Moisés: He aquí, yo vengo á ti en una nube espesa, para que el pueblo oiga mientras yo hablo contigo, y también para que te crean para siempre. Y Moisés denunció las palabras del pueblo á Jehová."}, {"numero": 10, "texto": "Y Jehová dijo á Moisés: Ve al pueblo, y santifícalos hoy y mañana, y laven sus vestidos;"}, {"numero": 11, "texto": "Y estén apercibidos para el día tercero, porque al tercer día Jehová descenderá, á ojos de todo el pueblo, sobre el monte de Sinaí."}, {"numero": 12, "texto": "Y señalarás término al pueblo en derredor, diciendo: Guardaos, no subáis al monte, ni toquéis á su término: cualquiera que tocare el monte, de seguro morirá:"}, {"numero": 13, "texto": "No le tocará mano, mas será apedreado ó asaeteado; sea animal ó sea hombre, no vivirá. En habiendo sonado largamente la bocina, subirán al monte."}, {"numero": 14, "texto": "Y descendió Moisés del monte al pueblo, y santificó al pueblo; y lavaron sus vestidos."}, {"numero": 15, "texto": "Y dijo al pueblo: Estad apercibidos para el tercer día; no lleguéis á mujer."}, {"numero": 16, "texto": "Y aconteció al tercer día cuando vino la mañana, que vinieron truenos y relámpagos, y espesa nube sobre el monte, y sonido de bocina muy fuerte; y estremecióse todo el pueblo que estaba en el real."}, {"numero": 17, "texto": "Y Moisés sacó del real al pueblo á recibir á Dios; y pusiéronse á lo bajo del monte."}, {"numero": 18, "texto": "Y todo el monte de Sinaí humeaba, porque Jehová había descendido sobre él en fuego: y el humo de él subía como el humo de un horno, y todo el monte se estremeció en gran manera."}, {"numero": 19, "texto": "Y el sonido de la bocina iba esforzándose en extremo: Moisés hablaba, y Dios le respondía en voz."}, {"numero": 20, "texto": "Y descendió Jehová sobre el monte de Sinaí, sobre la cumbre del monte: y llamó Jehová á Moisés á la cumbre del monte, y Moisés subió."}, {"numero": 21, "texto": "Y Jehová dijo á Moisés: Desciende, requiere al pueblo que no traspasen el término por ver á Jehová, porque caerá multitud de ellos."}, {"numero": 22, "texto": "Y también los sacerdotes que se llegan á Jehová, se santifiquen, porque Jehová no haga en ellos estrago."}, {"numero": 23, "texto": "Y Moisés dijo á Jehová: El pueblo no podrá subir al monte de Sinaí, porque tú nos has requerido diciendo: Señala términos al monte, y santifícalo."}, {"numero": 24, "texto": "Y Jehová le dijo: Ve, desciende, y subirás tú, y Aarón contigo: mas los sacerdotes y el pueblo no traspasen el término por subir á Jehová, porque no haga en ellos estrago."}, {"numero": 25, "texto": "Entonces Moisés descendió al pueblo, y habló con ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 20, 'pt', '[{"numero": 1, "texto": "E falou Deus todas estas palavras, dizendo:"}, {"numero": 2, "texto": "Eu sou o SENHOR teu Deus, que te tirei da terra do Egito, de casa de servos."}, {"numero": 3, "texto": "Não terás deuses alheios diante de mim."}, {"numero": 4, "texto": "Não te farás imagem, nem nenhuma semelhança de coisa que esteja acima no céu, nem abaixo na terra, nem nas águas debaixo da terra:"}, {"numero": 5, "texto": "Não te inclinarás a elas, nem as honrarás; porque eu sou o SENHOR teu Deus, forte, zeloso, que visito a maldade dos pais sobre os filhos, sobre os terceiros e sobre os quartos, aos que me aborrecem,"}, {"numero": 6, "texto": "E que faço misericórdia em milhares aos que me amam, e guardam meus mandamentos."}, {"numero": 7, "texto": "Não tomarás o nome do SENHOR teu Deus em vão; porque não dará por inocente o SENHOR ao que tomar seu nome em vão."}, {"numero": 8, "texto": "Tu te lembrarás do dia do repouso, para santificá-lo:"}, {"numero": 9, "texto": "Seis dias trabalharás, e farás toda tua obra;"}, {"numero": 10, "texto": "Mas o sétimo dia será repouso para o SENHOR teu Deus: não faças nele obra alguma, tu, nem teu filho, nem tua filha, nem teu servo, nem tua criada, nem teu animal, nem teu estrangeiro que está dentro de tuas portas:"}, {"numero": 11, "texto": "Porque em seis dias fez o SENHOR os céus e a terra, o mar e todas as coisas que neles há, e repousou no sétimo dia: portanto o SENHOR abençoou o dia do repouso e o santificou."}, {"numero": 12, "texto": "Honra a teu pai e a tua mãe, para que teus dias se alarguem na terra que o SENHOR teu Deus te dá."}, {"numero": 13, "texto": "Não cometerás homicídio."}, {"numero": 14, "texto": "Não cometerás adultério."}, {"numero": 15, "texto": "Não furtarás."}, {"numero": 16, "texto": "Não falarás contra teu próximo falso testemunho."}, {"numero": 17, "texto": "Não cobiçarás a casa de teu próximo, não cobiçarás a mulher de teu próximo, nem seu servo, nem sua criada, nem seu boi, nem seu asno, nem coisa alguma de teu próximo."}, {"numero": 18, "texto": "Todo o povo considerava as vozes, e as chamas, e o som da trombeta, e o monte que fumegava: e vendo-o o povo, tremeram, e puseram-se de longe."}, {"numero": 19, "texto": "E disseram a Moisés: Fala tu conosco, que nós ouviremos; mas não fale Deus conosco, para que não morramos."}, {"numero": 20, "texto": "E Moisés respondeu ao povo: Não temais; que para provar-vos veio Deus, e para que seu temor esteja em vossa presença para que não pequeis."}, {"numero": 21, "texto": "Então o povo se pôs de longe, e Moisés se chegou à escuridão na qual estava Deus."}, {"numero": 22, "texto": "E o SENHOR disse a Moisés: Assim dirás aos filhos de Israel: Vós vistes que falei desde o céu convosco."}, {"numero": 23, "texto": "Não façais comigo deuses de prata, nem deuses de ouro vos fareis."}, {"numero": 24, "texto": "Da terra farás altar para mim, e sacrificarás sobre ele teus holocaustos e tuas ofertas pacíficas, tuas ovelhas e tuas vacas: em qualquer lugar onde eu fizer que esteja a memória de meu nome, virei a ti, e te abençoarei."}, {"numero": 25, "texto": "E se me fizeres altar de pedras, não as faças lavradas; porque se levantares teu buril sobre ele, tu o profanarás."}, {"numero": 26, "texto": "E não subirás por degraus a meu altar, para que tua nudez não seja junto a ele descoberta."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 20, 'en', '[{"numero": 1, "texto": "And God spake all these words, saying,"}, {"numero": 2, "texto": "I am the Lord thy God, which have brought thee out of the land of Egypt, out of the house of bondage."}, {"numero": 3, "texto": "Thou shalt have no other gods before me."}, {"numero": 4, "texto": "Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth."}, {"numero": 5, "texto": "Thou shalt not bow down thyself to them, nor serve them: for I the Lord thy God am a jealous God, visiting the iniquity of the fathers upon the children unto the third and fourth generation of them that hate me;"}, {"numero": 6, "texto": "And shewing mercy unto thousands of them that love me, and keep my commandments."}, {"numero": 7, "texto": "Thou shalt not take the name of the Lord thy God in vain; for the Lord will not hold him guiltless that taketh his name in vain."}, {"numero": 8, "texto": "Remember the sabbath day, to keep it holy."}, {"numero": 9, "texto": "Six days shalt thou labour, and do all thy work:"}, {"numero": 10, "texto": "But the seventh day is the sabbath of the Lord thy God: in it thou shalt not do any work, thou, nor thy son, nor thy daughter, thy manservant, nor thy maidservant, nor thy cattle, nor thy stranger that is within thy gates:"}, {"numero": 11, "texto": "For in six days the Lord made heaven and earth, the sea, and all that in them is, and rested the seventh day: wherefore the Lord blessed the sabbath day, and hallowed it."}, {"numero": 12, "texto": "Honour thy father and thy mother: that thy days may be long upon the land which the Lord thy God giveth thee."}, {"numero": 13, "texto": "Thou shalt not kill."}, {"numero": 14, "texto": "Thou shalt not commit adultery."}, {"numero": 15, "texto": "Thou shalt not steal."}, {"numero": 16, "texto": "Thou shalt not bear false witness against thy neighbour."}, {"numero": 17, "texto": "Thou shalt not covet thy neighbour''s house, thou shalt not covet thy neighbour''s wife, nor his manservant, nor his maidservant, nor his ox, nor his ass, nor any thing that is thy neighbour''s."}, {"numero": 18, "texto": "And all the people saw the thunderings, and the lightnings, and the noise of the trumpet, and the mountain smoking: and when the people saw it, they removed, and stood afar off."}, {"numero": 19, "texto": "And they said unto Moses, Speak thou with us, and we will hear: but let not God speak with us, lest we die."}, {"numero": 20, "texto": "And Moses said unto the people, Fear not: for God is come to prove you, and that his fear may be before your faces, that ye sin not."}, {"numero": 21, "texto": "And the people stood afar off, and Moses drew near unto the thick darkness where God was."}, {"numero": 22, "texto": "And the Lord said unto Moses, Thus thou shalt say unto the children of Israel, Ye have seen that I have talked with you from heaven."}, {"numero": 23, "texto": "Ye shall not make with me gods of silver, neither shall ye make unto you gods of gold."}, {"numero": 24, "texto": "An altar of earth thou shalt make unto me, and shalt sacrifice thereon thy burnt offerings, and thy peace offerings, thy sheep, and thine oxen: in all places where I record my name I will come unto thee, and I will bless thee."}, {"numero": 25, "texto": "And if thou wilt make me an altar of stone, thou shalt not build it of hewn stone: for if thou lift up thy tool upon it, thou hast polluted it."}, {"numero": 26, "texto": "Neither shalt thou go up by steps unto mine altar, that thy nakedness be not discovered thereon."}]'::jsonb, 'King James Version'),
  ('Ex', 20, 'fr', '[{"numero": 1, "texto": "Alors Dieu prononça toutes ces paroles, en disant:"}, {"numero": 2, "texto": "Je suis l''''Eternel, ton Dieu, qui t''''ai fait sortir du pays d''''Egypte, de la maison de servitude."}, {"numero": 3, "texto": "Tu n''''auras pas d''''autres dieux devant ma face."}, {"numero": 4, "texto": "Tu ne te feras point d''''image taillée, ni de représentation quelconque des choses qui sont en haut dans les cieux, qui sont en bas sur la terre, et qui sont dans les eaux plus bas que la terre."}, {"numero": 5, "texto": "Tu ne te prosterneras point devant elles, et tu ne les serviras point; car moi, l''''Eternel, ton Dieu, je suis un Dieu jaloux, qui punis l''''iniquité des pères sur les enfants jusqu''''à la troisième et la quatrième génération de ceux qui me haïssent,"}, {"numero": 6, "texto": "et qui fais miséricorde jusqu''''en mille générations à ceux qui m''''aiment et qui gardent mes commandements."}, {"numero": 7, "texto": "Tu ne prendras point le nom de l''''Eternel, ton Dieu, en vain; car l''''Eternel ne laissera point impuni celui qui prendra son nom en vain."}, {"numero": 8, "texto": "Souviens-toi du jour du repos, pour le sanctifier."}, {"numero": 9, "texto": "Tu travailleras six jours, et tu feras tout ton ouvrage."}, {"numero": 10, "texto": "Mais le septième jour est le jour du repos de l''''Eternel, ton Dieu: tu ne feras aucun ouvrage, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bétail, ni l''''étranger qui est dans tes portes."}, {"numero": 11, "texto": "Car en six jours l''''Eternel a fait les cieux, la terre et la mer, et tout ce qui y est contenu, et il s''''est reposé le septième jour: c''''est pourquoi l''''Eternel a béni le jour du repos et l''''a sanctifié."}, {"numero": 12, "texto": "Honore ton père et ta mère, afin que tes jours se prolongent dans le pays que l''''Eternel, ton Dieu, te donne."}, {"numero": 13, "texto": "Tu ne tueras point."}, {"numero": 14, "texto": "Tu ne commettras point d''''adultère."}, {"numero": 15, "texto": "Tu ne déroberas point."}, {"numero": 16, "texto": "Tu ne porteras point de faux témoignage contre ton prochain."}, {"numero": 17, "texto": "Tu ne convoiteras point la maison de ton prochain; tu ne convoiteras point la femme de ton prochain, ni son serviteur, ni sa servante, ni son boeuf, ni son âne, ni aucune chose qui appartienne à ton prochain."}, {"numero": 18, "texto": "Tout le peuple entendait les tonnerres et le son de la trompette; il voyait les flammes de la montagne fumante. A ce spectacle, le peuple tremblait, et se tenait dans l''''éloignement."}, {"numero": 19, "texto": "Ils dirent à Moïse: Parle-nous toi-même, et nous écouterons; mais que Dieu ne nous parle point, de peur que nous ne mourions."}, {"numero": 20, "texto": "Moïse dit au peuple: Ne vous effrayez pas; car c''''est pour vous mettre à l''''épreuve que Dieu est venu, et c''''est pour que vous ayez sa crainte devant les yeux, afin que vous ne péchiez point."}, {"numero": 21, "texto": "Le peuple restait dans l''''éloignement; mais Moïse s''''approcha de la nuée où était Dieu."}, {"numero": 22, "texto": "L''''Eternel dit à Moïse: Tu parleras ainsi aux enfants d''''Israël: Vous avez vu que je vous ai parlé depuis les cieux."}, {"numero": 23, "texto": "Vous ne ferez point des dieux d''''argent et des dieux d''''or, pour me les associer; vous ne vous en ferez point."}, {"numero": 24, "texto": "Tu m''''élèveras un autel de terre, sur lequel tu offriras tes holocaustes et tes sacrifices d''''actions de grâces, tes brebis et tes boeufs. Partout où je rappellerai mon nom, je viendrai à toi, et je te bénirai."}, {"numero": 25, "texto": "Si tu m''''élèves un autel de pierre, tu ne le bâtiras point en pierres taillées; car en passant ton ciseau sur la pierre, tu la profanerais."}, {"numero": 26, "texto": "Tu ne monteras point à mon autel par des degrés, afin que ta nudité ne soit pas découverte."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 20, 'es', '[{"numero": 1, "texto": "Y HABLÓ Dios todas estas palabras, diciendo:"}, {"numero": 2, "texto": "Yo soy JEHOVÁ tu Dios, que te saqué de la tierra de Egipto, de casa de siervos."}, {"numero": 3, "texto": "No tendrás dioses ajenos delante de mí."}, {"numero": 4, "texto": "No te harás imagen, ni ninguna semejanza de cosa que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra:"}, {"numero": 5, "texto": "No te inclinarás á ellas, ni las honrarás; porque yo soy Jehová tu Dios, fuerte, celoso, que visito la maldad de los padres sobre los hijos, sobre los terceros y sobre los cuartos, á los que me aborrecen,"}, {"numero": 6, "texto": "Y que hago misericordia en millares á los que me aman, y guardan mis mandamientos."}, {"numero": 7, "texto": "No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano."}, {"numero": 8, "texto": "Acordarte has del día del reposo, para santificarlo:"}, {"numero": 9, "texto": "Seis días trabajarás, y harás toda tu obra;"}, {"numero": 10, "texto": "Mas el séptimo día será reposo para Jehová tu Dios: no hagas en él obra alguna, tú, ni tu hijo, ni tu hija, ni tu siervo, ni tu criada ni tu bestia, ni tu extranjero que está dentro de tus puertas:"}, {"numero": 11, "texto": "Porque en seis días hizo Jehová los cielos y la tierra, la mar y todas las cosas que en ellos hay, y reposó en el séptimo día: por tanto Jehová bendijo el día del reposo y lo santificó."}, {"numero": 12, "texto": "Honra á tu padre y á tu madre, porque tus días se alarguen en la tierra que Jehová tu Dios te da."}, {"numero": 13, "texto": "No matarás."}, {"numero": 14, "texto": "No cometerás adulterio."}, {"numero": 15, "texto": "No hurtarás."}, {"numero": 16, "texto": "No hablarás contra tu prójimo falso testimonio."}, {"numero": 17, "texto": "No codiciarás la casa de tu prójimo, no codiciarás la mujer de tu prójimo, ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo."}, {"numero": 18, "texto": "Todo el pueblo consideraba las voces, y las llamas, y el sonido de la bocina, y el monte que humeaba: y viéndolo el pueblo, temblaron, y pusiéronse de lejos."}, {"numero": 19, "texto": "Y dijeron á Moisés: Habla tú con nosotros, que nosotros oiremos; mas no hable Dios con nosotros, porque no muramos."}, {"numero": 20, "texto": "Y Moisés respondió al pueblo: No temáis; que por probaros vino Dios, y porque su temor esté en vuestra presencia para que no pequéis."}, {"numero": 21, "texto": "Entonces el pueblo se puso de lejos, y Moisés se llegó á la osbcuridad, en la cual estaba Dios."}, {"numero": 22, "texto": "Y Jehová dijo á Moisés: Así dirás á los hijos de Israel: Vosotros habéis visto que he hablado desde el cielo con vosotros."}, {"numero": 23, "texto": "No hagáis conmigo dioses de plata, ni dioses de oro os haréis."}, {"numero": 24, "texto": "Altar de tierra harás para mí, y sacrificarás sobre él tus holocaustos y tus pacíficos, tus ovejas y tus vacas: en cualquier lugar donde yo hiciere que esté la memoria de mi nombre, vendré á ti, y te bendeciré."}, {"numero": 25, "texto": "Y si me hicieres altar de piedras, no las labres de cantería; porque si alzares tu pico sobre él, tú lo profanarás."}, {"numero": 26, "texto": "Y no subirás por gradas á mi altar, porque tu desnudez no sea junto á él descubierta."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 24, 'pt', '[{"numero": 1, "texto": "E disse a Moisés: Sobe ao SENHOR, tu, e Arão, Nadabe, e Abiú, e setenta dos anciãos de Israel; e vos inclinareis desde longe."}, {"numero": 2, "texto": "Mas Moisés somente se chegará ao SENHOR; e eles não se aproximem, nem suba com ele o povo."}, {"numero": 3, "texto": "E Moisés veio e contou ao povo todas as palavras do SENHOR, e todos os estatutos: e todo o povo respondeu em uma voz, e disseram: Executaremos todas as palavras que o SENHOR disse."}, {"numero": 4, "texto": "E Moisés escreveu todas as palavras do SENHOR, e levantando-se de manhã edificou um altar ao pé do monte, e doze colunas, segundo as doze tribos de Israel."}, {"numero": 5, "texto": "E enviou aos rapazes dos filhos de Israel, os quais ofereceram holocaustos e sacrificaram pacíficos ao SENHOR, bezerros."}, {"numero": 6, "texto": "E Moisés tomou a metade do sangue, e a pôs em bacias, e espargiu a outra metade do sangue sobre o altar."}, {"numero": 7, "texto": "E tomou o livro da aliança, e leu aos ouvidos do povo, o qual disse: Faremos todas as coisas que o SENHOR disse, e obedeceremos."}, {"numero": 8, "texto": "Então Moisés tomou o sangue, e salpicou sobre o povo, e disse: Eis o sangue da aliança que o SENHOR fez convosco sobre todas estas coisas."}, {"numero": 9, "texto": "E subiram Moisés e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel;"}, {"numero": 10, "texto": "E viram ao Deus de Israel; e havia debaixo de seus pés como um pavimento de safira, semelhante ao céu quando está claro."}, {"numero": 11, "texto": "Mas não estendeu sua mão sobre os príncipes dos filhos de Israel: e viram a Deus, e comeram e beberam."}, {"numero": 12, "texto": "Então o SENHOR disse a Moisés: Sobe a mim ao monte, e espera ali, e te darei tábuas de pedra, e a lei, e mandamentos que escrevi para ensiná-los."}, {"numero": 13, "texto": "E levantou-se Moisés, e Josué seu assistente; e Moisés subiu ao monte de Deus."}, {"numero": 14, "texto": "E disse aos anciãos: Esperai-nos aqui até que voltemos a vós: e eis que Arão e Hur estão convosco: o que tiver negócios chegue-se a eles."}, {"numero": 15, "texto": "Então Moisés subiu ao monte, e uma nuvem cobriu o monte."}, {"numero": 16, "texto": "E a glória do SENHOR repousou sobre o monte Sinai, e a nuvem o cobriu por seis dias: e ao sétimo dia chamou a Moisés do meio da nuvem."}, {"numero": 17, "texto": "E a aparência da glória do SENHOR era como um fogo abrasador no cume do monte, aos olhos dos filhos de Israel."}, {"numero": 18, "texto": "E entrou Moisés em meio da nuvem, e subiu ao monte: e esteve Moisés no monte quarenta dias e quarenta noites."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 24, 'en', '[{"numero": 1, "texto": "And he said unto Moses, Come up unto the Lord, thou, and Aaron, Nadab, and Abihu, and seventy of the elders of Israel; and worship ye afar off."}, {"numero": 2, "texto": "And Moses alone shall come near the Lord: but they shall not come nigh; neither shall the people go up with him."}, {"numero": 3, "texto": "And Moses came and told the people all the words of the Lord, and all the judgments: and all the people answered with one voice, and said, All the words which the Lord hath said will we do."}, {"numero": 4, "texto": "And Moses wrote all the words of the Lord, and rose up early in the morning, and builded an altar under the hill, and twelve pillars, according to the twelve tribes of Israel."}, {"numero": 5, "texto": "And he sent young men of the children of Israel, which offered burnt offerings, and sacrificed peace offerings of oxen unto the Lord."}, {"numero": 6, "texto": "And Moses took half of the blood, and put it in basons; and half of the blood he sprinkled on the altar."}, {"numero": 7, "texto": "And he took the book of the covenant, and read in the audience of the people: and they said, All that the Lord hath said will we do, and be obedient."}, {"numero": 8, "texto": "And Moses took the blood, and sprinkled it on the people, and said, Behold the blood of the covenant, which the Lord hath made with you concerning all these words."}, {"numero": 9, "texto": "Then went up Moses, and Aaron, Nadab, and Abihu, and seventy of the elders of Israel:"}, {"numero": 10, "texto": "And they saw the God of Israel: and there was under his feet as it were a paved work of a sapphire stone, and as it were the body of heaven in his clearness."}, {"numero": 11, "texto": "And upon the nobles of the children of Israel he laid not his hand: also they saw God, and did eat and drink."}, {"numero": 12, "texto": "And the Lord said unto Moses, Come up to me into the mount, and be there: and I will give thee tables of stone, and a law, and commandments which I have written; that thou mayest teach them."}, {"numero": 13, "texto": "And Moses rose up, and his minister Joshua: and Moses went up into the mount of God."}, {"numero": 14, "texto": "And he said unto the elders, Tarry ye here for us, until we come again unto you: and, behold, Aaron and Hur are with you: if any man have any matters to do, let him come unto them."}, {"numero": 15, "texto": "And Moses went up into the mount, and a cloud covered the mount."}, {"numero": 16, "texto": "And the glory of the Lord abode upon mount Sinai, and the cloud covered it six days: and the seventh day he called unto Moses out of the midst of the cloud."}, {"numero": 17, "texto": "And the sight of the glory of the Lord was like devouring fire on the top of the mount in the eyes of the children of Israel."}, {"numero": 18, "texto": "And Moses went into the midst of the cloud, and gat him up into the mount: and Moses was in the mount forty days and forty nights."}]'::jsonb, 'King James Version'),
  ('Ex', 24, 'fr', '[{"numero": 1, "texto": "Dieu dit à Moïse: Monte vers l''''Eternel, toi et Aaron, Nadab et Abihu, et soixante-dix des anciens d''''Israël, et vous vous prosternerez de loin."}, {"numero": 2, "texto": "Moïse s''''approchera seul de l''''Eternel; les autres ne s''''approcheront pas, et le peuple ne montera point avec lui."}, {"numero": 3, "texto": "Moïse vint rapporter au peuple toutes les paroles de l''''Eternel et toutes les lois. Le peuple entier répondit d''''une même voix: Nous ferons tout ce que l''''Eternel a dit."}, {"numero": 4, "texto": "Moïse écrivit toutes les paroles de l''''Eternel. Puis il se leva de bon matin; il bâtit un autel au pied de la montagne, et dressa douze pierres pour les douze tribus d''''Israël."}, {"numero": 5, "texto": "Il envoya des jeunes hommes, enfants d''''Israël, pour offrir à l''''Eternel des holocaustes, et immoler des taureaux en sacrifices d''''actions de grâces."}, {"numero": 6, "texto": "Moïse prit la moitié du sang, qu''''il mit dans des bassins, et il répandit l''''autre moitié sur l''''autel."}, {"numero": 7, "texto": "Il prit le livre de l''''alliance, et le lut en présence du peuple; ils dirent: Nous ferons tout ce que l''''Eternel a dit, et nous obéirons."}, {"numero": 8, "texto": "Moïse prit le sang, et il le répandit sur le peuple, en disant: Voici le sang de l''''alliance que l''''Eternel a faite avec vous selon toutes ces paroles."}, {"numero": 9, "texto": "Moïse monta avec Aaron, Nadab et Abihu, et soixante-dix anciens d''''Israël."}, {"numero": 10, "texto": "Ils virent le Dieu d''''Israël; sous ses pieds, c''''était comme un ouvrage de saphir transparent, comme le ciel lui-même dans sa pureté."}, {"numero": 11, "texto": "Il n''''étendit point sa main sur l''''élite des enfants d''''Israël. Ils virent Dieu, et ils mangèrent et burent."}, {"numero": 12, "texto": "L''''Eternel dit à Moïse: Monte vers moi sur la montagne, et reste là; je te donnerai des tables de pierre, la loi et les ordonnances que j''''ai écrites pour leur instruction."}, {"numero": 13, "texto": "Moïse se leva, avec Josué qui le servait, et Moïse monta sur la montagne de Dieu."}, {"numero": 14, "texto": "Il dit aux anciens: Attendez-nous ici, jusqu''''à ce que nous revenions auprès de vous. Voici, Aaron et Hur resteront avec vous; si quelqu''''un a un différend, c''''est à eux qu''''il s''''adressera."}, {"numero": 15, "texto": "Moïse monta sur la montagne, et la nuée couvrit la montagne."}, {"numero": 16, "texto": "La gloire de l''''Eternel reposa sur la montagne de Sinaï, et la nuée la couvrit pendant six jours. Le septième jour, l''''Eternel appela Moïse du milieu de la nuée."}, {"numero": 17, "texto": "L''''aspect de la gloire de l''''Eternel était comme un feu dévorant sur le sommet de la montagne, aux yeux des enfants d''''Israël."}, {"numero": 18, "texto": "Moïse entra au milieu de la nuée, et il monta sur la montagne. Moïse demeura sur la montagne quarante jours et quarante nuits."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 24, 'es', '[{"numero": 1, "texto": "Y DIJO á Moisés: Sube á Jehová, tú, y Aarón, Nadab, y Abiú, y setenta de los ancianos de Israel; y os inclinaréis desde lejos."}, {"numero": 2, "texto": "Mas Moisés sólo se llegará á Jehová; y ellos no se lleguen cerca, ni suba con él el pueblo."}, {"numero": 3, "texto": "Y Moisés vino y contó al pueblo todas las palabras de Jehová, y todos los derechos: y todo el pueblo respondió á una voz, y dijeron: Ejecutaremos todas las palabras que Jehová ha dicho."}, {"numero": 4, "texto": "Y Moisés escribió todas las palabras de Jehová, y levantándose de mañana edificó un altar al pie del monte, y doce columnas, según las doce tribus de Israel."}, {"numero": 5, "texto": "Y envió á los mancebos de los hijos de Israel, los cuales ofrecieron holocaustos, y sacrificaron pacíficos á Jehová, becerros."}, {"numero": 6, "texto": "Y Moisés tomó la mitad de la sangre, y púsola en tazones, y esparció la otra mitad de la sangre sobre el altar."}, {"numero": 7, "texto": "Y tomó el libro de la alianza, y leyó á oídos del pueblo, el cual dijo: Haremos todas las cosas que Jehová ha dicho, y obedeceremos."}, {"numero": 8, "texto": "Entonces Moisés tomó la sangre, y roció sobre el pueblo, y dijo: He aquí la sangre de la alianza que Jehová ha hecho con vosotros sobre todas estas cosas."}, {"numero": 9, "texto": "Y subieron Moisés y Aarón, Nadab y Abiú, y setenta de los ancianos de Israel;"}, {"numero": 10, "texto": "Y vieron al Dios de Israel; y había debajo de sus pies como un embaldosado de zafiro, semejante al cielo cuando está sereno."}, {"numero": 11, "texto": "Mas no extendió su mano sobre los príncipes de los hijos de Israel: y vieron á Dios, y comieron y bebieron."}, {"numero": 12, "texto": "Entonces Jehová dijo á Moisés: Sube á mí al monte, y espera allá, y te daré tablas de piedra, y la ley, y mandamientos que he escrito para enseñarlos."}, {"numero": 13, "texto": "Y levantóse Moisés, y Josué su ministro; y Moisés subió al monte de Dios."}, {"numero": 14, "texto": "Y dijo á los ancianos: Esperadnos aquí hasta que volvamos á vosotros: y he aquí Aarón y Hur están con vosotros: el que tuviere negocios, lléguese á ellos."}, {"numero": 15, "texto": "Entonces Moisés subió al monte, y una nube cubrió el monte."}, {"numero": 16, "texto": "Y la gloria de Jehová reposó sobre el monte Sinaí, y la nube lo cubrió por seis días: y al séptimo día llamó á Moisés de en medio de la nube."}, {"numero": 17, "texto": "Y el parecer de la gloria de Jehová era como un fuego abrasador en la cumbre del monte, á los ojos de los hijos de Israel."}, {"numero": 18, "texto": "Y entró Moisés en medio de la nube, y subió al monte: y estuvo Moisés en el monte cuarenta días y cuarenta noches."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 32, 'pt', '[{"numero": 1, "texto": "Mas vendo o povo que Moisés tardava em descer do monte, achegou-se então a Arão, e disseram-lhe: Levanta-te, faze-nos deuses que vão adiante de nós; porque a este Moisés, aquele homem que tirou da terra do Egito, não sabemos o que lhe aconteceu."}, {"numero": 2, "texto": "E Arão lhes disse: Separai os pendentes de ouro que estão nas orelhas de vossas mulheres, e de vossos filhos, e de vossas filhas, e trazei-os a mim."}, {"numero": 3, "texto": "Então todo o povo separou os pendentes de ouro que tinham em suas orelhas, e trouxeram-nos a Arão:"}, {"numero": 4, "texto": "O qual os tomou das mãos deles, e formou-o com buril, e fez disso um bezerro de fundição. Então disseram: Israel, estes são teus deuses, que te tiraram da terra do Egito."}, {"numero": 5, "texto": "E vendo isto Arão, edificou um altar diante do bezerro; e apregoou Arão, e disse: Amanhã será festa ao SENHOR."}, {"numero": 6, "texto": "E no dia seguinte madrugaram, e ofereceram holocaustos, e apresentaram pacíficos: e sentou-se o povo a comer e a beber, e levantaram-se a regozijar-se."}, {"numero": 7, "texto": "Então o SENHOR disse a Moisés: Anda, desce, porque teu povo que tiraste da terra do Egito se corrompeu:"}, {"numero": 8, "texto": "Logo se apartaram do caminho que eu lhes mandei, e se fizeram um bezerro de fundição, e o adoraram, e sacrificaram a ele, e disseram: Israel, estes são teus deuses, que te tiraram da terra do Egito."}, {"numero": 9, "texto": "Disse mais o SENHOR a Moisés: Eu vi a este povo, que por certo é povo de dura cerviz:"}, {"numero": 10, "texto": "Agora, pois, deixa-me que se acenda meu furor neles, e os consuma: e a ti eu porei sobre grande gente."}, {"numero": 11, "texto": "Então Moisés orou à face do SENHOR seu Deus, e disse: Ó SENHOR, por que se acenderá teu furor em teu povo, que tu tiraste da terra do Egito com grande força, e com mão forte?"}, {"numero": 12, "texto": "Por que hão de falar os egípcios, dizendo: Para o mal os tirou, para matá-los nos montes, e para exterminá-los de sobre a face da terra? Volta-te do furor de tua ira, e arrepende-te do mal de teu povo."}, {"numero": 13, "texto": "Lembra-te de Abraão, de Isaque, e de Israel teus servos, aos quais juraste por ti mesmo, e disse-lhes: Eu multiplicarei vossa semente como as estrelas do céu; e darei a vossa semente toda esta terra que disse, e a tomarão por herança para sempre."}, {"numero": 14, "texto": "Então o SENHOR se arrependeu do mal que disse que havia de fazer a seu povo."}, {"numero": 15, "texto": "E virou-se Moisés, e desceu do monte trazendo em sua mão as duas tábuas do testemunho, as tábuas escritas por ambos os lados; de uma parte e de outra estavam escritas."}, {"numero": 16, "texto": "E as tábuas eram obra de Deus, e a escritura era escritura de Deus gravada sobre as tábuas."}, {"numero": 17, "texto": "E ouvindo Josué o clamor do povo que gritava, disse a Moisés: Barulho de batalha há no campo."}, {"numero": 18, "texto": "E ele respondeu: Não é eco de gritos de vitória de fortes, nem eco de gritos de fracos: eu ouço barulho de cantorias."}, {"numero": 19, "texto": "E aconteceu, que quando chegou ele ao acampamento, e viu o bezerro e as danças, acendeu-se a ira a Moisés, e lançou as tábuas de suas mãos, e quebrou-as ao pé do monte."}, {"numero": 20, "texto": "E tomou o bezerro que fizeram, e queimou-o no fogo, e moeu-o até reduzi-lo a pó, que espalhou sobre as águas, e deu-o a beber aos filhos de Israel."}, {"numero": 21, "texto": "E disse Moisés a Arão: Que te fez este povo, que trouxeste sobre ele tão grande pecado?"}, {"numero": 22, "texto": "E respondeu Arão: Não se ire meu senhor; tu conheces o povo, que é inclinado ao mal."}, {"numero": 23, "texto": "Porque me disseram: Faze-nos deuses que vão adiante de nós, que a este Moisés, o homem que tirou da terra do Egito, não sabemos o que lhe aconteceu."}, {"numero": 24, "texto": "E eu lhes respondi: Quem tem ouro? Separai-o. E o deram a mim, e lancei-o no fogo, e saiu este bezerro."}, {"numero": 25, "texto": "E vendo Moisés que o povo estava descontrolado, porque Arão o havia deixado se descontrolarem para vergonha entre seus inimigos,"}, {"numero": 26, "texto": "Pôs-se Moisés à porta do acampamento, e disse: Quem é do SENHOR? junte-se comigo. E juntaram-se com ele todos os filhos de Levi."}, {"numero": 27, "texto": "E ele lhes disse: Assim disse o SENHOR, o Deus de Israel: Ponde cada um sua espada sobre sua coxa: passai e voltai de porta em porta pelo acampamento, e matai cada um a seu irmão, e a seu amigo, e a seu parente."}, {"numero": 28, "texto": "E os filhos de Levi o fizeram conforme o dito de Moisés: e caíram do povo naquele dia como três mil homens."}, {"numero": 29, "texto": "Então Moisés disse: Hoje vos consagrastes ao SENHOR, porque cada um se consagrou em seu filho, e em seu irmão, para que dê ele hoje bênção sobre vós."}, {"numero": 30, "texto": "E aconteceu que no dia seguinte disse Moisés ao povo: Vós cometestes um grande pecado: mas eu subirei agora ao SENHOR; talvez lhe consiga apaziguar o furor acerca de vosso pecado."}, {"numero": 31, "texto": "Então voltou Moisés ao SENHOR, e disse: Rogo-te, pois este povo cometeu um grande pecado, porque fizeram para si deuses de ouro,"}, {"numero": 32, "texto": "Que perdoes agora seu pecado, e se não, apaga-me agora de teu livro que escreveste."}, {"numero": 33, "texto": "E o SENHOR respondeu a Moisés: Ao que pecar contra mim, a este apagarei eu de meu livro."}, {"numero": 34, "texto": "Vai, pois, agora, leva a este povo aonde te disse: eis que meu anjo irá diante de ti; que no dia de minha visitação eu visitarei neles seu pecado."}, {"numero": 35, "texto": "E o SENHOR feriu ao povo, porque fizeram o bezerro que formou Arão."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 32, 'en', '[{"numero": 1, "texto": "And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him."}, {"numero": 2, "texto": "And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me."}, {"numero": 3, "texto": "And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron."}, {"numero": 4, "texto": "And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt."}, {"numero": 5, "texto": "And when Aaron saw it, he built an altar before it; and Aaron made proclamation, and said, To morrow is a feast to the Lord."}, {"numero": 6, "texto": "And they rose up early on the morrow, and offered burnt offerings, and brought peace offerings; and the people sat down to eat and to drink, and rose up to play."}, {"numero": 7, "texto": "And the Lord said unto Moses, Go, get thee down; for thy people, which thou broughtest out of the land of Egypt, have corrupted themselves:"}, {"numero": 8, "texto": "They have turned aside quickly out of the way which I commanded them: they have made them a molten calf, and have worshipped it, and have sacrificed thereunto, and said, These be thy gods, O Israel, which have brought thee up out of the land of Egypt."}, {"numero": 9, "texto": "And the Lord said unto Moses, I have seen this people, and, behold, it is a stiffnecked people:"}, {"numero": 10, "texto": "Now therefore let me alone, that my wrath may wax hot against them, and that I may consume them: and I will make of thee a great nation."}, {"numero": 11, "texto": "And Moses besought the Lord his God, and said, Lord, why doth thy wrath wax hot against thy people, which thou hast brought forth out of the land of Egypt with great power, and with a mighty hand?"}, {"numero": 12, "texto": "Wherefore should the Egyptians speak, and say, For mischief did he bring them out, to slay them in the mountains, and to consume them from the face of the earth? Turn from thy fierce wrath, and repent of this evil against thy people."}, {"numero": 13, "texto": "Remember Abraham, Isaac, and Israel, thy servants, to whom thou swarest by thine own self, and saidst unto them, I will multiply your seed as the stars of heaven, and all this land that I have spoken of will I give unto your seed, and they shall inherit it for ever."}, {"numero": 14, "texto": "And the Lord repented of the evil which he thought to do unto his people."}, {"numero": 15, "texto": "And Moses turned, and went down from the mount, and the two tables of the testimony were in his hand: the tables were written on both their sides; on the one side and on the other were they written."}, {"numero": 16, "texto": "And the tables were the work of God, and the writing was the writing of God, graven upon the tables."}, {"numero": 17, "texto": "And when Joshua heard the noise of the people as they shouted, he said unto Moses, There is a noise of war in the camp."}, {"numero": 18, "texto": "And he said, It is not the voice of them that shout for mastery, neither is it the voice of them that cry for being overcome: but the noise of them that sing do I hear."}, {"numero": 19, "texto": "And it came to pass, as soon as he came nigh unto the camp, that he saw the calf, and the dancing: and Moses'' anger waxed hot, and he cast the tables out of his hands, and brake them beneath the mount."}, {"numero": 20, "texto": "And he took the calf which they had made, and burnt it in the fire, and ground it to powder, and strawed it upon the water, and made the children of Israel drink of it."}, {"numero": 21, "texto": "And Moses said unto Aaron, What did this people unto thee, that thou hast brought so great a sin upon them?"}, {"numero": 22, "texto": "And Aaron said, Let not the anger of my lord wax hot: thou knowest the people, that they are set on mischief."}, {"numero": 23, "texto": "For they said unto me, Make us gods, which shall go before us: for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him."}, {"numero": 24, "texto": "And I said unto them, Whosoever hath any gold, let them break it off. So they gave it me: then I cast it into the fire, and there came out this calf."}, {"numero": 25, "texto": "And when Moses saw that the people were naked; (for Aaron had made them naked unto their shame among their enemies:)"}, {"numero": 26, "texto": "Then Moses stood in the gate of the camp, and said, Who is on the Lord''s side? let him come unto me. And all the sons of Levi gathered themselves together unto him."}, {"numero": 27, "texto": "And he said unto them, Thus saith the Lord God of Israel, Put every man his sword by his side, and go in and out from gate to gate throughout the camp, and slay every man his brother, and every man his companion, and every man his neighbour."}, {"numero": 28, "texto": "And the children of Levi did according to the word of Moses: and there fell of the people that day about three thousand men."}, {"numero": 29, "texto": "For Moses had said, Consecrate yourselves today to the Lord, even every man upon his son, and upon his brother; that he may bestow upon you a blessing this day."}, {"numero": 30, "texto": "And it came to pass on the morrow, that Moses said unto the people, Ye have sinned a great sin: and now I will go up unto the Lord; peradventure I shall make an atonement for your sin."}, {"numero": 31, "texto": "And Moses returned unto the Lord, and said, Oh, this people have sinned a great sin, and have made them gods of gold."}, {"numero": 32, "texto": "Yet now, if thou wilt forgive their sin--; and if not, blot me, I pray thee, out of thy book which thou hast written."}, {"numero": 33, "texto": "And the Lord said unto Moses, Whosoever hath sinned against me, him will I blot out of my book."}, {"numero": 34, "texto": "Therefore now go, lead the people unto the place of which I have spoken unto thee: behold, mine Angel shall go before thee: nevertheless in the day when I visit I will visit their sin upon them."}, {"numero": 35, "texto": "And the Lord plagued the people, because they made the calf, which Aaron made."}]'::jsonb, 'King James Version'),
  ('Ex', 32, 'fr', '[{"numero": 1, "texto": "Le peuple, voyant que Moïse tardait à descendre de la montagne, s''''assembla autour d''''Aaron, et lui dit: Allons! fais-nous un dieu qui marche devant nous, car ce Moïse, cet homme qui nous a fait sortir du pays d''''Egypte, nous ne savons ce qu''''il est devenu."}, {"numero": 2, "texto": "Aaron leur dit: Otez les anneaux d''''or qui sont aux oreilles de vos femmes, de vos fils et de vos filles, et apportez-les-moi."}, {"numero": 3, "texto": "Et tous ôtèrent les anneaux d''''or qui étaient à leurs oreilles, et ils les apportèrent à Aaron."}, {"numero": 4, "texto": "Il les reçut de leurs mains, jeta l''''or dans un moule, et fit un veau en fonte. Et ils dirent: Israël! voici ton dieu, qui t''''a fait sortir du pays d''''Egypte."}, {"numero": 5, "texto": "Lorsqu''''Aaron vit cela, il bâtit un autel devant lui, et il s''''écria: Demain, il y aura fête en l''''honneur de l''''Eternel!"}, {"numero": 6, "texto": "Le lendemain, ils se levèrent de bon matin, et ils offrirent des holocaustes et des sacrifices d''''actions de grâces. Le peuple s''''assit pour manger et pour boire; puis ils se levèrent pour se divertir."}, {"numero": 7, "texto": "L''''Eternel dit à Moïse: Va, descends; car ton peuple, que tu as fait sortir du pays d''''Egypte, s''''est corrompu."}, {"numero": 8, "texto": "Ils se sont promptement écartés de la voie que je leur avais prescrite; ils se sont fait un veau en fonte, ils se sont prosternés devant lui, ils lui ont offert des sacrifices, et ils ont dit: Israël! voici ton dieu, qui t''''a fait sortir du pays d''''Egypte."}, {"numero": 9, "texto": "L''''Eternel dit à Moïse: Je vois que ce peuple est un peuple au cou roide."}, {"numero": 10, "texto": "Maintenant laisse-moi; ma colère va s''''enflammer contre eux, et je les consumerai; mais je ferai de toi une grande nation."}, {"numero": 11, "texto": "Moïse implora l''''Eternel, son Dieu, et dit: Pourquoi, ô Eternel! ta colère s''''enflammerait-elle contre ton peuple, que tu as fait sortir du pays d''''Egypte par une grande puissance et par une main forte?"}, {"numero": 12, "texto": "Pourquoi les Egyptiens diraient-ils: C''''est pour leur malheur qu''''il les a fait sortir, c''''est pour les tuer dans les montagnes, et pour les exterminer de dessus la terre? Reviens de l''''ardeur de ta colère, et repens-toi du mal que tu veux faire à ton peuple."}, {"numero": 13, "texto": "Souviens-toi d''''Abraham, d''''Isaac et d''''Israël, tes serviteurs, auxquels tu as dit, en jurant par toi-même: Je multiplierai votre postérité comme les étoiles du ciel, je donnerai à vos descendants tout ce pays dont j''''ai parlé, et ils le posséderont à jamais."}, {"numero": 14, "texto": "Et l''''Eternel se repentit du mal qu''''il avait déclaré vouloir faire à son peuple."}, {"numero": 15, "texto": "Moïse retourna et descendit de la montagne, les deux tables du témoignage dans sa main; les tables étaient écrites des deux côtés, elles étaient écrites de l''''un et de l''''autre côté."}, {"numero": 16, "texto": "Les tables étaient l''''ouvrage de Dieu, et l''''écriture était l''''écriture de Dieu, gravée sur les tables."}, {"numero": 17, "texto": "Josué entendit la voix du peuple, qui poussait des cris, et il dit à Moïse: Il y a un cri de guerre dans le camp."}, {"numero": 18, "texto": "Moïse répondit: Ce n''''est ni un cri de vainqueurs, ni un cri de vaincus; ce que j''''entends, c''''est la voix de gens qui chantent."}, {"numero": 19, "texto": "Et, comme il approchait du camp, il vit le veau et les danses. La colère de Moïse s''''enflamma; il jeta de ses mains les tables, et les brisa au pied de la montagne."}, {"numero": 20, "texto": "Il prit le veau qu''''ils avaient fait, et le brûla au feu; il le réduisit en poudre, répandit cette poudre à la surface de l''''eau, et fit boire les enfants d''''Israël."}, {"numero": 21, "texto": "Moïse dit à Aaron: Que t''''a fait ce peuple, pour que tu l''''aies laissé commettre un si grand péché?"}, {"numero": 22, "texto": "Aaron répondit: Que la colère de mon seigneur ne s''''enflamme point! Tu sais toi-même que ce peuple est porté au mal."}, {"numero": 23, "texto": "Ils m''''ont dit: Fais-nous un dieu qui marche devant nous; car ce Moïse, cet homme qui nous a fait sortir du pays d''''Egypte, nous ne savons ce qu''''il est devenu."}, {"numero": 24, "texto": "Je leur ai dit: Que ceux qui ont de l''''or, s''''en dépouillent! Et ils me l''''ont donné; je l''''ai jeté au feu, et il en est sorti ce veau."}, {"numero": 25, "texto": "Moïse vit que le peuple était livré au désordre, et qu''''Aaron l''''avait laissé dans ce désordre, exposé à l''''opprobre parmi ses ennemis."}, {"numero": 26, "texto": "Moïse se plaça à la porte du camp, et dit: A moi ceux qui sont pour l''''Eternel! Et tous les enfants de Lévi s''''assemblèrent auprès de lui."}, {"numero": 27, "texto": "Il leur dit: Ainsi parle l''''Eternel, le Dieu d''''Israël: Que chacun de vous mette son épée au côté; traversez et parcourez le camp d''''une porte à l''''autre, et que chacun tue son frère, son parent."}, {"numero": 28, "texto": "Les enfants de Lévi firent ce qu''''ordonnait Moïse; et environ trois mille hommes parmi le peuple périrent en cette journée."}, {"numero": 29, "texto": "Moïse dit: Consacrez-vous aujourd''''hui à l''''Eternel, même en sacrifiant votre fils et votre frère, afin qu''''il vous accorde aujourd''''hui une bénédiction."}, {"numero": 30, "texto": "Le lendemain, Moïse dit au peuple: Vous avez commis un grand péché. Je vais maintenant monter vers l''''Eternel: j''''obtiendrai peut-être le pardon de votre péché."}, {"numero": 31, "texto": "Moïse retourna vers l''''Eternel et dit: Ah! ce peuple a commis un grand péché. Ils se sont fait un dieu d''''or."}, {"numero": 32, "texto": "Pardonne maintenant leur péché! Sinon, efface-moi de ton livre que tu as écrit."}, {"numero": 33, "texto": "L''''Eternel dit à Moïse: C''''est celui qui a péché contre moi que j''''effacerai de mon livre."}, {"numero": 34, "texto": "Va donc, conduis le peuple où je t''''ai dit. Voici, mon ange marchera devant toi, mais au jour de ma vengeance, je les punirai de leur péché."}, {"numero": 35, "texto": "L''''Eternel frappa le peuple, parce qu''''il avait fait le veau, fabriqué par Aaron."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 32, 'es', '[{"numero": 1, "texto": "MAS viendo el pueblo que Moisés tardaba en descender del monte, allegóse entonces á Aarón, y dijéronle: Levántate, haznos dioses que vayan delante de nosotros; porque á este Moisés, aquel varón que nos sacó de la tierra de Egipto, no sabemos qué le haya acontecido."}, {"numero": 2, "texto": "Y Aarón les dijo: Apartad los zarcillos de oro que están en las orejas de vuestras mujeres, y de vuestros hijos, y de vuestras hijas, y traédmelos."}, {"numero": 3, "texto": "Entonces todo el pueblo apartó los zarcillos de oro que tenían en sus orejas, y trajéronlos á Aarón:"}, {"numero": 4, "texto": "El cual los tomó de las manos de ellos, y formólo con buril, é hizo de ello un becerro de fundición. Entonces dijeron: Israel, estos son tus dioses, que te sacaron de la tierra de Egipto."}, {"numero": 5, "texto": "Y viendo esto Aarón, edificó un altar delante del becerro; y pregonó Aarón, y dijo: Mañana será fiesta á Jehová."}, {"numero": 6, "texto": "Y el día siguiente madrugaron, y ofrecieron holocaustos, y presentaron pacíficos: y sentóse el pueblo á comer y á beber, y levantáronse á regocijarse."}, {"numero": 7, "texto": "Entonces Jehová dijo á Moisés: Anda, desciende, porque tu pueblo que sacaste de tierra de Egipto se ha corrompido:"}, {"numero": 8, "texto": "Presto se han apartado del camino que yo les mandé, y se han hecho un becerro de fundición, y lo han adorado, y han sacrificado á él, y han dicho: Israel, estos son tus dioses, que te sacaron de la tierra de Egipto."}, {"numero": 9, "texto": "Dijo más Jehová á Moisés: Yo he visto á este pueblo, que por cierto es pueblo de dura cerviz:"}, {"numero": 10, "texto": "Ahora pues, déjame que se encienda mi furor en ellos, y los consuma: y á ti yo te pondré sobre gran gente."}, {"numero": 11, "texto": "Entonces Moisés oró á la faz de Jehová su Dios, y dijo: Oh Jehová, ¿por qué se encenderá tu furor en tu pueblo, que tú sacaste de la tierra de Egipto con gran fortaleza, y con mano fuerte?"}, {"numero": 12, "texto": "¿Por qué han de hablar los Egipcios, diciendo: Para mal los sacó, para matarlos en los montes, y para raerlos de sobre la haz de la tierra? Vuélvete del furor de tu ira, y arrepiéntete del mal de tu pueblo."}, {"numero": 13, "texto": "Acuérdate de Abraham, de Isaac, y de Israel, tus siervos, á los cuales has jurado por ti mismo, y dícholes: Yo multiplicaré vuestra simiente como las estrellas del cielo; y daré á vuestra simiente toda esta tierra que he dicho, y la tomarán por heredad para siempre."}, {"numero": 14, "texto": "Entonces Jehová se arrepintió del mal que dijo que había de hacer á su pueblo."}, {"numero": 15, "texto": "Y volvióse Moisés, y descendió del monte trayendo en su mano las dos tablas del testimonio, las tablas escritas por ambos lados; de una parte y de otra estaban escritas."}, {"numero": 16, "texto": "Y las tablas eran obra de Dios, y la escritura era escritura de Dios grabada sobre las tablas."}, {"numero": 17, "texto": "Y oyendo Josué el clamor del pueblo que gritaba, dijo á Moisés: Alarido de pelea hay en el campo."}, {"numero": 18, "texto": "Y él respondió: No es eco de algazara de fuertes, ni eco de alaridos de flacos: algazara de cantar oigo yo."}, {"numero": 19, "texto": "Y aconteció, que como llegó él al campo, y vió el becerro y las danzas, enardeciósele la ira á Moisés, y arrojó las tablas de sus manos, y quebrólas al pie del monte."}, {"numero": 20, "texto": "Y tomó el becerro que habían hecho, y quemólo en el fuego, y moliólo hasta reducirlo á polvo, que esparció sobre las aguas, y diólo á beber á los hijos de Israel."}, {"numero": 21, "texto": "Y dijo Moisés á Aarón: ¿Qué te ha hecho este pueblo, que has traído sobre él tan gran pecado?"}, {"numero": 22, "texto": "Y respondió Aarón: No se enoje mi señor; tú conoces el pueblo, que es inclinado á mal."}, {"numero": 23, "texto": "Porque me dijeron: Haznos dioses que vayan delante de nosotros, que á este Moisés, el varón que nos sacó de tierra de Egipto, no sabemos qué le ha acontecido."}, {"numero": 24, "texto": "Y yo les respondí: ¿Quién tiene oro? apartadlo. Y diéronmelo, y echélo en el fuego, y salió este becerro."}, {"numero": 25, "texto": "Y viendo Moisés que el pueblo estaba despojado, porque Aarón lo había despojado para vergüenza entre sus enemigos,"}, {"numero": 26, "texto": "Púsose Moisés á la puerta del real, y dijo: ¿Quién es de Jehová? júntese conmigo. Y juntáronse con él todos los hijos de Leví."}, {"numero": 27, "texto": "Y él les dijo: Así ha dicho Jehová, el Dios de Israel: Poned cada uno su espada sobre su muslo: pasad y volved de puerta á puerta por el campo, y matad cada uno á su hermano, y á su amigo, y á su pariente."}, {"numero": 28, "texto": "Y los hijos de Leví lo hicieron conforme al dicho de Moisés: y cayeron del pueblo en aquel día como tres mil hombres."}, {"numero": 29, "texto": "Entonces Moisés dijo: Hoy os habéis consagrado á Jehová, porque cada uno se ha consagrado en su hijo, y en su hermano, para que dé él hoy bendición sobre vosotros."}, {"numero": 30, "texto": "Y aconteció que el día siguiente dijo Moisés al pueblo: Vosotros habéis cometido un gran pecado: mas yo subiré ahora á Jehová; quizá le aplacaré acerca de vuestro pecado."}, {"numero": 31, "texto": "Entonces volvió Moisés á Jehová, y dijo: Ruégote, pues este pueblo ha cometido un gran pecado, porque se hicieron dioses de oro,"}, {"numero": 32, "texto": "Que perdones ahora su pecado, y si no, ráeme ahora de tu libro que has escrito."}, {"numero": 33, "texto": "Y Jehová respondió á Moisés: Al que pecare contra mí, á éste raeré yo de mi libro."}, {"numero": 34, "texto": "Ve pues ahora, lleva á este pueblo donde te he dicho: he aquí mi ángel irá delante de ti; que en el día de mi visitación yo visitaré en ellos su pecado."}, {"numero": 35, "texto": "Y Jehová hirió al pueblo, porque habían hecho el becerro que formó Aarón."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 33, 'pt', '[{"numero": 1, "texto": "E o SENHOR disse a Moisés: Vai, sobe daqui, tu e o povo que tiraste da terra do Egito, à terra da qual jurei a Abraão, Isaque, e Jacó, dizendo: À tua semente a darei:"}, {"numero": 2, "texto": "E eu enviarei diante de ti o anjo, e lançarei fora aos cananeus e aos amorreus, e aos heteus, e aos perizeus, e aos heveus e aos jebuseus:"}, {"numero": 3, "texto": "(À terra que flui leite e mel); porque eu não subirei em meio de ti, porque és povo de dura cerviz, não seja que te consuma no caminho."}, {"numero": 4, "texto": "E ouvindo o povo esta desagradável palavra, vestiram luto, e ninguém se pôs seus ornamentos:"}, {"numero": 5, "texto": "Pois o SENHOR disse a Moisés: Dize aos filhos de Israel: Vós sois povo de dura cerviz: em um momento subirei em meio de ti, e te consumirei: tira de ti, pois, agora teus ornamentos, que eu saberei o que te tenho de fazer."}, {"numero": 6, "texto": "Então os filhos de Israel se despojaram de seus ornamentos desde o monte Horebe."}, {"numero": 7, "texto": "E Moisés tomou o tabernáculo, e estendeu-o fora do acampamento, longe do acampamento, e chamou-o o Tabernáculo do Testemunho. E foi que qualquer um que buscava ao SENHOR saía ao tabernáculo do testemunho, que estava fora do acampamento."}, {"numero": 8, "texto": "E sucedia que, quando saía Moisés ao tabernáculo, todo o povo se levantava, e estava cada qual em pé à porta de sua tenda, e olhavam por trás de Moisés, até que ele entrava no tabernáculo."}, {"numero": 9, "texto": "E quando Moisés entrava no tabernáculo, a coluna de nuvem descia, e punha-se à porta do tabernáculo, e o SENHOR falava com Moisés."}, {"numero": 10, "texto": "E vendo todo o povo a coluna de nuvem, que estava à porta do tabernáculo, levantava-se todo o povo, cada um à porta de sua tenda e adorava."}, {"numero": 11, "texto": "E falava o SENHOR a Moisés face a face, como fala qualquer um a seu companheiro. E voltava-se ao campo; mas o jovem Josué, seu criado, filho de Num, nunca se afastava do meio do tabernáculo."}, {"numero": 12, "texto": "E disse Moisés ao SENHOR: Olha, tu me dizes a mim: Tira este povo: e tu não me declaraste a quem hás de enviar comigo: porém, tu dizes: Eu te conheci por teu nome, e achaste também graça em meus olhos."}, {"numero": 13, "texto": "Agora, pois, se achei graça em teus olhos, rogo-te que me mostres agora teu caminho, para que te conheça, para que ache graça em teus olhos: e olha que teu povo é esta gente."}, {"numero": 14, "texto": "E ele disse: Meu rosto irá contigo, e te farei descansar."}, {"numero": 15, "texto": "E ele respondeu: Se teu rosto não for comigo, não nos tires daqui."}, {"numero": 16, "texto": "E em que se conhecerá aqui que achei favor em teus olhos, eu e teu povo, se não em andar tu conosco, e que eu e teu povo sejamos separados de todos os povos que estão sobre a face da terra?"}, {"numero": 17, "texto": "E o SENHOR disse a Moisés: Também farei isto que disseste, porquanto achaste favor em meus olhos, e te conheci por teu nome."}, {"numero": 18, "texto": "O então disse: Rogo-te que me mostres tua glória."}, {"numero": 19, "texto": "E respondeu-lhe: Eu farei passar todo o meu bem diante de teu rosto, e proclamarei o nome do SENHOR diante de ti; e terei misericórdia do que terei misericórdia, e serei clemente para com o que serei clemente."}, {"numero": 20, "texto": "Disse mais: Não poderás ver meu rosto: porque não me verá homem, e viverá."}, {"numero": 21, "texto": "E disse ainda o SENHOR: Eis aqui um lugar junto a mim, e tu estarás sobre a rocha:"}, {"numero": 22, "texto": "E será que, quando passar minha glória, eu te porei em uma brecha da rocha, e te cobrirei com minha mão até que tenha passado:"}, {"numero": 23, "texto": "Depois tirarei minha mão, e verás minhas costas; mas não se verá meu rosto."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 33, 'en', '[{"numero": 1, "texto": "And the Lord said unto Moses, Depart, and go up hence, thou and the people which thou hast brought up out of the land of Egypt, unto the land which I sware unto Abraham, to Isaac, and to Jacob, saying, Unto thy seed will I give it:"}, {"numero": 2, "texto": "And I will send an angel before thee; and I will drive out the Canaanite, the Amorite, and the Hittite, and the Perizzite, the Hivite, and the Jebusite:"}, {"numero": 3, "texto": "Unto a land flowing with milk and honey: for I will not go up in the midst of thee; for thou art a stiffnecked people: lest I consume thee in the way."}, {"numero": 4, "texto": "And when the people heard these evil tidings, they mourned: and no man did put on him his ornaments."}, {"numero": 5, "texto": "For the Lord had said unto Moses, Say unto the children of Israel, Ye are a stiffnecked people: I will come up into the midst of thee in a moment, and consume thee: therefore now put off thy ornaments from thee, that I may know what to do unto thee."}, {"numero": 6, "texto": "And the children of Israel stripped themselves of their ornaments by the mount Horeb."}, {"numero": 7, "texto": "And Moses took the tabernacle, and pitched it without the camp, afar off from the camp, and called it the Tabernacle of the congregation. And it came to pass, that every one which sought the Lord went out unto the tabernacle of the congregation, which was without the camp."}, {"numero": 8, "texto": "And it came to pass, when Moses went out unto the tabernacle, that all the people rose up, and stood every man at his tent door, and looked after Moses, until he was gone into the tabernacle."}, {"numero": 9, "texto": "And it came to pass, as Moses entered into the tabernacle, the cloudy pillar descended, and stood at the door of the tabernacle, and the Lord talked with Moses."}, {"numero": 10, "texto": "And all the people saw the cloudy pillar stand at the tabernacle door: and all the people rose up and worshipped, every man in his tent door."}, {"numero": 11, "texto": "And the Lord spake unto Moses face to face, as a man speaketh unto his friend. And he turned again into the camp: but his servant Joshua, the son of Nun, a young man, departed not out of the tabernacle."}, {"numero": 12, "texto": "And Moses said unto the Lord, See, thou sayest unto me, Bring up this people: and thou hast not let me know whom thou wilt send with me. Yet thou hast said, I know thee by name, and thou hast also found grace in my sight."}, {"numero": 13, "texto": "Now therefore, I pray thee, if I have found grace in thy sight, shew me now thy way, that I may know thee, that I may find grace in thy sight: and consider that this nation is thy people."}, {"numero": 14, "texto": "And he said, My presence shall go with thee, and I will give thee rest."}, {"numero": 15, "texto": "And he said unto him, If thy presence go not with me, carry us not up hence."}, {"numero": 16, "texto": "For wherein shall it be known here that I and thy people have found grace in thy sight? is it not in that thou goest with us? so shall we be separated, I and thy people, from all the people that are upon the face of the earth."}, {"numero": 17, "texto": "And the Lord said unto Moses, I will do this thing also that thou hast spoken: for thou hast found grace in my sight, and I know thee by name."}, {"numero": 18, "texto": "And he said, I beseech thee, shew me thy glory."}, {"numero": 19, "texto": "And he said, I will make all my goodness pass before thee, and I will proclaim the name of the Lord before thee; and will be gracious to whom I will be gracious, and will shew mercy on whom I will shew mercy."}, {"numero": 20, "texto": "And he said, Thou canst not see my face: for there shall no man see me, and live."}, {"numero": 21, "texto": "And the Lord said, Behold, there is a place by me, and thou shalt stand upon a rock:"}, {"numero": 22, "texto": "And it shall come to pass, while my glory passeth by, that I will put thee in a clift of the rock, and will cover thee with my hand while I pass by:"}, {"numero": 23, "texto": "And I will take away mine hand, and thou shalt see my back parts: but my face shall not be seen."}]'::jsonb, 'King James Version'),
  ('Ex', 33, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Va, pars d''''ici, toi et le peuple que tu as fait sortir du pays d''''Egypte; monte vers le pays que j''''ai juré de donner à Abraham, à Isaac et à Jacob, en disant: Je le donnerai à ta postérité."}, {"numero": 2, "texto": "J''''enverrai devant toi un ange, et je chasserai les Cananéens, les Amoréens, les Héthiens, les Phéréziens, les Héviens et les Jébusiens."}, {"numero": 3, "texto": "Monte vers ce pays où coulent le lait et le miel. Mais je ne monterai point au milieu de toi, de peur que je ne te consume en chemin, car tu es un peuple au cou roide."}, {"numero": 4, "texto": "Lorsque le peuple eut entendu ces sinistres paroles, il fut dans la désolation, et personne ne mit ses ornements."}, {"numero": 5, "texto": "Et l''''Eternel dit à Moïse: Dis aux enfants d''''Israël: Vous êtes un peuple au cou roide; si je montais un seul instant au milieu de toi, je te consumerais. Ote maintenant tes ornements de dessus toi, et je verrai ce que je te ferai."}, {"numero": 6, "texto": "Les enfants d''''Israël se dépouillèrent de leurs ornements, en s''''éloignant du mont Horeb."}, {"numero": 7, "texto": "Moïse prit la tente et la dressa hors du camp, à quelque distance; il l''''appela tente d''''assignation; et tous ceux qui consultaient l''''Eternel allaient vers la tente d''''assignation, qui était hors du camp."}, {"numero": 8, "texto": "Lorsque Moïse se rendait à la tente, tout le peuple se levait; chacun se tenait à l''''entrée de sa tente, et suivait des yeux Moïse, jusqu''''à ce qu''''il fût entré dans la tente."}, {"numero": 9, "texto": "Et lorsque Moïse était entré dans la tente, la colonne de nuée descendait et s''''arrêtait à l''''entrée de la tente, et l''''Eternel parlait avec Moïse."}, {"numero": 10, "texto": "Tout le peuple voyait la colonne de nuée qui s''''arrêtait à l''''entrée de la tente, tout le peuple se levait et se prosternait à l''''entrée de sa tente."}, {"numero": 11, "texto": "L''''Eternel parlait avec Moïse face à face, comme un homme parle à son ami. Puis Moïse retournait au camp; mais son jeune serviteur, Josué, fils de Nun, ne sortait pas du milieu de la tente."}, {"numero": 12, "texto": "Moïse dit à l''''Eternel: Voici, tu me dis: Fais monter ce peuple! Et tu ne me fais pas connaître qui tu enverras avec moi. Cependant, tu as dit: Je te connais par ton nom, et tu as trouvé grâce à mes yeux."}, {"numero": 13, "texto": "Maintenant, si j''''ai trouvé grâce à tes yeux, fais-moi connaître tes voies; alors je te connaîtrai, et je trouverai encore grâce à tes yeux. Considère que cette nation est ton peuple."}, {"numero": 14, "texto": "L''''Eternel répondit: Je marcherai moi-même avec toi, et je te donnerai du repos."}, {"numero": 15, "texto": "Moïse lui dit: Si tu ne marches pas toi-même avec nous, ne nous fais point partir d''''ici."}, {"numero": 16, "texto": "Comment sera-t-il donc certain que j''''ai trouvé grâce à tes yeux, moi et ton peuple? Ne sera-ce pas quand tu marcheras avec nous, et quand nous serons distingués, moi et ton peuple, de tous les peuples qui sont sur la face de la terre?"}, {"numero": 17, "texto": "L''''Eternel dit à Moïse: Je ferai ce que tu me demandes, car tu as trouvé grâce à mes yeux, et je te connais par ton nom."}, {"numero": 18, "texto": "Moïse dit: Fais-moi voir ta gloire!"}, {"numero": 19, "texto": "L''''Eternel répondit: Je ferai passer devant toi toute ma bonté, et je proclamerai devant toi le nom de l''''Eternel; je fais grâce à qui je fais grâce, et miséricorde à qui je fais miséricorde."}, {"numero": 20, "texto": "L''''Eternel dit: Tu ne pourras pas voir ma face, car l''''homme ne peut me voir et vivre."}, {"numero": 21, "texto": "L''''Eternel dit: Voici un lieu près de moi; tu te tiendras sur le rocher."}, {"numero": 22, "texto": "Quand ma gloire passera, je te mettrai dans un creux du rocher, et je te couvrirai de ma main jusqu''''à ce que j''''aie passé."}, {"numero": 23, "texto": "Et lorsque je retournerai ma main, tu me verras par derrière, mais ma face ne pourra pas être vue."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 33, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Moisés: Ve, sube de aquí, tú y el pueblo que sacaste de la tierra de Egipto, á la tierra de la cual juré á Abraham, Isaac, y Jacob, diciendo: A tu simiente la daré:"}, {"numero": 2, "texto": "Y yo enviaré delante de ti el ángel, y echaré fuera al Cananeo y al Amorrheo, y al Hetheo, y al Pherezeo, y al Heveo y al Jebuseo:"}, {"numero": 3, "texto": "(A la tierra que fluye leche y miel); porque yo no subiré en medio de ti, porque eres pueblo de dura cerviz, no sea que te consuma en el camino."}, {"numero": 4, "texto": "Y oyendo el pueblo esta sensible palabra, vistieron luto, y ninguno se puso sus atavíos:"}, {"numero": 5, "texto": "Pues Jehová dijo á Moisés: Di á los hijos de Israel: Vosotros sois pueblo de dura cerviz: en un momento subiré en medio de ti, y te consumiré: quítate pues ahora tus atavíos, que yo sabré lo que te tengo de hacer."}, {"numero": 6, "texto": "Entonces los hijos de Israel se despojaron de sus atavíos desde el monte Horeb."}, {"numero": 7, "texto": "Y Moisés tomó el tabernáculo, y extendiólo fuera del campo, lejos del campo, y llamólo el Tabernáculo del Testimonio. Y fué, que cualquiera que requería á Jehová, salía al tabernáculo del testimonio, que estaba fuera del campo."}, {"numero": 8, "texto": "Y sucedía que, cuando salía Moisés al tabernáculo, todo el pueblo se levantaba, y estaba cada cual en pie á la puerta de su tienda, y miraban en pos de Moisés, hasta que él entraba en el tabernáculo."}, {"numero": 9, "texto": "Y cuando Moisés entraba en el tabernáculo, la columna de nube descendía, y poníase á la puerta del tabernáculo, y Jehová hablaba con Moisés."}, {"numero": 10, "texto": "Y viendo todo el pueblo la columna de la nube, que estaba á la puerta del tabernáculo, levantábase todo el pueblo, cada uno á la puerta de su tienda, y adoraba."}, {"numero": 11, "texto": "Y hablaba Jehová á Moisés cara á cara, como habla cualquiera á su compañero. Y volvíase al campo; mas el joven Josué, su criado, hijo de Nun, nunca se apartaba de en medio del tabernáculo."}, {"numero": 12, "texto": "Y dijo Moisés á Jehová: Mira, tú me dices á mí: Saca este pueblo: y tú no me has declarado á quién has de enviar conmigo: sin embargo tú dices: Yo te he conocido por tu nombre, y has hallado también gracia en mis ojos."}, {"numero": 13, "texto": "Ahora, pues, si he hallado gracia en tus ojos, ruégote que me muestres ahora tu camino, para que te conozca, porque halle gracia en tus ojos: y mira que tu pueblo es aquesta gente."}, {"numero": 14, "texto": "Y él dijo: Mi rostro irá contigo, y te haré descansar."}, {"numero": 15, "texto": "Y él respondió: Si tu rostro no ha de ir conmigo, no nos saques de aquí."}, {"numero": 16, "texto": "¿Y en qué se conocerá aquí que he hallado gracia en tus ojos, yo y tu pueblo, sino en andar tú con nosotros, y que yo y tu pueblo seamos apartados de todos los pueblos que están sobre la faz de la tierra?"}, {"numero": 17, "texto": "Y Jehová dijo á Moisés: También haré esto que has dicho, por cuanto has hallado gracia en mis ojos, y te he conocido por tu nombre."}, {"numero": 18, "texto": "El entonces dijo: Ruégote que me muestres tu gloria."}, {"numero": 19, "texto": "Y respondióle: Yo haré pasar todo mi bien delante de tu rostro, y proclamaré el nombre de Jehová delante de ti; y tendré misericordia del que tendré misericordia, y seré clemente para con el que seré clemente."}, {"numero": 20, "texto": "Dijo más: No podrás ver mi rostro: porque no me verá hombre, y vivirá."}, {"numero": 21, "texto": "Y dijo aún Jehová: He aquí lugar junto á mí, y tú estarás sobre la peña:"}, {"numero": 22, "texto": "Y será que, cuando pasare mi gloria, yo te pondré en una hendidura de la peña, y te cubriré con mi mano hasta que haya pasado:"}, {"numero": 23, "texto": "Después apartaré mi mano, y verás mis espaldas; mas no se verá mi rostro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 34, 'pt', '[{"numero": 1, "texto": "E o SENHOR disse a Moisés: Entalha para ti duas tábuas de pedra como as primeiras, e escreverei sobre essas tábuas as palavras que estavam nas tábuas primeiras que quebraste."}, {"numero": 2, "texto": "Prepara-te, pois, para amanhã, e sobe pela manhã ao monte de Sinai, e fica diante de mim ali sobre o cume do monte."}, {"numero": 3, "texto": "E não suba homem contigo, nem apareça alguém em todo o monte; nem ovelhas nem bois apascentem diante do monte."}, {"numero": 4, "texto": "E Moisés entalhou duas tábuas de pedra como as primeiras; e levantou-se pela manhã, e subiu ao monte de Sinai, como lhe mandou o SENHOR, e levou em sua mão as duas tábuas de pedra."}, {"numero": 5, "texto": "E o SENHOR desceu na nuvem, e esteve ali com ele, proclamando o nome do SENHOR."}, {"numero": 6, "texto": "E passando o SENHOR por diante dele, proclamou: SENHOR, SENHOR, forte, misericordioso, e piedoso; tardio para a ira, e grande em benignidade e verdade;"}, {"numero": 7, "texto": "Que guarda a misericórdia em milhares, que perdoa a iniquidade, a rebelião, e o pecado, e que de nenhum modo justificará ao malvado; que visita a iniquidade dos pais sobre os filhos e sobre os filhos dos filhos, sobre os de terceira, e quarta gerações."}, {"numero": 8, "texto": "Então Moisés, apressando-se, baixou a cabeça até o chão e encurvou-se;"}, {"numero": 9, "texto": "E disse: Se agora, Senhor, achei favor em teus olhos, vá agora o Senhor em meio de nós; porque este é povo de dura cerviz; e perdoa nossa iniquidade e nosso pecado, e possui-nos."}, {"numero": 10, "texto": "E ele disse: Eis que, eu faço concerto diante de todo o teu povo: farei maravilhas que não foram feitas em toda a terra, nem em nação alguma; e verá todo o povo em meio do qual estás tu, a obra do SENHOR; porque será coisa terrível a que eu farei contigo."}, {"numero": 11, "texto": "Guarda o que eu te mando hoje; eis que eu expulso de diante de tua presença aos amorreus, e aos cananeus, e aos heteus, e aos perizeus, e aos heveus, e aos jebuseus."}, {"numero": 12, "texto": "Guarda-te que não faças aliança com os moradores da terra de onde hás de entrar, para que não sejam por tropeço em meio de ti:"}, {"numero": 13, "texto": "Mas derrubareis seus altares, e quebrareis suas estátuas, e cortareis seus bosques:"}, {"numero": 14, "texto": "Porque não te hás de inclinar a deus alheio; que o SENHOR, cujo nome é zeloso, Deus zeloso é."}, {"numero": 15, "texto": "Portanto não farás aliança com os moradores daquela terra; pois senão fornicarão após seus deuses, e sacrificarão a seus deuses, e te chamarão, e comerás de seus sacrifícios;"}, {"numero": 16, "texto": "Ou, se tomarem de suas filhas para teus filhos, e fornicarem suas filhas após seus deuses, farão também fornicar a teus filhos atrás dos deuses delas."}, {"numero": 17, "texto": "Não farás deuses de fundição para ti."}, {"numero": 18, "texto": "A festa dos pães ázimos guardarás: sete dias comerás sem levedar, segundo te mandei, no tempo do mês de Abibe; porque no mês de Abibe saíste do Egito."}, {"numero": 19, "texto": "Todo o que abre madre, meu é; e de teu gado todo primeiro de vaca ou de ovelha que for macho."}, {"numero": 20, "texto": "Porém resgatarás com cordeiro o primeiro do asno; e se não o resgatares, lhe cortarás a cabeça. Resgatarás todo primogênito de teus filhos, e não serão vistos vazios diante de mim."}, {"numero": 21, "texto": "Seis dias trabalharás, mas no sétimo dia cessarás: cessarás ainda na arada e na colheita."}, {"numero": 22, "texto": "E te farás a festa das semanas aos princípios da colheita do trigo: e a festa da colheita à volta do ano."}, {"numero": 23, "texto": "Três vezes no ano será visto todo homem teu diante do Soberano SENHOR, Deus de Israel."}, {"numero": 24, "texto": "Porque eu lançarei as nações de tua presença, e alargarei teu termo: e ninguém cobiçará tua terra, quando tu subires para ser visto diante do SENHOR teu Deus três vezes no ano."}, {"numero": 25, "texto": "Não oferecerás com levedado o sangue de meu sacrifício; nem ficará da noite para a manhã o sacrifício da festa da páscoa."}, {"numero": 26, "texto": "A primícia dos primeiros frutos de tua terra meterás na casa do SENHOR teu Deus. Não cozerás o cabrito no leite de sua mãe."}, {"numero": 27, "texto": "E o SENHOR disse a Moisés: Escreve tu estas palavras; porque conforme estas palavras fiz a aliança contigo e com Israel."}, {"numero": 28, "texto": "E ele esteve ali com o SENHOR quarenta dias e quarenta noites: não comeu pão, nem bebeu água; e escreveu em tábuas as palavras da aliança, os dez dizeres."}, {"numero": 29, "texto": "E aconteceu que, descendo Moisés do monte Sinai com as duas tábuas do testemunho em sua mão, enquanto descia do monte, não sabia ele que a pele de seu rosto resplandecia, depois que havia com ele falado."}, {"numero": 30, "texto": "E olhou Arão e todos os filhos de Israel a Moisés, e eis que a pele de seu rosto era resplandescente; e tiveram medo de chegar-se a ele."}, {"numero": 31, "texto": "E chamou-os Moisés; e Arão e todos os príncipes da congregação voltaram-se a ele, e Moisés lhes falou."}, {"numero": 32, "texto": "E depois se chegaram todos os filhos de Israel, aos quais mandou todas as coisas que o SENHOR lhe havia dito no monte de Sinai."}, {"numero": 33, "texto": "E quando acabou Moisés de falar com eles, pôs um véu sobre seu rosto."}, {"numero": 34, "texto": "E quando vinha Moisés diante do SENHOR para falar com ele, tirava-se o véu até que saía; e saindo, falava com os filhos de Israel o que lhe era mandado;"}, {"numero": 35, "texto": "E viam os filhos de Israel o rosto de Moisés, que a pele de seu rosto era resplandescente; e voltava Moisés a pôr o véu sobre seu rosto, até que entrava a falar com ele."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 34, 'en', '[{"numero": 1, "texto": "And the Lord said unto Moses, Hew thee two tables of stone like unto the first: and I will write upon these tables the words that were in the first tables, which thou brakest."}, {"numero": 2, "texto": "And be ready in the morning, and come up in the morning unto mount Sinai, and present thyself there to me in the top of the mount."}, {"numero": 3, "texto": "And no man shall come up with thee, neither let any man be seen throughout all the mount; neither let the flocks nor herds feed before that mount."}, {"numero": 4, "texto": "And he hewed two tables of stone like unto the first; and Moses rose up early in the morning, and went up unto mount Sinai, as the Lord had commanded him, and took in his hand the two tables of stone."}, {"numero": 5, "texto": "And the Lord descended in the cloud, and stood with him there, and proclaimed the name of the Lord."}, {"numero": 6, "texto": "And the Lord passed by before him, and proclaimed, The Lord, The Lord God, merciful and gracious, longsuffering, and abundant in goodness and truth,"}, {"numero": 7, "texto": "Keeping mercy for thousands, forgiving iniquity and transgression and sin, and that will by no means clear the guilty; visiting the iniquity of the fathers upon the children, and upon the children''s children, unto the third and to the fourth generation."}, {"numero": 8, "texto": "And Moses made haste, and bowed his head toward the earth, and worshipped."}, {"numero": 9, "texto": "And he said, If now I have found grace in thy sight, O Lord, let my Lord, I pray thee, go among us; for it is a stiffnecked people; and pardon our iniquity and our sin, and take us for thine inheritance."}, {"numero": 10, "texto": "And he said, Behold, I make a covenant: before all thy people I will do marvels, such as have not been done in all the earth, nor in any nation: and all the people among which thou art shall see the work of the Lord: for it is a terrible thing that I will do with thee."}, {"numero": 11, "texto": "Observe thou that which I command thee this day: behold, I drive out before thee the Amorite, and the Canaanite, and the Hittite, and the Perizzite, and the Hivite, and the Jebusite."}, {"numero": 12, "texto": "Take heed to thyself, lest thou make a covenant with the inhabitants of the land whither thou goest, lest it be for a snare in the midst of thee:"}, {"numero": 13, "texto": "But ye shall destroy their altars, break their images, and cut down their groves:"}, {"numero": 14, "texto": "For thou shalt worship no other god: for the Lord, whose name is Jealous, is a jealous God:"}, {"numero": 15, "texto": "Lest thou make a covenant with the inhabitants of the land, and they go a whoring after their gods, and do sacrifice unto their gods, and one call thee, and thou eat of his sacrifice;"}, {"numero": 16, "texto": "And thou take of their daughters unto thy sons, and their daughters go a whoring after their gods, and make thy sons go a whoring after their gods."}, {"numero": 17, "texto": "Thou shalt make thee no molten gods."}, {"numero": 18, "texto": "The feast of unleavened bread shalt thou keep. Seven days thou shalt eat unleavened bread, as I commanded thee, in the time of the month Abib: for in the month Abib thou camest out from Egypt."}, {"numero": 19, "texto": "All that openeth the matrix is mine; and every firstling among thy cattle, whether ox or sheep, that is male."}, {"numero": 20, "texto": "But the firstling of an ass thou shalt redeem with a lamb: and if thou redeem him not, then shalt thou break his neck. All the firstborn of thy sons thou shalt redeem. And none shall appear before me empty."}, {"numero": 21, "texto": "Six days thou shalt work, but on the seventh day thou shalt rest: in earing time and in harvest thou shalt rest."}, {"numero": 22, "texto": "And thou shalt observe the feast of weeks, of the firstfruits of wheat harvest, and the feast of ingathering at the year''s end."}, {"numero": 23, "texto": "Thrice in the year shall all your menchildren appear before the Lord God, the God of Israel."}, {"numero": 24, "texto": "For I will cast out the nations before thee, and enlarge thy borders: neither shall any man desire thy land, when thou shalt go up to appear before the Lord thy God thrice in the year."}, {"numero": 25, "texto": "Thou shalt not offer the blood of my sacrifice with leaven; neither shall the sacrifice of the feast of the passover be left unto the morning."}, {"numero": 26, "texto": "The first of the firstfruits of thy land thou shalt bring unto the house of the Lord thy God. Thou shalt not seethe a kid in his mother''s milk."}, {"numero": 27, "texto": "And the Lord said unto Moses, Write thou these words: for after the tenor of these words I have made a covenant with thee and with Israel."}, {"numero": 28, "texto": "And he was there with the Lord forty days and forty nights; he did neither eat bread, nor drink water. And he wrote upon the tables the words of the covenant, the ten commandments."}, {"numero": 29, "texto": "And it came to pass, when Moses came down from mount Sinai with the two tables of testimony in Moses'' hand, when he came down from the mount, that Moses wist not that the skin of his face shone while he talked with him."}, {"numero": 30, "texto": "And when Aaron and all the children of Israel saw Moses, behold, the skin of his face shone; and they were afraid to come nigh him."}, {"numero": 31, "texto": "And Moses called unto them; and Aaron and all the rulers of the congregation returned unto him: and Moses talked with them."}, {"numero": 32, "texto": "And afterward all the children of Israel came nigh: and he gave them in commandment all that the Lord had spoken with him in mount Sinai."}, {"numero": 33, "texto": "And till Moses had done speaking with them, he put a vail on his face."}, {"numero": 34, "texto": "But when Moses went in before the Lord to speak with him, he took the vail off, until he came out. And he came out, and spake unto the children of Israel that which he was commanded."}, {"numero": 35, "texto": "And the children of Israel saw the face of Moses, that the skin of Moses'' face shone: and Moses put the vail upon his face again, until he went in to speak with him."}]'::jsonb, 'King James Version'),
  ('Ex', 34, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Moïse: Taille deux tables de pierre comme les premières, et j''''y écrirai les paroles qui étaient sur les premières tables que tu as brisées."}, {"numero": 2, "texto": "Sois prêt de bonne heure, et tu monteras dès le matin sur la montagne de Sinaï; tu te tiendras là devant moi, sur le sommet de la montagne."}, {"numero": 3, "texto": "Que personne ne monte avec toi, et que personne ne paraisse sur toute la montagne; et même que ni brebis ni boeufs ne paissent près de cette montagne."}, {"numero": 4, "texto": "Moïse tailla deux tables de pierre comme les premières; il se leva de bon matin, et monta sur la montagne de Sinaï, selon l''''ordre que l''''Eternel lui avait donné, et il prit dans sa main les deux tables de pierre."}, {"numero": 5, "texto": "L''''Eternel descendit dans une nuée, se tint là auprès de lui, et proclama le nom de l''''Eternel."}, {"numero": 6, "texto": "Et l''''Eternel passa devant lui, et s''''écria: L''''Eternel, l''''Eternel, Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité,"}, {"numero": 7, "texto": "qui conserve son amour jusqu''''à mille générations, qui pardonne l''''iniquité, la rébellion et le péché, mais qui ne tient point le coupable pour innocent, et qui punit l''''iniquité des pères sur les enfants et sur les enfants des enfants jusqu''''à la troisième et à la quatrième génération!"}, {"numero": 8, "texto": "Aussitôt Moïse s''''inclina à terre et se prosterna."}, {"numero": 9, "texto": "Il dit: Seigneur, si j''''ai trouvé grâce à tes yeux, que le Seigneur marche au milieu de nous, car c''''est un peuple au cou roide; pardonne nos iniquités et nos péchés, et prends-nous pour ta possession."}, {"numero": 10, "texto": "L''''Eternel répondit: Voici, je traite une alliance. Je ferai, en présence de tout ton peuple, des prodiges qui n''''ont eu lieu dans aucun pays et chez aucune nation; tout le peuple qui t''''environne verra l''''oeuvre de l''''Eternel, et c''''est par toi que j''''accomplirai des choses terribles."}, {"numero": 11, "texto": "Prends garde à ce que je t''''ordonne aujourd''''hui. Voici, je chasserai devant toi les Amoréens, les Cananéens, les Héthiens, les Phéréziens, les Héviens et les Jébusiens."}, {"numero": 12, "texto": "Garde-toi de faire alliance avec les habitants du pays où tu dois entrer, de peur qu''''ils ne soient un piège pour toi."}, {"numero": 13, "texto": "Au contraire, vous renverserez leurs autels, vous briserez leurs statues, et vous abattrez leurs idoles."}, {"numero": 14, "texto": "Tu ne te prosterneras point devant un autre dieu; car l''''Eternel porte le nom de jaloux, il est un Dieu jaloux."}, {"numero": 15, "texto": "Garde-toi de faire alliance avec les habitants du pays, de peur que, se prostituant à leurs dieux et leur offrant des sacrifices, ils ne t''''invitent, et que tu ne manges de leurs victimes;"}, {"numero": 16, "texto": "de peur que tu ne prennes de leurs filles pour tes fils, et que leurs filles, se prostituant à leurs dieux, n''''entraînent tes fils à se prostituer à leurs dieux."}, {"numero": 17, "texto": "Tu ne te feras point de dieu en fonte."}, {"numero": 18, "texto": "Tu observeras la fête des pains sans levain; pendant sept jours, au temps fixé dans le mois des épis, tu mangeras des pains sans levain, comme je t''''en ai donné l''''ordre, car c''''est dans le mois des épis que tu es sorti d''''Egypte."}, {"numero": 19, "texto": "Tout premier-né m''''appartient, même tout mâle premier-né dans les troupeaux de gros et de menu bétail."}, {"numero": 20, "texto": "Tu rachèteras avec un agneau le premier-né de l''''âne; et si tu ne le rachètes pas, tu lui briseras la nuque. Tu rachèteras tout premier-né de tes fils; et l''''on ne se présentera point à vide devant ma face."}, {"numero": 21, "texto": "Tu travailleras six jours, et tu te reposeras le septième jour; tu te reposeras, même au temps du labourage et de la moisson."}, {"numero": 22, "texto": "Tu célébreras la fête des semaines, des prémices de la moisson du froment, et la fête de la récolte, à la fin de l''''année."}, {"numero": 23, "texto": "Trois fois par an, tous les mâles se présenteront devant le Seigneur, l''''Eternel, Dieu d''''Israël."}, {"numero": 24, "texto": "Car je chasserai les nations devant toi, et j''''étendrai tes frontières; et personne ne convoitera ton pays, pendant que tu monteras pour te présenter devant l''''Eternel, ton Dieu, trois fois par an."}, {"numero": 25, "texto": "Tu n''''offriras point avec du pain levé le sang de la victime immolée en mon honneur; et le sacrifice de la fête de Pâque ne sera point gardé pendant la nuit jusqu''''au matin."}, {"numero": 26, "texto": "Tu apporteras à la maison de L''''Eternel, ton Dieu, les prémices des premiers fruits de la terre. Tu ne feras point cuire un chevreau dans le lait de sa mère."}, {"numero": 27, "texto": "L''''Eternel dit à Moïse: Ecris ces paroles; car c''''est conformément à ces paroles que je traite alliance avec toi et avec Israël."}, {"numero": 28, "texto": "Moïse fut là avec l''''Eternel quarante jours et quarante nuits. Il ne mangea point de pain, et il ne but point d''''eau. Et l''''Eternel écrivit sur les tables les paroles de l''''alliance, les dix paroles."}, {"numero": 29, "texto": "Moïse descendit de la montagne de Sinaï, ayant les deux tables du témoignage dans sa main, en descendant de la montagne; et il ne savait pas que la peau de son visage rayonnait, parce qu''''il avait parlé avec l''''Eternel."}, {"numero": 30, "texto": "Aaron et tous les enfants d''''Israël regardèrent Moïse, et voici la peau de son visage rayonnait; et ils craignaient de s''''approcher de lui."}, {"numero": 31, "texto": "Moïse les appela; Aaron et tous les principaux de l''''assemblée vinrent auprès de lui, et il leur parla."}, {"numero": 32, "texto": "Après cela, tous les enfants d''''Israël s''''approchèrent, et il leur donna tous les ordres qu''''il avait reçus de l''''Eternel, sur la montagne de Sinaï."}, {"numero": 33, "texto": "Lorsque Moïse eut achevé de leur parler, il mit un voile sur son visage."}, {"numero": 34, "texto": "Quand Moïse entrait devant l''''Eternel, pour lui parler, il ôtait le voile, jusqu''''à ce qu''''il sortît; et quand il sortait, il disait aux enfants d''''Israël ce qui lui avait été ordonné."}, {"numero": 35, "texto": "Les enfants d''''Israël regardaient le visage de Moïse, et voyaient que la peau de son visage rayonnait; et Moïse remettait le voile sur son visage jusqu''''à ce qu''''il entrât, pour parler avec l''''Eternel."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 34, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Moisés: Alísate dos tablas de piedra como las primeras, y escribiré sobre esas tablas las palabras que estaban en las tablas primeras que quebraste."}, {"numero": 2, "texto": "Apercíbete, pues, para mañana, y sube por la mañana al monte de Sinaí, y estáme allí sobre la cumbre del monte."}, {"numero": 3, "texto": "Y no suba hombre contigo, ni parezca alguno en todo el monte; ni ovejas ni bueyes pazcan delante del monte."}, {"numero": 4, "texto": "Y Moisés alisó dos tablas de piedra como las primeras; y levantóse por la mañana, y subió al monte de Sinaí, como le mandó Jehová, y llevó en su mano las dos tablas de piedra."}, {"numero": 5, "texto": "Y Jehová descendió en la nube, y estuvo allí con él, proclamando el nombre de Jehová."}, {"numero": 6, "texto": "Y pasando Jehová por delante de él, proclamó: Jehová, Jehová, fuerte, misericordioso, y piadoso; tardo para la ira, y grande en benignidad y verdad;"}, {"numero": 7, "texto": "Que guarda la misericordia en millares, que perdona la iniquidad, la rebelión, y el pecado, y que de ningún modo justificará al malvado; que visita la iniquidad de los padres sobre los hijos y sobre los hijos de los hijos, sobre los terceros, y sobre los cuartos."}, {"numero": 8, "texto": "Entonces Moisés, apresurándose, bajó la cabeza hacia el suelo y encorvóse;"}, {"numero": 9, "texto": "Y dijo: Si ahora, Señor, he hallado gracia en tus ojos, vaya ahora el Señor en medio de nosotros; porque este es pueblo de dura cerviz; y perdona nuestra iniquidad y nuestro pecado, y poséenos."}, {"numero": 10, "texto": "Y él dijo: He aquí, yo hago concierto delante de todo tu pueblo: haré maravillas que no han sido hechas en toda la tierra, ni en nación alguna; y verá todo el pueblo en medio del cual estás tú, la obra de Jehová; porque ha de ser cosa terrible la que yo haré contigo."}, {"numero": 11, "texto": "Guarda lo que yo te mando hoy; he aquí que yo echo de delante de tu presencia al Amorrheo, y al Cananeo, y al Hetheo, y al Pherezeo, y al Heveo, y al Jebuseo."}, {"numero": 12, "texto": "Guárdate que no hagas alianza con los moradores de la tierra donde has de entrar, porque no sean por tropezadero en medio de tí:"}, {"numero": 13, "texto": "Mas derribaréis sus altares, y quebraréis sus estatuas, y talaréis sus bosques:"}, {"numero": 14, "texto": "Porque no te has de inclinar á dios ajeno; que Jehová, cuyo nombre es Celoso, Dios celoso es."}, {"numero": 15, "texto": "Por tanto no harás alianza con los moradores de aquella tierra; porque fornicarán en pos de sus dioses, y sacrificarán á sus dioses, y te llamarán, y comerás de sus sacrificios;"}, {"numero": 16, "texto": "O tomando de sus hijas para tus hijos, y fornicando sus hijas en pos de sus dioses, harán también fornicar á tus hijos en pos de los dioses de ellas."}, {"numero": 17, "texto": "No harás dioses de fundición para ti."}, {"numero": 18, "texto": "La fiesta de los ázimos guardarás: siete días comerás por leudar, según te he mandado, en el tiempo del mes de Abib; porque en el mes de Abib saliste de Egipto."}, {"numero": 19, "texto": "Todo lo que abre matriz, mío es; y de tu ganado todo primerizo de vaca ó de oveja que fuere macho."}, {"numero": 20, "texto": "Empero redimirás con cordero el primerizo del asno; y si no lo redimieres, le has de cortar la cabeza. Redimirás todo primogénito de tus hijos, y no serán vistos vacíos delante de mí."}, {"numero": 21, "texto": "Seis días trabajarás, mas en el séptimo día cesarás: cesarás aun en la arada y en la siega."}, {"numero": 22, "texto": "Y te harás la fiesta de las semanas á los principios de la siega del trigo: y la fiesta de la cosecha á la vuelta del año."}, {"numero": 23, "texto": "Tres veces en el año será visto todo varón tuyo delante del Señoreador Jehová, Dios de Israel."}, {"numero": 24, "texto": "Porque yo arrojaré las gentes de tu presencia, y ensancharé tu término: y ninguno codiciará tu tierra, cuando tú subieres para ser visto delante de Jehová tu Dios tres veces en el año."}, {"numero": 25, "texto": "No ofrecerás con leudo la sangre de mi sacrificio; ni quedará de la noche para la mañana el sacrificio de la fiesta de la pascua."}, {"numero": 26, "texto": "La primicia de los primeros frutos de tu tierra meterás en la casa de Jehová tu Dios. No cocerás el cabrito en la leche de su madre."}, {"numero": 27, "texto": "Y Jehová dijo á Moisés: Escribe tú estas palabras; porque conforme á estas palabras he hecho la alianza contigo y con Israel."}, {"numero": 28, "texto": "Y él estuvo allí con Jehová cuarenta días y cuarenta noches: no comió pan, ni bebió agua; y escribió en tablas las palabras de la alianza, las diez palabras."}, {"numero": 29, "texto": "Y aconteció, que descendiendo Moisés del monte Sinaí con las dos tablas del testimonio en su mano, mientras descendía del monte, no sabía él que la tez de su rostro resplandecía, después que hubo con El hablado."}, {"numero": 30, "texto": "Y miró Aarón y todos los hijos de Israel á Moisés, y he aquí la tez de su rostro era resplandeciente; y tuvieron miedo de llegarse á él."}, {"numero": 31, "texto": "Y llamólos Moisés; y Aarón y todos los príncipes de la congregación volvieron á él, y Moisés les habló."}, {"numero": 32, "texto": "Y después se llegaron todos los hijos de Israel, á los cuales mandó todas las cosas que Jehová le había dicho en el monte de Sinaí."}, {"numero": 33, "texto": "Y cuando hubo acabado Moisés de hablar con ellos, puso un velo sobre su rostro."}, {"numero": 34, "texto": "Y cuando venía Moisés delante de Jehová para hablar con él, quitábase el velo hasta que salía; y saliendo, hablaba con los hijos de Israel lo que le era mandado;"}, {"numero": 35, "texto": "Y veían los hijos de Israel el rostro de Moisés, que la tez de su rostro era resplandeciente; y volvía Moisés á poner el velo sobre su rostro, hasta que entraba á hablar con El."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 35, 'pt', '[{"numero": 1, "texto": "E Moisés fez juntar toda a congregação dos filhos de Israel, e disse-lhes: Estas são as coisas que o SENHOR mandou que façais."}, {"numero": 2, "texto": "Seis dias se fará obra, mas o dia sétimo vos será santo, sábado de repouso ao SENHOR: qualquer um que nele fizer obra morrerá."}, {"numero": 3, "texto": "Não acendereis fogo em todas as vossas moradas no dia do sábado."}, {"numero": 4, "texto": "E falou Moisés a toda a congregação dos filhos de Israel, dizendo: Isto é o que o SENHOR mandou, dizendo:"}, {"numero": 5, "texto": "Tomai dentre vós oferta para o SENHOR: todo generoso de coração a trará ao SENHOR: ouro, prata, bronze;"}, {"numero": 6, "texto": "E azul, e púrpura, e carmesim, e linho fino, e pelo de cabras;"}, {"numero": 7, "texto": "E couros vermelhos de carneiros, e couros finos, e madeira de acácia;"}, {"numero": 8, "texto": "E azeite para a luminária, e especiarias aromáticas para o azeite da unção, e para o incenso aromático;"}, {"numero": 9, "texto": "E pedras de ônix, e demais pedrarias, para o éfode, e para o peitoral."}, {"numero": 10, "texto": "E todo sábio de coração dentre vós, virá e fará todas as coisas que o SENHOR mandou:"}, {"numero": 11, "texto": "O tabernáculo, sua tenda, e sua coberta, e seus anéis, e suas tábuas, suas barras, suas colunas, e suas bases;"}, {"numero": 12, "texto": "A arca, e suas varas, o propiciatório, e o véu da tenda;"}, {"numero": 13, "texto": "A mesa, e suas varas, e todos os seus utensílios, e o pão da proposição."}, {"numero": 14, "texto": "O candelabro da luminária, e seus utensílios, e suas lâmpadas, e o azeite para a luminária;"}, {"numero": 15, "texto": "E o altar do incenso, e suas varas, e o azeite da unção, e o incenso aromático, e a cortina da porta, para a entrada do tabernáculo;"}, {"numero": 16, "texto": "O altar do holocausto, e sua grelha de bronze, e suas varas, e todos os seus utensílios, e a pia com sua base;"}, {"numero": 17, "texto": "As cortinas do átrio, suas colunas, e suas bases, e a cortina da porta do átrio;"}, {"numero": 18, "texto": "As estacas do tabernáculo, e as estacas do átrio, e suas cordas;"}, {"numero": 19, "texto": "As vestimentas dos serviço para ministrar no santuário, as sagradas vestimentas de Arão o sacerdote, e as vestimentas de seus filhos para servir no sacerdócio."}, {"numero": 20, "texto": "E saiu toda a congregação dos filhos de Israel de diante de Moisés."}, {"numero": 21, "texto": "E veio todo homem a quem seu coração estimulou, e todo aquele a quem seu espírito lhe deu vontade, e trouxeram oferta ao SENHOR para a obra do tabernáculo do testemunho, e para toda sua confecção, e para as sagradas vestimentas."}, {"numero": 22, "texto": "E vieram tanto homens como mulheres, todo voluntário de coração, e trouxeram correntes e pendentes, anéis e braceletes, e toda joia de ouro; e qualquer um oferecia oferta de ouro ao SENHOR."}, {"numero": 23, "texto": "Todo homem que se achava com material azul, ou púrpura, ou carmesim, ou linho fino, ou pelo de cabras, ou odres vermelhos de carneiros, ou couros finos, o trazia."}, {"numero": 24, "texto": "Qualquer um que oferecia oferta de prata ou de bronze, trazia ao SENHOR a oferta: e todo o que se achava com madeira de acácia, trazia-a para toda a obra do serviço."}, {"numero": 25, "texto": "Além disso todas as mulheres sábias de coração fiavam de suas mãos, e traziam o que haviam fiado: azul, ou púrpura, ou carmesim, ou linho fino."}, {"numero": 26, "texto": "E todas as mulheres cujo coração as levantou em sabedoria, fiaram pelos de cabras."}, {"numero": 27, "texto": "E os príncipes trouxeram pedras de ônix, e as pedras dos engastes para o éfode e o peitoral;"}, {"numero": 28, "texto": "E a especiaria aromática e azeite, para a luminária, e para o azeite da unção, e para o incenso aromático."}, {"numero": 29, "texto": "Dos filhos de Israel, tanto homens como mulheres, todos os que tiveram coração voluntário para trazer para toda a obra, que o SENHOR havia mandado por meio de Moisés que fizessem, trouxeram oferta voluntária ao SENHOR."}, {"numero": 30, "texto": "E disse Moisés aos filhos de Israel: Olhai, o SENHOR nomeou a Bezalel filho de Uri, filho de Hur, da tribo de Judá;"}, {"numero": 31, "texto": "E o encheu de espírito de Deus, em sabedoria, em inteligência, e em conhecimento, e em todo artifício,"}, {"numero": 32, "texto": "Para projetar inventos, para trabalhar em ouro, e em prata, e em bronze,"}, {"numero": 33, "texto": "E em obra de pedrarias para engastar, e em obra de madeira, para trabalhar em toda invenção engenhosa."}, {"numero": 34, "texto": "E pôs em seu coração o que podia ensinar, tanto ele como Aoliabe filho de Aisamaque, da tribo de Dã:"}, {"numero": 35, "texto": "E os encheu de sabedoria de coração, para que façam toda obra de artifício, e de invenção, e de recamado em azul, e em púrpura, e em carmesim, e em linho fino, e em tear; para que façam todo trabalho, e inventem todo desenho."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 35, 'en', '[{"numero": 1, "texto": "And Moses gathered all the congregation of the children of Israel together, and said unto them, These are the words which the Lord hath commanded, that ye should do them."}, {"numero": 2, "texto": "Six days shall work be done, but on the seventh day there shall be to you an holy day, a sabbath of rest to the Lord: whosoever doeth work therein shall be put to death."}, {"numero": 3, "texto": "Ye shall kindle no fire throughout your habitations upon the sabbath day."}, {"numero": 4, "texto": "And Moses spake unto all the congregation of the children of Israel, saying, This is the thing which the Lord commanded, saying,"}, {"numero": 5, "texto": "Take ye from among you an offering unto the Lord: whosoever is of a willing heart, let him bring it, an offering of the Lord; gold, and silver, and brass,"}, {"numero": 6, "texto": "And blue, and purple, and scarlet, and fine linen, and goats'' hair,"}, {"numero": 7, "texto": "And rams'' skins dyed red, and badgers'' skins, and shittim wood,"}, {"numero": 8, "texto": "And oil for the light, and spices for anointing oil, and for the sweet incense,"}, {"numero": 9, "texto": "And onyx stones, and stones to be set for the ephod, and for the breastplate."}, {"numero": 10, "texto": "And every wise hearted among you shall come, and make all that the Lord hath commanded;"}, {"numero": 11, "texto": "The tabernacle, his tent, and his covering, his taches, and his boards, his bars, his pillars, and his sockets,"}, {"numero": 12, "texto": "The ark, and the staves thereof, with the mercy seat, and the vail of the covering,"}, {"numero": 13, "texto": "The table, and his staves, and all his vessels, and the shewbread,"}, {"numero": 14, "texto": "The candlestick also for the light, and his furniture, and his lamps, with the oil for the light,"}, {"numero": 15, "texto": "And the incense altar, and his staves, and the anointing oil, and the sweet incense, and the hanging for the door at the entering in of the tabernacle,"}, {"numero": 16, "texto": "The altar of burnt offering, with his brasen grate, his staves, and all his vessels, the laver and his foot,"}, {"numero": 17, "texto": "The hangings of the court, his pillars, and their sockets, and the hanging for the door of the court,"}, {"numero": 18, "texto": "The pins of the tabernacle, and the pins of the court, and their cords,"}, {"numero": 19, "texto": "The cloths of service, to do service in the holy place, the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest''s office."}, {"numero": 20, "texto": "And all the congregation of the children of Israel departed from the presence of Moses."}, {"numero": 21, "texto": "And they came, every one whose heart stirred him up, and every one whom his spirit made willing, and they brought the Lord''s offering to the work of the tabernacle of the congregation, and for all his service, and for the holy garments."}, {"numero": 22, "texto": "And they came, both men and women, as many as were willing hearted, and brought bracelets, and earrings, and rings, and tablets, all jewels of gold: and every man that offered offered an offering of gold unto the Lord."}, {"numero": 23, "texto": "And every man, with whom was found blue, and purple, and scarlet, and fine linen, and goats'' hair, and red skins of rams, and badgers'' skins, brought them."}, {"numero": 24, "texto": "Every one that did offer an offering of silver and brass brought the Lord''s offering: and every man, with whom was found shittim wood for any work of the service, brought it."}, {"numero": 25, "texto": "And all the women that were wise hearted did spin with their hands, and brought that which they had spun, both of blue, and of purple, and of scarlet, and of fine linen."}, {"numero": 26, "texto": "And all the women whose heart stirred them up in wisdom spun goats'' hair."}, {"numero": 27, "texto": "And the rulers brought onyx stones, and stones to be set, for the ephod, and for the breastplate;"}, {"numero": 28, "texto": "And spice, and oil for the light, and for the anointing oil, and for the sweet incense."}, {"numero": 29, "texto": "The children of Israel brought a willing offering unto the Lord, every man and woman, whose heart made them willing to bring for all manner of work, which the Lord had commanded to be made by the hand of Moses."}, {"numero": 30, "texto": "And Moses said unto the children of Israel, See, the Lord hath called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah;"}, {"numero": 31, "texto": "And he hath filled him with the spirit of God, in wisdom, in understanding, and in knowledge, and in all manner of workmanship;"}, {"numero": 32, "texto": "And to devise curious works, to work in gold, and in silver, and in brass,"}, {"numero": 33, "texto": "And in the cutting of stones, to set them, and in carving of wood, to make any manner of cunning work."}, {"numero": 34, "texto": "And he hath put in his heart that he may teach, both he, and Aholiab, the son of Ahisamach, of the tribe of Dan."}, {"numero": 35, "texto": "Them hath he filled with wisdom of heart, to work all manner of work, of the engraver, and of the cunning workman, and of the embroiderer, in blue, and in purple, in scarlet, and in fine linen, and of the weaver, even of them that do any work, and of those that devise cunning work."}]'::jsonb, 'King James Version'),
  ('Ex', 35, 'fr', '[{"numero": 1, "texto": "Moïse convoqua toute l''''assemblée des enfants d''''Israël, et leur dit: Voici les choses que l''''Eternel ordonne de faire."}, {"numero": 2, "texto": "On travaillera six jours; mais le septième jour sera pour vous une chose sainte; c''''est le sabbat, le jour du repos, consacré à l''''Eternel. Celui qui fera quelque ouvrage ce jour-là, sera puni de mort."}, {"numero": 3, "texto": "Vous n''''allumerez point de feu, dans aucune de vos demeures, le jour du sabbat."}, {"numero": 4, "texto": "Moïse parla à toute l''''assemblée des enfants d''''Israël, et dit: Voici ce que l''''Eternel a ordonné."}, {"numero": 5, "texto": "Prenez sur ce qui vous appartient une offrande pour l''''Eternel. Tout homme dont le coeur est bien disposé apportera en offrande à l''''Eternel: de l''''or, de l''''argent et de l''''airain;"}, {"numero": 6, "texto": "des étoffes teintes en bleu, en pourpre, en cramoisi, du fin lin et du poil de chèvre;"}, {"numero": 7, "texto": "des peaux de béliers teintes en rouge et des peaux de dauphins; du bois d''''acacia;"}, {"numero": 8, "texto": "de l''''huile pour le chandelier, des aromates pour l''''huile d''''onction et pour le parfum odoriférant;"}, {"numero": 9, "texto": "des pierres d''''onyx et d''''autres pierres pour la garniture de l''''éphod et du pectoral."}, {"numero": 10, "texto": "Que tous ceux d''''entre vous qui ont de l''''habileté viennent et exécutent tout ce que l''''Eternel a ordonné:"}, {"numero": 11, "texto": "le tabernacle, sa tente et sa couverture, ses agrafes, ses planches, ses barres, ses colonnes et ses bases;"}, {"numero": 12, "texto": "l''''arche et ses barres, le propitiatoire, et le voile pour couvrir l''''arche;"}, {"numero": 13, "texto": "la table et ses barres, et tous ses ustensiles, et les pains de proposition;"}, {"numero": 14, "texto": "le chandelier et ses ustensiles, ses lampes, et l''''huile pour le chandelier;"}, {"numero": 15, "texto": "l''''autel des parfums et ses barres, l''''huile d''''onction et le parfum odoriférant, et le rideau de la porte pour l''''entrée du tabernacle;"}, {"numero": 16, "texto": "l''''autel des holocaustes, sa grille d''''airain, ses barres, et tous ses ustensiles; la cuve avec sa base;"}, {"numero": 17, "texto": "les toiles du parvis, ses colonnes, ses bases, et le rideau de la porte du parvis;"}, {"numero": 18, "texto": "les pieux du tabernacle, les pieux du parvis, et leurs cordages;"}, {"numero": 19, "texto": "les vêtements d''''office pour le service dans le sanctuaire, les vêtements sacrés pour le sacrificateur Aaron, et les vêtements de ses fils pour les fonctions du sacerdoce."}, {"numero": 20, "texto": "Toute l''''assemblée des enfants d''''Israël sortit de la présence de Moïse."}, {"numero": 21, "texto": "Tous ceux qui furent entraînés par le coeur et animés de bonne volonté vinrent et apportèrent une offrande à l''''Eternel pour l''''oeuvre de la tente d''''assignation, pour tout son service, et pour les vêtements sacrés."}, {"numero": 22, "texto": "Les hommes vinrent aussi bien que les femmes; tous ceux dont le coeur était bien disposé apportèrent des boucles, des anneaux, des bagues, des bracelets, toutes sortes d''''objets d''''or; chacun présenta l''''offrande d''''or qu''''il avait consacrée à l''''Eternel."}, {"numero": 23, "texto": "Tous ceux qui avaient des étoffes teintes en bleu, en pourpre, en cramoisi, du fin lin et du poil de chèvre, des peaux de béliers teintes en rouge et des peaux de dauphins, les apportèrent."}, {"numero": 24, "texto": "Tous ceux qui présentèrent par élévation une offrande d''''argent et d''''airain apportèrent l''''offrande à l''''Eternel. Tous ceux qui avaient du bois d''''acacia pour les ouvrages destinés au service, l''''apportèrent."}, {"numero": 25, "texto": "Toutes les femmes qui avaient de l''''habileté filèrent de leurs mains, et elles apportèrent leur ouvrage, des fils teints en bleu, en pourpre, en cramoisi, et du fin lin."}, {"numero": 26, "texto": "Toutes les femmes dont le coeur était bien disposé, et qui avaient de l''''habileté, filèrent du poil de chèvre."}, {"numero": 27, "texto": "Les principaux du peuple apportèrent des pierres d''''onyx et d''''autres pierres pour la garniture de l''''éphod et du pectoral;"}, {"numero": 28, "texto": "des aromates et de l''''huile pour le chandelier, pour l''''huile d''''onction et pour le parfum odoriférant."}, {"numero": 29, "texto": "Tous les enfants d''''Israël, hommes et femmes, dont le coeur était disposé à contribuer pour l''''oeuvre que l''''Eternel avait ordonnée par Moïse, apportèrent des offrandes volontaires à l''''Eternel."}, {"numero": 30, "texto": "Moïse dit aux enfants d''''Israël: Sachez que l''''Eternel a choisi Betsaleel, fils d''''Uri, fils de Hur, de la tribu de Juda."}, {"numero": 31, "texto": "Il l''''a rempli de l''''Esprit de Dieu, de sagesse, d''''intelligence, et de savoir pour toutes sortes d''''ouvrages."}, {"numero": 32, "texto": "Il l''''a rendu capable de faire des inventions, de travailler l''''or, l''''argent et l''''airain,"}, {"numero": 33, "texto": "de graver les pierres à enchâsser, de travailler le bois, et d''''exécuter toutes sortes d''''ouvrages d''''art."}, {"numero": 34, "texto": "Il lui a accordé aussi le don d''''enseigner, de même qu''''à Oholiab, fils d''''Ahisamac, de la tribu de Dan."}, {"numero": 35, "texto": "Il les a remplis d''''intelligence, pour exécuter tous les ouvrages de sculpture et d''''art, pour broder et tisser les étoffes teintes en bleu, en pourpre, en cramoisi, et le fin lin, pour faire toute espèce de travaux et d''''inventions."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 35, 'es', '[{"numero": 1, "texto": "Y MOISÉS hizo juntar toda la congregación de los hijos de Israel, y díjoles: Estas son las cosas que Jehová ha mandado que hagáis."}, {"numero": 2, "texto": "Seis días se hará obra, mas el día séptimo os será santo, sábado de reposo á Jehová: cualquiera que en él hiciere obra, morirá."}, {"numero": 3, "texto": "No encenderéis fuego en todas vuestras moradas en el día del sábado."}, {"numero": 4, "texto": "Y habló Moisés á toda la congregación de los hijos de Israel, diciendo: Esto es lo que Jehová ha mandado, diciendo:"}, {"numero": 5, "texto": "Tomad de entre vosotros ofrenda para Jehová: todo liberal de corazón la traerá á Jehová: oro, plata, metal;"}, {"numero": 6, "texto": "Y cárdeno, y púrpura, y carmesí, y lino fino, y pelo de cabras;"}, {"numero": 7, "texto": "Y cueros rojos de carneros, y cueros de tejones, y madera de Sittim;"}, {"numero": 8, "texto": "Y aceite para la luminaria, y especias aromáticas para el aceite de la unción, y para el perfume aromático;"}, {"numero": 9, "texto": "Y piedras de onix, y demás pedrería, para el ephod, y para el racional."}, {"numero": 10, "texto": "Y todo sabio de corazón entre vosotros, vendrá y hará todas las cosas que Jehová ha mandado:"}, {"numero": 11, "texto": "El tabernáculo, su tienda, y su cubierta, y sus anillos, y sus tablas, sus barras, sus columnas, y sus basas;"}, {"numero": 12, "texto": "El arca, y sus varas, la cubierta, y el velo de la tienda;"}, {"numero": 13, "texto": "La mesa, y sus varas, y todos sus vasos, y el pan de la proposición."}, {"numero": 14, "texto": "El candelero de la luminaria, y sus vasos, y sus candilejas, y el aceite para la luminaria;"}, {"numero": 15, "texto": "Y el altar del perfume, y sus varas, y el aceite de la unción, y el perfume aromático, y el pabellón de la puerta, para la entrada del tabernáculo;"}, {"numero": 16, "texto": "El altar del holocausto, y su enrejado de metal, y sus varas, y todos sus vasos, y la fuente con su basa;"}, {"numero": 17, "texto": "Las cortinas del atrio, sus columnas, y sus basas, y el pabellón de la puerta del atrio;"}, {"numero": 18, "texto": "Las estacas del tabernáculo, y las estacas del atrio, y sus cuerdas;"}, {"numero": 19, "texto": "Las vestiduras del servicio para ministrar en el santuario, las sagradas vestiduras de Aarón el sacerdote, y las vestiduras de sus hijos para servir en el sacerdocio."}, {"numero": 20, "texto": "Y salió toda la congregación de los hijos de Israel de delante de Moisés."}, {"numero": 21, "texto": "Y vino todo varón á quien su corazón estimuló, y todo aquel á quien su espíritu le dió voluntad, y trajeron ofrenda á Jehová para la obra del tabernáculo del testimonio, y para toda su fábrica, y para las sagradas vestiduras."}, {"numero": 22, "texto": "Y vinieron así hombres como mujeres, todo voluntario de corazón, y trajeron cadenas y zarcillos, sortijas y brazaletes, y toda joya de oro; y cualquiera ofrecía ofrenda de oro á Jehová."}, {"numero": 23, "texto": "Todo hombre que se hallaba con jacinto, ó púrpura, ó carmesí, ó lino fino, ó pelo de cabras, ó cueros rojos de carneros, ó cueros de tejones, lo traía."}, {"numero": 24, "texto": "Cualquiera que ofrecía ofrenda de plata ó de metal, traía á Jehová la ofrenda: y todo el que se hallaba con madera de Sittim, traíala para toda la obra del servicio."}, {"numero": 25, "texto": "Además todas las mujeres sabias de corazón hilaban de sus manos, y traían lo que habían hilado: cárdeno, ó púrpura, ó carmesí, ó lino fino."}, {"numero": 26, "texto": "Y todas las mujeres cuyo corazón las levantó en sabiduría, hilaron pelos de cabras."}, {"numero": 27, "texto": "Y los príncipes trajeron piedras de onix, y las piedras de los engastes para el ephod y el racional;"}, {"numero": 28, "texto": "Y la especia aromática y aceite, para la luminaria, y para el aceite de la unción, y para el perfume aromático."}, {"numero": 29, "texto": "De los hijos de Israel, así hombres como mujeres, todos los que tuvieron corazón voluntario para traer para toda la obra, que Jehová había mandado por medio de Moisés que hiciesen, trajeron ofrenda voluntaria á Jehová."}, {"numero": 30, "texto": "Y dijo Moisés á los hijos de Israel: Mirad, Jehová ha nombrado á Bezaleel, hijo de Uri, hijo de Hur, de la tribu de Judá;"}, {"numero": 31, "texto": "Y lo ha henchido de espíritu de Dios, en sabiduría, en inteligencia, y en ciencia, y en todo artificio,"}, {"numero": 32, "texto": "Para proyectar inventos, para trabajar en oro, y en plata, y en metal,"}, {"numero": 33, "texto": "Y en obra de pedrería para engastar, y en obra de madera, para trabajar en toda invención ingeniosa."}, {"numero": 34, "texto": "Y ha puesto en su corazón el que pueda enseñar, así él como Aholiab, hijo de Ahisamac, de la tribu de Dan:"}, {"numero": 35, "texto": "Y los ha henchido de sabiduría de corazón, para que hagan toda obra de artificio, y de invención, y de recamado en jacinto, y en púrpura, y en carmesí, y en lino fino, y en telar; para que hagan toda labor, é inventen todo diseño."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ex', 40, 'pt', '[{"numero": 1, "texto": "E o SENHOR falou a Moisés, dizendo:"}, {"numero": 2, "texto": "No primeiro dia do mês primeiro farás levantar o tabernáculo, o tabernáculo do testemunho:"}, {"numero": 3, "texto": "E porás nele a arca do testemunho, e a cobrirás com o véu:"}, {"numero": 4, "texto": "E meterás a mesa, e a porás em ordem: meterás também o candelabro e acenderás suas lâmpadas:"}, {"numero": 5, "texto": "E porás o altar de ouro para o incenso diante da arca do testemunho, e porás a cortina diante da porta do tabernáculo."}, {"numero": 6, "texto": "Depois porás o altar do holocausto diante da porta do tabernáculo, do tabernáculo do testemunho."}, {"numero": 7, "texto": "Logo porás a pia entre o tabernáculo do testemunho e o altar; e porás água nela."}, {"numero": 8, "texto": "Finalmente porás o átrio em derredor, e a cortina da porta do átrio."}, {"numero": 9, "texto": "E tomarás o azeite da unção e ungirás o tabernáculo, e tudo o que está nele; e lhe santificarás com todos os seus utensílios, e será santo."}, {"numero": 10, "texto": "Ungirás também o altar do holocausto e todos os seus utensílios: e santificarás o altar, e será um altar santíssimo."}, {"numero": 11, "texto": "Também ungirás a pia e sua base, e a santificarás."}, {"numero": 12, "texto": "E farás chegar a Arão e a seus filhos à porta do tabernáculo do testemunho, e os lavarás com água."}, {"numero": 13, "texto": "E farás vestir a Arão as vestimentas sagradas, e o ungirás, e o consagrarás, para que seja meu sacerdote."}, {"numero": 14, "texto": "Depois farás chegar seus filhos, e lhes vestirás as túnicas:"}, {"numero": 15, "texto": "E os ungirás como ungiste a seu pai, e serão meus sacerdotes: e será que sua unção lhes servirá por sacerdócio perpétuo por suas gerações."}, {"numero": 16, "texto": "E Moisés fez conforme tudo o que o SENHOR lhe mandou; assim o fez."}, {"numero": 17, "texto": "E assim no dia primeiro do primeiro mês, no segundo ano, o tabernáculo foi erigido."}, {"numero": 18, "texto": "E Moisés fez levantar o tabernáculo, e assentou suas bases, e colocou suas tábuas, e pôs suas barras, e fez erguer suas colunas."}, {"numero": 19, "texto": "E estendeu a tenda sobre o tabernáculo, e pôs a cobertura encima do mesmo; como o SENHOR havia mandado a Moisés."}, {"numero": 20, "texto": "E tomou e pôs o testemunho dentro da arca, e colocou as varas na arca, e encima o propiciatório sobre a arca:"}, {"numero": 21, "texto": "E meteu a arca no tabernáculo, e pôs o véu da tenda, e cobriu a arca do testemunho; como o SENHOR havia mandado a Moisés."}, {"numero": 22, "texto": "E pôs a mesa no tabernáculo do testemunho, ao lado norte da cortina, fora do véu:"}, {"numero": 23, "texto": "E sobre ela pôs por ordem os pães diante do SENHOR, como o SENHOR havia mandado a Moisés."}, {"numero": 24, "texto": "E pôs o candelabro no tabernáculo do testemunho, em frente da mesa, ao lado sul da cortina."}, {"numero": 25, "texto": "E acendeu as lâmpadas diante do SENHOR; como o SENHOR havia mandado a Moisés."}, {"numero": 26, "texto": "Pôs também o altar de ouro no tabernáculo do testemunho, diante do véu:"}, {"numero": 27, "texto": "E acendeu sobre ele o incenso aromático; como o SENHOR havia mandado a Moisés."}, {"numero": 28, "texto": "Pôs também a cortina da porta do tabernáculo."}, {"numero": 29, "texto": "E colocou o altar do holocausto à porta do tabernáculo, do tabernáculo do testemunho; e ofereceu sobre ele holocausto e oferta de cereais; como o SENHOR havia mandado a Moisés."}, {"numero": 30, "texto": "E pôs a pia entre o tabernáculo do testemunho e o altar; e pôs nela água para lavar."}, {"numero": 31, "texto": "E Moisés e Arão e seus filhos lavavam nela suas mãos e seus pés."}, {"numero": 32, "texto": "Quando entravam no tabernáculo do testemunho, e quando se traziam ao altar, se lavavam; como o SENHOR havia mandado a Moisés."}, {"numero": 33, "texto": "Finalmente erigiu o átrio em derredor do tabernáculo e do altar, e pôs a cortina da porta do átrio. E assim acabou Moisés a obra."}, {"numero": 34, "texto": "Então uma nuvem cobriu o tabernáculo do testemunho, e a glória do SENHOR encheu o tabernáculo."}, {"numero": 35, "texto": "E não podia Moisés entrar no tabernáculo do testemunho, porque a nuvem estava sobre ele, e a glória do SENHOR o tinha enchido."}, {"numero": 36, "texto": "E quando a nuvem se erguia do tabernáculo, os filhos de Israel se moviam em todas suas jornadas:"}, {"numero": 37, "texto": "Porém se a nuvem não se erguia, não se partiam até o dia em que ela se erguia."}, {"numero": 38, "texto": "Porque a nuvem do SENHOR estava de dia sobre o tabernáculo, e o fogo estava de noite nele, à vista de toda a casa de Israel, em todas as suas jornadas."}]'::jsonb, 'Almeida Livre'),
  ('Ex', 40, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 2, "texto": "On the first day of the first month shalt thou set up the tabernacle of the tent of the congregation."}, {"numero": 3, "texto": "And thou shalt put therein the ark of the testimony, and cover the ark with the vail."}, {"numero": 4, "texto": "And thou shalt bring in the table, and set in order the things that are to be set in order upon it; and thou shalt bring in the candlestick, and light the lamps thereof."}, {"numero": 5, "texto": "And thou shalt set the altar of gold for the incense before the ark of the testimony, and put the hanging of the door to the tabernacle."}, {"numero": 6, "texto": "And thou shalt set the altar of the burnt offering before the door of the tabernacle of the tent of the congregation."}, {"numero": 7, "texto": "And thou shalt set the laver between the tent of the congregation and the altar, and shalt put water therein."}, {"numero": 8, "texto": "And thou shalt set up the court round about, and hang up the hanging at the court gate."}, {"numero": 9, "texto": "And thou shalt take the anointing oil, and anoint the tabernacle, and all that is therein, and shalt hallow it, and all the vessels thereof: and it shall be holy."}, {"numero": 10, "texto": "And thou shalt anoint the altar of the burnt offering, and all his vessels, and sanctify the altar: and it shall be an altar most holy."}, {"numero": 11, "texto": "And thou shalt anoint the laver and his foot, and sanctify it."}, {"numero": 12, "texto": "And thou shalt bring Aaron and his sons unto the door of the tabernacle of the congregation, and wash them with water."}, {"numero": 13, "texto": "And thou shalt put upon Aaron the holy garments, and anoint him, and sanctify him; that he may minister unto me in the priest''s office."}, {"numero": 14, "texto": "And thou shalt bring his sons, and clothe them with coats:"}, {"numero": 15, "texto": "And thou shalt anoint them, as thou didst anoint their father, that they may minister unto me in the priest''s office: for their anointing shall surely be an everlasting priesthood throughout their generations."}, {"numero": 16, "texto": "Thus did Moses: according to all that the Lord commanded him, so did he."}, {"numero": 17, "texto": "And it came to pass in the first month in the second year, on the first day of the month, that the tabernacle was reared up."}, {"numero": 18, "texto": "And Moses reared up the tabernacle, and fastened his sockets, and set up the boards thereof, and put in the bars thereof, and reared up his pillars."}, {"numero": 19, "texto": "And he spread abroad the tent over the tabernacle, and put the covering of the tent above upon it; as the Lord commanded Moses."}, {"numero": 20, "texto": "And he took and put the testimony into the ark, and set the staves on the ark, and put the mercy seat above upon the ark:"}, {"numero": 21, "texto": "And he brought the ark into the tabernacle, and set up the vail of the covering, and covered the ark of the testimony; as the Lord commanded Moses."}, {"numero": 22, "texto": "And he put the table in the tent of the congregation, upon the side of the tabernacle northward, without the vail."}, {"numero": 23, "texto": "And he set the bread in order upon it before the Lord; as the Lord had commanded Moses."}, {"numero": 24, "texto": "And he put the candlestick in the tent of the congregation, over against the table, on the side of the tabernacle southward."}, {"numero": 25, "texto": "And he lighted the lamps before the Lord; as the Lord commanded Moses."}, {"numero": 26, "texto": "And he put the golden altar in the tent of the congregation before the vail:"}, {"numero": 27, "texto": "And he burnt sweet incense thereon; as the Lord commanded Moses."}, {"numero": 28, "texto": "And he set up the hanging at the door of the tabernacle."}, {"numero": 29, "texto": "And he put the altar of burnt offering by the door of the tabernacle of the tent of the congregation, and offered upon it the burnt offering and the meat offering; as the Lord commanded Moses."}, {"numero": 30, "texto": "And he set the laver between the tent of the congregation and the altar, and put water there, to wash withal."}, {"numero": 31, "texto": "And Moses and Aaron and his sons washed their hands and their feet thereat:"}, {"numero": 32, "texto": "When they went into the tent of the congregation, and when they came near unto the altar, they washed; as the Lord commanded Moses."}, {"numero": 33, "texto": "And he reared up the court round about the tabernacle and the altar, and set up the hanging of the court gate. So Moses finished the work."}, {"numero": 34, "texto": "Then a cloud covered the tent of the congregation, and the glory of the Lord filled the tabernacle."}, {"numero": 35, "texto": "And Moses was not able to enter into the tent of the congregation, because the cloud abode thereon, and the glory of the Lord filled the tabernacle."}, {"numero": 36, "texto": "And when the cloud was taken up from over the tabernacle, the children of Israel went onward in all their journeys:"}, {"numero": 37, "texto": "But if the cloud were not taken up, then they journeyed not till the day that it was taken up."}, {"numero": 38, "texto": "For the cloud of the Lord was upon the tabernacle by day, and fire was on it by night, in the sight of all the house of Israel, throughout all their journeys."}]'::jsonb, 'King James Version'),
  ('Ex', 40, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 2, "texto": "Le premier jour du premier mois, tu dresseras le tabernacle, la tente d''''assignation."}, {"numero": 3, "texto": "Tu y placeras l''''arche du témoignage, et tu couvriras l''''arche avec le voile."}, {"numero": 4, "texto": "Tu apporteras la table, et tu la disposeras en ordre. Tu apporteras le chandelier, et tu en arrangeras les lampes."}, {"numero": 5, "texto": "Tu placeras l''''autel d''''or pour le parfum devant l''''arche du témoignage, et tu mettras le rideau à l''''entrée du tabernacle."}, {"numero": 6, "texto": "Tu placeras l''''autel des holocaustes devant l''''entrée du tabernacle, de la tente d''''assignation."}, {"numero": 7, "texto": "Tu placeras la cuve entre la tente d''''assignation et l''''autel, et tu y mettras de l''''eau."}, {"numero": 8, "texto": "Tu placeras le parvis à l''''entour, et tu mettras le rideau à la porte du parvis."}, {"numero": 9, "texto": "Tu prendras l''''huile d''''onction, tu en oindras le tabernacle et tout ce qu''''il renferme, et tu le sanctifieras, avec tous ses ustensiles; et il sera saint."}, {"numero": 10, "texto": "Tu oindras l''''autel des holocaustes et tous ses ustensiles, et tu sanctifieras l''''autel; et l''''autel sera très saint."}, {"numero": 11, "texto": "Tu oindras la cuve avec sa base, et tu la sanctifieras."}, {"numero": 12, "texto": "Tu feras avancer Aaron et ses fils vers l''''entrée de la tente d''''assignation, et tu les laveras avec de l''''eau."}, {"numero": 13, "texto": "Tu revêtiras Aaron des vêtements sacrés, tu l''''oindras, et tu le sanctifieras, pour qu''''il soit à mon service dans le sacerdoce."}, {"numero": 14, "texto": "Tu feras approcher ses fils, tu les revêtiras des tuniques,"}, {"numero": 15, "texto": "et tu les oindras comme tu auras oint leur père, pour qu''''ils soient à mon service dans le sacerdoce. Cette onction leur assurera à perpétuité le sacerdoce parmi leurs descendants."}, {"numero": 16, "texto": "Moïse fit tout ce que l''''Eternel lui avait ordonné; il fit ainsi."}, {"numero": 17, "texto": "Le premier jour du premier mois de la seconde année, le tabernacle fut dressé."}, {"numero": 18, "texto": "Moïse dressa le tabernacle; il en posa les bases, plaça les planches et les barres, et éleva les colonnes."}, {"numero": 19, "texto": "Il étendit la tente sur le tabernacle, et il mit la couverture de la tente par-dessus, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 20, "texto": "Il prit le témoignage, et le plaça dans l''''arche; il mit les barres à l''''arche, et il posa le propitiatoire au-dessus de l''''arche."}, {"numero": 21, "texto": "Il apporta l''''arche dans le tabernacle; il mit le voile de séparation, et il en couvrit l''''arche du témoignage, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 22, "texto": "Il plaça la table dans la tente d''''assignation, au côté septentrional du tabernacle, en dehors du voile;"}, {"numero": 23, "texto": "et il y déposa en ordre les pains, devant l''''Eternel, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 24, "texto": "Il plaça le chandelier dans la tente d''''assignation, en face de la table, au côté méridional du tabernacle;"}, {"numero": 25, "texto": "et il en arrangea les lampes, devant l''''Eternel, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 26, "texto": "Il plaça l''''autel d''''or dans la tente d''''assignation, devant le voile;"}, {"numero": 27, "texto": "et il y fit brûler le parfum odoriférant, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 28, "texto": "Il plaça le rideau à l''''entrée du tabernacle."}, {"numero": 29, "texto": "Il plaça l''''autel des holocaustes à l''''entrée du tabernacle, de la tente d''''assignation; et il y offrit l''''holocauste et l''''offrande, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 30, "texto": "Il plaça la cuve entre la tente d''''assignation et l''''autel, et il y mit de l''''eau pour les ablutions;"}, {"numero": 31, "texto": "Moïse, Aaron et ses fils, s''''y lavèrent les mains et les pieds;"}, {"numero": 32, "texto": "lorsqu''''ils entrèrent dans la tente d''''assignation et qu''''ils s''''approchèrent de l''''autel, ils se lavèrent, comme l''''Eternel l''''avait ordonné à Moïse."}, {"numero": 33, "texto": "Il dressa le parvis autour du tabernacle et de l''''autel, et il mit le rideau à la porte du parvis. Ce fut ainsi que Moïse acheva l''''ouvrage."}, {"numero": 34, "texto": "Alors la nuée couvrit la tente d''''assignation, et la gloire de l''''Eternel remplit le tabernacle."}, {"numero": 35, "texto": "Moïse ne pouvait pas entrer dans la tente d''''assignation, parce que la nuée restait dessus, et que la gloire de l''''Eternel remplissait le tabernacle."}, {"numero": 36, "texto": "Aussi longtemps que durèrent leurs marches, les enfants d''''Israël partaient, quand la nuée s''''élevait de dessus le tabernacle."}, {"numero": 37, "texto": "Et quand la nuée ne s''''élevait pas, ils ne partaient pas, jusqu''''à ce qu''''elle s''''élevât."}, {"numero": 38, "texto": "La nuée de l''''Eternel était de jour sur le tabernacle; et de nuit, il y avait un feu, aux yeux de toute la maison d''''Israël, pendant toutes leurs marches."}]'::jsonb, 'Louis Segond 1910'),
  ('Ex', 40, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ habló á Moisés, diciendo:"}, {"numero": 2, "texto": "En el primer día del mes primero harás levantar el tabernáculo, el tabernáculo del testimonio:"}, {"numero": 3, "texto": "Y pondrás en él el arca del testimonio, y la cubrirás con el velo:"}, {"numero": 4, "texto": "Y meterás la mesa, y la pondrás en orden: meterás también el candelero, y encenderás sus lámparas:"}, {"numero": 5, "texto": "Y pondrás el altar de oro para el perfume delante del arca del testimonio, y pondrás el pabellón delante de la puerta del tabernáculo."}, {"numero": 6, "texto": "Después pondrás el altar del holocausto delante de la puerta del tabernáculo, del tabernáculo del testimonio."}, {"numero": 7, "texto": "Luego pondrás la fuente entre el tabernáculo del testimonio y el altar; y pondrás agua en ella."}, {"numero": 8, "texto": "Finalmente pondrás el atrio en derredor, y el pabellón de la puerta del atrio."}, {"numero": 9, "texto": "Y tomarás el aceite de la unción, y ungirás el tabernáculo, y todo lo que está en él; y le santificarás con todos sus vasos, y será santo."}, {"numero": 10, "texto": "Ungirás también el altar del holocausto y todos sus vasos: y santificarás el altar, y será un altar santísimo."}, {"numero": 11, "texto": "Asimismo ungirás la fuente y su basa, y la santificarás."}, {"numero": 12, "texto": "Y harás llegar á Aarón y á sus hijos á la puerta del tabernáculo del testimonio, y los lavarás con agua."}, {"numero": 13, "texto": "Y harás vestir á Aarón las vestiduras sagradas, y lo ungirás, y lo consagrarás, para que sea mi sacerdote."}, {"numero": 14, "texto": "Después harás llegar sus hijos, y les vestirás las túnicas:"}, {"numero": 15, "texto": "Y los ungirás como ungiste á su padre, y serán mis sacerdotes: y será que su unción les servirá por sacerdocio perpetuo por sus generaciones."}, {"numero": 16, "texto": "Y Moisés hizo conforme á todo lo que Jehová le mandó; así lo hizo."}, {"numero": 17, "texto": "Y así en el día primero del primer mes, en el segundo año, el tabernáculo fué erigido."}, {"numero": 18, "texto": "Y Moisés hizo levantar el tabernáculo, y asentó sus basas, y colocó sus tablas, y puso sus barras, é hizo alzar sus columnas."}, {"numero": 19, "texto": "Y extendió la tienda sobre el tabernáculo, y puso la sobrecubierta encima del mismo; como Jehová había mandado á Moisés."}, {"numero": 20, "texto": "Y tomó y puso el testimonio dentro del arca, y colocó las varas en el arca, y encima la cubierta sobre el arca:"}, {"numero": 21, "texto": "Y metió el arca en el tabernáculo, y puso el velo de la tienda, y cubrió el arca del testimonio; como Jehová había mandado á Moisés."}, {"numero": 22, "texto": "Y puso la mesa en el tabernáculo del testimonio, al lado septentrional del pabellón, fuera del velo:"}, {"numero": 23, "texto": "Y sobre ella puso por orden los panes delante de Jehová, como Jehová había mandado á Moisés."}, {"numero": 24, "texto": "Y puso el candelero en el tabernáculo del testimonio, enfrente de la mesa, al lado meridional del pabellón."}, {"numero": 25, "texto": "Y encendió las lámparas delante de Jehová; como Jehová había mandado á Moisés."}, {"numero": 26, "texto": "Puso también el altar de oro en el tabernáculo del testimonio, delante del velo:"}, {"numero": 27, "texto": "Y encendió sobre él el perfume aromático; como Jehová había mandado á Moisés."}, {"numero": 28, "texto": "Puso asimismo la cortina de la puerta del tabernáculo."}, {"numero": 29, "texto": "Y colocó el altar del holocausto á la puerta del tabernáculo, del tabernáculo del testimonio; y ofreció sobre él holocausto y presente; como Jehová había mandado á Moisés."}, {"numero": 30, "texto": "Y puso la fuente entre el tabernáculo del testimonio y el altar; y puso en ella agua para lavar."}, {"numero": 31, "texto": "Y Moisés y Aarón y sus hijos lavaban en ella sus manos y sus pies."}, {"numero": 32, "texto": "Cuando entraban en el tabernáculo del testimonio, y cuando se llegaban al altar, se lavaban; como Jehová había mandado á Moisés."}, {"numero": 33, "texto": "Finalmente erigió el atrio en derredor del tabernáculo y del altar, y puso la cortina de la puerta del atrio. Y así acabó Moisés la obra."}, {"numero": 34, "texto": "Entonces una nube cubrió el tabernáculo del testimonio, y la gloria de Jehová hinchió el tabernáculo."}, {"numero": 35, "texto": "Y no podía Moisés entrar en el tabernáculo del testimonio, porque la nube estaba sobre él, y la gloria de Jehová lo tenía lleno."}, {"numero": 36, "texto": "Y cuando la nube se alzaba del tabernáculo, los hijos de Israel se movían en todas sus jornadas:"}, {"numero": 37, "texto": "Pero si la nube no se alzaba, no se partían hasta el día en que ella se alzaba."}, {"numero": 38, "texto": "Porque la nube de Jehová estaba de día sobre el tabernáculo, y el fuego estaba de noche en él, á vista de toda la casa de Israel, en todas sus jornadas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Fp', 2, 'pt', '[{"numero": 1, "texto": "Portanto, se há alguma consolação em Cristo, se há algum conforto de amor, se há alguma comunhão do Espírito, se há afetos e compaixões,"}, {"numero": 2, "texto": "completai a minha alegria: que penseis da mesma maneira, tenhais o mesmo amor, sejais unidos de ânimo, tendo um mesmo modo de pensar."}, {"numero": 3, "texto": "Nada [façais] por rivalidade egoísta ou por vanglória; ao contrário, por humildade cada um considere o outro superior a si mesmo."}, {"numero": 4, "texto": "Cada um não cuide [somente] do que é seu; mas cada um cuide também do que é dos outros."}, {"numero": 5, "texto": "Isto seja, para que esteja em vós este modo de pensar, que também esteve em Cristo Jesus:"}, {"numero": 6, "texto": "mesmo ele sendo em forma de Deus, não considerou a igualdade a Deus como algo para se apegar;"}, {"numero": 7, "texto": "Pelo contrário, ele esvaziou a si mesmo, tomando a forma de servo, e se tornou semelhante aos homens;"}, {"numero": 8, "texto": "e, quando se encontrava em forma humana, ele humilhou a si mesmo, sendo obediente até a morte, e morte de cruz."}, {"numero": 9, "texto": "Por isso Deus também o exaltou supremamente, e lhe deu um nome que é acima de todo nome;"}, {"numero": 10, "texto": "a fim de que no nome de Jesus se dobre todo joelho dos que estão nos céus, na terra, e debaixo da terra,"}, {"numero": 11, "texto": "e toda língua confesse que Jesus Cristo é o Senhor, para a glória de Deus Pai."}, {"numero": 12, "texto": "Portanto, meus amados, assim como sempre obedecestes, não somente na minha presença, mas muito mais agora na minha ausência, assim exercei a vossa salvação com temor e tremor;"}, {"numero": 13, "texto": "pois é Deus quem opera em vós tanto o querer como o agir, conforme a [sua] boa vontade."}, {"numero": 14, "texto": "Fazei tudo sem murmurações nem brigas,"}, {"numero": 15, "texto": "para que sejais irrepreensíveis e puros, filhos de Deus, inculpáveis no meio de uma geração corrupta e perversa, na qual brilhais como luminárias no mundo;"}, {"numero": 16, "texto": "e mantende a palavra da vida, para que no dia de Cristo eu possa me orgulhar de que não tenho corrido nem trabalhado em vão."}, {"numero": 17, "texto": "E ainda que eu seja derramado como oferta sobre o sacrifício e serviço da vossa fé, alegro-me e contento-me com todos vós;"}, {"numero": 18, "texto": "e, pelo mesmo motivo, alegrai-vos e contentai-vos comigo."}, {"numero": 19, "texto": "Tenho esperança no Senhor Jesus de em breve vos enviar Timóteo, para que também eu me anime quando souber notícias de vós."}, {"numero": 20, "texto": "Pois não tenho ninguém de mesmo ânimo que se importe sinceramente convosco,"}, {"numero": 21, "texto": "pois todos buscam as suas próprias coisas, e não as de Cristo Jesus."}, {"numero": 22, "texto": "Mas vós sabeis a prova que ele passou, porque serviu comigo no Evangelho como um filho ao pai."}, {"numero": 23, "texto": "Assim, pois, espero enviá-lo, tão logo eu veja o que há de haver comigo."}, {"numero": 24, "texto": "Mas confio no Senhor de que também eu mesmo virei em breve."}, {"numero": 25, "texto": "Julguei necessário, porém, enviar-vos Epafrodito, meu irmão, cooperador, e companheiro de batalha, mensageiro enviado por vós, e auxiliador naquilo que necessito;"}, {"numero": 26, "texto": "porque ele tinha muitas saudades de todos vós, e estava muito angustiado por haverdes ouvido de que ele havia ficado doente."}, {"numero": 27, "texto": "E ele ficou mesmo doente, quase a morrer; mas o Deus dele teve misericórdia, não somente dele, mas também de mim, para que eu não tivesse tristeza após tristeza."}, {"numero": 28, "texto": "Por isso eu o enviei mais depressa, a fim de que, vendo-o de novo, alegrei-vos e eu fique menos triste."}, {"numero": 29, "texto": "Recebei-o, pois, no Senhor, com toda alegria; e honrai ao que são como ele;"}, {"numero": 30, "texto": "pois, por causa da obra de Cristo, ele chegou perto da morte, arriscando a sua própria vida para suprir em meu benefício a falta do vosso serviço."}]'::jsonb, 'Almeida Livre'),
  ('Fp', 2, 'en', '[{"numero": 1, "texto": "If there be therefore any consolation in Christ, if any comfort of love, if any fellowship of the Spirit, if any bowels and mercies,"}, {"numero": 2, "texto": "Fulfil ye my joy, that ye be likeminded, having the same love, being of one accord, of one mind."}, {"numero": 3, "texto": "Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves."}, {"numero": 4, "texto": "Look not every man on his own things, but every man also on the things of others."}, {"numero": 5, "texto": "Let this mind be in you, which was also in Christ Jesus:"}, {"numero": 6, "texto": "Who, being in the form of God, thought it not robbery to be equal with God:"}, {"numero": 7, "texto": "But made himself of no reputation, and took upon him the form of a servant, and was made in the likeness of men:"}, {"numero": 8, "texto": "And being found in fashion as a man, he humbled himself, and became obedient unto death, even the death of the cross."}, {"numero": 9, "texto": "Wherefore God also hath highly exalted him, and given him a name which is above every name:"}, {"numero": 10, "texto": "That at the name of Jesus every knee should bow, of things in heaven, and things in earth, and things under the earth;"}, {"numero": 11, "texto": "And that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father."}, {"numero": 12, "texto": "Wherefore, my beloved, as ye have always obeyed, not as in my presence only, but now much more in my absence, work out your own salvation with fear and trembling."}, {"numero": 13, "texto": "For it is God which worketh in you both to will and to do of his good pleasure."}, {"numero": 14, "texto": "Do all things without murmurings and disputings:"}, {"numero": 15, "texto": "That ye may be blameless and harmless, the sons of God, without rebuke, in the midst of a crooked and perverse nation, among whom ye shine as lights in the world;"}, {"numero": 16, "texto": "Holding forth the word of life; that I may rejoice in the day of Christ, that I have not run in vain, neither laboured in vain."}, {"numero": 17, "texto": "Yea, and if I be offered upon the sacrifice and service of your faith, I joy, and rejoice with you all."}, {"numero": 18, "texto": "For the same cause also do ye joy, and rejoice with me."}, {"numero": 19, "texto": "But I trust in the Lord Jesus to send Timotheus shortly unto you, that I also may be of good comfort, when I know your state."}, {"numero": 20, "texto": "For I have no man likeminded, who will naturally care for your state."}, {"numero": 21, "texto": "For all seek their own, not the things which are Jesus Christ''s."}, {"numero": 22, "texto": "But ye know the proof of him, that, as a son with the father, he hath served with me in the gospel."}, {"numero": 23, "texto": "Him therefore I hope to send presently, so soon as I shall see how it will go with me."}, {"numero": 24, "texto": "But I trust in the Lord that I also myself shall come shortly."}, {"numero": 25, "texto": "Yet I supposed it necessary to send to you Epaphroditus, my brother, and companion in labour, and fellowsoldier, but your messenger, and he that ministered to my wants."}, {"numero": 26, "texto": "For he longed after you all, and was full of heaviness, because that ye had heard that he had been sick."}, {"numero": 27, "texto": "For indeed he was sick nigh unto death: but God had mercy on him; and not on him only, but on me also, lest I should have sorrow upon sorrow."}, {"numero": 28, "texto": "I sent him therefore the more carefully, that, when ye see him again, ye may rejoice, and that I may be the less sorrowful."}, {"numero": 29, "texto": "Receive him therefore in the Lord with all gladness; and hold such in reputation:"}, {"numero": 30, "texto": "Because for the work of Christ he was nigh unto death, not regarding his life, to supply your lack of service toward me."}]'::jsonb, 'King James Version'),
  ('Fp', 2, 'fr', '[{"numero": 1, "texto": "Si donc il y a quelque consolation en Christ, s''''il y a quelque soulagement dans la charité, s''''il y a quelque union d''''esprit, s''''il y a quelque compassion et quelque miséricorde,"}, {"numero": 2, "texto": "rendez ma joie parfaite, ayant un même sentiment, un même amour, une même âme, une même pensée."}, {"numero": 3, "texto": "Ne faites rien par esprit de parti ou par vaine gloire, mais que l''''humilité vous fasse regarder les autres comme étant au-dessus de vous-mêmes."}, {"numero": 4, "texto": "Que chacun de vous, au lieu de considérer ses propres intérêts, considère aussi ceux des autres."}, {"numero": 5, "texto": "Ayez en vous les sentiments qui étaient en Jésus-Christ,"}, {"numero": 6, "texto": "lequel, existant en forme de Dieu, n''''a point regardé comme une proie à arracher d''''être égal avec Dieu,"}, {"numero": 7, "texto": "mais s''''est dépouillé lui-même, en prenant une forme de serviteur, en devenant semblable aux hommes;"}, {"numero": 8, "texto": "et ayant paru comme un simple homme, il s''''est humilié lui-même, se rendant obéissant jusqu''''à la mort, même jusqu''''à la mort de la croix."}, {"numero": 9, "texto": "C''''est pourquoi aussi Dieu l''''a souverainement élevé, et lui a donné le nom qui est au-dessus de tout nom,"}, {"numero": 10, "texto": "afin qu''''au nom de Jésus tout genou fléchisse dans les cieux, sur la terre et sous la terre,"}, {"numero": 11, "texto": "et que toute langue confesse que Jésus-Christ est Seigneur, à la gloire de Dieu le Père."}, {"numero": 12, "texto": "Ainsi, mes bien-aimés, comme vous avez toujours obéi, travaillez à votre salut avec crainte et tremblement, non seulement comme en ma présence, mais bien plus encore maintenant que je suis absent;"}, {"numero": 13, "texto": "car c''''est Dieu qui produit en vous le vouloir et le faire, selon son bon plaisir."}, {"numero": 14, "texto": "Faites toutes choses sans murmures ni hésitations,"}, {"numero": 15, "texto": "afin que vous soyez irréprochables et purs, des enfants de Dieu irrépréhensibles au milieu d''''une génération perverse et corrompue, parmi laquelle vous brillez comme des flambeaux dans le monde,"}, {"numero": 16, "texto": "portant la parole de vie; et je pourrai me glorifier, au jour de Christ, de n''''avoir pas couru en vain ni travaillé en vain."}, {"numero": 17, "texto": "Et même si je sers de libation pour le sacrifice et pour le service de votre foi, je m''''en réjouis, et je me réjouis avec vous tous."}, {"numero": 18, "texto": "Vous aussi, réjouissez-vous de même, et réjouissez-vous avec moi."}, {"numero": 19, "texto": "J''''espère dans le Seigneur Jésus vous envoyer bientôt Timothée, afin d''''être encouragé moi-même en apprenant ce qui vous concerne."}, {"numero": 20, "texto": "Car je n''''ai personne ici qui partage mes sentiments, pour prendre sincèrement à coeur votre situation;"}, {"numero": 21, "texto": "tous, en effet, cherchent leurs propres intérêts, et non ceux de Jésus-Christ."}, {"numero": 22, "texto": "Vous savez qu''''il a été mis à l''''épreuve, en se consacrant au service de l''''Evangile avec moi, comme un enfant avec son père."}, {"numero": 23, "texto": "J''''espère donc vous l''''envoyer dès que j''''apercevrai l''''issue de l''''état où je suis;"}, {"numero": 24, "texto": "et j''''ai cette confiance dans le Seigneur que moi-même aussi j''''irai bientôt."}, {"numero": 25, "texto": "J''''ai estimé nécessaire de vous envoyer mon frère Epaphrodite, mon compagnon d''''oeuvre et de combat, par qui vous m''''avez fait parvenir de quoi pourvoir à mes besoins."}, {"numero": 26, "texto": "Car il désirait vous voir tous, et il était fort en peine de ce que vous aviez appris sa maladie."}, {"numero": 27, "texto": "Il a été malade, en effet, et tout près de la mort; mais Dieu a eu pitié de lui, et non seulement de lui, mais aussi de moi, afin que je n''''eusse pas tristesse sur tristesse."}, {"numero": 28, "texto": "Je l''''ai donc envoyé avec d''''autant plus d''''empressement, afin que vous vous réjouissiez de le revoir, et que je sois moi-même moins triste."}, {"numero": 29, "texto": "Recevez-le donc dans le Seigneur avec une joie entière, et honorez de tels hommes."}, {"numero": 30, "texto": "Car c''''est pour l''''oeuvre de Christ qu''''il a été près de la mort, ayant exposé sa vie afin de suppléer à votre absence dans le service que vous me rendiez."}]'::jsonb, 'Louis Segond 1910'),
  ('Fp', 2, 'es', '[{"numero": 1, "texto": "POR tanto, si hay alguna consolación en Cristo; si algún refrigerio de amor; si alguna comunión del Espíritu; si algunas entrañas y misericordias,"}, {"numero": 2, "texto": "Cumplid mi gozo; que sintáis lo mismo, teniendo el mismo amor, unánimes, sintiendo una misma cosa."}, {"numero": 3, "texto": "Nada hagáis por contienda ó por vanagloria; antes bien en humildad, estimándoos inferiores los unos á los otros:"}, {"numero": 4, "texto": "No mirando cada uno á lo suyo propio, sino cada cual también á lo de los otros."}, {"numero": 5, "texto": "Haya, pues, en vosotros este sentir que hubo también en Cristo Jesús:"}, {"numero": 6, "texto": "El cual, siendo en forma de Dios, no tuvo por usurpación ser igual á Dios:"}, {"numero": 7, "texto": "Sin embargo, se anonadó á sí mismo, tomando forma de siervo, hecho semejante á los hombres;"}, {"numero": 8, "texto": "Y hallado en la condición como hombre, se humilló á sí mismo, hecho obediente hasta la muerte, y muerte de cruz."}, {"numero": 9, "texto": "Por lo cual Dios también le ensalzó á lo sumo, y dióle un nombre que es sobre todo nombre;"}, {"numero": 10, "texto": "Para que en el nombre de Jesús se doble toda rodilla de los que están en los cielos, y de los que en la tierra, y de los que debajo de la tierra;"}, {"numero": 11, "texto": "Y toda lengua confiese que Jesucristo es el Señor, á la gloria de Dios Padre."}, {"numero": 12, "texto": "Por tanto, amados míos, como siempre habéis obedecido, no como en mi presencia solamente, sino mucho más ahora en mi ausencia, ocupaos en vuestra salvación con temor y temblor;"}, {"numero": 13, "texto": "Porque Dios es el que en vosotros obra así el querer como el hacer, por su buena voluntad."}, {"numero": 14, "texto": "Haced todo sin murmuraciones y contiendas,"}, {"numero": 15, "texto": "Para que seáis irreprensibles y sencillos, hijos de Dios sin culpa en medio de la nación maligna y perversa, entre los cuales resplandecéis como luminares en el mundo;"}, {"numero": 16, "texto": "Reteniendo la palabra de vida para que yo pueda gloriarme en el día de Cristo, que no he corrido en vano, ni trabajado en vano."}, {"numero": 17, "texto": "Y aun si soy derramado en libación sobre el sacrificio y servicio de vuestra fe, me gozo y congratulo por todos vosotros."}, {"numero": 18, "texto": "Y asimismo gozaos también vosotros, y regocijaos conmigo."}, {"numero": 19, "texto": "Mas espero en el Señor Jesús enviaros presto á Timoteo, para que yo también esté de buen ánimo, entendido vuestro estado."}, {"numero": 20, "texto": "Porque á ninguno tengo tan unánime, y que con sincera afición esté solícito por vosotros."}, {"numero": 21, "texto": "Porque todos buscan lo suyo propio, no lo que es de Cristo Jesús."}, {"numero": 22, "texto": "Pero la experiencia de él habéis conocido, que como hijo á padre ha servido conmigo en el evangelio."}, {"numero": 23, "texto": "Así que á éste espero enviaros, luego que yo viere cómo van mis negocios;"}, {"numero": 24, "texto": "Y confío en el Señor que yo también iré presto á vosotros."}, {"numero": 25, "texto": "Mas tuve por cosa necesaria enviaros á Epafrodito, mi hermano, y colaborador y compañero de milicia, y vuestro mensajero, y ministrador de mis necesidades;"}, {"numero": 26, "texto": "Porque tenía gran deseo de ver á todos vosotros, y gravemente se angustió porque habíais oído que había enfermado."}, {"numero": 27, "texto": "Pues en verdad estuvo enfermo á la muerte: mas Dios tuvo misericordia de él; y no solamente de él, sino aun de mí, para que yo no tuviese tristeza sobre tristeza."}, {"numero": 28, "texto": "Así que le envío más presto, para que viéndole os volváis á gozar, y yo esté con menos tristeza."}, {"numero": 29, "texto": "Recibidle pues en el Señor con todo gozo; y tened en estima á los tales:"}, {"numero": 30, "texto": "Porque por la obra de Cristo estuvo cercano á la muerte, poniendo su vida para suplir vuestra falta en mi servicio."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gl', 5, 'pt', '[{"numero": 1, "texto": "Estai, pois, firmes na liberdade com que Cristo nos libertou, e não volteis a vos prender com o jugo da escravidão."}, {"numero": 2, "texto": "Eis que eu, Paulo, vos digo, que se vos deixardes circuncidar, Cristo vos será útil em nada."}, {"numero": 3, "texto": "E de novo atesto que todo homem que se deixar circuncidar está obrigado a obedecer a toda a Lei."}, {"numero": 4, "texto": "Desligados estais de Cristo, vós que [quereis] ser justos pela Lei; da graça caístes."}, {"numero": 5, "texto": "Pois, por meio do Espírito, pela fé, aguardamos a esperança da justiça;"}, {"numero": 6, "texto": "porque, em Cristo Jesus, nem a circuncisão nem a incircuncisão tem valor algum; mas sim a fé, que opera por meio do amor."}, {"numero": 7, "texto": "Estáveis correndo bem; quem vos impediu de obedecerdes à verdade?"}, {"numero": 8, "texto": "Esta persuasão não parte daquele que vos chama."}, {"numero": 9, "texto": "Um pouco de fermento leveda toda a massa."}, {"numero": 10, "texto": "Acerca de vós, confio no Senhor de que não mudareis a vossa mentalidade; mas aquele que vos perturba, seja quem for, sofrerá o julgamento."}, {"numero": 11, "texto": "Mas se eu, irmãos, ainda prego a circuncisão, por que, então, sou perseguido? Então a ofensa da cruz está anulada!"}, {"numero": 12, "texto": "Gostaria que aqueles que estão vos perturbando castrassem a si mesmos."}, {"numero": 13, "texto": "Pois vós, irmãos, fostes chamados para a liberdade. Somente não [useis] a liberdade como oportunidade para a carne; em vez disso, servi-vos uns aos outros pelo amor."}, {"numero": 14, "texto": "Pois toda a Lei se cumpre em uma só regra, que é: Amarás ao teu próximo como a ti mesmo."}, {"numero": 15, "texto": "Se, porém, mordeis e devorais uns aos outros, cuidado para não vos destruirdes mutuamente."}, {"numero": 16, "texto": "Mas eu digo: andai no Espírito, e não executeis o mau desejo da carne."}, {"numero": 17, "texto": "Pois a carne deseja contra o Espírito, e o Espírito contra a carne; e estes se opõem mutuamente, para que não façais o que quereis."}, {"numero": 18, "texto": "Mas, se sois guiados pelo Espírito, não estais debaixo da Lei."}, {"numero": 19, "texto": "As obras da carne são evidentes. São elas: adultério, pecado sexual, impureza, devassidão,"}, {"numero": 20, "texto": "idolatria, feitiçaria, inimizades, brigas, ciúmes, iras, rivalidades egoístas, desavenças, facções,"}, {"numero": 21, "texto": "invejas, homicídios, bebedices, orgias, e coisas semelhantes a essas, das quais eu havia vos dito anteriormente; assim como eu também haviavos dito antes que os que praticam tais coisas não herdarão o Reino de Deus."}, {"numero": 22, "texto": "Mas o fruto do Espírito é: amor, alegria, paz, paciência, benignidade, bondade, fidelidade,"}, {"numero": 23, "texto": "mansidão, domínio próprio. Contra essas coisas não há lei."}, {"numero": 24, "texto": "Os que são de Cristo crucificaram a carne com as paixões e os maus desejos."}, {"numero": 25, "texto": "Se vivemos no Espírito, também no Espírito andemos."}, {"numero": 26, "texto": "Não nos tornemos presunçosos, irritando uns aos outros, e invejando uns aos outros."}]'::jsonb, 'Almeida Livre'),
  ('Gl', 5, 'en', '[{"numero": 1, "texto": "Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage."}, {"numero": 2, "texto": "Behold, I Paul say unto you, that if ye be circumcised, Christ shall profit you nothing."}, {"numero": 3, "texto": "For I testify again to every man that is circumcised, that he is a debtor to do the whole law."}, {"numero": 4, "texto": "Christ is become of no effect unto you, whosoever of you are justified by the law; ye are fallen from grace."}, {"numero": 5, "texto": "For we through the Spirit wait for the hope of righteousness by faith."}, {"numero": 6, "texto": "For in Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love."}, {"numero": 7, "texto": "Ye did run well; who did hinder you that ye should not obey the truth?"}, {"numero": 8, "texto": "This persuasion cometh not of him that calleth you."}, {"numero": 9, "texto": "A little leaven leaveneth the whole lump."}, {"numero": 10, "texto": "I have confidence in you through the Lord, that ye will be none otherwise minded: but he that troubleth you shall bear his judgment, whosoever he be."}, {"numero": 11, "texto": "And I, brethren, if I yet preach circumcision, why do I yet suffer persecution? then is the offence of the cross ceased."}, {"numero": 12, "texto": "I would they were even cut off which trouble you."}, {"numero": 13, "texto": "For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another."}, {"numero": 14, "texto": "For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself."}, {"numero": 15, "texto": "But if ye bite and devour one another, take heed that ye be not consumed one of another."}, {"numero": 16, "texto": "This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh."}, {"numero": 17, "texto": "For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would."}, {"numero": 18, "texto": "But if ye be led of the Spirit, ye are not under the law."}, {"numero": 19, "texto": "Now the works of the flesh are manifest, which are these; Adultery, fornication, uncleanness, lasciviousness,"}, {"numero": 20, "texto": "Idolatry, witchcraft, hatred, variance, emulations, wrath, strife, seditions, heresies,"}, {"numero": 21, "texto": "Envyings, murders, drunkenness, revellings, and such like: of the which I tell you before, as I have also told you in time past, that they which do such things shall not inherit the kingdom of God."}, {"numero": 22, "texto": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,"}, {"numero": 23, "texto": "Meekness, temperance: against such there is no law."}, {"numero": 24, "texto": "And they that are Christ''s have crucified the flesh with the affections and lusts."}, {"numero": 25, "texto": "If we live in the Spirit, let us also walk in the Spirit."}, {"numero": 26, "texto": "Let us not be desirous of vain glory, provoking one another, envying one another."}]'::jsonb, 'King James Version'),
  ('Gl', 5, 'fr', '[{"numero": 1, "texto": "C''''est pour la liberté que Christ nous a affranchis. Demeurez donc fermes, et ne vous laissez pas mettre de nouveau sous le joug de la servitude."}, {"numero": 2, "texto": "Voici, moi Paul, je vous dis que, si vous vous faites circoncire, Christ ne vous servira de rien."}, {"numero": 3, "texto": "Et je proteste encore une fois à tout homme qui se fait circoncire, qu''''il est tenu de pratiquer la loi tout entière."}, {"numero": 4, "texto": "Vous êtes séparés de Christ, vous tous qui cherchez la justification dans la loi; vous êtes déchus de la grâce."}, {"numero": 5, "texto": "Pour nous, c''''est de la foi que nous attendons, par l''''Esprit, l''''espérance de la justice."}, {"numero": 6, "texto": "Car, en Jésus-Christ, ni la circoncision ni l''''incirconcision n''''a de valeur, mais la foi qui est agissante par la charité."}, {"numero": 7, "texto": "Vous couriez bien: qui vous a arrêtés, pour vous empêcher d''''obéir à la vérité?"}, {"numero": 8, "texto": "Cette influence ne vient pas de celui qui vous appelle."}, {"numero": 9, "texto": "Un peu de levain fait lever toute la pâte."}, {"numero": 10, "texto": "J''''ai cette confiance en vous, dans le Seigneur, que vous ne penserez pas autrement. Mais celui qui vous trouble, quel qu''''il soit, en portera la peine."}, {"numero": 11, "texto": "Pour moi, frères, si je prêche encore la circoncision, pourquoi suis-je encore persécuté? Le scandale de la croix a donc disparu!"}, {"numero": 12, "texto": "Puissent-ils être retranchés, ceux qui mettent le trouble parmi vous!"}, {"numero": 13, "texto": "Frères, vous avez été appelés à la liberté, seulement ne faites pas de cette liberté un prétexte de vivre selon la chair; mais rendez-vous, par la charité, serviteurs les uns des autres."}, {"numero": 14, "texto": "Car toute la loi est accomplie dans une seule parole, dans celle-ci: Tu aimeras ton prochain comme toi-même."}, {"numero": 15, "texto": "Mais si vous vous mordez et vous dévorez les uns les autres, prenez garde que vous ne soyez détruits les uns par les autres."}, {"numero": 16, "texto": "Je dis donc: Marchez selon l''''Esprit, et vous n''''accomplirez pas les désirs de la chair."}, {"numero": 17, "texto": "Car la chair a des désirs contraires à ceux de l''''Esprit, et l''''Esprit en a de contraires à ceux de la chair; ils sont opposés entre eux, afin que vous ne fassiez point ce que vous voudriez."}, {"numero": 18, "texto": "Si vous êtes conduits par l''''Esprit, vous n''''êtes point sous la loi."}, {"numero": 19, "texto": "Or, les oeuvres de la chair sont manifestes, ce sont l''''impudicité, l''''impureté, la dissolution,"}, {"numero": 20, "texto": "l''''idolâtrie, la magie, les inimitiés, les querelles, les jalousies, les animosités, les disputes, les divisions, les sectes,"}, {"numero": 21, "texto": "l''''envie, l''''ivrognerie, les excès de table, et les choses semblables. Je vous dis d''''avance, comme je l''''ai déjà dit, que ceux qui commettent de telles choses n''''hériteront point le royaume de Dieu."}, {"numero": 22, "texto": "Mais le fruit de l''''Esprit, c''''est l''''amour, la joie, la paix, la patience, la bonté, la bénignité, la fidélité,"}, {"numero": 23, "texto": "la douceur, la tempérance; la loi n''''est pas contre ces choses."}, {"numero": 24, "texto": "Ceux qui sont à Jésus-Christ ont crucifié la chair avec ses passions et ses désirs."}, {"numero": 25, "texto": "Si nous vivons par l''''Esprit, marchons aussi selon l''''Esprit."}, {"numero": 26, "texto": "Ne cherchons pas une vaine gloire, en nous provoquant les uns les autres, en nous portant envie les uns aux autres."}]'::jsonb, 'Louis Segond 1910'),
  ('Gl', 5, 'es', '[{"numero": 1, "texto": "ESTAD, pues, firmes en la libertad con que Cristo nos hizo libres, y no volváis otra vez á ser presos en el yugo de servidumbre."}, {"numero": 2, "texto": "He aquí yo Pablo os digo, que si os circuncidareis, Cristo no os aprovechará nada."}, {"numero": 3, "texto": "Y otra vez vuelvo á protestar á todo hombre que se circuncidare, que está obligado á hacer toda la ley."}, {"numero": 4, "texto": "Vacíos sois de Cristo los que por la ley os justificáis; de la gracia habéis caído."}, {"numero": 5, "texto": "Porque nosotros por el Espíritu esperamos la esperanza de la justicia por la fe."}, {"numero": 6, "texto": "Porque en Cristo Jesús ni la circuncisión vale algo, ni la incircuncisión; sino la fe que obra por la caridad."}, {"numero": 7, "texto": "Vosotros corríais bien: ¿quién os embarazó para no obedecer á la verdad?"}, {"numero": 8, "texto": "Esta persuasión no es de aquel que os llama."}, {"numero": 9, "texto": "Un poco de levadura leuda toda la masa."}, {"numero": 10, "texto": "Yo confío de vosotros en el Señor, que ninguna otra cosa sentiréis: mas el que os inquieta, llevará el juicio, quienquiera que él sea."}, {"numero": 11, "texto": "Y yo, hermanos, si aun predico la circuncisión, ¿por qué padezco persecución todavía? pues que quitado es el escándalo de la cruz."}, {"numero": 12, "texto": "Ojalá fuesen también cortados los que os inquietan."}, {"numero": 13, "texto": "Porque vosotros, hermanos, á libertad habéis sido llamados; solamente que no uséis la libertad como ocasión á la carne, sino servíos por amor los unos á los otros."}, {"numero": 14, "texto": "Porque toda la ley en aquesta sola palabra se cumple: Amarás á tu prójimo como á ti mismo."}, {"numero": 15, "texto": "Y si os mordéis y os coméis los unos á los otros, mirad que también no os consumáis los unos á los otros."}, {"numero": 16, "texto": "Digo pues: Andad en el Espíritu, y no satisfagáis la concupiscencia de la carne."}, {"numero": 17, "texto": "Porque la carne codicia contra el Espíritu, y el Espíritu contra la carne: y estas cosas se oponen la una á la otra, para que no hagáis lo que quisiereis."}, {"numero": 18, "texto": "Mas si sois guiados del Espíritu, no estáis bajo la ley."}, {"numero": 19, "texto": "Y manifiestas son las obras de la carne, que son: adulterio, fornicación, inmundicia, disolución,"}, {"numero": 20, "texto": "Idolatría, hechicerías, enemistades, pleitos, celos, iras, contiendas, disensiones, herejías,"}, {"numero": 21, "texto": "Envidias, homicidios, borracheras, banqueteos, y cosas semejantes á éstas: de las cuales os denuncio, como ya os he anunciado, que los que hacen tales cosas no heredarán el reino de Dios."}, {"numero": 22, "texto": "Mas el fruto del Espíritu es: caridad, gozo, paz, tolerancia, benignidad, bondad, fe,"}, {"numero": 23, "texto": "Mansedumbre, templanza: contra tales cosas no hay ley."}, {"numero": 24, "texto": "Porque los que son de Cristo, han crucificado la carne con los afectos y concupiscencias."}, {"numero": 25, "texto": "Si vivimos en el Espíritu, andemos también en el Espíritu."}, {"numero": 26, "texto": "No seamos codiciosos de vana gloria, irritando los unos á los otros, envidiándose los unos á los otros."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 1, 'pt', '[{"numero": 1, "texto": "No princípio criou Deus os céus e a terra."}, {"numero": 2, "texto": "E a terra estava desordenada e vazia, e as trevas estavam sobre a face do abismo, e o Espírito de Deus se movia sobre a face das águas."}, {"numero": 3, "texto": "E disse Deus: Haja luz; e houve luz."}, {"numero": 4, "texto": "E viu Deus que a luz era boa: e separou Deus a luz das trevas."}, {"numero": 5, "texto": "E chamou Deus à luz Dia, e às trevas chamou Noite: e foi a tarde e a manhã o primeiro dia."}, {"numero": 6, "texto": "E disse Deus: Haja expansão em meio das águas, e separe as águas das águas."}, {"numero": 7, "texto": "E fez Deus a expansão, e separou as águas que estavam debaixo da expansão, das águas que estavam sobre a expansão: e foi assim."}, {"numero": 8, "texto": "E chamou Deus à expansão Céus: e foi a tarde e a manhã, o dia segundo."}, {"numero": 9, "texto": "E disse Deus: Juntem-se as águas que estão debaixo dos céus em um lugar, e descubra-se a porção seca; e foi assim."}, {"numero": 10, "texto": "E chamou Deus à porção seca Terra, e à reunião das águas chamou Mares; e viu Deus que era bom."}, {"numero": 11, "texto": "E disse Deus: Produza a terra erva verde, erva que dê semente; árvore de fruto que dê fruto segundo a sua espécie, que sua semente esteja nela, sobre a terra: e foi assim."}, {"numero": 12, "texto": "E produziu a terra erva verde, erva que dá semente segundo sua natureza, e árvore que dá fruto, cuja semente está nele, segundo a sua espécie; e viu Deus que era bom."}, {"numero": 13, "texto": "E foi a tarde e a manhã, o dia terceiro."}, {"numero": 14, "texto": "E disse Deus: Haja luminares na expansão dos céus para separar o dia e a noite: e sejam por sinais, e para as estações, e para dias e anos;"}, {"numero": 15, "texto": "E sejam por luminares na expansão dos céus para iluminar sobre a terra: e foi."}, {"numero": 16, "texto": "E fez Deus os dois grandes luminares; o luminar maior para que exerça domínio no dia, e o luminar menor para que exerça domínio na noite; fez também as estrelas."}, {"numero": 17, "texto": "E as pôs Deus na expansão dos céus, para iluminar sobre a terra,"}, {"numero": 18, "texto": "E para exercer domínio no dia e na noite, e para separar a luz e as trevas: e viu Deus que era bom."}, {"numero": 19, "texto": "E foi a tarde e a manhã, o dia quarto."}, {"numero": 20, "texto": "E disse Deus: Produzam as águas répteis de alma vivente, e aves que voem sobre a terra, na expansão aberta dos céus."}, {"numero": 21, "texto": "E criou Deus as grandes criaturas marinhas, e toda coisa viva que anda arrastando, que as águas produziram segundo a sua espécie, e toda ave de asas segundo sua espécie: e viu Deus que era bom."}, {"numero": 22, "texto": "E Deus os abençoou dizendo: Frutificai e multiplicai, e enchei as águas nos mares, e as aves se multipliquem na terra."}, {"numero": 23, "texto": "E foi a tarde e a manhã, o dia quinto."}, {"numero": 24, "texto": "E disse Deus: Produza a terra seres viventes segundo a sua espécie, animais e serpentes e animais da terra segundo sua espécie: e foi assim."}, {"numero": 25, "texto": "E fez Deus animais da terra segundo a sua espécie, e gado segundo a sua espécie, e todo animal que anda arrastando sobre a terra segundo sua espécie: e viu Deus que era bom."}, {"numero": 26, "texto": "E disse Deus: Façamos ao ser humano à nossa imagem, conforme nossa semelhança; e domine os peixes do mar, e as aves dos céus, e os animais, e toda a terra, e todo animal que anda arrastando sobre a terra."}, {"numero": 27, "texto": "E criou Deus o ser humano à sua imagem, à imagem de Deus o criou; macho e fêmea os criou."}, {"numero": 28, "texto": "E Deus os abençoou; e disse-lhes Deus: Frutificai e multiplicai, e enchei a terra, e subjugai-a, e dominai os peixes do mar, as aves dos céus, e todos os animais que se movem sobre a terra."}, {"numero": 29, "texto": "E disse Deus: Eis que vos dei toda erva que dá semente, que está sobre a face de toda a terra; e toda árvore em que há fruto de árvore que dá semente, vos será para comer."}, {"numero": 30, "texto": "E a todo animal da terra, e a todas as aves dos céus, e a tudo o que se move sobre a terra, em que há vida, toda erva verde lhes será para comer: e foi assim."}, {"numero": 31, "texto": "E viu Deus tudo o que havia feito, e eis que era bom em grande maneira. E foi a tarde e a manhã, o dia sexto."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 1, 'en', '[{"numero": 1, "texto": "In the beginning God created the heaven and the earth."}, {"numero": 2, "texto": "And the earth was without form, and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters."}, {"numero": 3, "texto": "And God said, Let there be light: and there was light."}, {"numero": 4, "texto": "And God saw the light, that it was good: and God divided the light from the darkness."}, {"numero": 5, "texto": "And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day."}, {"numero": 6, "texto": "And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters."}, {"numero": 7, "texto": "And God made the firmament, and divided the waters which were under the firmament from the waters which were above the firmament: and it was so."}, {"numero": 8, "texto": "And God called the firmament Heaven. And the evening and the morning were the second day."}, {"numero": 9, "texto": "And God said, Let the waters under the heaven be gathered together unto one place, and let the dry land appear: and it was so."}, {"numero": 10, "texto": "And God called the dry land Earth; and the gathering together of the waters called he Seas: and God saw that it was good."}, {"numero": 11, "texto": "And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so."}, {"numero": 12, "texto": "And the earth brought forth grass, and herb yielding seed after his kind, and the tree yielding fruit, whose seed was in itself, after his kind: and God saw that it was good."}, {"numero": 13, "texto": "And the evening and the morning were the third day."}, {"numero": 14, "texto": "And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years:"}, {"numero": 15, "texto": "And let them be for lights in the firmament of the heaven to give light upon the earth: and it was so."}, {"numero": 16, "texto": "And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: he made the stars also."}, {"numero": 17, "texto": "And God set them in the firmament of the heaven to give light upon the earth,"}, {"numero": 18, "texto": "And to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good."}, {"numero": 19, "texto": "And the evening and the morning were the fourth day."}, {"numero": 20, "texto": "And God said, Let the waters bring forth abundantly the moving creature that hath life, and fowl that may fly above the earth in the open firmament of heaven."}, {"numero": 21, "texto": "And God created great whales, and every living creature that moveth, which the waters brought forth abundantly, after their kind, and every winged fowl after his kind: and God saw that it was good."}, {"numero": 22, "texto": "And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let fowl multiply in the earth."}, {"numero": 23, "texto": "And the evening and the morning were the fifth day."}, {"numero": 24, "texto": "And God said, Let the earth bring forth the living creature after his kind, cattle, and creeping thing, and beast of the earth after his kind: and it was so."}, {"numero": 25, "texto": "And God made the beast of the earth after his kind, and cattle after their kind, and every thing that creepeth upon the earth after his kind: and God saw that it was good."}, {"numero": 26, "texto": "And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth, and over every creeping thing that creepeth upon the earth."}, {"numero": 27, "texto": "So God created man in his own image, in the image of God created he him; male and female created he them."}, {"numero": 28, "texto": "And God blessed them, and God said unto them, Be fruitful, and multiply, and replenish the earth, and subdue it: and have dominion over the fish of the sea, and over the fowl of the air, and over every living thing that moveth upon the earth."}, {"numero": 29, "texto": "And God said, Behold, I have given you every herb bearing seed, which is upon the face of all the earth, and every tree, in the which is the fruit of a tree yielding seed; to you it shall be for meat."}, {"numero": 30, "texto": "And to every beast of the earth, and to every fowl of the air, and to every thing that creepeth upon the earth, wherein there is life, I have given every green herb for meat: and it was so."}, {"numero": 31, "texto": "And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day."}]'::jsonb, 'King James Version'),
  ('Gn', 1, 'fr', '[{"numero": 1, "texto": "Au commencement, Dieu créa les cieux et la terre."}, {"numero": 2, "texto": "La terre était informe et vide: il y avait des ténèbres à la surface de l''''abîme, et l''''esprit de Dieu se mouvait au-dessus des eaux."}, {"numero": 3, "texto": "Dieu dit: Que la lumière soit! Et la lumière fut."}, {"numero": 4, "texto": "Dieu vit que la lumière était bonne; et Dieu sépara la lumière d''''avec les ténèbres."}, {"numero": 5, "texto": "Dieu appela la lumière jour, et il appela les ténèbres nuit. Ainsi, il y eut un soir, et il y eut un matin: ce fut le premier jour."}, {"numero": 6, "texto": "Dieu dit: Qu''''il y ait une étendue entre les eaux, et qu''''elle sépare les eaux d''''avec les eaux."}, {"numero": 7, "texto": "Et Dieu fit l''''étendue, et il sépara les eaux qui sont au-dessous de l''''étendue d''''avec les eaux qui sont au-dessus de l''''étendue. Et cela fut ainsi."}, {"numero": 8, "texto": "Dieu appela l''''étendue ciel. Ainsi, il y eut un soir, et il y eut un matin: ce fut le second jour."}, {"numero": 9, "texto": "Dieu dit: Que les eaux qui sont au-dessous du ciel se rassemblent en un seul lieu, et que le sec paraisse. Et cela fut ainsi."}, {"numero": 10, "texto": "Dieu appela le sec terre, et il appela l''''amas des eaux mers. Dieu vit que cela était bon."}, {"numero": 11, "texto": "Puis Dieu dit: Que la terre produise de la verdure, de l''''herbe portant de la semence, des arbres fruitiers donnant du fruit selon leur espèce et ayant en eux leur semence sur la terre. Et cela fut ainsi."}, {"numero": 12, "texto": "La terre produisit de la verdure, de l''''herbe portant de la semence selon son espèce, et des arbres donnant du fruit et ayant en eux leur semence selon leur espèce. Dieu vit que cela était bon."}, {"numero": 13, "texto": "Ainsi, il y eut un soir, et il y eut un matin: ce fut le troisième jour."}, {"numero": 14, "texto": "Dieu dit: Qu''''il y ait des luminaires dans l''''étendue du ciel, pour séparer le jour d''''avec la nuit; que ce soient des signes pour marquer les époques, les jours et les années;"}, {"numero": 15, "texto": "et qu''''ils servent de luminaires dans l''''étendue du ciel, pour éclairer la terre. Et cela fut ainsi."}, {"numero": 16, "texto": "Dieu fit les deux grands luminaires, le plus grand luminaire pour présider au jour, et le plus petit luminaire pour présider à la nuit; il fit aussi les étoiles."}, {"numero": 17, "texto": "Dieu les plaça dans l''''étendue du ciel, pour éclairer la terre,"}, {"numero": 18, "texto": "pour présider au jour et à la nuit, et pour séparer la lumière d''''avec les ténèbres. Dieu vit que cela était bon."}, {"numero": 19, "texto": "Ainsi, il y eut un soir, et il y eut un matin: ce fut le quatrième jour."}, {"numero": 20, "texto": "Dieu dit: Que les eaux produisent en abondance des animaux vivants, et que des oiseaux volent sur la terre vers l''''étendue du ciel."}, {"numero": 21, "texto": "Dieu créa les grands poissons et tous les animaux vivants qui se meuvent, et que les eaux produisirent en abondance selon leur espèce; il créa aussi tout oiseau ailé selon son espèce. Dieu vit que cela était bon."}, {"numero": 22, "texto": "Dieu les bénit, en disant: Soyez féconds, multipliez, et remplissez les eaux des mers; et que les oiseaux multiplient sur la terre."}, {"numero": 23, "texto": "Ainsi, il y eut un soir, et il y eut un matin: ce fut le cinquième jour."}, {"numero": 24, "texto": "Dieu dit: Que la terre produise des animaux vivants selon leur espèce, du bétail, des reptiles et des animaux terrestres, selon leur espèce. Et cela fut ainsi."}, {"numero": 25, "texto": "Dieu fit les animaux de la terre selon leur espèce, le bétail selon son espèce, et tous les reptiles de la terre selon leur espèce. Dieu vit que cela était bon."}, {"numero": 26, "texto": "Puis Dieu dit: Faisons l''''homme à notre image, selon notre ressemblance, et qu''''il domine sur les poissons de la mer, sur les oiseaux du ciel, sur le bétail, sur toute la terre, et sur tous les reptiles qui rampent sur la terre."}, {"numero": 27, "texto": "Dieu créa l''''homme à son image, il le créa à l''''image de Dieu, il créa l''''homme et la femme."}, {"numero": 28, "texto": "Dieu les bénit, et Dieu leur dit: Soyez féconds, multipliez, remplissez la terre, et l''''assujettissez; et dominez sur les poissons de la mer, sur les oiseaux du ciel, et sur tout animal qui se meut sur la terre."}, {"numero": 29, "texto": "Et Dieu dit: Voici, je vous donne toute herbe portant de la semence et qui est à la surface de toute la terre, et tout arbre ayant en lui du fruit d''''arbre et portant de la semence: ce sera votre nourriture."}, {"numero": 30, "texto": "Et à tout animal de la terre, à tout oiseau du ciel, et à tout ce qui se meut sur la terre, ayant en soi un souffle de vie, je donne toute herbe verte pour nourriture. Et cela fut ainsi."}, {"numero": 31, "texto": "Dieu vit tout ce qu''''il avait fait et voici, cela était très bon. Ainsi, il y eut un soir, et il y eut un matin: ce fut le sixième jour."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 1, 'es', '[{"numero": 1, "texto": "EN el principio crió Dios los cielos y la tierra."}, {"numero": 2, "texto": "Y la tierra estaba desordenada y vacía, y las tinieblas estaban sobre la haz del abismo, y el Espíritu de Dios se movía sobre la haz de las aguas."}, {"numero": 3, "texto": "Y dijo Dios: Sea la luz: y fué la luz."}, {"numero": 4, "texto": "Y vió Dios que la luz era buena: y apartó Dios la luz de las tinieblas."}, {"numero": 5, "texto": "Y llamó Dios á la luz Día, y á las tinieblas llamó Noche: y fué la tarde y la mañana un día."}, {"numero": 6, "texto": "Y dijo Dios: Haya expansión en medio de las aguas, y separe las aguas de las aguas."}, {"numero": 7, "texto": "E hizo Dios la expansión, y apartó las aguas que estaban debajo de la expansión, de las aguas que estaban sobre la expansión: y fué así."}, {"numero": 8, "texto": "Y llamó Dios á la expansión Cielos: y fué la tarde y la mañana el día segundo."}, {"numero": 9, "texto": "Y dijo Dios: Júntense las aguas que están debajo de los cielos en un lugar, y descúbrase la seca: y fué así."}, {"numero": 10, "texto": "Y llamó Dios á la seca Tierra, y á la reunión de las aguas llamó Mares: y vió Dios que era bueno."}, {"numero": 11, "texto": "Y dijo Dios: Produzca la tierra hierba verde, hierba que dé simiente; árbol de fruto que dé fruto según su género, que su simiente esté en él, sobre la tierra: y fué así."}, {"numero": 12, "texto": "Y produjo la tierra hierba verde, hierba que da simiente según su naturaleza, y árbol que da fruto, cuya simiente está en él, según su género: y vió Dios que era bueno."}, {"numero": 13, "texto": "Y fué la tarde y la mañana el día tercero."}, {"numero": 14, "texto": "Y dijo Dios: Sean lumbreras en la expansión de los cielos para apartar el día y la noche: y sean por señales, y para las estaciones, y para días y años;"}, {"numero": 15, "texto": "Y sean por lumbreras en la expansión de los cielos para alumbrar sobre la tierra: y fué así."}, {"numero": 16, "texto": "E hizo Dios las dos grandes lumbreras; la lumbrera mayor para que señorease en el día, y la lumbrera menor para que señorease en la noche: hizo también las estrellas."}, {"numero": 17, "texto": "Y púsolas Dios en la expansión de los cielos, para alumbrar sobre la tierra,"}, {"numero": 18, "texto": "Y para señorear en el día y en la noche, y para apartar la luz y las tinieblas: y vió Dios que era bueno."}, {"numero": 19, "texto": "Y fué la tarde y la mañana el día cuarto."}, {"numero": 20, "texto": "Y dijo Dios: Produzcan las aguas reptil de ánima viviente, y aves que vuelen sobre la tierra, en la abierta expansión de los cielos."}, {"numero": 21, "texto": "Y crió Dios las grandes ballenas, y toda cosa viva que anda arrastrando, que las aguas produjeron según su género, y toda ave alada según su especie: y vió Dios que era bueno."}, {"numero": 22, "texto": "Y Dios los bendijo diciendo: Fructificad y multiplicad, y henchid las aguas en los mares, y las aves se multipliquen en la tierra."}, {"numero": 23, "texto": "Y fué la tarde y la mañana el día quinto."}, {"numero": 24, "texto": "Y dijo Dios: Produzca la tierra seres vivientes según su género, bestias y serpientes y animales de la tierra según su especie: y fué así."}, {"numero": 25, "texto": "E hizo Dios animales de la tierra según su género, y ganado según su género, y todo animal que anda arrastrando sobre la tierra según su especie: y vió Dios que era bueno."}, {"numero": 26, "texto": "Y dijo Dios: Hagamos al hombre á nuestra imagen, conforme á nuestra semejanza; y señoree en los peces de la mar, y en las aves de los cielos, y en las bestias, y en toda la tierra, y en todo animal que anda arrastrando sobre la tierra."}, {"numero": 27, "texto": "Y crió Dios al hombre á su imagen, á imagen de Dios lo crió; varón y hembra los crió."}, {"numero": 28, "texto": "Y los bendijo Dios; y díjoles Dios: Fructificad y multiplicad, y henchid la tierra, y sojuzgadla, y señoread en los peces de la mar, y en las aves de los cielos, y en todas las bestias que se mueven sobre la tierra."}, {"numero": 29, "texto": "Y dijo Dios: He aquí que os he dado toda hierba que da simiente, que está sobre la haz de toda la tierra; y todo árbol en que hay fruto de árbol que da simiente, seros ha para comer."}, {"numero": 30, "texto": "Y á toda bestia de la tierra, y á todas las aves de los cielos, y á todo lo que se mueve sobre la tierra, en que hay vida, toda hierba verde les será para comer: y fué así."}, {"numero": 31, "texto": "Y vió Dios todo lo que había hecho, y he aquí que era bueno en gran manera. Y fué la tarde y la mañana el día sexto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 2, 'pt', '[{"numero": 1, "texto": "E foram concluídos os céus e a terra, e tudo o que neles há."}, {"numero": 2, "texto": "E acabou Deus no dia sétimo sua obra que fez, e repousou o dia sétimo de toda sua obra que havia feito."}, {"numero": 3, "texto": "E abençoou Deus ao dia sétimo, e o santificou, porque nele repousou de toda sua obra que havia Deus criado e feito."}, {"numero": 4, "texto": "Estas são as origens dos céus e da terra quando foram criados, no dia que o SENHOR Deus fez a terra e os céus,"}, {"numero": 5, "texto": "E antes que toda planta do campo existisse na terra, e antes que toda erva do campo nascesse; porque ainda não havia o SENHOR Deus feito chover sobre a terra, nem havia homem para que lavrasse a terra;"}, {"numero": 6, "texto": "Mas subia da terra um vapor, que regava toda a face da terra."}, {"numero": 7, "texto": "Formou, pois, o SENHOR Deus ao homem do pó da terra, e assoprou em seu nariz sopro de vida; e foi o homem em alma vivente."}, {"numero": 8, "texto": "E havia o SENHOR Deus plantado um jardim em Éden ao oriente, e pôs ali ao homem que havia formado."}, {"numero": 9, "texto": "E havia o SENHOR Deus feito nascer da terra toda árvore agradável à vista, e boa para comer: também a árvore da vida em meio do jardim, e a árvore do conhecimento do bem e do mal."}, {"numero": 10, "texto": "E saía de Éden um rio para regar o jardim, e dali se repartia em quatro ramificações."}, {"numero": 11, "texto": "O nome de um era Pisom: este é o que cerca toda a terra de Havilá, onde há ouro:"}, {"numero": 12, "texto": "E o ouro daquela terra é bom; há ali também bdélio e pedra ônix."}, {"numero": 13, "texto": "O nome do segundo rio é Giom; este é o que rodeia toda a terra de Cuxe."}, {"numero": 14, "texto": "E o nome do terceiro rio é Tigre; este é o que vai diante da Assíria. E o quarto rio é o Eufrates."}, {"numero": 15, "texto": "Então o SENHOR Deus tomou o homem, e o pôs no jardim de Éden, para que o lavrasse e o guardasse."}, {"numero": 16, "texto": "E mandou o SENHOR Deus ao homem, dizendo: De toda árvore do jardim comerás;"}, {"numero": 17, "texto": "Mas da árvore do conhecimento do bem e do mal não comerás dela; porque no dia que dela comeres, morrerás."}, {"numero": 18, "texto": "E disse o SENHOR Deus: Não é bom que o homem esteja só; farei para ele ajuda idônea para ele."}, {"numero": 19, "texto": "Formou, pois, o SENHOR Deus da terra todo animal do campo, e toda ave dos céus, e trouxe-os a Adão, para que visse como lhes havia de chamar; e tudo o que Adão chamou aos animais viventes, esse é seu nome."}, {"numero": 20, "texto": "E pôs Adão nomes a todo animal e ave dos céus e a todo animal do campo: mas para Adão não achou ajuda que estivesse idônea para ele."}, {"numero": 21, "texto": "E o SENHOR Deus fez cair sonho sobre Adão, e ele adormeceu: então tomou uma de suas costelas, e fechou a carne em seu lugar;"}, {"numero": 22, "texto": "E da costela que o SENHOR Deus tomou do homem, fez uma mulher, e trouxe-a ao homem."}, {"numero": 23, "texto": "E disse Adão: Esta é agora osso de meus ossos, e carne de minha carne: esta será chamada Mulher, porque do homem foi tomada."}, {"numero": 24, "texto": "Portanto, deixará o homem a seu pai e a sua mãe, e se achegará à sua mulher, e serão uma só carne."}, {"numero": 25, "texto": "E estavam ambos nus, Adão e sua mulher, e não se envergonhavam."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 2, 'en', '[{"numero": 1, "texto": "Thus the heavens and the earth were finished, and all the host of them."}, {"numero": 2, "texto": "And on the seventh day God ended his work which he had made; and he rested on the seventh day from all his work which he had made."}, {"numero": 3, "texto": "And God blessed the seventh day, and sanctified it: because that in it he had rested from all his work which God created and made."}, {"numero": 4, "texto": "These are the generations of the heavens and of the earth when they were created, in the day that the Lord God made the earth and the heavens,"}, {"numero": 5, "texto": "And every plant of the field before it was in the earth, and every herb of the field before it grew: for the Lord God had not caused it to rain upon the earth, and there was not a man to till the ground."}, {"numero": 6, "texto": "But there went up a mist from the earth, and watered the whole face of the ground."}, {"numero": 7, "texto": "And the Lord God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul."}, {"numero": 8, "texto": "And the Lord God planted a garden eastward in Eden; and there he put the man whom he had formed."}, {"numero": 9, "texto": "And out of the ground made the Lord God to grow every tree that is pleasant to the sight, and good for food; the tree of life also in the midst of the garden, and the tree of knowledge of good and evil."}, {"numero": 10, "texto": "And a river went out of Eden to water the garden; and from thence it was parted, and became into four heads."}, {"numero": 11, "texto": "The name of the first is Pison: that is it which compasseth the whole land of Havilah, where there is gold;"}, {"numero": 12, "texto": "And the gold of that land is good: there is bdellium and the onyx stone."}, {"numero": 13, "texto": "And the name of the second river is Gihon: the same is it that compasseth the whole land of Ethiopia."}, {"numero": 14, "texto": "And the name of the third river is Hiddekel: that is it which goeth toward the east of Assyria. And the fourth river is Euphrates."}, {"numero": 15, "texto": "And the Lord God took the man, and put him into the garden of Eden to dress it and to keep it."}, {"numero": 16, "texto": "And the Lord God commanded the man, saying, Of every tree of the garden thou mayest freely eat:"}, {"numero": 17, "texto": "But of the tree of the knowledge of good and evil, thou shalt not eat of it: for in the day that thou eatest thereof thou shalt surely die."}, {"numero": 18, "texto": "And the Lord God said, It is not good that the man should be alone; I will make him an help meet for him."}, {"numero": 19, "texto": "And out of the ground the Lord God formed every beast of the field, and every fowl of the air; and brought them unto Adam to see what he would call them: and whatsoever Adam called every living creature, that was the name thereof."}, {"numero": 20, "texto": "And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him."}, {"numero": 21, "texto": "And the Lord God caused a deep sleep to fall upon Adam, and he slept: and he took one of his ribs, and closed up the flesh instead thereof;"}, {"numero": 22, "texto": "And the rib, which the Lord God had taken from man, made he a woman, and brought her unto the man."}, {"numero": 23, "texto": "And Adam said, This is now bone of my bones, and flesh of my flesh: she shall be called Woman, because she was taken out of Man."}, {"numero": 24, "texto": "Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh."}, {"numero": 25, "texto": "And they were both naked, the man and his wife, and were not ashamed."}]'::jsonb, 'King James Version'),
  ('Gn', 2, 'fr', '[{"numero": 1, "texto": "Ainsi furent achevés les cieux et la terre, et toute leur armée."}, {"numero": 2, "texto": "Dieu acheva au septième jour son oeuvre, qu''''il avait faite: et il se reposa au septième jour de toute son oeuvre, qu''''il avait faite."}, {"numero": 3, "texto": "Dieu bénit le septième jour, et il le sanctifia, parce qu''''en ce jour il se reposa de toute son oeuvre qu''''il avait créée en la faisant."}, {"numero": 4, "texto": "Voici les origines des cieux et de la terre, quand ils furent créés. Lorsque l''''Eternel Dieu fit une terre et des cieux,"}, {"numero": 5, "texto": "aucun arbuste des champs n''''était encore sur la terre, et aucune herbe des champs ne germait encore: car l''''Eternel Dieu n''''avait pas fait pleuvoir sur la terre, et il n''''y avait point d''''homme pour cultiver le sol."}, {"numero": 6, "texto": "Mais une vapeur s''''éleva de la terre, et arrosa toute la surface du sol."}, {"numero": 7, "texto": "L''''Eternel Dieu forma l''''homme de la poussière de la terre, il souffla dans ses narines un souffle de vie et l''''homme devint un être vivant."}, {"numero": 8, "texto": "Puis l''''Eternel Dieu planta un jardin en Eden, du côté de l''''orient, et il y mit l''''homme qu''''il avait formé."}, {"numero": 9, "texto": "L''''Eternel Dieu fit pousser du sol des arbres de toute espèce, agréables à voir et bons à manger, et l''''arbre de la vie au milieu du jardin, et l''''arbre de la connaissance du bien et du mal."}, {"numero": 10, "texto": "Un fleuve sortait d''''Eden pour arroser le jardin, et de là il se divisait en quatre bras."}, {"numero": 11, "texto": "Le nom du premier est Pischon; c''''est celui qui entoure tout le pays de Havila, où se trouve l''''or."}, {"numero": 12, "texto": "L''''or de ce pays est pur; on y trouve aussi le bdellium et la pierre d''''onyx."}, {"numero": 13, "texto": "Le nom du second fleuve est Guihon; c''''est celui qui entoure tout le pays de Cusch."}, {"numero": 14, "texto": "Le nom du troisième est Hiddékel; c''''est celui qui coule à l''''orient de l''''Assyrie. Le quatrième fleuve, c''''est l''''Euphrate."}, {"numero": 15, "texto": "L''''Eternel Dieu prit l''''homme, et le plaça dans le jardin d''''Eden pour le cultiver et pour le garder."}, {"numero": 16, "texto": "L''''Eternel Dieu donna cet ordre à l''''homme: Tu pourras manger de tous les arbres du jardin;"}, {"numero": 17, "texto": "mais tu ne mangeras pas de l''''arbre de la connaissance du bien et du mal, car le jour où tu en mangeras, tu mourras."}, {"numero": 18, "texto": "L''''Eternel Dieu dit: Il n''''est pas bon que l''''homme soit seul; je lui ferai une aide semblable à lui."}, {"numero": 19, "texto": "L''''Eternel Dieu forma de la terre tous les animaux des champs et tous les oiseaux du ciel, et il les fit venir vers l''''homme, pour voir comment il les appellerait, et afin que tout être vivant portât le nom que lui donnerait l''''homme."}, {"numero": 20, "texto": "Et l''''homme donna des noms à tout le bétail, aux oiseaux du ciel et à tous les animaux des champs; mais, pour l''''homme, il ne trouva point d''''aide semblable à lui."}, {"numero": 21, "texto": "Alors l''''Eternel Dieu fit tomber un profond sommeil sur l''''homme, qui s''''endormit; il prit une de ses côtes, et referma la chair à sa place."}, {"numero": 22, "texto": "L''''Eternel Dieu forma une femme de la côte qu''''il avait prise de l''''homme, et il l''''amena vers l''''homme."}, {"numero": 23, "texto": "Et l''''homme dit: Voici cette fois celle qui est os de mes os et chair de ma chair! on l''''appellera femme, parce qu''''elle a été prise de l''''homme."}, {"numero": 24, "texto": "C''''est pourquoi l''''homme quittera son père et sa mère, et s''''attachera à sa femme, et ils deviendront une seule chair."}, {"numero": 25, "texto": "L''''homme et sa femme étaient tous deux nus, et ils n''''en avaient point honte."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 2, 'es', '[{"numero": 1, "texto": "Y FUERON acabados los cielos y la tierra, y todo su ornamento."}, {"numero": 2, "texto": "Y acabó Dios en el día séptimo su obra que hizo, y reposó el día séptimo de toda su obra que había hecho."}, {"numero": 3, "texto": "Y bendijo Dios al día séptimo, y santificólo, porque en él reposó de toda su obra que había Dios criado y hecho."}, {"numero": 4, "texto": "Estos son los orígenes de los cielos y de la tierra cuando fueron criados, el día que Jehová Dios hizo la tierra y los cielos,"}, {"numero": 5, "texto": "Y toda planta del campo antes que fuese en la tierra, y toda hierba del campo antes que naciese: porque aun no había Jehová Dios hecho llover sobre la tierra, ni había hombre para que labrase la tierra;"}, {"numero": 6, "texto": "Mas subía de la tierra un vapor, que regaba toda la faz de la tierra."}, {"numero": 7, "texto": "Formó, pues, Jehová Dios al hombre del polvo de la tierra, y alentó en su nariz soplo de vida; y fué el hombre en alma viviente."}, {"numero": 8, "texto": "Y había Jehová Dios plantado un huerto en Edén al oriente, y puso allí al hombre que había formado."}, {"numero": 9, "texto": "Y había Jehová Dios hecho nacer de la tierra todo árbol delicioso á la vista, y bueno para comer: también el árbol de vida en medio del huerto, y el árbol de ciencia del bien y del mal."}, {"numero": 10, "texto": "Y salía de Edén un río para regar el huerto, y de allí se repartía en cuatro ramales."}, {"numero": 11, "texto": "El nombre del uno era Pisón: éste es el que cerca toda la tierra de Havilah, donde hay oro:"}, {"numero": 12, "texto": "Y el oro de aquella tierra es bueno: hay allí también bdelio y piedra cornerina."}, {"numero": 13, "texto": "El nombre del segundo río es Gihón: éste es el que rodea toda la tierra de Etiopía."}, {"numero": 14, "texto": "Y el nombre del tercer río es Hiddekel: éste es el que va delante de Asiria. Y el cuarto río es el Eufrates."}, {"numero": 15, "texto": "Tomó, pues, Jehová Dios al hombre, y le puso en el huerto de Edén, para que lo labrara y lo guardase."}, {"numero": 16, "texto": "Y mandó Jehová Dios al hombre, diciendo: De todo árbol del huerto comerás;"}, {"numero": 17, "texto": "Mas del árbol de ciencia del bien y del mal no comerás de él; porque el día que de él comieres, morirás."}, {"numero": 18, "texto": "Y dijo Jehová Dios: No es bueno que el hombre esté solo; haréle ayuda idónea para él."}, {"numero": 19, "texto": "Formó, pues, Jehová Dios de la tierra toda bestia del campo, y toda ave de los cielos, y trájolas á Adam, para que viese cómo les había de llamar; y todo lo que Adam llamó á los animales vivientes, ese es su nombre."}, {"numero": 20, "texto": "Y puso Adam nombres á toda bestia y ave de los cielos y á todo animal del campo: mas para Adam no halló ayuda que estuviese idónea para él."}, {"numero": 21, "texto": "Y Jehová Dios hizo caer sueño sobre Adam, y se quedó dormido: entonces tomó una de sus costillas, y cerró la carne en su lugar;"}, {"numero": 22, "texto": "Y de la costilla que Jehová Dios tomó del hombre, hizo una mujer, y trájola al hombre."}, {"numero": 23, "texto": "Y dijo Adam: Esto es ahora hueso de mis huesos, y carne de mi carne: ésta será llamada Varona, porque del varón fué tomada."}, {"numero": 24, "texto": "Por tanto, dejará el hombre á su padre y á su madre, y allegarse ha á su mujer, y serán una sola carne."}, {"numero": 25, "texto": "Y estaban ambos desnudos, Adam y su mujer, y no se avergonzaban."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 3, 'pt', '[{"numero": 1, "texto": "Porém a serpente era astuta, mais que todos os animais do campo que o SENHOR Deus havia feito. E ela disse à mulher: Deus vos disse: Não comais de toda árvore do jardim?"}, {"numero": 2, "texto": "E a mulher respondeu à serpente: Do fruto das árvores do jardim podemos comer;"}, {"numero": 3, "texto": "mas do fruto da árvore que está no meio do jardim, Deus disse: Não comereis dele, nem o tocareis, para que não morrais."}, {"numero": 4, "texto": "Então a serpente disse à mulher: Não morrereis;"}, {"numero": 5, "texto": "Mas Deus sabe que no dia que comerdes dele, vossos olhos serão abertos, e sereis como deuses, sabendo o bem e o mal."}, {"numero": 6, "texto": "E a mulher viu que a árvore era boa para se comer, agradável aos olhos, e árvore desejável para se obter conhecimento. E ela tomou de seu fruto, e comeu; e deu também ao seu marido com ela, e ele comeu."}, {"numero": 7, "texto": "E foram abertos os olhos de ambos, e conheceram que estavam nus. Então coseram folhas de figueira, e fizeram para si aventais."}, {"numero": 8, "texto": "E ouviram a voz do SENHOR Deus, que passeava no jardim à brisa do dia; e o homem e sua mulher esconderam-se da presença do SENHOR Deus entre as árvores do jardim."}, {"numero": 9, "texto": "E o SENHOR Deus chamou ao homem, e lhe disse: “Onde estás?"}, {"numero": 10, "texto": "E ele respondeu: “Ouvi tua voz no jardim, e tive medo, porque estava nu; e me escondi”."}, {"numero": 11, "texto": "E disse-lhe: “Quem te ensinou que estavas nu? Comeste da árvore de que te mandei que não comesses?”"}, {"numero": 12, "texto": "E o homem respondeu: “A mulher que me deste por companheira me deu da árvore, e eu comi”."}, {"numero": 13, "texto": "Então o SENHOR Deus disse à mulher: “Por que fizeste isto?” E a mulher disse: “A serpente me enganou, e comi”."}, {"numero": 14, "texto": "E o SENHOR Deus disse à serpente: “Porque fizeste isto, maldita serás entre todos os animais selvagens e entre todos os animais do campo; sobre teu ventre andarás, e pó comerás todos os dias da tua vida."}, {"numero": 15, "texto": "E porei inimizade entre ti e a mulher, e entre tua descendência e a descendência dela; esta te ferirá a cabeça, e tu lhe ferirás o calcanhar”."}, {"numero": 16, "texto": "E para a mulher disse: “Multiplicarei grandemente as tuas dores e teus sofrimentos de parto; com dor darás à luz filhos; e o teu desejo será para o teu marido, e ele te dominará”."}, {"numero": 17, "texto": "E ao homem disse: “Porque deste ouvidos à voz de tua mulher, e comeste da árvore de que te mandei dizendo, ‘Não comerás dela’, maldita será a terra por causa de ti; com dor comerás dela todos os dias da tua vida;"}, {"numero": 18, "texto": "Espinhos e cardos te produzirá, e comerás erva do campo."}, {"numero": 19, "texto": "No suor do teu rosto comerás o pão até que voltes à terra, porque dela foste tomado; porque pó és, e ao pó voltarás”."}, {"numero": 20, "texto": "E chamou o homem o nome de sua mulher, Eva; porquanto ela era mãe de todos o viventes."}, {"numero": 21, "texto": "E o SENHOR Deus fez ao homem e à sua mulher túnicas de peles, e os vestiu."}, {"numero": 22, "texto": "E disse o SENHOR Deus: Eis que o homem é como um de Nos sabendo o bem e o mal; agora, pois, para que não estenda sua mão, e tome também da árvore da vida, e coma, e viva para sempre:"}, {"numero": 23, "texto": "E tirou-o o SENHOR do jardim de Éden, para que lavrasse a terra de que foi tomado."}, {"numero": 24, "texto": "Lançou, pois, fora ao homem, e pôs ao oriente do jardim de Éden querubins, e uma espada acesa que se revolvia a todos os lados, para guardar o caminho da árvore da vida."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 3, 'en', '[{"numero": 1, "texto": "Now the serpent was more subtil than any beast of the field which the Lord God had made. And he said unto the woman, Yea, hath God said, Ye shall not eat of every tree of the garden?"}, {"numero": 2, "texto": "And the woman said unto the serpent, We may eat of the fruit of the trees of the garden:"}, {"numero": 3, "texto": "But of the fruit of the tree which is in the midst of the garden, God hath said, Ye shall not eat of it, neither shall ye touch it, lest ye die."}, {"numero": 4, "texto": "And the serpent said unto the woman, Ye shall not surely die:"}, {"numero": 5, "texto": "For God doth know that in the day ye eat thereof, then your eyes shall be opened, and ye shall be as gods, knowing good and evil."}, {"numero": 6, "texto": "And when the woman saw that the tree was good for food, and that it was pleasant to the eyes, and a tree to be desired to make one wise, she took of the fruit thereof, and did eat, and gave also unto her husband with her; and he did eat."}, {"numero": 7, "texto": "And the eyes of them both were opened, and they knew that they were naked; and they sewed fig leaves together, and made themselves aprons."}, {"numero": 8, "texto": "And they heard the voice of the Lord God walking in the garden in the cool of the day: and Adam and his wife hid themselves from the presence of the Lord God amongst the trees of the garden."}, {"numero": 9, "texto": "And the Lord God called unto Adam, and said unto him, Where art thou?"}, {"numero": 10, "texto": "And he said, I heard thy voice in the garden, and I was afraid, because I was naked; and I hid myself."}, {"numero": 11, "texto": "And he said, Who told thee that thou wast naked? Hast thou eaten of the tree, whereof I commanded thee that thou shouldest not eat?"}, {"numero": 12, "texto": "And the man said, The woman whom thou gavest to be with me, she gave me of the tree, and I did eat."}, {"numero": 13, "texto": "And the Lord God said unto the woman, What is this that thou hast done? And the woman said, The serpent beguiled me, and I did eat."}, {"numero": 14, "texto": "And the Lord God said unto the serpent, Because thou hast done this, thou art cursed above all cattle, and above every beast of the field; upon thy belly shalt thou go, and dust shalt thou eat all the days of thy life:"}, {"numero": 15, "texto": "And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel."}, {"numero": 16, "texto": "Unto the woman he said, I will greatly multiply thy sorrow and thy conception; in sorrow thou shalt bring forth children; and thy desire shall be to thy husband, and he shall rule over thee."}, {"numero": 17, "texto": "And unto Adam he said, Because thou hast hearkened unto the voice of thy wife, and hast eaten of the tree, of which I commanded thee, saying, Thou shalt not eat of it: cursed is the ground for thy sake; in sorrow shalt thou eat of it all the days of thy life;"}, {"numero": 18, "texto": "Thorns also and thistles shall it bring forth to thee; and thou shalt eat the herb of the field;"}, {"numero": 19, "texto": "In the sweat of thy face shalt thou eat bread, till thou return unto the ground; for out of it wast thou taken: for dust thou art, and unto dust shalt thou return."}, {"numero": 20, "texto": "And Adam called his wife''s name Eve; because she was the mother of all living."}, {"numero": 21, "texto": "Unto Adam also and to his wife did the Lord God make coats of skins, and clothed them."}, {"numero": 22, "texto": "And the Lord God said, Behold, the man is become as one of us, to know good and evil: and now, lest he put forth his hand, and take also of the tree of life, and eat, and live for ever:"}, {"numero": 23, "texto": "Therefore the Lord God sent him forth from the garden of Eden, to till the ground from whence he was taken."}, {"numero": 24, "texto": "So he drove out the man; and he placed at the east of the garden of Eden Cherubims, and a flaming sword which turned every way, to keep the way of the tree of life."}]'::jsonb, 'King James Version'),
  ('Gn', 3, 'fr', '[{"numero": 1, "texto": "Le serpent était le plus rusé de tous les animaux des champs, que l''''Eternel Dieu avait faits. Il dit à la femme: Dieu a-t-il réellement dit: Vous ne mangerez pas de tous les arbres du jardin?"}, {"numero": 2, "texto": "La femme répondit au serpent: Nous mangeons du fruit des arbres du jardin."}, {"numero": 3, "texto": "Mais quant au fruit de l''''arbre qui est au milieu du jardin, Dieu a dit: Vous n''''en mangerez point et vous n''''y toucherez point, de peur que vous ne mouriez."}, {"numero": 4, "texto": "Alors le serpent dit à la femme: Vous ne mourrez point;"}, {"numero": 5, "texto": "mais Dieu sait que, le jour où vous en mangerez, vos yeux s''''ouvriront, et que vous serez comme des dieux, connaissant le bien et le mal."}, {"numero": 6, "texto": "La femme vit que l''''arbre était bon à manger et agréable à la vue, et qu''''il était précieux pour ouvrir l''''intelligence; elle prit de son fruit, et en mangea; elle en donna aussi à son mari, qui était auprès d''''elle, et il en mangea."}, {"numero": 7, "texto": "Les yeux de l''''un et de l''''autre s''''ouvrirent, ils connurent qu''''ils étaient nus, et ayant cousu des feuilles de figuier, ils s''''en firent des ceintures."}, {"numero": 8, "texto": "Alors ils entendirent la voix de l''''Eternel Dieu, qui parcourait le jardin vers le soir, et l''''homme et sa femme se cachèrent loin de la face de l''''Eternel Dieu, au milieu des arbres du jardin."}, {"numero": 9, "texto": "Mais l''''Eternel Dieu appela l''''homme, et lui dit: Où es-tu?"}, {"numero": 10, "texto": "Il répondit: J''''ai entendu ta voix dans le jardin, et j''''ai eu peur, parce que je suis nu, et je me suis caché."}, {"numero": 11, "texto": "Et l''''Eternel Dieu dit: Qui t''''a appris que tu es nu? Est-ce que tu as mangé de l''''arbre dont je t''''avais défendu de manger?"}, {"numero": 12, "texto": "L''''homme répondit: La femme que tu as mise auprès de moi m''''a donné de l''''arbre, et j''''en ai mangé."}, {"numero": 13, "texto": "Et l''''Eternel Dieu dit à la femme: Pourquoi as-tu fait cela? La femme répondit: Le serpent m''''a séduite, et j''''en ai mangé."}, {"numero": 14, "texto": "L''''Eternel Dieu dit au serpent: Puisque tu as fait cela, tu seras maudit entre tout le bétail et entre tous les animaux des champs, tu marcheras sur ton ventre, et tu mangeras de la poussière tous les jours de ta vie."}, {"numero": 15, "texto": "Je mettrai inimitié entre toi et la femme, entre ta postérité et sa postérité: celle-ci t''''écrasera la tête, et tu lui blesseras le talon."}, {"numero": 16, "texto": "Il dit à la femme: J''''augmenterai la souffrance de tes grossesses, tu enfanteras avec douleur, et tes désirs se porteront vers ton mari, mais il dominera sur toi."}, {"numero": 17, "texto": "Il dit à l''''homme: Puisque tu as écouté la voix de ta femme, et que tu as mangé de l''''arbre au sujet duquel je t''''avais donné cet ordre: Tu n''''en mangeras point! le sol sera maudit à cause de toi. C''''est à force de peine que tu en tireras ta nourriture tous les jours de ta vie,"}, {"numero": 18, "texto": "il te produira des épines et des ronces, et tu mangeras de l''''herbe des champs."}, {"numero": 19, "texto": "C''''est à la sueur de ton visage que tu mangeras du pain, jusqu''''à ce que tu retournes dans la terre, d''''où tu as été pris; car tu es poussière, et tu retourneras dans la poussière."}, {"numero": 20, "texto": "Adam donna à sa femme le nom d''''Eve: car elle a été la mère de tous les vivants."}, {"numero": 21, "texto": "L''''Eternel Dieu fit à Adam et à sa femme des habits de peau, et il les en revêtit."}, {"numero": 22, "texto": "L''''Eternel Dieu dit: Voici, l''''homme est devenu comme l''''un de nous, pour la connaissance du bien et du mal. Empêchons-le maintenant d''''avancer sa main, de prendre de l''''arbre de vie, d''''en manger, et de vivre éternellement."}, {"numero": 23, "texto": "Et l''''Eternel Dieu le chassa du jardin d''''Eden, pour qu''''il cultivât la terre, d''''où il avait été pris."}, {"numero": 24, "texto": "C''''est ainsi qu''''il chassa Adam; et il mit à l''''orient du jardin d''''Eden les chérubins qui agitent une épée flamboyante, pour garder le chemin de l''''arbre de vie."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 3, 'es', '[{"numero": 1, "texto": "EMPERO la serpiente era astuta, más que todos los animales del campo que Jehová Dios había hecho; la cual dijo á la mujer: ¿Conque Dios os ha dicho: No comáis de todo árbol del huerto?"}, {"numero": 2, "texto": "Y la mujer respondió á la serpiente: Del fruto de los árboles del huerto comemos;"}, {"numero": 3, "texto": "Mas del fruto del árbol que está en medio del huerto dijo Dios: No comeréis de él, ni le tocaréis, porque no muráis."}, {"numero": 4, "texto": "Entonces la serpiente dijo á la mujer: No moriréis;"}, {"numero": 5, "texto": "Mas sabe Dios que el día que comiereis de él, serán abiertos vuestros ojos, y seréis como dioses sabiendo el bien y el mal."}, {"numero": 6, "texto": "Y vió la mujer que el árbol era bueno para comer, y que era agradable á los ojos, y árbol codiciable para alcanzar la sabiduría; y tomó de su fruto, y comió; y dió también á su marido, el cual comió así como ella."}, {"numero": 7, "texto": "Y fueron abiertos los ojos de entrambos, y conocieron que estaban desnudos: entonces cosieron hojas de higuera, y se hicieron delantales."}, {"numero": 8, "texto": "Y oyeron la voz de Jehová Dios que se paseaba en el huerto al aire del día: y escondióse el hombre y su mujer de la presencia de Jehová Dios entre los árboles del huerto."}, {"numero": 9, "texto": "Y llamó Jehová Dios al hombre, y le dijo: ¿Dónde estás tú?"}, {"numero": 10, "texto": "Y él respondió: Oí tu voz en el huerto, y tuve miedo, porque estaba desnudo; y escondíme."}, {"numero": 11, "texto": "Y díjole: ¿Quién te enseñó que estabas desnudo? ¿Has comido del árbol de que yo te mandé no comieses?"}, {"numero": 12, "texto": "Y el hombre respondió: La mujer que me diste por compañera me dió del árbol, y yo comí."}, {"numero": 13, "texto": "Entonces Jehová Dios dijo á la mujer: ¿Qué es lo que has hecho? Y dijo la mujer: La serpiente me engañó, y comí."}, {"numero": 14, "texto": "Y Jehová Dios dijo á la serpiente: Por cuanto esto hiciste, maldita serás entre todas las bestias y entre todos los animales del campo; sobre tu pecho andarás, y polvo comerás todos los días de tu vida:"}, {"numero": 15, "texto": "Y enemistad pondré entre ti y la mujer, y entre tu simiente y la simiente suya; ésta te herirá en la cabeza, y tú le herirás en el calcañar."}, {"numero": 16, "texto": "A la mujer dijo: Multiplicaré en gran manera tus dolores y tus preñeces; con dolor parirás los hijos; y á tu marido será tu deseo, y él se enseñoreará de ti."}, {"numero": 17, "texto": "Y al hombre dijo: Por cuanto obedeciste á la voz de tu mujer, y comiste del árbol de que te mandé diciendo, No comerás de él; maldita será la tierra por amor de ti; con dolor comerás de ella todos los días de tu vida;"}, {"numero": 18, "texto": "Espinos y cardos te producirá, y comerás hierba del campo;"}, {"numero": 19, "texto": "En el sudor de tu rostro comerás el pan hasta que vuelvas á la tierra; porque de ella fuiste tomado: pues polvo eres, y al polvo serás tornado."}, {"numero": 20, "texto": "Y llamó el hombre el nombre de su mujer, Eva; por cuanto ella era madre de todos los vivientes."}, {"numero": 21, "texto": "Y Jehová Dios hizo al hombre y á su mujer túnicas de pieles, y vistiólos."}, {"numero": 22, "texto": "Y dijo Jehová Dios: He aquí el hombre es como uno de Nos sabiendo el bien y el mal: ahora, pues, porque no alargue su mano, y tome también del árbol de la vida, y coma, y viva para siempre:"}, {"numero": 23, "texto": "Y sacólo Jehová del huerto de Edén, para que labrase la tierra de que fué tomado."}, {"numero": 24, "texto": "Echó, pues, fuera al hombre, y puso al oriente del huerto de Edén querubines, y una espada encendida que se revolvía á todos lados, para guardar el camino del árbol de la vida."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 4, 'pt', '[{"numero": 1, "texto": "E Adão conheceu a sua mulher Eva, a qual concebeu e deu à luz a Caim, e disse: Obtive um homem pelo SENHOR."}, {"numero": 2, "texto": "E depois deu à luz a seu irmão Abel. E foi Abel pastor de ovelhas, e Caim foi lavrador da terra."}, {"numero": 3, "texto": "E aconteceu, decorrendo o tempo, que Caim trouxe do fruto da terra uma oferta ao SENHOR."}, {"numero": 4, "texto": "E Abel trouxe também dos primogênitos de suas ovelhas, e de sua gordura. E olhou o SENHOR com agrado a Abel e à sua oferta;"}, {"numero": 5, "texto": "mas não olhou com bons olhos a Caim e à sua oferta. Caim irritou-se muito, e descaiu-lhe o semblante."}, {"numero": 6, "texto": "Então o SENHOR disse a Caim: Por que te irritaste, e por que o teu semblante descaiu?"}, {"numero": 7, "texto": "Se bem fizeres, não serás aceito? E se não fizeres bem, o pecado está à porta; contra ti será o seu desejo, porém tu deves dominá-lo."}, {"numero": 8, "texto": "Depois Caim falou a seu irmão Abel; e aconteceu que, estando eles no campo, Caim se levantou contra seu irmão Abel, e o matou."}, {"numero": 9, "texto": "E o SENHOR disse a Caim: Onde está teu irmão Abel? E ele respondeu: Não sei; sou eu guarda do meu irmão?"}, {"numero": 10, "texto": "E ele lhe disse: Que fizeste? A voz do sangue do teu irmão clama a mim desde a terra."}, {"numero": 11, "texto": "Agora, pois, maldito sejas tu da terra que abriu sua boca para receber o sangue de teu irmão de tua mão:"}, {"numero": 12, "texto": "Quando lavrares a terra, não te voltará a dar sua força: errante e fugitivo serás na terra."}, {"numero": 13, "texto": "E disse Caim ao SENHOR: Grande é minha iniquidade para ser perdoada."}, {"numero": 14, "texto": "Eis que me expulsas hoje da face da terra, e de tua presença me esconderei; e serei errante e fugitivo na terra; e sucederá que qualquer um que me achar, me matará."}, {"numero": 15, "texto": "E respondeu-lhe o SENHOR: Certo que qualquer um que matar a Caim, sete vezes será castigado. Então o SENHOR pôs sinal em Caim, para que não o ferisse qualquer um que o achasse."}, {"numero": 16, "texto": "E saiu Caim de diante do SENHOR, e habitou na terra de Node, ao oriente de Éden."}, {"numero": 17, "texto": "E conheceu Caim a sua mulher, a qual concebeu e deu à luz a Enoque: e edificou uma cidade, e chamou o nome da cidade do nome de seu filho, Enoque."}, {"numero": 18, "texto": "E a Enoque nasceu Irade, e Irade gerou a Meujael, e Meujael gerou a Metusael, e Metusael gerou a Lameque."}, {"numero": 19, "texto": "E tomou para si Lameque duas mulheres; o nome de uma foi Ada, e o nome da outra Zilá."}, {"numero": 20, "texto": "E Ada deu à luz a Jabal, o qual foi pai dos que habitam em tendas, e criam gados."}, {"numero": 21, "texto": "E o nome de seu irmão foi Jubal, o qual foi pai de todos os que manejam harpa e flauta."}, {"numero": 22, "texto": "E Zilá também deu à luz a Tubalcaim, feitor de toda obra de bronze e de ferro: e a irmã de Tubalcaim foi Naamá."}, {"numero": 23, "texto": "E disse Lameque a suas mulheres: Ada e Zilá, ouvi minha voz; Mulheres de Lameque, escutai meu dito: Que matei um homem por ter me ferido, E um rapaz por ter me golpeado:"}, {"numero": 24, "texto": "Se sete vezes será vingado Caim, Lameque em verdade setenta vezes sete o será."}, {"numero": 25, "texto": "E conheceu de novo Adão à sua mulher, a qual deu à luz um filho, e chamou seu nome Sete: Porque Deus (disse ela) me substituiu outra descendência em lugar de Abel, a quem matou Caim."}, {"numero": 26, "texto": "E a Sete também lhe nasceu um filho, e chamou seu nome Enos. Então os homens começaram a invocar o nome do SENHOR."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 4, 'en', '[{"numero": 1, "texto": "And Adam knew Eve his wife; and she conceived, and bare Cain, and said, I have gotten a man from the Lord."}, {"numero": 2, "texto": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}, {"numero": 3, "texto": "And in process of time it came to pass, that Cain brought of the fruit of the ground an offering unto the Lord."}, {"numero": 4, "texto": "And Abel, he also brought of the firstlings of his flock and of the fat thereof. And the Lord had respect unto Abel and to his offering:"}, {"numero": 5, "texto": "But unto Cain and to his offering he had not respect. And Cain was very wroth, and his countenance fell."}, {"numero": 6, "texto": "And the Lord said unto Cain, Why art thou wroth? and why is thy countenance fallen?"}, {"numero": 7, "texto": "If thou doest well, shalt thou not be accepted? and if thou doest not well, sin lieth at the door. And unto thee shall be his desire, and thou shalt rule over him."}, {"numero": 8, "texto": "And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him."}, {"numero": 9, "texto": "And the Lord said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother''s keeper?"}, {"numero": 10, "texto": "And he said, What hast thou done? the voice of thy brother''s blood crieth unto me from the ground."}, {"numero": 11, "texto": "And now art thou cursed from the earth, which hath opened her mouth to receive thy brother''s blood from thy hand;"}, {"numero": 12, "texto": "When thou tillest the ground, it shall not henceforth yield unto thee her strength; a fugitive and a vagabond shalt thou be in the earth."}, {"numero": 13, "texto": "And Cain said unto the Lord, My punishment is greater than I can bear."}, {"numero": 14, "texto": "Behold, thou hast driven me out this day from the face of the earth; and from thy face shall I be hid; and I shall be a fugitive and a vagabond in the earth; and it shall come to pass, that every one that findeth me shall slay me."}, {"numero": 15, "texto": "And the Lord said unto him, Therefore whosoever slayeth Cain, vengeance shall be taken on him sevenfold. And the Lord set a mark upon Cain, lest any finding him should kill him."}, {"numero": 16, "texto": "And Cain went out from the presence of the Lord, and dwelt in the land of Nod, on the east of Eden."}, {"numero": 17, "texto": "And Cain knew his wife; and she conceived, and bare Enoch: and he builded a city, and called the name of the city, after the name of his son, Enoch."}, {"numero": 18, "texto": "And unto Enoch was born Irad: and Irad begat Mehujael: and Mehujael begat Methusael: and Methusael begat Lamech."}, {"numero": 19, "texto": "And Lamech took unto him two wives: the name of the one was Adah, and the name of the other Zillah."}, {"numero": 20, "texto": "And Adah bare Jabal: he was the father of such as dwell in tents, and of such as have cattle."}, {"numero": 21, "texto": "And his brother''s name was Jubal: he was the father of all such as handle the harp and organ."}, {"numero": 22, "texto": "And Zillah, she also bare Tubalcain, an instructer of every artificer in brass and iron: and the sister of Tubalcain was Naamah."}, {"numero": 23, "texto": "And Lamech said unto his wives, Adah and Zillah, Hear my voice; ye wives of Lamech, hearken unto my speech: for I have slain a man to my wounding, and a young man to my hurt."}, {"numero": 24, "texto": "If Cain shall be avenged sevenfold, truly Lamech seventy and sevenfold."}, {"numero": 25, "texto": "And Adam knew his wife again; and she bare a son, and called his name Seth: For God, said she, hath appointed me another seed instead of Abel, whom Cain slew."}, {"numero": 26, "texto": "And to Seth, to him also there was born a son; and he called his name Enos: then began men to call upon the name of the Lord."}]'::jsonb, 'King James Version'),
  ('Gn', 4, 'fr', '[{"numero": 1, "texto": "Adam connut Eve, sa femme; elle conçut, et enfanta Caïn et elle dit: J''''ai formé un homme avec l''''aide de l''''Eternel."}, {"numero": 2, "texto": "Elle enfanta encore son frère Abel. Abel fut berger, et Caïn fut laboureur."}, {"numero": 3, "texto": "Au bout de quelque temps, Caïn fit à l''''Eternel une offrande des fruits de la terre;"}, {"numero": 4, "texto": "et Abel, de son côté, en fit une des premiers-nés de son troupeau et de leur graisse. L''''Eternel porta un regard favorable sur Abel et sur son offrande;"}, {"numero": 5, "texto": "mais il ne porta pas un regard favorable sur Caïn et sur son offrande. Caïn fut très irrité, et son visage fut abattu."}, {"numero": 6, "texto": "Et l''''Eternel dit à Caïn: Pourquoi es-tu irrité, et pourquoi ton visage est-il abattu?"}, {"numero": 7, "texto": "Certainement, si tu agis bien, tu relèveras ton visage, et si tu agis mal, le péché se couche à la porte, et ses désirs se portent vers toi: mais toi, domine sur lui."}, {"numero": 8, "texto": "Cependant, Caïn adressa la parole à son frère Abel; mais, comme ils étaient dans les champs, Caïn se jeta sur son frère Abel, et le tua."}, {"numero": 9, "texto": "L''''Eternel dit à Caïn: Où est ton frère Abel? Il répondit: Je ne sais pas; suis-je le gardien de mon frère?"}, {"numero": 10, "texto": "Et Dieu dit: Qu''''as-tu fait? La voix du sang de ton frère crie de la terre jusqu''''à moi."}, {"numero": 11, "texto": "Maintenant, tu seras maudit de la terre qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère."}, {"numero": 12, "texto": "Quand tu cultiveras le sol, il ne te donnera plus sa richesse. Tu seras errant et vagabond sur la terre."}, {"numero": 13, "texto": "Caïn dit à l''''Eternel: Mon châtiment est trop grand pour être supporté."}, {"numero": 14, "texto": "Voici, tu me chasses aujourd''''hui de cette terre; je serai caché loin de ta face, je serai errant et vagabond sur la terre, et quiconque me trouvera me tuera."}, {"numero": 15, "texto": "L''''Eternel lui dit: Si quelqu''''un tuait Caïn, Caïn serait vengé sept fois. Et l''''Eternel mit un signe sur Caïn pour que quiconque le trouverait ne le tuât point."}, {"numero": 16, "texto": "Puis, Caïn s''''éloigna de la face de l''''Eternel, et habita dans la terre de Nod, à l''''orient d''''Eden."}, {"numero": 17, "texto": "Caïn connut sa femme; elle conçut, et enfanta Hénoc. Il bâtit ensuite une ville, et il donna à cette ville le nom de son fils Hénoc."}, {"numero": 18, "texto": "Hénoc engendra Irad, Irad engendra Mehujaël, Mehujaël engendra Metuschaël, et Metuschaël engendra Lémec."}, {"numero": 19, "texto": "Lémec prit deux femmes: le nom de l''''une était Ada, et le nom de l''''autre Tsilla."}, {"numero": 20, "texto": "Ada enfanta Jabal: il fut le père de ceux qui habitent sous des tentes et près des troupeaux."}, {"numero": 21, "texto": "Le nom de son frère était Jubal: il fut le père de tous ceux qui jouent de la harpe et du chalumeau."}, {"numero": 22, "texto": "Tsilla, de son côté, enfanta Tubal-Caïn, qui forgeait tous les instruments d''''airain et de fer. La soeur de Tubal-Caïn était Naama."}, {"numero": 23, "texto": "Lémec dit à ses femmes: Ada et Tsilla, écoutez ma voix! Femmes de Lémec, écoutez ma parole! J''''ai tué un homme pour ma blessure, Et un jeune homme pour ma meurtrissure."}, {"numero": 24, "texto": "Caïn sera vengé sept fois, Et Lémec soixante-dix-sept fois."}, {"numero": 25, "texto": "Adam connut encore sa femme; elle enfanta un fils, et l''''appela du nom de Seth, car, dit-elle, Dieu m''''a donné un autre fils à la place d''''Abel, que Caïn a tué."}, {"numero": 26, "texto": "Seth eut aussi un fils, et il l''''appela du nom d''''Enosch. C''''est alors que l''''on commença à invoquer le nom de l''''Eternel."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 4, 'es', '[{"numero": 1, "texto": "Y CONOCIÓ Adam á su mujer Eva, la cual concibió y parió á Caín, y dijo: Adquirido he varón por Jehová."}, {"numero": 2, "texto": "Y después parió á su hermano Abel. Y fué Abel pastor de ovejas, y Caín fué labrador de la tierra."}, {"numero": 3, "texto": "Y aconteció andando el tiempo, que Caín trajo del fruto de la tierra una ofrenda á Jehová."}, {"numero": 4, "texto": "Y Abel trajo también de los primogénitos de sus ovejas, y de su grosura. Y miró Jehová con agrado á Abel y á su ofrenda;"}, {"numero": 5, "texto": "Mas no miró propicio á Caín y á la ofrenda suya. Y ensañóse Caín en gran manera, y decayó su semblante."}, {"numero": 6, "texto": "Entonces Jehová dijo á Caín: ¿Por qué te has ensañado, y por qué se ha inmutado tu rostro?"}, {"numero": 7, "texto": "Si bien hicieres, ¿no serás ensalzado? y si no hicieres bien, el pecado está á la puerta: con todo esto, á ti será su deseo, y tú te enseñorearás de él."}, {"numero": 8, "texto": "Y habló Caín á su hermano Abel: y aconteció que estando ellos en el campo, Caín se levantó contra su hermano Abel, y le mató."}, {"numero": 9, "texto": "Y Jehová dijo á Caín: ¿Dónde está Abel tu hermano? Y él respondió: No sé; ¿soy yo guarda de mi hermano?"}, {"numero": 10, "texto": "Y él le dijo: ¿Qué has hecho? La voz de la sangre de tu hermano clama á mí desde la tierra."}, {"numero": 11, "texto": "Ahora pues, maldito seas tú de la tierra que abrió su boca para recibir la sangre de tu hermano de tu mano:"}, {"numero": 12, "texto": "Cuando labrares la tierra, no te volverá á dar su fuerza: errante y extranjero serás en la tierra."}, {"numero": 13, "texto": "Y dijo Caín á Jehová: Grande es mi iniquidad para ser perdonada."}, {"numero": 14, "texto": "He aquí me echas hoy de la faz de la tierra, y de tu presencia me esconderé; y seré errante y extranjero en la tierra; y sucederá que cualquiera que me hallare, me matará."}, {"numero": 15, "texto": "Y respondióle Jehová: Cierto que cualquiera que matare á Caín, siete veces será castigado. Entonces Jehová puso señal en Caín, para que no lo hiriese cualquiera que le hallara."}, {"numero": 16, "texto": "Y salió Caín de delante de Jehová, y habitó en tierra de Nod, al oriente de Edén."}, {"numero": 17, "texto": "Y conoció Caín á su mujer, la cual concibió y parió á Henoch: y edificó una ciudad, y llamó el nombre de la ciudad del nombre de su hijo, Henoch."}, {"numero": 18, "texto": "Y á Henoch nació Irad, é Irad engendró á Mehujael, y Mehujael engendró á Methusael, y Methusael engendró á Lamech."}, {"numero": 19, "texto": "Y tomó para sí Lamech dos mujeres; el nombre de la una fué Ada, y el nombre de la otra Zilla."}, {"numero": 20, "texto": "Y Ada parió á Jabal, el cual fué padre de los que habitan en tiendas, y crían ganados."}, {"numero": 21, "texto": "Y el nombre de su hermano fué Jubal, el cual fué padre de todos los que manejan arpa y órgano."}, {"numero": 22, "texto": "Y Zilla también parió á Tubal-Caín, acicalador de toda obra de metal y de hierro: y la hermana de Tubal-Caín fué Naama."}, {"numero": 23, "texto": "Y dijo Lamech á sus mujeres: Ada y Zilla, oid mi voz; mujeres de Lamech, escuchad mi dicho: que varón mataré por mi herida, y mancebo por mi golpe:"}, {"numero": 24, "texto": "Si siete veces será vengado Caín, Lamech en verdad setenta veces siete lo será."}, {"numero": 25, "texto": "Y conoció de nuevo Adam á su mujer, la cual parió un hijo, y llamó su nombre Seth: Porque Dios (dijo ella) me ha sustituído otra simiente en lugar de Abel, á quien mató Caín."}, {"numero": 26, "texto": "Y á Seth también le nació un hijo, y llamó su nombre Enós. Entonces los hombres comenzaron á llamarse del nombre de Jehová."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 6, 'pt', '[{"numero": 1, "texto": "E aconteceu que, quando começaram os homens a multiplicar-se sobre a face da terra, e lhes nasceram filhas,"}, {"numero": 2, "texto": "Vendo os filhos de Deus que as filhas dos homens eram belas, tomaram para si mulheres, escolhendo entre todas."}, {"numero": 3, "texto": "E disse o SENHOR: Não brigará meu espírito com o ser humano para sempre, porque certamente ele é carne: mas serão seus dias cento e vinte anos."}, {"numero": 4, "texto": "Havia gigantes na terra naqueles dias, e também depois que entraram os filhos de Deus às filhas dos homens, e lhes geraram filhos: estes foram os valentes que desde a antiguidade foram homens de renome."}, {"numero": 5, "texto": "E o SENHOR viu que a maldade dos seres humanos era muita na terra, e que todo desígnio dos pensamentos dos seus corações era só mau continuamente."}, {"numero": 6, "texto": "E o SENHOR se arrependeu de haver feito o ser humano na terra, e pesou-lhe em seu coração."}, {"numero": 7, "texto": "E disse o SENHOR: Apagarei os seres humanos que criei de sobre a face da terra, desde o ser humano até o animal, e até o réptil e as aves do céu; porque me arrependo de havê-los feito."}, {"numero": 8, "texto": "Porém Noé achou favor aos olhos do SENHOR."}, {"numero": 9, "texto": "Estas são as gerações de Noé: Noé, homem justo, foi íntegro em suas gerações; Noé andava com Deus."}, {"numero": 10, "texto": "E gerou Noé três filhos: a Sem, a Cam, e a Jafé."}, {"numero": 11, "texto": "Porém a terra se corrompeu diante de Deus, e a terra encheu-se de violência."}, {"numero": 12, "texto": "E Deus olhou a terra, e eis que estava corrompida; porque toda carne havia corrompido seu caminho sobre a terra."}, {"numero": 13, "texto": "E disse Deus a Noé: O fim de toda carne veio diante de mim; porque a terra está cheia de violência por causa deles; e eis que eu os destruirei com a terra."}, {"numero": 14, "texto": "Faze-te uma arca de madeira de gôfer: farás aposentos na arca e a selarás com betume por dentro e por fora."}, {"numero": 15, "texto": "E desta maneira a farás: de trezentos côvados o comprimento da arca, de cinquenta côvados sua largura, e de trinta côvados sua altura."}, {"numero": 16, "texto": "Uma janela farás à arca, e a acabarás a um côvado de elevação pela parte de cima: e porás a porta da arca a seu lado; e lhe farás piso abaixo, segundo e terceiro."}, {"numero": 17, "texto": "E eu, eis que eu trago um dilúvio de águas sobre a terra, para destruir toda carne em que haja espírito de vida debaixo do céu; tudo o que há na terra morrerá."}, {"numero": 18, "texto": "Mas estabelecerei meu pacto contigo, e entrarás na arca tu, e teus filhos e tua mulher, e as mulheres de teus filhos contigo."}, {"numero": 19, "texto": "E de tudo o que vive, de toda carne, dois de cada espécie porás na arca, para que tenham vida contigo; macho e fêmea serão."}, {"numero": 20, "texto": "Das aves segundo sua espécie, e dos animais segundo sua espécie, de todo réptil da terra segundo sua espécie, dois de cada espécie entrarão contigo para que tenham vida."}, {"numero": 21, "texto": "E toma contigo de toda comida que se come, e traga-a a ti; servirá de alimento para ti e para eles."}, {"numero": 22, "texto": "E o fez assim Noé; fez conforme tudo o que Deus lhe mandou."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 6, 'en', '[{"numero": 1, "texto": "And it came to pass, when men began to multiply on the face of the earth, and daughters were born unto them,"}, {"numero": 2, "texto": "That the sons of God saw the daughters of men that they were fair; and they took them wives of all which they chose."}, {"numero": 3, "texto": "And the Lord said, My spirit shall not always strive with man, for that he also is flesh: yet his days shall be an hundred and twenty years."}, {"numero": 4, "texto": "There were giants in the earth in those days; and also after that, when the sons of God came in unto the daughters of men, and they bare children to them, the same became mighty men which were of old, men of renown."}, {"numero": 5, "texto": "And God saw that the wickedness of man was great in the earth, and that every imagination of the thoughts of his heart was only evil continually."}, {"numero": 6, "texto": "And it repented the Lord that he had made man on the earth, and it grieved him at his heart."}, {"numero": 7, "texto": "And the Lord said, I will destroy man whom I have created from the face of the earth; both man, and beast, and the creeping thing, and the fowls of the air; for it repenteth me that I have made them."}, {"numero": 8, "texto": "But Noah found grace in the eyes of the Lord."}, {"numero": 9, "texto": "These are the generations of Noah: Noah was a just man and perfect in his generations, and Noah walked with God."}, {"numero": 10, "texto": "And Noah begat three sons, Shem, Ham, and Japheth."}, {"numero": 11, "texto": "The earth also was corrupt before God, and the earth was filled with violence."}, {"numero": 12, "texto": "And God looked upon the earth, and, behold, it was corrupt; for all flesh had corrupted his way upon the earth."}, {"numero": 13, "texto": "And God said unto Noah, The end of all flesh is come before me; for the earth is filled with violence through them; and, behold, I will destroy them with the earth."}, {"numero": 14, "texto": "Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch."}, {"numero": 15, "texto": "And this is the fashion which thou shalt make it of: The length of the ark shall be three hundred cubits, the breadth of it fifty cubits, and the height of it thirty cubits."}, {"numero": 16, "texto": "A window shalt thou make to the ark, and in a cubit shalt thou finish it above; and the door of the ark shalt thou set in the side thereof; with lower, second, and third stories shalt thou make it."}, {"numero": 17, "texto": "And, behold, I, even I, do bring a flood of waters upon the earth, to destroy all flesh, wherein is the breath of life, from under heaven; and every thing that is in the earth shall die."}, {"numero": 18, "texto": "But with thee will I establish my covenant; and thou shalt come into the ark, thou, and thy sons, and thy wife, and thy sons'' wives with thee."}, {"numero": 19, "texto": "And of every living thing of all flesh, two of every sort shalt thou bring into the ark, to keep them alive with thee; they shall be male and female."}, {"numero": 20, "texto": "Of fowls after their kind, and of cattle after their kind, of every creeping thing of the earth after his kind, two of every sort shall come unto thee, to keep them alive."}, {"numero": 21, "texto": "And take thou unto thee of all food that is eaten, and thou shalt gather it to thee; and it shall be for food for thee, and for them."}, {"numero": 22, "texto": "Thus did Noah; according to all that God commanded him, so did he."}]'::jsonb, 'King James Version'),
  ('Gn', 6, 'fr', '[{"numero": 1, "texto": "Lorsque les hommes eurent commencé à se multiplier sur la face de la terre, et que des filles leur furent nées,"}, {"numero": 2, "texto": "les fils de Dieu virent que les filles des hommes étaient belles, et ils en prirent pour femmes parmi toutes celles qu''''ils choisirent."}, {"numero": 3, "texto": "Alors l''''Eternel dit: Mon esprit ne restera pas à toujours dans l''''homme, car l''''homme n''''est que chair, et ses jours seront de cent vingt ans."}, {"numero": 4, "texto": "Les géants étaient sur la terre en ces temps-là, après que les fils de Dieu furent venus vers les filles des hommes, et qu''''elles leur eurent donné des enfants: ce sont ces héros qui furent fameux dans l''''antiquité."}, {"numero": 5, "texto": "L''''Eternel vit que la méchanceté des hommes était grande sur la terre, et que toutes les pensées de leur coeur se portaient chaque jour uniquement vers le mal."}, {"numero": 6, "texto": "L''''Eternel se repentit d''''avoir fait l''''homme sur la terre, et il fut affligé en son coeur."}, {"numero": 7, "texto": "Et l''''Eternel dit: J''''exterminerai de la face de la terre l''''homme que j''''ai créé, depuis l''''homme jusqu''''au bétail, aux reptiles, et aux oiseaux du ciel; car je me repens de les avoir faits."}, {"numero": 8, "texto": "Mais Noé trouva grâce aux yeux de l''''Eternel."}, {"numero": 9, "texto": "Voici la postérité de Noé. Noé était un homme juste et intègre dans son temps; Noé marchait avec Dieu."}, {"numero": 10, "texto": "Noé engendra trois fils: Sem, Cham et Japhet."}, {"numero": 11, "texto": "La terre était corrompue devant Dieu, la terre était pleine de violence."}, {"numero": 12, "texto": "Dieu regarda la terre, et voici, elle était corrompue; car toute chair avait corrompu sa voie sur la terre."}, {"numero": 13, "texto": "Alors Dieu dit à Noé: La fin de toute chair est arrêtée par devers moi; car ils ont rempli la terre de violence; voici, je vais les détruire avec la terre."}, {"numero": 14, "texto": "Fais-toi une arche de bois de gopher; tu disposeras cette arche en cellules, et tu l''''enduiras de poix en dedans et en dehors."}, {"numero": 15, "texto": "Voici comment tu la feras: l''''arche aura trois cents coudées de longueur, cinquante coudées de largeur et trente coudées de hauteur."}, {"numero": 16, "texto": "Tu feras à l''''arche une fenêtre, que tu réduiras à une coudée en haut; tu établiras une porte sur le côté de l''''arche; et tu construiras un étage inférieur, un second et un troisième."}, {"numero": 17, "texto": "Et moi, je vais faire venir le déluge d''''eaux sur la terre, pour détruire toute chair ayant souffle de vie sous le ciel; tout ce qui est sur la terre périra."}, {"numero": 18, "texto": "Mais j''''établis mon alliance avec toi; tu entreras dans l''''arche, toi et tes fils, ta femme et les femmes de tes fils avec toi."}, {"numero": 19, "texto": "De tout ce qui vit, de toute chair, tu feras entrer dans l''''arche deux de chaque espèce, pour les conserver en vie avec toi: il y aura un mâle et une femelle."}, {"numero": 20, "texto": "Des oiseaux selon leur espèce, du bétail selon son espèce, et de tous les reptiles de la terre selon leur espèce, deux de chaque espèce viendront vers toi, pour que tu leur conserves la vie."}, {"numero": 21, "texto": "Et toi, prends de tous les aliments que l''''on mange, et fais-en une provision auprès de toi, afin qu''''ils te servent de nourriture ainsi qu''''à eux."}, {"numero": 22, "texto": "C''''est ce que fit Noé: il exécuta tout ce que Dieu lui avait ordonné."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 6, 'es', '[{"numero": 1, "texto": "Y ACAECIÓ que, cuando comenzaron los hombres á multiplicarse sobre la faz de la tierra, y les nacieron hijas,"}, {"numero": 2, "texto": "Viendo los hijos de Dios que las hijas de los hombres eran hermosas, tomáronse mujeres, escogiendo entre todas."}, {"numero": 3, "texto": "Y dijo Jehová: No contenderá mi espíritu con el hombre para siempre, porque ciertamente él es carne: mas serán sus días ciento y veinte años."}, {"numero": 4, "texto": "Había gigantes en la tierra en aquellos días, y también después que entraron los hijos de Dios á las hijas de los hombres, y les engendraron hijos: éstos fueron los valientes que desde la antigüedad fueron varones de nombre."}, {"numero": 5, "texto": "Y vió Jehová que la malicia de los hombres era mucha en la tierra, y que todo designio de los pensamientos del corazón de ellos era de continuo solamente el mal."}, {"numero": 6, "texto": "Y arrepintióse Jehová de haber hecho hombre en la tierra, y pesóle en su corazón."}, {"numero": 7, "texto": "Y dijo Jehová: Raeré los hombres que he criado de sobre la faz de la tierra, desde el hombre hasta la bestia, y hasta el reptil y las aves del cielo: porque me arrepiento de haberlos hecho."}, {"numero": 8, "texto": "Empero Noé halló gracia en los ojos de Jehová."}, {"numero": 9, "texto": "Estas son las generaciones de Noé: Noé, varón justo, perfecto fué en sus generaciones; con Dios caminó Noé."}, {"numero": 10, "texto": "Y engendró Noé tres hijos: á Sem, á Châm, y á Japhet."}, {"numero": 11, "texto": "Y corrompióse la tierra delante de Dios, y estaba la tierra llena de violencia."}, {"numero": 12, "texto": "Y miró Dios la tierra, y he aquí que estaba corrompida; porque toda carne había corrompido su camino sobre la tierra."}, {"numero": 13, "texto": "Y dijo Dios á Noé: El fin de toda carne ha venido delante de mí; porque la tierra está llena de violencia á causa de ellos; y he aquí que yo los destruiré con la tierra."}, {"numero": 14, "texto": "Hazte un arca de madera de Gopher: harás aposentos en el arca, y la embetunarás con brea por dentro y por fuera."}, {"numero": 15, "texto": "Y de esta manera la harás: de trescientos codos la longitud del arca, de cincuenta codos su anchura, y de treinta codos su altura."}, {"numero": 16, "texto": "Una ventana harás al arca, y la acabarás á un codo de elevación por la parte de arriba: y pondrás la puerta del arca á su lado; y le harás piso bajo, segundo y tercero."}, {"numero": 17, "texto": "Y yo, he aquí que yo traigo un diluvio de aguas sobre la tierra, para destruir toda carne en que haya espíritu de vida debajo del cielo; todo lo que hay en la tierra morirá."}, {"numero": 18, "texto": "Mas estableceré mi pacto contigo, y entrarás en el arca tú, y tus hijos y tu mujer, y las mujeres de tus hijos contigo."}, {"numero": 19, "texto": "Y de todo lo que vive, de toda carne, dos de cada especie meterás en el arca, para que tengan vida contigo; macho y hembra serán."}, {"numero": 20, "texto": "De las aves según su especie, y de las bestias según su especie, de todo reptil de la tierra según su especie, dos de cada especie entrarán contigo para que hayan vida."}, {"numero": 21, "texto": "Y toma contigo de toda vianda que se come, y allégala á ti; servirá de alimento para ti y para ellos."}, {"numero": 22, "texto": "E hízolo así Noé; hizo conforme á todo lo que Dios le mandó."}]'::jsonb, 'Reina-Valera 1909')
